function sketch(p) {
  let sulley;
  let leaderboard = [];
  let colleagues = [];
  let sparkles = [];
  let glowPulse = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize Sulley position
    sulley = {
      x: 200,
      y: 350,
      confidence: 1.0
    };

    // Create leaderboard entries
    leaderboard = [
      { name: "SULLIVAN, J.P.", score: 9999, glow: 1.0 },
      { name: "WAZOWSKI, M.", score: 2319, glow: 0.3 },
      { name: "FUNGUS", score: 1567, glow: 0.2 },
      { name: "RANDALL", score: 1320, glow: 0.2 }
    ];

    // Create admiring colleagues
    for (let i = 0; i < 8; i++) {
      colleagues.push({
        x: p.random(50, 350),
        y: p.random(480, 550),
        size: p.random(15, 25),
        bobOffset: p.random(p.TWO_PI),
        admiration: p.random(0.8, 1.0)
      });
    }

    // Create sparkle particles
    for (let i = 0; i < 30; i++) {
      sparkles.push({
        x: p.random(400),
        y: p.random(200),
        size: p.random(2, 6),
        speed: p.random(0.5, 2),
        alpha: p.random(100, 255)
      });
    }
  };

  p.draw = function() {
    // Corporate blue-green gradient background
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(20, 40, 80), p.color(10, 60, 90), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    glowPulse += 0.05;
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0.8, 1.2);

    // Draw scare floor tiles
    p.stroke(40, 80, 120, 100);
    p.strokeWeight(1);
    for (let x = 0; x < p.width; x += 40) {
      for (let y = 300; y < p.height; y += 40) {
        p.noFill();
        p.rect(x, y, 40, 40);
      }
    }

    // Draw leaderboard background
    p.fill(0, 0, 0, 150);
    p.noStroke();
    p.rect(50, 40, 300, 180, 10);

    // Corporate frame
    p.strokeWeight(3);
    p.stroke(100, 150, 200);
    p.noFill();
    p.rect(52, 42, 296, 176, 8);

    // Draw leaderboard entries
    for (let i = 0; i < leaderboard.length; i++) {
      let entry = leaderboard[i];
      let y = 80 + i * 35;

      if (i === 0) {
        // Sulley's glowing entry
        let glow = 0.5 + 0.3 * p.sin(glowPulse * 2) * mouseInfluence;
        p.fill(255, 200, 0, 255 * glow);
        p.noStroke();
        p.rect(60, y - 15, 280, 25, 5);

        p.fill(255, 255, 100);
        p.textAlign(p.LEFT);
        p.textSize(16);
        p.textStyle(p.BOLD);
        p.text(entry.name, 70, y);

        p.textAlign(p.RIGHT);
        p.text(entry.score, 330, y);
      } else {
        p.fill(150, 180, 220, 150);
        p.textAlign(p.LEFT);
        p.textSize(12);
        p.textStyle(p.NORMAL);
        p.text(entry.name, 70, y);

        p.textAlign(p.RIGHT);
        p.text(entry.score, 330, y);
      }
    }

    // Draw sparkles around leaderboard
    for (let sparkle of sparkles) {
      sparkle.x += sparkle.speed * p.sin(p.frameCount * 0.02);
      sparkle.y += sparkle.speed * 0.5;

      if (sparkle.y > 220) {
        sparkle.y = 40;
        sparkle.x = p.random(50, 350);
      }

      let alpha = sparkle.alpha * (0.7 + 0.3 * p.sin(p.frameCount * 0.1 + sparkle.x));
      p.fill(255, 255, 150, alpha);
      p.noStroke();
      p.ellipse(sparkle.x, sparkle.y, sparkle.size);
    }

    // Draw Sulley silhouette
    let sulleyScale = 0.9 + 0.1 * p.sin(glowPulse) * mouseInfluence;
    p.push();
    p.translate(sulley.x, sulley.y);
    p.scale(sulleyScale);

    // Confidence glow around Sulley
    let confidence = sulley.confidence * mouseInfluence;
    p.fill(0, 150, 255, 30 * confidence);
    p.noStroke();
    p.ellipse(0, 0, 180, 220);

    // Sulley's body
    p.fill(0, 120, 180);
    p.ellipse(0, 20, 120, 160);

    // Sulley's head
    p.fill(0, 140, 200);
    p.ellipse(0, -40, 100, 100);

    // Horns
    p.fill(80, 100, 140);
    p.ellipse(-25, -75, 15, 25);
    p.ellipse(25, -75, 15, 25);

    // Eyes (confident stare)
    p.fill(255);
    p.ellipse(-20, -45, 25, 30);
    p.ellipse(20, -45, 25, 30);

    p.fill(0);
    p.ellipse(-20, -40, 15, 20);
    p.ellipse(20, -40, 15, 20);

    // Spots
    p.fill(80, 60, 120, 150);
    p.ellipse(-30, -10, 20, 25);
    p.ellipse(40, 10, 15, 20);
    p.ellipse(-20, 50, 18, 22);
    p.ellipse(25, 35, 12, 15);

    p.pop();

    // Draw admiring colleagues
    for (let colleague of colleagues) {
      let bob = p.sin(p.frameCount * 0.05 + colleague.bobOffset) * 3;
      let admirationPulse = colleague.admiration * (0.8 + 0.2 * p.sin(p.frameCount * 0.03));

      p.push();
      p.translate(colleague.x, colleague.y + bob);

      // Admiration glow
      p.fill(255, 200, 100, 50 * admirationPulse);
      p.noStroke();
      p.ellipse(0, 0, colleague.size * 2, colleague.size * 2);

      // Colleague silhouette
      p.fill(40, 80, 120);
      p.ellipse(0, 0, colleague.size, colleague.size * 1.2);

      // Eyes looking at Sulley
      let eyeAngle = p.atan2(sulley.y - (colleague.y + bob), sulley.x - colleague.x);
      p.fill(255, 255, 100, 200);
      p.push();
      p.rotate(eyeAngle);
      p.ellipse(colleague.size * 0.2, 0, 3, 3);
      p.pop();

      p.pop();
    }

    // Interactive confidence boost on mouse proximity
    let distanceToSulley = p.dist(p.mouseX, p.mouseY, sulley.x, sulley.y);
    if (distanceToSulley < 100) {
      sulley.confidence = p.lerp(sulley.confidence, 1.3, 0.1);

      // Extra sparkles when mouse is near
      if (p.frameCount % 3 === 0) {
        sparkles.push({
          x: sulley.x + p.random(-50, 50),
          y: sulley.y + p.random(-50, 50),
          size: p.random(3, 8),
          speed: p.random(1, 3),
          alpha: 255
        });
      }
    } else {
      sulley.confidence = p.lerp(sulley.confidence, 1.0, 0.05);
    }

    // Remove excess sparkles
    if (sparkles.length > 50) {
      sparkles.splice(0, sparkles.length - 50);
    }

    // Corporate lighting effects
    p.fill(100, 150, 255, 20);
    p.noStroke();
    for (let i = 0; i < 3; i++) {
      let lightY = 250 + i * 100;
      p.ellipse(200, lightY, 400, 30);
    }
  };
}

function sketch(p) {
  let mike;
  let paperwork = [];
  let clipboard;
  let sparkles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize Mike's position
    mike = {
      x: 200,
      y: 350,
      eyeSize: 80,
      pupilX: 0,
      pupilY: 0,
      armAngle: 0
    };

    // Create floating paperwork
    for (let i = 0; i < 8; i++) {
      paperwork.push({
        x: p.random(50, 350),
        y: p.random(100, 250),
        rotation: p.random(-0.3, 0.3),
        floatOffset: p.random(0, p.TWO_PI),
        type: p.floor(p.random(3))
      });
    }

    clipboard = {
      x: 320,
      y: 200,
      rotation: 0.1
    };

    // Initialize sparkles for professional efficiency
    for (let i = 0; i < 15; i++) {
      sparkles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(2, 6),
        alpha: p.random(100, 255),
        speed: p.random(0.5, 1.5)
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Corporate background gradient
    for (let i = 0; i <= 600; i++) {
      let inter = p.map(i, 0, 600, 0, 1);
      let c = p.lerpColor(p.color(20, 40, 80), p.color(40, 80, 120), inter);
      p.stroke(c);
      p.line(0, i, 400, i);
    }

    // Draw office environment silhouettes
    p.fill(10, 20, 40, 150);
    p.noStroke();
    p.rect(0, 480, 400, 120); // Floor

    // Filing cabinets in background
    p.fill(15, 25, 45);
    p.rect(50, 420, 80, 60);
    p.rect(150, 430, 60, 50);
    p.rect(280, 425, 70, 55);

    // Draw floating paperwork
    for (let paper of paperwork) {
      p.push();
      p.translate(paper.x, paper.y + p.sin(time * 2 + paper.floatOffset) * 3);
      p.rotate(paper.rotation + p.sin(time + paper.floatOffset) * 0.05);

      // Paper shadow
      p.fill(0, 0, 0, 30);
      p.rect(2, 2, 40, 50);

      // Paper
      p.fill(240, 245, 250);
      p.stroke(200, 210, 220);
      p.strokeWeight(1);
      p.rect(0, 0, 40, 50);

      // Content lines based on type
      p.stroke(80, 100, 140);
      p.strokeWeight(0.5);
      if (paper.type === 0) {
        // Text lines
        for (let i = 0; i < 8; i++) {
          p.line(5, 8 + i * 4, 35, 8 + i * 4);
        }
      } else if (paper.type === 1) {
        // Checkboxes
        for (let i = 0; i < 6; i++) {
          p.rect(5, 6 + i * 6, 3, 3);
          p.line(12, 8 + i * 6, 30, 8 + i * 6);
        }
      } else {
        // Graph
        p.line(8, 40, 32, 40);
        p.line(8, 40, 8, 15);
        for (let i = 0; i < 6; i++) {
          let h = p.random(5, 20);
          p.rect(10 + i * 3, 40 - h, 2, h);
        }
      }
      p.pop();
    }

    // Draw clipboard
    p.push();
    p.translate(clipboard.x, clipboard.y);
    p.rotate(clipboard.rotation);

    // Clipboard back
    p.fill(120, 90, 60);
    p.stroke(80, 60, 40);
    p.strokeWeight(2);
    p.rect(-25, -35, 50, 70, 3);

    // Clip
    p.fill(150, 150, 150);
    p.rect(-8, -40, 16, 12, 2);

    // Paper on clipboard
    p.fill(250, 250, 255);
    p.stroke(200);
    p.strokeWeight(1);
    p.rect(-20, -25, 40, 50);

    // Checkmarks
    p.stroke(50, 150, 50);
    p.strokeWeight(2);
    p.noFill();
    for (let i = 0; i < 5; i++) {
      p.beginShape();
      p.vertex(-15, -15 + i * 8);
      p.vertex(-10, -10 + i * 8);
      p.vertex(-5, -18 + i * 8);
      p.endShape();
    }
    p.pop();

    // Draw Mike Wazowski
    p.push();
    p.translate(mike.x, mike.y);

    // Mike's body (green)
    p.fill(100, 200, 100);
    p.stroke(80, 160, 80);
    p.strokeWeight(2);
    p.ellipse(0, 20, 120, 140);

    // Mike's eye (large single eye)
    p.fill(255);
    p.stroke(80, 160, 80);
    p.strokeWeight(3);
    p.ellipse(0, -10, mike.eyeSize, mike.eyeSize);

    // Pupil tracking mouse
    let mouseAngle = p.atan2(p.mouseY - (mike.y - 10), p.mouseX - mike.x);
    let pupilDistance = p.constrain(p.dist(p.mouseX, p.mouseY, mike.x, mike.y - 10) * 0.1, 0, 15);
    mike.pupilX = p.cos(mouseAngle) * pupilDistance;
    mike.pupilY = p.sin(mouseAngle) * pupilDistance;

    // Pupil
    p.fill(50, 50, 200);
    p.noStroke();
    p.ellipse(mike.pupilX, -10 + mike.pupilY, 25, 25);

    // Pupil highlight
    p.fill(255);
    p.ellipse(mike.pupilX + 5, -15 + mike.pupilY, 8, 8);

    // Mike's arms (animated for paperwork handling)
    mike.armAngle = p.sin(time * 3) * 0.3;

    // Left arm reaching for paperwork
    p.stroke(80, 160, 80);
    p.strokeWeight(8);
    p.line(-30, 0, -50 + p.cos(mike.armAngle) * 10, -20 + p.sin(mike.armAngle) * 5);

    // Right arm holding pen
    p.line(30, 0, 50 + p.cos(-mike.armAngle) * 8, -15 + p.sin(-mike.armAngle) * 3);

    // Pen in right hand
    p.stroke(200, 180, 100);
    p.strokeWeight(3);
    p.line(50, -15, 55, -25);

    // Mike's legs
    p.stroke(80, 160, 80);
    p.strokeWeight(6);
    p.line(-15, 80, -20, 120);
    p.line(15, 80, 20, 120);

    // Feet
    p.fill(100, 200, 100);
    p.noStroke();
    p.ellipse(-25, 125, 20, 12);
    p.ellipse(25, 125, 20, 12);

    p.pop();

    // Professional efficiency sparkles
    for (let sparkle of sparkles) {
      sparkle.y -= sparkle.speed;
      sparkle.alpha -= 2;

      if (sparkle.y < 0 || sparkle.alpha <= 0) {
        sparkle.y = 600;
        sparkle.x = p.random(400);
        sparkle.alpha = p.random(100, 255);
      }

      p.fill(255, 220, 100, sparkle.alpha);
      p.noStroke();
      p.ellipse(sparkle.x, sparkle.y, sparkle.size, sparkle.size);
    }

    // Interactive effect - clicking organizes paperwork
    if (p.mouseIsPressed) {
      for (let i = 0; i < paperwork.length; i++) {
        paperwork[i].x = p.lerp(paperwork[i].x, 320 + (i % 3) * 5, 0.05);
        paperwork[i].y = p.lerp(paperwork[i].y, 180 + i * 3, 0.05);
        paperwork[i].rotation = p.lerp(paperwork[i].rotation, 0, 0.05);
      }
    }

    // Professional glow around Mike when mouse is near
    let distToMike = p.dist(p.mouseX, p.mouseY, mike.x, mike.y);
    if (distToMike < 100) {
      p.fill(255, 255, 200, 50);
      p.noStroke();
      p.ellipse(mike.x, mike.y, 200, 200);
    }
  };
}

function sketch(p) {
  let monsters = [];
  let windows = [];
  let time = 0;
  let buildingPulse = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create monster flow particles
    for (let i = 0; i < 60; i++) {
      monsters.push({
        x: p.random(40, 360),
        y: p.random(150, 580),
        size: p.random(3, 8),
        speed: p.random(0.5, 2),
        direction: p.random(p.TWO_PI),
        color: p.color(p.random(100, 255), p.random(50, 150), p.random(200, 255), 150),
        phase: p.random(p.TWO_PI)
      });
    }

    // Create building windows
    for (let x = 60; x < 340; x += 20) {
      for (let y = 180; y < 500; y += 25) {
        if (p.random() > 0.3) {
          windows.push({
            x: x,
            y: y,
            brightness: p.random(0.2, 1),
            flicker: p.random(0.01, 0.03)
          });
        }
      }
    }
  };

  p.draw = function() {
    time += 0.02;
    buildingPulse = p.sin(time * 0.5) * 0.1;

    // Dark corporate sky gradient
    for (let y = 0; y < 150; y++) {
      let inter = p.map(y, 0, 150, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(35, 45, 70), inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    // Ground/foundation gradient
    for (let y = 500; y < 600; y++) {
      let inter = p.map(y, 500, 600, 0, 1);
      let c = p.lerpColor(p.color(25, 30, 40), p.color(10, 15, 25), inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    // Main building structure - imposing and corporate
    p.fill(35 + buildingPulse * 10, 40 + buildingPulse * 10, 55 + buildingPulse * 10);
    p.noStroke();
    p.rect(50, 150, 300, 350, 5);

    // Building accent lines - corporate aesthetic
    p.stroke(70, 80, 100);
    p.strokeWeight(2);
    p.line(50, 200, 350, 200);
    p.line(50, 450, 350, 450);
    p.line(120, 150, 120, 500);
    p.line(280, 150, 280, 500);

    // Monsters Inc logo area
    p.fill(0, 120, 200, 180);
    p.noStroke();
    p.ellipse(200, 220, 80, 60);
    p.fill(255, 255, 255, 200);
    p.ellipse(200, 220, 60, 45);
    p.fill(0, 120, 200);
    p.textAlign(p.CENTER);
    p.textSize(8);
    p.text("M", 200, 225);

    // Animated windows with corporate energy
    p.noStroke();
    for (let window of windows) {
      window.brightness += p.random(-window.flicker, window.flicker);
      window.brightness = p.constrain(window.brightness, 0.1, 1);

      let brightness = window.brightness * (1 + buildingPulse * 0.3);
      p.fill(100 * brightness, 150 * brightness, 200 * brightness, 180);
      p.rect(window.x, window.y, 12, 15, 2);

      // Occasional screen glow
      if (p.random() > 0.95) {
        p.fill(0, 255, 150, 100);
        p.rect(window.x - 2, window.y - 2, 16, 19, 3);
      }
    }

    // Monster flow - like cells in an organism
    for (let monster of monsters) {
      monster.x += p.cos(monster.direction) * monster.speed;
      monster.y += p.sin(monster.direction) * monster.speed;

      // Organic movement pattern
      monster.direction += p.sin(time + monster.phase) * 0.05;

      // Wrap around and institutional flow patterns
      if (monster.x < 0) monster.x = 400;
      if (monster.x > 400) monster.x = 0;
      if (monster.y < 120) monster.y = 580;
      if (monster.y > 580) monster.y = 120;

      // Draw monster as organic cell-like shapes
      p.fill(monster.color);
      p.noStroke();
      let pulseSize = monster.size * (1 + p.sin(time * 2 + monster.phase) * 0.3);
      p.ellipse(monster.x, monster.y, pulseSize);

      // Motion trails for institutional flow
      p.fill(p.red(monster.color), p.green(monster.color), p.blue(monster.color), 50);
      p.ellipse(monster.x - p.cos(monster.direction) * 8, monster.y - p.sin(monster.direction) * 8, pulseSize * 0.6);
    }

    // Mouse interaction - institutional authority responds
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, 200, 300) / 200;

    // Building response to presence
    if (mouseInfluence < 1) {
      p.fill(100, 50, 0, (1 - mouseInfluence) * 30);
      p.noStroke();
      p.rect(50, 150, 300, 350, 5);

      // Enhanced window activity
      for (let window of windows) {
        if (p.random() > mouseInfluence) {
          p.fill(255, 150, 0, 120);
          p.rect(window.x - 1, window.y - 1, 14, 17, 2);
        }
      }
    }

    // Corporate power structure visualization
    p.stroke(80, 100, 140, 100);
    p.strokeWeight(1);
    for (let i = 0; i < 5; i++) {
      let radius = 150 + i * 30 + buildingPulse * 20;
      p.noFill();
      p.ellipse(200, 300, radius, radius * 0.6);
    }

    // Energy flow lines - corporate circulation
    p.stroke(0, 150, 255, 80);
    p.strokeWeight(2);
    for (let i = 0; i < 8; i++) {
      let angle = (time + i * 0.8) % p.TWO_PI;
      let x1 = 200 + p.cos(angle) * 80;
      let y1 = 300 + p.sin(angle) * 40;
      let x2 = 200 + p.cos(angle + 0.5) * 120;
      let y2 = 300 + p.sin(angle + 0.5) * 60;
      p.line(x1, y1, x2, y2);
    }
  };
}

function sketch(p) {
  let leaderboard = [];
  let canisters = [];
  let charts = [];
  let conveyor = 0;
  let glowIntensity = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize leaderboard data
    leaderboard = [
      { name: "SULLIVAN", score: 2319, rank: 1 },
      { name: "WAZOWSKI", score: 2018, rank: 2 },
      { name: "RANDALL", score: 1856, rank: 3 },
      { name: "FUNGUS", score: 1203, rank: 4 },
      { name: "NEEDLEMAN", score: 891, rank: 5 }
    ];

    // Initialize canisters
    for (let i = 0; i < 12; i++) {
      canisters.push({
        x: -50 + i * 70,
        y: 450 + p.random(-10, 10),
        fill: p.random(0.3, 1.0)
      });
    }

    // Initialize chart data points
    for (let i = 0; i < 20; i++) {
      charts.push({
        x: 50 + i * 15,
        y: 350 + p.random(-50, 50),
        height: p.random(20, 80)
      });
    }
  };

  p.draw = function() {
    // Dark corporate background with gradient
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(5, 10, 20), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    glowIntensity = p.sin(p.millis() * 0.003) * 0.5 + 0.5;
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);
    conveyor += 1.5;

    // Corporate grid pattern
    p.stroke(30, 50, 80, 100);
    p.strokeWeight(0.5);
    for (let i = 0; i < p.width; i += 40) {
      p.line(i, 0, i, p.height);
    }
    for (let i = 0; i < p.height; i += 40) {
      p.line(0, i, p.width, i);
    }

    // Main leaderboard screen
    drawLeaderboard();

    // Conveyor belt with canisters
    drawConveyor();

    // Performance charts
    drawCharts();

    // Data streams
    drawDataStreams();
  };

  function drawLeaderboard() {
    // Screen glow effect
    p.push();
    p.drawingContext.shadowBlur = 30 + glowIntensity * 20;
    p.drawingContext.shadowColor = 'rgba(0, 255, 100, 0.8)';
    p.fill(20, 30, 40);
    p.stroke(0, 255, 100, 150 + glowIntensity * 105);
    p.strokeWeight(2);
    p.rect(30, 50, 340, 220, 5);
    p.pop();

    // Screen inner glow
    p.fill(0, 40, 20, 50);
    p.noStroke();
    p.rect(35, 55, 330, 210, 3);

    // Leaderboard title
    p.fill(0, 255, 100, 200 + glowIntensity * 55);
    p.textAlign(p.CENTER);
    p.textSize(16);
    p.text("SCARE LEADERBOARD", 200, 80);

    // Rankings
    for (let i = 0; i < leaderboard.length; i++) {
      let entry = leaderboard[i];
      let yPos = 110 + i * 30;
      let intensity = 1.0 - i * 0.15;

      // Rank glow based on position
      let rankGlow = i === 0 ? glowIntensity * 100 : 30;

      // Rank number
      p.fill(255, 200, 0, 150 + rankGlow);
      p.textAlign(p.LEFT);
      p.textSize(14);
      p.text(entry.rank, 50, yPos);

      // Name
      p.fill(255, 255, 255, 180 * intensity);
      p.text(entry.name, 80, yPos);

      // Score with mouse interaction
      let scoreGlow = mouseInfluence * 100;
      p.fill(0, 255, 100, 120 + scoreGlow);
      p.textAlign(p.RIGHT);
      p.text(entry.score, 350, yPos);

      // Progress bar
      let barWidth = p.map(entry.score, 0, 2500, 0, 200);
      p.fill(0, 150, 50, 80);
      p.rect(120, yPos - 10, 200, 8);
      p.fill(0, 255, 100, 150 + intensity * 105);
      p.rect(120, yPos - 10, barWidth, 8);
    }
  }

  function drawConveyor() {
    // Conveyor belt
    p.stroke(60, 70, 80);
    p.strokeWeight(3);
    p.fill(40, 45, 50);
    p.rect(0, 440, p.width, 30);

    // Belt movement lines
    for (let i = 0; i < 20; i++) {
      let x = (i * 30 + conveyor) % p.width;
      p.stroke(80, 85, 90);
      p.strokeWeight(1);
      p.line(x, 445, x + 15, 445);
      p.line(x, 465, x + 15, 465);
    }

    // Scream canisters
    for (let canister of canisters) {
      canister.x += 1.5;
      if (canister.x > p.width + 50) {
        canister.x = -50;
        canister.fill = p.random(0.3, 1.0);
      }

      // Canister body
      p.fill(80, 90, 120);
      p.stroke(100, 110, 140);
      p.strokeWeight(1);
      p.rect(canister.x, canister.y, 25, 35, 3);

      // Energy level
      let fillHeight = canister.fill * 30;
      p.fill(255, 100, 255, 180);
      p.noStroke();
      p.rect(canister.x + 2, canister.y + 33 - fillHeight, 21, fillHeight);

      // Glow effect
      if (canister.fill > 0.8) {
        p.drawingContext.shadowBlur = 15;
        p.drawingContext.shadowColor = 'rgba(255, 100, 255, 0.8)';
        p.fill(255, 100, 255, 100);
        p.rect(canister.x, canister.y, 25, 35, 3);
        p.drawingContext.shadowBlur = 0;
      }

      // Label
      p.fill(200, 200, 200, 150);
      p.textAlign(p.CENTER);
      p.textSize(8);
      p.text(p.int(canister.fill * 100), canister.x + 12.5, canister.y + 50);
    }
  }

  function drawCharts() {
    // Chart background
    p.fill(25, 35, 50, 150);
    p.stroke(60, 80, 120, 100);
    p.strokeWeight(1);
    p.rect(30, 300, 340, 120, 5);

    // Grid lines
    p.stroke(60, 80, 120, 50);
    for (let i = 0; i < 5; i++) {
      let y = 320 + i * 20;
      p.line(40, y, 360, y);
    }

    // Performance bars
    for (let i = 0; i < charts.length; i++) {
      let bar = charts[i];
      let mouseEffect = p.map(p.mouseY, 0, p.height, 0.5, 1.5);
      let currentHeight = bar.height * mouseEffect;

      // Bar gradient
      for (let j = 0; j < currentHeight; j++) {
        let alpha = p.map(j, 0, currentHeight, 255, 100);
        p.fill(0, 200, 255, alpha);
        p.noStroke();
        p.rect(bar.x, 400 - j, 12, 1);
      }

      // Top highlight
      p.fill(100, 255, 255, 200);
      p.rect(bar.x, 400 - currentHeight, 12, 2);
    }

    // Chart title
    p.fill(255, 255, 255, 150);
    p.textAlign(p.LEFT);
    p.textSize(12);
    p.text("PRODUCTIVITY METRICS", 40, 320);
  }

  function drawDataStreams() {
    // Floating data points
    for (let i = 0; i < 30; i++) {
      let x = (p.millis() * 0.02 + i * 50) % p.width;
      let y = 500 + p.sin(p.millis() * 0.005 + i) * 20;
      let size = 3 + p.sin(p.millis() * 0.01 + i) * 2;

      p.fill(0, 255, 200, 120);
      p.noStroke();
      p.ellipse(x, y, size);

      // Connecting lines
      if (i > 0) {
        let prevX = (p.millis() * 0.02 + (i-1) * 50) % p.width;
        let prevY = 500 + p.sin(p.millis() * 0.005 + (i-1)) * 20;
        p.stroke(0, 255, 200, 50);
        p.strokeWeight(0.5);
        p.line(x, y, prevX, prevY);
      }
    }

    // Numbers floating up
    p.fill(255, 255, 255, 100 + glowIntensity * 55);
    p.textAlign(p.CENTER);
    p.textSize(10);
    for (let i = 0; i < 8; i++) {
      let x = 50 + i * 40;
      let y = (550 - (p.millis() * 0.05 + i * 100) % 600);
      p.text(p.int(p.random(100, 999)), x, y);
    }
  }

  p.mousePressed = function() {
    // Boost all scores temporarily
    for (let entry of leaderboard) {
      entry.score += p.int(p.random(50, 200));
    }

    // Add energy to canisters
    for (let canister of canisters) {
      canister.fill = p.min(1.0, canister.fill + 0.2);
    }
  };
}

function sketch(p) {
  let randallPos = { x: 200, y: 300 };
  let camouflageOpacity = 0;
  let eyeGlow = 0;
  let shadowParticles = [];
  let time = 0;
  let lurking = true;
  let watchingIntensity = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize shadow particles
    for (let i = 0; i < 30; i++) {
      shadowParticles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(3, 8),
        speed: p.random(0.5, 2),
        opacity: p.random(10, 40)
      });
    }
  };

  p.draw = function() {
    // Dark corporate background with subtle gradient
    for (let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(5, 10, 20), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    time += 0.02;

    // Animated shadow particles
    p.fill(20, 30, 50, 30);
    p.noStroke();
    for (let particle of shadowParticles) {
      particle.y += particle.speed;
      if (particle.y > p.height) particle.y = -10;

      p.fill(20, 30, 50, particle.opacity);
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Mouse tracking for Randall's lurking behavior
    let mouseDistance = p.dist(p.mouseX, p.mouseY, randallPos.x, randallPos.y);
    watchingIntensity = p.map(mouseDistance, 0, 300, 1, 0);
    watchingIntensity = p.constrain(watchingIntensity, 0, 1);

    // Randall's camouflage flicker
    camouflageOpacity = 50 + p.sin(time * 3) * 20 + watchingIntensity * 100;
    camouflageOpacity = p.constrain(camouflageOpacity, 30, 200);

    // Randall's body - lizard-like silhouette
    p.fill(80, 40, 120, camouflageOpacity);
    p.noStroke();

    // Main body
    p.ellipse(randallPos.x, randallPos.y, 80, 120);

    // Head
    p.ellipse(randallPos.x, randallPos.y - 60, 60, 70);

    // Legs (crouched, ready to pounce)
    p.ellipse(randallPos.x - 30, randallPos.y + 40, 25, 60);
    p.ellipse(randallPos.x + 30, randallPos.y + 40, 25, 60);

    // Arms
    p.ellipse(randallPos.x - 35, randallPos.y - 20, 20, 50);
    p.ellipse(randallPos.x + 35, randallPos.y - 20, 20, 50);

    // Tail (curved and menacing)
    p.push();
    p.translate(randallPos.x, randallPos.y + 50);
    p.rotate(p.sin(time) * 0.3);
    p.ellipse(20, 20, 15, 80);
    p.pop();

    // Glowing eyes that track mouse
    eyeGlow = 100 + p.sin(time * 2) * 50 + watchingIntensity * 100;

    // Eye direction follows mouse subtly
    let eyeOffsetX = p.map(p.mouseX, 0, p.width, -5, 5);
    let eyeOffsetY = p.map(p.mouseY, 0, p.height, -3, 3);

    // Eye glow
    p.fill(255, 100, 150, eyeGlow * 0.5);
    p.ellipse(randallPos.x - 15 + eyeOffsetX, randallPos.y - 65 + eyeOffsetY, 20, 20);
    p.ellipse(randallPos.x + 15 + eyeOffsetX, randallPos.y - 65 + eyeOffsetY, 20, 20);

    // Pupils
    p.fill(255, 50, 100, eyeGlow);
    p.ellipse(randallPos.x - 15 + eyeOffsetX, randallPos.y - 65 + eyeOffsetY, 8, 8);
    p.ellipse(randallPos.x + 15 + eyeOffsetX, randallPos.y - 65 + eyeOffsetY, 8, 8);

    // Scheming calculation lines (like thought processes)
    if (watchingIntensity > 0.3) {
      p.stroke(100, 60, 140, 80 * watchingIntensity);
      p.strokeWeight(1);

      for (let i = 0; i < 5; i++) {
        let lineX = randallPos.x + p.sin(time + i) * 60;
        let lineY = randallPos.y - 100 + i * 15;
        p.line(lineX, lineY, lineX + 30, lineY - 10);
      }
    }

    // Corporate environment hints - geometric shapes representing the corporate world
    p.fill(60, 80, 100, 40);
    p.noStroke();

    // Factory/office silhouettes in background
    for (let i = 0; i < 3; i++) {
      let buildingX = i * 150 + 50;
      p.rect(buildingX, p.height - 150, 80, 150);

      // Windows
      p.fill(80, 100, 120, 60);
      for (let row = 0; row < 4; row++) {
        for (let col = 0; col < 3; col++) {
          p.rect(buildingX + col * 20 + 10, p.height - 140 + row * 30, 15, 20);
        }
      }
      p.fill(60, 80, 100, 40);
    }

    // Subtle camouflage pattern that flickers
    if (p.frameCount % 60 < 30) {
      p.fill(40, 80, 60, camouflageOpacity * 0.3);
      p.ellipse(randallPos.x - 20, randallPos.y - 20, 30, 40);
      p.ellipse(randallPos.x + 15, randallPos.y + 10, 25, 35);
    }

    // Interactive shadow expansion on click
    if (p.mouseIsPressed) {
      p.fill(0, 0, 0, 30);
      p.ellipse(randallPos.x, randallPos.y + 60, 200 + p.sin(time * 5) * 50, 40);
    }
  };
}

function sketch(p) {
  let particles = [];
  let shadowPulse = 0;
  let extractor = { y: 0, visible: false };
  let waternooseEyes = { glow: 0 };
  let mousePressed = false;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize shadow particles
    for (let i = 0; i < 20; i++) {
      particles.push({
        x: p.random(200, 400),
        y: p.random(400, 580),
        size: p.random(3, 8),
        alpha: p.random(50, 150),
        speed: p.random(0.5, 2)
      });
    }
  };

  p.draw = function() {
    // Corporate gradient background
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(30, 50, 80), p.color(10, 15, 25), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    shadowPulse += 0.02;

    // Office environment - corporate aesthetic
    drawOffice();

    // Hidden scream extractor shadows
    drawHiddenThreat();

    // Waternoose figure
    drawWaternoose();

    // Dynamic shadow particles
    updateParticles();

    // Interactive elements
    handleInteraction();
  };

  function drawOffice() {
    // Desk silhouette
    p.fill(20, 30, 45);
    p.noStroke();
    p.rect(50, 350, 300, 80);

    // Corporate logo/emblem on wall
    p.fill(60, 90, 120, 100);
    p.ellipse(200, 150, 80, 80);
    p.fill(40, 70, 100, 150);
    p.ellipse(200, 150, 60, 60);

    // Window frames suggesting corporate power
    p.stroke(40, 60, 90);
    p.strokeWeight(4);
    p.noFill();
    p.rect(20, 80, 100, 120);
    p.rect(280, 80, 100, 120);

    // Subtle grid pattern for corporate aesthetic
    p.stroke(25, 35, 50, 50);
    p.strokeWeight(1);
    for (let x = 0; x < p.width; x += 40) {
      p.line(x, 0, x, 300);
    }
    for (let y = 0; y < 300; y += 40) {
      p.line(0, y, p.width, y);
    }
  }

  function drawHiddenThreat() {
    // Scream extractor shadow rising from below
    let extractorAlpha = p.map(p.sin(shadowPulse), -1, 1, 20, 80);

    // Mouse interaction reveals more of the threat
    if (p.mouseY > 400) {
      extractorAlpha += 40;
    }

    p.fill(80, 20, 20, extractorAlpha);
    p.noStroke();

    // Mechanical arms/extractors emerging from shadows
    for (let i = 0; i < 3; i++) {
      let x = 150 + i * 50;
      let y = 500 + p.sin(shadowPulse + i) * 20;

      // Extractor arm
      p.rect(x - 5, y, 10, 80);

      // Claw/grabber
      p.ellipse(x, y, 20, 15);
      p.rect(x - 8, y - 5, 6, 10);
      p.rect(x + 2, y - 5, 6, 10);
    }

    // Energy tubes/pipes
    p.stroke(100, 30, 30, extractorAlpha);
    p.strokeWeight(8);
    p.noFill();
    p.beginShape();
    p.vertex(120, 580);
    p.vertex(140, 520);
    p.vertex(180, 540);
    p.vertex(220, 510);
    p.vertex(260, 530);
    p.vertex(280, 580);
    p.endShape();
  }

  function drawWaternoose() {
    p.push();
    p.translate(200, 280);

    // Body silhouette - imposing and bulky
    p.fill(40, 60, 90);
    p.noStroke();
    p.ellipse(0, 40, 120, 100);

    // Multiple legs creating spider-like silhouette
    for (let i = 0; i < 6; i++) {
      let angle = p.map(i, 0, 6, -p.PI/3, p.PI/3);
      let legX = p.cos(angle) * 60;
      let legY = 80 + p.sin(angle) * 20;

      p.strokeWeight(8);
      p.stroke(30, 45, 70);
      p.line(0, 60, legX, legY);

      // Leg segments
      p.strokeWeight(6);
      p.line(legX, legY, legX + p.cos(angle) * 30, legY + 40);
    }

    // Head/face area
    p.fill(50, 70, 100);
    p.noStroke();
    p.ellipse(0, -10, 80, 70);

    // Eyes with sinister glow
    waternooseEyes.glow = p.map(p.sin(shadowPulse * 2), -1, 1, 100, 255);

    // Mouse interaction makes eyes more menacing
    if (p.mouseX > 150 && p.mouseX < 250 && p.mouseY > 200 && p.mouseY < 320) {
      waternooseEyes.glow = 255;
    }

    p.fill(waternooseEyes.glow, 50, 50, 200);
    p.ellipse(-15, -15, 12, 12);
    p.ellipse(15, -15, 12, 12);

    // Authority symbol/badge
    p.fill(120, 100, 60, 150);
    p.rect(-20, 20, 40, 20, 5);

    p.pop();
  }

  function updateParticles() {
    for (let particle of particles) {
      // Floating shadow particles
      particle.y -= particle.speed;
      particle.x += p.sin(p.frameCount * 0.01 + particle.y * 0.01) * 0.5;

      if (particle.y < 400) {
        particle.y = 580;
        particle.x = p.random(200, 400);
      }

      p.fill(20, 10, 10, particle.alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }
  }

  function handleInteraction() {
    // Mouse hover reveals more corruption
    if (p.mouseY > p.height * 0.6) {
      // Reveal more of the hidden machinery
      p.fill(100, 20, 20, 30);
      p.noStroke();
      p.rect(0, p.height * 0.7, p.width, p.height * 0.3);

      // Warning lights
      let flash = p.sin(p.frameCount * 0.3) > 0.5 ? 100 : 20;
      p.fill(255, 50, 50, flash);
      p.ellipse(50, p.height - 50, 20);
      p.ellipse(p.width - 50, p.height - 50, 20);
    }
  }

  p.mousePressed = function() {
    // Click interaction - momentary revelation
    for (let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        size: p.random(2, 6),
        alpha: p.random(100, 200),
        speed: p.random(1, 3)
      });
    }
  };
}

function sketch(p) {
  let doorX, doorY, doorWidth, doorHeight;
  let glowIntensity = 0;
  let glowDirection = 1;
  let energyParticles = [];
  let doorOpenness = 0;
  let mouseInfluence = 0;
  let floorTiles = [];
  let lightBeams = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Door properties
    doorX = p.width / 2 - 60;
    doorY = p.height / 2 - 80;
    doorWidth = 120;
    doorHeight = 160;

    // Initialize floor tiles
    for (let x = 0; x < p.width + 40; x += 40) {
      for (let y = p.height - 100; y < p.height; y += 40) {
        floorTiles.push({x: x, y: y, brightness: p.random(20, 40)});
      }
    }

    // Initialize energy particles
    for (let i = 0; i < 30; i++) {
      energyParticles.push({
        x: p.random(doorX - 50, doorX + doorWidth + 50),
        y: p.random(doorY - 50, doorY + doorHeight + 50),
        size: p.random(2, 8),
        speed: p.random(0.5, 2),
        angle: p.random(p.TWO_PI),
        color: p.color(p.random(100, 255), p.random(150, 255), p.random(200, 255), 150)
      });
    }

    // Initialize light beams
    for (let i = 0; i < 5; i++) {
      lightBeams.push({
        angle: p.random(p.PI * 0.2, p.PI * 0.8),
        intensity: p.random(30, 80),
        width: p.random(15, 30)
      });
    }
  };

  p.draw = function() {
    // Dark scare floor background
    p.background(15, 18, 25);

    // Calculate mouse influence
    let distToDoor = p.dist(p.mouseX, p.mouseY, doorX + doorWidth/2, doorY + doorHeight/2);
    mouseInfluence = p.map(distToDoor, 0, 200, 1, 0);
    mouseInfluence = p.constrain(mouseInfluence, 0, 1);

    // Animate glow intensity
    glowIntensity += 0.02 * glowDirection;
    if (glowIntensity > 1 || glowIntensity < 0.3) {
      glowDirection *= -1;
    }

    // Draw floor tiles with corporate aesthetic
    p.fill(35, 40, 50);
    p.stroke(45, 50, 60);
    p.strokeWeight(1);
    for (let tile of floorTiles) {
      let tileBrightness = tile.brightness + mouseInfluence * 20;
      p.fill(tileBrightness, tileBrightness + 5, tileBrightness + 10);
      p.rect(tile.x - 20, tile.y - 20, 40, 40);
    }

    // Draw atmospheric light beams from door
    let beamOpacity = (glowIntensity + mouseInfluence) * 40;
    for (let beam of lightBeams) {
      p.push();
      p.translate(doorX + doorWidth/2, doorY + doorHeight);
      p.rotate(beam.angle);

      let gradient = p.drawingContext.createLinearGradient(0, 0, 0, -300);
      gradient.addColorStop(0, `rgba(100, 200, 255, ${beamOpacity/255})`);
      gradient.addColorStop(1, `rgba(100, 200, 255, 0)`);

      p.drawingContext.fillStyle = gradient;
      p.noStroke();
      p.beginShape();
      p.vertex(-beam.width/2, 0);
      p.vertex(beam.width/2, 0);
      p.vertex(beam.width * 1.5, -300);
      p.vertex(-beam.width * 1.5, -300);
      p.endShape(p.CLOSE);
      p.pop();
    }

    // Draw door frame (corporate/industrial)
    p.fill(60, 65, 75);
    p.stroke(80, 85, 95);
    p.strokeWeight(3);
    p.rect(doorX - 10, doorY - 10, doorWidth + 20, doorHeight + 20, 5);

    // Door inner glow
    let glowSize = (glowIntensity + mouseInfluence * 0.5) * 80;
    let glowColor = p.color(120, 200, 255, 80);

    for (let i = 0; i < 5; i++) {
      p.fill(p.red(glowColor), p.green(glowColor), p.blue(glowColor), 20 - i * 4);
      p.noStroke();
      p.rect(doorX - i * 2, doorY - i * 2, doorWidth + i * 4, doorHeight + i * 4, 3);
    }

    // Main door surface
    doorOpenness = mouseInfluence * 15;
    let doorColor = p.lerpColor(
      p.color(40, 45, 55),
      p.color(80, 120, 160),
      glowIntensity
    );

    p.fill(doorColor);
    p.stroke(100 + glowIntensity * 50, 150 + glowIntensity * 50, 200 + glowIntensity * 55);
    p.strokeWeight(2);

    // Door slightly ajar effect
    p.beginShape();
    p.vertex(doorX + doorOpenness, doorY);
    p.vertex(doorX + doorWidth, doorY);
    p.vertex(doorX + doorWidth, doorY + doorHeight);
    p.vertex(doorX + doorOpenness, doorY + doorHeight);
    p.endShape(p.CLOSE);

    // Light spilling from crack
    if (doorOpenness > 2) {
      let crackGradient = p.drawingContext.createLinearGradient(doorX, 0, doorX + doorOpenness, 0);
      crackGradient.addColorStop(0, `rgba(200, 230, 255, ${mouseInfluence * 150})`);
      crackGradient.addColorStop(1, 'rgba(200, 230, 255, 0)');

      p.drawingContext.fillStyle = crackGradient;
      p.noStroke();
      p.rect(doorX, doorY, doorOpenness, doorHeight);
    }

    // Door handle
    p.fill(120 + glowIntensity * 30, 120 + glowIntensity * 30, 130 + glowIntensity * 40);
    p.stroke(140, 140, 150);
    p.strokeWeight(1);
    p.ellipse(doorX + doorWidth - 20, doorY + doorHeight/2, 8, 8);

    // Energy particles
    for (let particle of energyParticles) {
      particle.x += p.cos(particle.angle) * particle.speed * (1 + mouseInfluence);
      particle.y += p.sin(particle.angle) * particle.speed * (1 + mouseInfluence);
      particle.angle += 0.02;

      // Attract particles to door when mouse is near
      if (mouseInfluence > 0.3) {
        let attractX = (doorX + doorWidth/2 - particle.x) * 0.01 * mouseInfluence;
        let attractY = (doorY + doorHeight/2 - particle.y) * 0.01 * mouseInfluence;
        particle.x += attractX;
        particle.y += attractY;
      }

      // Reset particles that drift too far
      if (particle.x < -50 || particle.x > p.width + 50 || particle.y < -50 || particle.y > p.height + 50) {
        particle.x = p.random(doorX - 50, doorX + doorWidth + 50);
        particle.y = p.random(doorY - 50, doorY + doorHeight + 50);
      }

      p.fill(particle.color);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size * (1 + mouseInfluence * 0.5));
    }

    // Mysterious threshold shimmer
    p.push();
    p.blendMode(p.SCREEN);
    let shimmerAlpha = p.sin(p.frameCount * 0.05) * 30 + 50;
    p.fill(150, 200, 255, shimmerAlpha * (glowIntensity + mouseInfluence));
    p.noStroke();
    p.rect(doorX + doorOpenness, doorY + 10, 2, doorHeight - 20);
    p.pop();

    // Subtle shadow beneath door
    p.fill(0, 0, 0, 60);
    p.noStroke();
    p.ellipse(doorX + doorWidth/2, doorY + doorHeight + 5, doorWidth * 1.2, 20);
  };

  p.mousePressed = function() {
    // Add burst of particles on click
    for (let i = 0; i < 10; i++) {
      energyParticles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        size: p.random(3, 12),
        speed: p.random(1, 3),
        angle: p.random(p.TWO_PI),
        color: p.color(p.random(150, 255), p.random(200, 255), 255, 200)
      });
    }
  };
}

function sketch(p) {
  let doorX, doorY, doorWidth, doorHeight;
  let booX, booY, booSize;
  let sulleyX, sulleyY;
  let particles = [];
  let glowIntensity = 0;
  let reachAmount = 0;
  let doorOpenAmount = 0;
  let sparkles = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Door positioned in upper portion
    doorX = 180;
    doorY = 120;
    doorWidth = 80;
    doorHeight = 120;

    // Boo positioned emerging from door
    booX = doorX + doorWidth/2;
    booY = doorY + doorHeight - 20;
    booSize = 25;

    // Sulley positioned lower right, large silhouette
    sulleyX = 280;
    sulleyY = 350;

    // Create initial sparkles
    for(let i = 0; i < 15; i++) {
      sparkles.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        size: p.random(2, 6),
        alpha: p.random(50, 150),
        speed: p.random(0.5, 1.5)
      });
    }
  };

  p.draw = function() {
    // Gradient background - warm corporate to intimate
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(25, 35, 60), p.color(40, 25, 35), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Animated values
    glowIntensity = p.sin(p.millis() * 0.003) * 30 + 50;
    reachAmount = p.sin(p.millis() * 0.002) * 10;
    doorOpenAmount = p.map(p.mouseX, 0, p.width, 0, 25);

    // Door frame with corporate aesthetic
    p.fill(45, 45, 55);
    p.noStroke();
    p.rect(doorX - 10, doorY - 10, doorWidth + 20, doorHeight + 20, 5);

    // Door opening with warm light
    p.fill(255, 220, 120, 180);
    p.rect(doorX - doorOpenAmount/2, doorY, doorWidth + doorOpenAmount, doorHeight, 3);

    // Light rays emanating from door
    p.stroke(255, 240, 150, 80);
    p.strokeWeight(2);
    for(let i = 0; i < 8; i++) {
      let angle = p.map(i, 0, 7, -p.PI/4, p.PI/4);
      let rayLength = 100 + p.sin(p.millis() * 0.004 + i) * 20;
      p.line(booX, booY, 
             booX + p.cos(angle + p.PI/2) * rayLength,
             booY + p.sin(angle + p.PI/2) * rayLength);
    }

    // Boo's silhouette - small, innocent, reaching
    p.noStroke();
    p.fill(255, 200, 180, 200 + glowIntensity * 0.5);

    // Boo's body
    p.ellipse(booX, booY, booSize, booSize * 1.2);

    // Boo's head
    p.ellipse(booX, booY - booSize * 0.8, booSize * 0.8, booSize * 0.8);

    // Boo's reaching arm
    let armX = booX + booSize/2 + reachAmount;
    let armY = booY - booSize/4;
    p.ellipse(armX, armY, 8, 15);
    p.ellipse(armX + 8, armY, 6, 6); // hand

    // Trust particles emanating from Boo toward Sulley
    if(p.frameCount % 8 == 0) {
      particles.push({
        x: booX,
        y: booY,
        targetX: sulleyX,
        targetY: sulleyY,
        life: 1.0,
        size: p.random(2, 5)
      });
    }

    // Update and draw trust particles
    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x = p.lerp(particle.x, particle.targetX, 0.02);
      particle.y = p.lerp(particle.y, particle.targetY, 0.02);
      particle.life -= 0.015;

      if(particle.life <= 0) {
        particles.splice(i, 1);
      } else {
        p.fill(255, 180, 200, particle.life * 150);
        p.ellipse(particle.x, particle.y, particle.size * particle.life);
      }
    }

    // Sulley's silhouette - large, protective presence
    p.fill(80, 120, 160, 180);

    // Sulley's body
    p.ellipse(sulleyX, sulleyY, 90, 110);

    // Sulley's head
    p.ellipse(sulleyX, sulleyY - 80, 70, 65);

    // Sulley's horns
    p.fill(60, 90, 120);
    p.ellipse(sulleyX - 20, sulleyY - 105, 8, 15);
    p.ellipse(sulleyX + 20, sulleyY - 105, 8, 15);

    // Sulley's arms - one reaching back toward Boo
    p.fill(80, 120, 160, 160);
    p.ellipse(sulleyX - 45, sulleyY - 30, 25, 40);
    p.ellipse(sulleyX + 45, sulleyY - 30, 25, 40);

    // Connection glow between Boo and Sulley
    let distance = p.dist(booX, booY, sulleyX, sulleyY);
    p.stroke(255, 200, 220, 60);
    p.strokeWeight(3);
    p.line(booX, booY, sulleyX, sulleyY);

    // Environmental sparkles
    p.noStroke();
    for(let sparkle of sparkles) {
      sparkle.y += sparkle.speed;
      sparkle.alpha = p.sin(p.millis() * 0.005 + sparkle.x) * 50 + 100;

      if(sparkle.y > p.height) {
        sparkle.y = -10;
        sparkle.x = p.random(50, 350);
      }

      p.fill(255, 240, 180, sparkle.alpha);
      p.ellipse(sparkle.x, sparkle.y, sparkle.size);
    }

    // Interactive glow on mouse proximity to Boo
    let mouseDistance = p.dist(p.mouseX, p.mouseY, booX, booY);
    if(mouseDistance < 80) {
      let glowSize = p.map(mouseDistance, 0, 80, 60, 20);
      p.fill(255, 220, 180, 40);
      p.ellipse(booX, booY, glowSize);
    }

    // Moment of first contact emphasis
    if(p.mouseIsPressed) {
      p.fill(255, 255, 255, 30);
      p.ellipse(p.width/2, p.height/2, p.width * 2, p.height * 2);
    }
  };
}

function sketch(p) {
  let particles = [];
  let handProgress = 0;
  let revelationGlow = 0;
  let eyeGlow = 0;
  let beliefFragments = [];
  let touchMoment = false;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize belief fragments - representing shattering assumptions
    for (let i = 0; i < 15; i++) {
      beliefFragments.push({
        x: p.random(50, 350),
        y: p.random(100, 300),
        vx: p.random(-2, 2),
        vy: p.random(-1, 3),
        size: p.random(8, 25),
        alpha: 255,
        rotation: p.random(p.TWO_PI),
        rotSpeed: p.random(-0.1, 0.1)
      });
    }

    // Initialize warm particles for the moment of discovery
    for (let i = 0; i < 30; i++) {
      particles.push({
        x: 200,
        y: 350,
        vx: p.random(-0.5, 0.5),
        vy: p.random(-2, 0),
        life: 255,
        size: p.random(2, 6)
      });
    }
  };

  p.draw = function() {
    // Dark background with subtle corporate blues fading to warm discovery
    p.background(15, 25, 45);

    // Create gradient background - corporate to warm
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(45, 35, 55), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Animate hand reaching progress
    handProgress += 0.008;
    if (handProgress > 1) handProgress = 1;

    // Check for touch moment
    if (handProgress > 0.7 && !touchMoment) {
      touchMoment = true;
      revelationGlow = 255;
    }

    // Draw Sulley's massive silhouette
    p.push();
    p.translate(80, 150);
    p.fill(50, 80, 140, 180);
    p.noStroke();

    // Sulley's body
    p.ellipse(0, 200, 180, 280);

    // Sulley's head
    p.ellipse(0, 50, 140, 120);

    // Sulley's distinctive horns
    p.triangle(-30, 0, -40, -30, -20, -10);
    p.triangle(30, 0, 40, -30, 20, -10);

    // Sulley's eye area with growing realization
    eyeGlow = p.lerp(eyeGlow, touchMoment ? 255 : 100, 0.02);
    p.fill(255, 255, 180, eyeGlow * 0.8);
    p.ellipse(-15, 40, 25, 35);
    p.ellipse(15, 40, 25, 35);

    // Eye pupils showing surprise/wonder
    p.fill(20, 20, 50);
    p.ellipse(-15, 45, 8, 12);
    p.ellipse(15, 45, 8, 12);

    p.pop();

    // Draw Sulley's reaching hand
    p.push();
    p.translate(200, 300);

    let handX = p.lerp(-50, 20, p.easeInOutCubic(handProgress));
    let handY = p.lerp(0, 50, p.easeInOutCubic(handProgress));

    p.fill(70, 100, 160);
    p.noStroke();

    // Arm
    p.ellipse(handX - 40, handY - 20, 60, 35);

    // Hand
    p.ellipse(handX, handY, 45, 35);

    // Fingers
    for (let i = 0; i < 4; i++) {
      let fingerX = handX + (i - 1.5) * 8;
      let fingerY = handY + 15;
      p.ellipse(fingerX, fingerY, 6, 20);
    }

    p.pop();

    // Draw Boo as small, innocent silhouette
    p.push();
    p.translate(240, 380);
    p.fill(255, 220, 180, 200);
    p.noStroke();

    // Boo's tiny body
    p.ellipse(0, 20, 30, 40);

    // Boo's head
    p.ellipse(0, 0, 25, 25);

    // Boo's characteristic hair tufts
    p.ellipse(-8, -10, 6, 12);
    p.ellipse(0, -12, 8, 10);
    p.ellipse(8, -10, 6, 12);

    // Boo's tiny hand reaching up
    p.ellipse(8, 15, 8, 8);

    p.pop();

    // The moment of contact - revelation glow
    if (touchMoment) {
      revelationGlow *= 0.98;

      p.push();
      p.translate(225, 350);

      // Warm, golden revelation light
      for (let r = 80; r > 0; r -= 10) {
        p.fill(255, 200, 100, revelationGlow * 0.3 * (1 - r/80));
        p.noStroke();
        p.ellipse(0, 0, r, r);
      }

      // Connection sparkles
      for (let i = 0; i < 8; i++) {
        let angle = p.frameCount * 0.05 + i * p.PI/4;
        let x = p.cos(angle) * 40;
        let y = p.sin(angle) * 40;
        p.fill(255, 255, 180, revelationGlow * 0.6);
        p.ellipse(x, y, 4, 4);
      }

      p.pop();
    }

    // Animate belief fragments shattering
    if (touchMoment) {
      for (let i = beliefFragments.length - 1; i >= 0; i--) {
        let frag = beliefFragments[i];

        frag.x += frag.vx;
        frag.y += frag.vy;
        frag.vy += 0.1; // gravity
        frag.alpha -= 2;
        frag.rotation += frag.rotSpeed;

        p.push();
        p.translate(frag.x, frag.y);
        p.rotate(frag.rotation);

        // Corporate blue fragments dissolving
        p.fill(100, 120, 180, frag.alpha * 0.7);
        p.noStroke();
        p.rect(-frag.size/2, -frag.size/2, frag.size, frag.size/3);

        p.pop();

        if (frag.alpha <= 0) {
          beliefFragments.splice(i, 1);
        }
      }
    }

    // Update and draw discovery particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let part = particles[i];

      if (touchMoment) {
        part.x += part.vx;
        part.y += part.vy;
        part.life -= 3;

        p.fill(255, 220, 150, part.life);
        p.noStroke();
        p.ellipse(part.x, part.y, part.size, part.size);

        if (part.life <= 0) {
          particles.splice(i, 1);
          // Replenish particles
          if (particles.length < 20) {
            particles.push({
              x: 225 + p.random(-10, 10),
              y: 350 + p.random(-10, 10),
              vx: p.random(-1, 1),
              vy: p.random(-2, 0),
              life: 255,
              size: p.random(2, 6)
            });
          }
        }
      }
    }

    // Interactive mouse glow effect
    let mouseDist = p.dist(p.mouseX, p.mouseY, 225, 350);
    if (mouseDist < 100) {
      p.push();
      p.translate(225, 350);
      let glowIntensity = p.map(mouseDist, 0, 100, 100, 0);
      p.fill(255, 255, 200, glowIntensity * 0.3);
      p.noStroke();
      p.ellipse(0, 0, 150, 150);
      p.pop();
    }
  };

  p.easeInOutCubic = function(t) {
    return t < 0.5 ? 4 * t * t * t : (t - 1) * (2 * t - 2) * (2 * t - 2) + 1;
  };

  p.mousePressed = function() {
    // Reset animation on click
    if (p.mouseX >= 0 && p.mouseX <= p.width && p.mouseY >= 0 && p.mouseY <= p.height) {
      handProgress = 0;
      touchMoment = false;
      revelationGlow = 0;
      eyeGlow = 0;

      // Reset belief fragments
      beliefFragments = [];
      for (let i = 0; i < 15; i++) {
        beliefFragments.push({
          x: p.random(50, 350),
          y: p.random(100, 300),
          vx: p.random(-2, 2),
          vy: p.random(-1, 3),
          size: p.random(8, 25),
          alpha: 255,
          rotation: p.random(p.TWO_PI),
          rotSpeed: p.random(-0.1, 0.1)
        });
      }
    }
  };
}

function sketch(p) {
  let doorOffset = 0;
  let doorSpeed = 0.02;
  let shadowIntensity = 0;
  let vigilanceLevel = 0;
  let particles = [];
  let stressLines = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize stress lines
    for(let i = 0; i < 15; i++) {
      stressLines.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        length: p.random(5, 20),
        angle: p.random(p.TWO_PI),
        opacity: p.random(0.3, 0.8)
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Background - corporate sterile environment with tension
    let bgColor1 = p.color(25, 35, 65);
    let bgColor2 = p.color(45, 55, 85);

    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(bgColor1, bgColor2, inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Mouse interaction affects vigilance and shadow intensity
    let mouseDistance = p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2);
    vigilanceLevel = p.map(mouseDistance, 0, 300, 1, 0.3);
    shadowIntensity = p.map(p.mouseY, 0, p.height, 0.8, 0.3);

    // Corporate corridor elements
    p.stroke(100, 120, 150);
    p.strokeWeight(2);
    p.noFill();

    // Perspective lines suggesting industrial corridor
    for(let i = 0; i < 5; i++) {
      let y = 150 + i * 80;
      p.line(50, y, 350, y + 20);
    }

    // Doors along corridor (corporate Screams aesthetic)
    doorOffset = p.sin(time * doorSpeed) * 5;

    for(let i = 0; i < 4; i++) {
      let doorX = 80 + i * 70;
      let doorY = 200 + i * 15;

      p.fill(60, 70, 100);
      p.stroke(80, 90, 120);
      p.rect(doorX + doorOffset, doorY, 40, 60);

      // Door handles
      p.fill(120, 130, 150);
      p.noStroke();
      p.ellipse(doorX + 35 + doorOffset, doorY + 30, 4, 4);
    }

    // Shadowy areas (dread aesthetic)
    p.fill(0, 0, 0, shadowIntensity * 100);
    p.noStroke();
    p.ellipse(100, 400, 120, 60);
    p.ellipse(300, 350, 90, 45);

    // Sulley's silhouette (large, protective figure)
    p.push();
    p.translate(200, 350);

    // Body - blue monster silhouette
    p.fill(40, 80, 140, 200);
    p.noStroke();
    p.ellipse(0, 20, 120, 140);

    // Sulley's distinctive horns
    p.fill(35, 70, 120);
    p.ellipse(-15, -40, 12, 20);
    p.ellipse(15, -40, 12, 20);

    // Head
    p.fill(45, 85, 145, 220);
    p.ellipse(0, -10, 80, 70);

    // Eyes showing stress and vigilance
    let eyeShake = vigilanceLevel * 2;
    p.fill(255, 255, 255, 180);
    p.ellipse(-12 + p.random(-eyeShake, eyeShake), -15, 15, 15);
    p.ellipse(12 + p.random(-eyeShake, eyeShake), -15, 15, 15);

    p.fill(20, 20, 20);
    p.ellipse(-12, -15, 8, 8);
    p.ellipse(12, -15, 8, 8);

    // Protective posture - arms curved around
    p.fill(35, 75, 135, 180);
    p.ellipse(-45, 0, 25, 80);
    p.ellipse(45, 0, 25, 80);

    p.pop();

    // Boo hidden in disguise (Hearts aesthetic - warm, intimate)
    p.push();
    p.translate(200, 320);

    // Monster costume disguise
    p.fill(80, 40, 120, 150);
    p.ellipse(0, 0, 40, 50);

    // Fake monster features
    p.fill(100, 50, 140);
    p.ellipse(-8, -10, 6, 8);
    p.ellipse(8, -10, 6, 8);

    // Hint of human child underneath (warm pink glow)
    p.fill(255, 200, 180, 60 + p.sin(time * 3) * 20);
    p.noStroke();
    p.ellipse(0, 5, 25, 25);

    p.pop();

    // Stress visualization lines
    p.stroke(255, 150, 100, 100);
    p.strokeWeight(1);

    for(let line of stressLines) {
      let intensity = vigilanceLevel * line.opacity;
      p.stroke(255, 150, 100, intensity * 255);

      let x1 = line.x + p.cos(line.angle + time) * 5;
      let y1 = line.y + p.sin(line.angle + time) * 5;
      let x2 = x1 + p.cos(line.angle) * line.length;
      let y2 = y1 + p.sin(line.angle) * line.length;

      p.line(x1, y1, x2, y2);
    }

    // Security cameras (corporate surveillance)
    p.fill(150, 50, 50);
    p.noStroke();
    p.ellipse(50, 100, 8, 8);
    p.ellipse(350, 120, 8, 8);

    // Scanning light beams
    p.stroke(200, 80, 80, 50 + p.sin(time * 4) * 30);
    p.strokeWeight(2);
    p.line(50, 100, 200, 250);
    p.line(350, 120, 200, 280);

    // Warning signs and corporate elements
    p.fill(200, 180, 50, 150);
    p.noStroke();
    p.rect(20, 50, 60, 30);
    p.rect(320, 70, 60, 30);

    p.fill(50, 50, 50);
    p.textAlign(p.CENTER, p.CENTER);
    p.textSize(8);
    p.text("RESTRICTED", 50, 65);
    p.text("AUTHORIZED", 350, 85);

    // Click interaction - momentary exposure/danger
    if(p.mouseIsPressed) {
      p.fill(255, 100, 100, 100);
      p.noStroke();
      p.rect(0, 0, p.width, p.height);

      // Alarm state - Boo more visible
      p.push();
      p.translate(200, 320);
      p.fill(255, 200, 180, 150);
      p.ellipse(0, 5, 35, 35);
      p.pop();
    }

    // Subtle energy particles (transformation theme)
    if(particles.length < 30) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        life: 255
      });
    }

    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 2;

      p.fill(150, 200, 255, particle.life * 0.3);
      p.noStroke();
      p.ellipse(particle.x, particle.y, 3, 3);

      if(particle.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Split existence visual metaphor
    p.stroke(255, 255, 255, 30);
    p.strokeWeight(1);
    p.line(p.width/2, 0, p.width/2, p.height);
  };
}

function sketch(p) {
