      x: 250,
      y: 350,
      size: 180,
      eyeBlink: 0,
      breathe: 0
    };

    boo = {
      x: 220,
      y: 280,
      size: 60,
      giggle: 0,
      bounce: 0
    };

    for(let i = 0; i < 15; i++) {
      sparkles.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        size: p.random(2, 6),
        alpha: p.random(100, 255),
        speed: p.random(0.5, 2)
      });
    }
  };

  p.draw = function() {
    // Intimate Hearts background - soft, warm gradient
    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(25, 15, 45), p.color(60, 30, 80), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Animated sparkles for magical atmosphere
    for(let sparkle of sparkles) {
      p.fill(255, 220, 150, sparkle.alpha);
      p.noStroke();
      p.ellipse(sparkle.x, sparkle.y, sparkle.size);

      sparkle.y -= sparkle.speed;
      sparkle.alpha -= 1;

      if(sparkle.y < 0 || sparkle.alpha < 0) {
        sparkle.y = p.height + 10;
        sparkle.x = p.random(50, 350);
        sparkle.alpha = p.random(100, 255);
      }
    }

    // Heart glow animation
    heartGlow = p.sin(p.frameCount * 0.05) * 30 + 50;
    handAnimPhase = p.sin(p.frameCount * 0.03) * 0.3;

    // Sulley's breathing animation
    sulley.breathe = p.sin(p.frameCount * 0.04) * 5;
    sulley.eyeBlink = p.max(0, p.sin(p.frameCount * 0.1) * 20 - 15);

    // Boo's gentle bounce
    boo.bounce = p.sin(p.frameCount * 0.06) * 8;
    boo.giggle = p.sin(p.frameCount * 0.08) * 3;

    p.push();
    p.translate(0, sulley.breathe);

    // Sulley's body - large, gentle blue monster
    p.fill(80, 150, 200);
    p.noStroke();
    p.ellipse(sulley.x, sulley.y, sulley.size, sulley.size * 0.9);

    // Sulley's spots
    p.fill(60, 100, 150);
    for(let i = 0; i < 8; i++) {
      let angle = (p.TWO_PI / 8) * i;
      let spotX = sulley.x + p.cos(angle) * 40;
      let spotY = sulley.y + p.sin(angle) * 35;
      p.ellipse(spotX, spotY, p.random(15, 25));
    }

    // Sulley's arms
    p.fill(90, 160, 210);
    p.ellipse(sulley.x - 60, sulley.y + 20, 50, 80);
    p.ellipse(sulley.x + 60, sulley.y + 20, 50, 80);

    // Sulley's paw (extended toward Boo)
    p.push();
    p.translate(sulley.x - 80, sulley.y - 30 + handAnimPhase * 10);
    p.rotate(handAnimPhase);
    p.fill(100, 170, 220);
    p.ellipse(0, 0, 45, 35);

    // Paw pads
    p.fill(70, 120, 170);
    p.ellipse(-8, -5, 8, 6);
    p.ellipse(8, -5, 8, 6);
    p.ellipse(0, 8, 12, 8);
    p.pop();

    // Sulley's face
    p.fill(85, 155, 205);
    p.ellipse(sulley.x, sulley.y - 40, 120, 100);

    // Sulley's eyes
    p.fill(255);
    p.ellipse(sulley.x - 25, sulley.y - 50, 35, 40 - sulley.eyeBlink);
    p.ellipse(sulley.x + 25, sulley.y - 50, 35, 40 - sulley.eyeBlink);

    if(sulley.eyeBlink < 5) {
      p.fill(40, 80, 120);
      p.ellipse(sulley.x - 25, sulley.y - 50, 20, 25);
      p.ellipse(sulley.x + 25, sulley.y - 50, 20, 25);

      p.fill(0);
      p.ellipse(sulley.x - 25, sulley.y - 50, 8, 12);
      p.ellipse(sulley.x + 25, sulley.y - 50, 8, 12);
    }

    // Sulley's mouth (gentle smile)
    p.noFill();
    p.stroke(40, 80, 120);
    p.strokeWeight(3);
    p.arc(sulley.x, sulley.y - 25, 40, 20, 0, p.PI);

    p.pop();

    // Boo
    p.push();
    p.translate(0, boo.bounce);

    // Boo's body
    p.fill(255, 200, 180);
    p.noStroke();
    p.ellipse(boo.x, boo.y + 20, boo.size * 0.8, boo.size);

    // Boo's head
    p.fill(255, 210, 190);
    p.ellipse(boo.x, boo.y - 10, boo.size * 0.9, boo.size * 0.8);

    // Boo's hair
    p.fill(80, 40, 20);
    for(let i = 0; i < 6; i++) {
      let hairX = boo.x - 20 + i * 8;
      let hairY = boo.y - 35 + p.sin(i + p.frameCount * 0.1) * 3;
      p.ellipse(hairX, hairY, 8, 15);
    }

    // Boo's eyes
    p.fill(50, 30, 20);
    p.ellipse(boo.x - 12, boo.y - 15, 8, 10);
    p.ellipse(boo.x + 12, boo.y - 15, 8, 10);

    p.fill(255);
    p.ellipse(boo.x - 10, boo.y - 17, 3, 3);
    p.ellipse(boo.x + 14, boo.y - 17, 3, 3);

    // Boo's mouth (happy)
    p.noFill();
    p.stroke(150, 80, 60);
    p.strokeWeight(2);
    p.arc(boo.x, boo.y - 5, 15, 10, 0, p.PI);

    // Boo's small hand reaching toward Sulley's paw
    p.fill(255, 200, 180);
    p.noStroke();
    p.push();
    p.translate(boo.x - 35, boo.y - 5 + boo.giggle);
    p.rotate(-handAnimPhase * 0.5);
    p.ellipse(0, 0, 12, 8);
    p.pop();

    p.pop();

    // Connection visualization - heart glow between them
    let midX = (sulley.x + boo.x) / 2 - 20;
    let midY = (sulley.y + boo.y) / 2 - 20;

    p.push();
    p.translate(midX, midY);

    // Glowing heart effect
    for(let i = 3; i > 0; i--) {
      p.fill(255, 150, 200, heartGlow / i);
      p.noStroke();
      let size = i * 8;

      // Heart shape
      p.beginShape();
      for(let a = 0; a < p.TWO_PI; a += 0.1) {
        let x = 16 * p.pow(p.sin(a), 3) * size / 20;
        let y = -(13 * p.cos(a) - 5 * p.cos(2*a) - 2 * p.cos(3*a) - p.cos(4*a)) * size / 20;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);
    }
    p.pop();

    // Interactive particles on mouse movement
    if(p.dist(p.mouseX, p.mouseY, midX, midY) < 80) {
      if(p.random() < 0.3) {
        particles.push({
          x: midX + p.random(-30, 30),
          y: midY + p.random(-30, 30),
          vx: p.random(-2, 2),
          vy: p.random(-3, -1),
          life: 60,
          maxLife: 60
        });
      }
    }

    // Update and draw particles
    for(let i = particles.length - 1; i >= 0; i--) {
      let pt = particles[i];
      pt.x += pt.vx;
      pt.y += pt.vy;
      pt.life--;

      let alpha = p.map(pt.life, 0, pt.maxLife, 0, 255);
      p.fill(255, 200, 150, alpha);
      p.noStroke();
      p.ellipse(pt.x, pt.y, 4, 4);

      if(pt.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Card border with gentle glow
    p.noFill();
    p.stroke(200, 150, 255, 100);
    p.strokeWeight(2);
    p.rect(10, 10, p.width - 20, p.height - 20, 15);
  };
}

function sketch(p) {
  let cdaAgents = [];
  let alarmPulse = 0;
  let quarantineZones = [];
  let steamParticles = [];
  let sirenRotation = 0;
  let warningFlash = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize CDA agents
    for (let i = 0; i < 8; i++) {
      cdaAgents.push({
        x: p.random(50, 350),
        y: p.random(200, 500),
        size: p.random(25, 40),
        bobOffset: p.random(0, p.TWO_PI),
        sweepAngle: p.random(0, p.TWO_PI)
      });
    }

    // Initialize quarantine zones
    for (let i = 0; i < 5; i++) {
      quarantineZones.push({
        x: p.random(100, 300),
        y: p.random(150, 450),
        size: p.random(40, 80),
        opacity: p.random(0.3, 0.7)
      });
    }

    // Initialize steam particles
    for (let i = 0; i < 30; i++) {
      steamParticles.push({
        x: p.random(0, 400),
        y: p.random(400, 600),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-2, -0.5),
        life: p.random(0.5, 1.0)
      });
    }
  };

  p.draw = function() {
    // Dark corporate background with alarm lighting
    p.background(15, 20, 35);

    // Pulsing alarm overlay
    alarmPulse += 0.15;
    warningFlash += 0.2;
    let alarmIntensity = (p.sin(alarmPulse) + 1) * 0.5;
    p.fill(220, 50, 50, alarmIntensity * 40);
    p.rect(0, 0, 400, 600);

    // Restaurant floor tiles (corrupted)
    p.strokeWeight(1);
    p.stroke(80, 80, 100, 150);
    for (let x = 0; x < 400; x += 40) {
      for (let y = 350; y < 600; y += 40) {
        p.fill(25 + p.sin(x * 0.1 + alarmPulse) * 10, 30, 45);
        p.rect(x, y, 40, 40);
      }
    }

    // Quarantine zones (yellow hazard areas)
    for (let zone of quarantineZones) {
      let pulse = p.sin(alarmPulse * 1.5 + zone.x * 0.01) * 0.3 + 0.7;
      p.fill(255, 255, 0, zone.opacity * pulse * 100);
      p.noStroke();
      p.ellipse(zone.x, zone.y, zone.size * pulse, zone.size * pulse);

      // Hazard stripes
      p.strokeWeight(3);
      p.stroke(255, 200, 0, pulse * 200);
      for (let i = -zone.size; i < zone.size; i += 10) {
        p.line(zone.x + i, zone.y - zone.size/2, 
               zone.x + i + 20, zone.y + zone.size/2);
      }
    }

    // Steam/decontamination effect
    for (let i = steamParticles.length - 1; i >= 0; i--) {
      let particle = steamParticles[i];
      p.fill(200, 255, 200, particle.life * 150);
      p.noStroke();
      p.ellipse(particle.x, particle.y, 8, 8);

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 0.01;

      if (particle.life <= 0 || particle.y < 0) {
        steamParticles[i] = {
          x: p.random(0, 400),
          y: p.random(500, 650),
          vx: p.random(-0.5, 0.5),
          vy: p.random(-2, -0.5),
          life: p.random(0.5, 1.0)
        };
      }
    }

    // CDA agents in hazmat suits
    for (let agent of cdaAgents) {
      let bob = p.sin(alarmPulse * 2 + agent.bobOffset) * 3;
      let agentY = agent.y + bob;

      // Agent shadow
      p.fill(0, 0, 0, 80);
      p.noStroke();
      p.ellipse(agent.x, agent.y + agent.size/2 + 5, agent.size * 0.8, 10);

      // Hazmat suit body (yellow)
      p.fill(255, 220, 0);
      p.stroke(200, 180, 0);
      p.strokeWeight(2);
      p.ellipse(agent.x, agentY, agent.size, agent.size * 1.2);

      // Helmet/mask
      p.fill(100, 150, 100);
      p.stroke(80, 120, 80);
      p.ellipse(agent.x, agentY - agent.size/3, agent.size * 0.7, agent.size * 0.7);

      // Face mask reflection
      p.fill(150, 200, 255, 150);
      p.noStroke();
      p.ellipse(agent.x - 5, agentY - agent.size/3 - 3, 8, 12);

      // Scanning device/detector
      let sweepX = agent.x + p.cos(agent.sweepAngle) * 15;
      let sweepY = agentY + p.sin(agent.sweepAngle) * 15;
      p.strokeWeight(3);
      p.stroke(255, 100, 100);
      p.line(agent.x, agentY, sweepX, sweepY);

      // Detection beam
      p.stroke(255, 0, 0, 100);
      p.strokeWeight(1);
      for (let j = 0; j < 5; j++) {
        let beamX = sweepX + p.cos(agent.sweepAngle) * j * 20;
        let beamY = sweepY + p.sin(agent.sweepAngle) * j * 20;
        if (beamX > 0 && beamX < 400 && beamY > 0 && beamY < 600) {
          p.line(sweepX, sweepY, beamX, beamY);
        }
      }

      agent.sweepAngle += 0.05;
    }

    // Warning sirens at top
    sirenRotation += 0.1;
    for (let i = 0; i < 3; i++) {
      let sirenX = 100 + i * 100;
      let sirenY = 50;

      // Siren base
      p.fill(60, 60, 80);
      p.stroke(40, 40, 60);
      p.strokeWeight(2);
      p.rect(sirenX - 15, sirenY - 10, 30, 20);

      // Rotating light
      p.push();
      p.translate(sirenX, sirenY);
      p.rotate(sirenRotation + i * p.PI/3);

      let flashIntensity = p.sin(warningFlash * 3 + i) > 0 ? 255 : 100;
      p.fill(255, flashIntensity, flashIntensity);
      p.noStroke();
      p.triangle(-8, 0, 8, 0, 0, -20);
      p.pop();

      // Light beam
      if (p.sin(warningFlash * 3 + i) > 0) {
        p.fill(255, 0, 0, 30);
        p.noStroke();
        p.triangle(sirenX - 40, sirenY, sirenX + 40, sirenY, sirenX, 150);
      }
    }

    // Institutional barriers/containment
    p.strokeWeight(8);
    p.stroke(255, 255, 0);
    for (let i = 0; i < 400; i += 60) {
      let barHeight = 100 + p.sin(alarmPulse + i * 0.1) * 20;
      p.line(i, 580, i, 580 - barHeight);
    }

    // "CONTAMINATION DETECTED" effect (visual only, no text)
    if (p.sin(warningFlash * 4) > 0.5) {
      p.fill(255, 0, 0, 200);
      p.noStroke();
      p.rect(0, 0, 400, 600);
    }

    // Interactive mouse effect - agents converge on mouse position
    if (p.mouseX > 0 && p.mouseX < 400 && p.mouseY > 0 && p.mouseY < 600) {
      for (let agent of cdaAgents) {
        agent.x += (p.mouseX - agent.x) * 0.02;
        agent.y += (p.mouseY - agent.y) * 0.02;
      }

      // Extra alarm intensity when mouse detected
      p.fill(255, 0, 0, 50);
      p.noStroke();
      p.ellipse(p.mouseX, p.mouseY, 100, 100);
    }
  };
}

function sketch(p) {
  let betrayalAngle = 0;
  let confessionAlpha = 0;
  let shadowIntensity = 0;
  let revelationProgress = 0;
  let particles = [];
  let recordingLines = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize recording visualization lines
    for(let i = 0; i < 50; i++) {
      recordingLines.push({
        x: p.random(50, 350),
        y: p.random(450, 500),
        width: p.random(20, 80),
        height: p.random(2, 8),
        pulse: p.random(0, p.TWO_PI)
      });
    }

    // Initialize shadow particles
    for(let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(3, 12),
        drift: p.random(-0.5, 0.5),
        alpha: p.random(50, 150)
      });
    }
  };

  p.draw = function() {
    // Dark, oppressive background with corporate coldness
    let bgGrad = p.drawingContext.createLinearGradient(0, 0, 0, 600);
    bgGrad.addColorStop(0, '#1a1a2e');
    bgGrad.addColorStop(0.7, '#16213e');
    bgGrad.addColorStop(1, '#0f1419');
    p.drawingContext.fillStyle = bgGrad;
    p.rect(0, 0, 400, 600);

    // Animate revelation progress based on mouse position
    let targetRevelation = p.map(p.mouseX, 0, 400, 0, 1);
    revelationProgress = p.lerp(revelationProgress, targetRevelation, 0.03);

    // Update shadow intensity
    shadowIntensity = 0.3 + revelationProgress * 0.7;

    // Draw ominous corporate shadows
    p.fill(0, 0, 0, shadowIntensity * 100);
    for(let particle of particles) {
      particle.x += particle.drift;
      if(particle.x > 420) particle.x = -20;
      if(particle.x < -20) particle.x = 420;

      p.ellipse(particle.x, particle.y, particle.size * (1 + revelationProgress));
    }

    // Waternoose's imposing silhouette (transformed by betrayal)
    p.push();
    p.translate(200, 180);
    p.rotate(p.sin(betrayalAngle) * 0.1 * revelationProgress);

    // Body - becoming more menacing as revelation progresses
    let bodyColor = p.lerpColor(p.color(70, 90, 120), p.color(40, 20, 60), revelationProgress);
    p.fill(bodyColor);
    p.stroke(30, 30, 30);
    p.strokeWeight(2);
    p.ellipse(0, 0, 120 + revelationProgress * 20, 140 + revelationProgress * 30);

    // Multiple spider-like legs becoming more aggressive
    p.strokeWeight(8);
    for(let i = 0; i < 6; i++) {
      let angle = p.map(i, 0, 6, -p.PI, p.PI);
      let legExtension = 60 + revelationProgress * 30;
      let bendAmount = p.sin(betrayalAngle + i) * revelationProgress * 20;

      p.stroke(p.red(bodyColor) - 20, p.green(bodyColor) - 20, p.blue(bodyColor) - 20);
      p.line(0, 20, 
             p.cos(angle) * legExtension + bendAmount, 
             p.sin(angle) * legExtension + 60);
    }

    // Eyes - cold, calculating, revealed malice
    let eyeColor = p.lerpColor(p.color(100, 150, 200), p.color(200, 50, 50), revelationProgress);
    p.fill(eyeColor);
    p.noStroke();
    p.ellipse(-20, -20, 25, 35);
    p.ellipse(20, -20, 25, 35);

    // Pupils that narrow with revelation
    p.fill(20, 10, 30);
    let pupilSize = p.lerp(12, 6, revelationProgress);
    p.ellipse(-20, -20, pupilSize, pupilSize * 2);
    p.ellipse(20, -20, pupilSize, pupilSize * 2);

    p.pop();

    // Sulley and Mike cowering (smaller, intimidated)
    p.push();
    p.translate(100 - revelationProgress * 20, 350 + revelationProgress * 30);

    // Sulley silhouette
    p.fill(30, 80, 120, 200 - revelationProgress * 50);
    p.stroke(20, 60, 100);
    p.strokeWeight(1);
    p.ellipse(0, 0, 40, 60);
    p.ellipse(0, -25, 35, 40); // head

    // Mike silhouette  
    p.fill(50, 120, 50, 200 - revelationProgress * 50);
    p.stroke(30, 90, 30);
    p.ellipse(30, 10, 25, 25);

    p.pop();

    // Recording device visualization (confession playing)
    confessionAlpha = p.sin(betrayalAngle * 2) * 0.3 + 0.7;
    p.fill(200, 100, 100, confessionAlpha * 255 * revelationProgress);
    p.noStroke();
    p.rect(50, 430, 300, 80, 5);

    // Sound waves from recording
    for(let line of recordingLines) {
      line.pulse += 0.1;
      let waveHeight = line.height * (1 + p.sin(line.pulse) * 0.5) * revelationProgress;
      p.fill(255, 150, 150, confessionAlpha * 200);
      p.rect(line.x, line.y, line.width, waveHeight);
    }

    // Dramatic lighting effect - harsh corporate fluorescent turning sinister
    let lightGrad = p.drawingContext.createRadialGradient(200, 150, 50, 200, 150, 300);
    lightGrad.addColorStop(0, `rgba(255,255,255,${0.1 * (1 - revelationProgress)})`);
    lightGrad.addColorStop(0.5, `rgba(200,180,160,${0.05 * (1 - revelationProgress)})`);
    lightGrad.addColorStop(1, 'rgba(100,50,50,0.05)');

    p.drawingContext.fillStyle = lightGrad;
    p.rect(0, 0, 400, 600);

    // Red warning lights flashing (institutional alarm)
    if(revelationProgress > 0.5) {
      let flashIntensity = p.sin(betrayalAngle * 4) * 0.5 + 0.5;
      p.fill(255, 0, 0, flashIntensity * 30 * revelationProgress);
      p.rect(0, 0, 400, 600);

      // Corner warning indicators
      p.fill(255, 50, 50, flashIntensity * 200);
      p.ellipse(30, 30, 15, 15);
      p.ellipse(370, 30, 15, 15);
      p.ellipse(30, 570, 15, 15);
      p.ellipse(370, 570, 15, 15);
    }

    betrayalAngle += 0.02;
  };

  p.mousePressed = function() {
    // Click creates a shock wave of realization
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        size: p.random(5, 15),
        drift: p.random(-2, 2),
        alpha: 150
      });
    }

    // Add more confession lines
    for(let i = 0; i < 5; i++) {
      recordingLines.push({
        x: p.random(50, 350),
        y: p.random(450, 500),
        width: p.random(10, 60),
        height: p.random(3, 12),
        pulse: p.random(0, p.TWO_PI)
      });
    }
  };
}

function sketch(p) {
  let snowflakes = [];
  let doorPieces = [];
  let sulleyPos = {x: 150, y: 450};
  let mikePos = {x: 280, y: 480};
  let windOffset = 0;
  let doorShattered = false;
  let shatterTime = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize snowflakes
    for(let i = 0; i < 150; i++) {
      snowflakes.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(2, 5),
        speed: p.random(1, 3),
        drift: p.random(-0.5, 0.5)
      });
    }

    // Initialize door pieces
    for(let i = 0; i < 12; i++) {
      doorPieces.push({
        x: 200 + p.random(-30, 30),
        y: 300 + p.random(-20, 20),
        vx: p.random(-3, 3),
        vy: p.random(-4, -1),
        rotation: p.random(p.TWO_PI),
        rotSpeed: p.random(-0.1, 0.1),
        size: p.random(15, 35),
        alpha: 255
      });
    }
  };

  p.draw = function() {
    // Dark, cold gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 40), p.color(45, 55, 75), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    windOffset += 0.02;

    // Draw mountain silhouettes
    p.fill(25, 35, 50);
    p.noStroke();
    p.beginShape();
    p.vertex(0, p.height);
    for(let x = 0; x <= p.width; x += 20) {
      let h = p.map(p.noise(x * 0.01, windOffset * 0.5), 0, 1, p.height * 0.3, p.height * 0.6);
      p.vertex(x, h);
    }
    p.vertex(p.width, p.height);
    p.endShape(p.CLOSE);

    // Back mountains
    p.fill(35, 45, 65);
    p.beginShape();
    p.vertex(0, p.height);
    for(let x = 0; x <= p.width; x += 25) {
      let h = p.map(p.noise(x * 0.008, windOffset * 0.3), 0, 1, p.height * 0.4, p.height * 0.7);
      p.vertex(x, h);
    }
    p.vertex(p.width, p.height);
    p.endShape(p.CLOSE);

    // Snow ground
    p.fill(220, 230, 240);
    p.beginShape();
    p.vertex(0, p.height);
    for(let x = 0; x <= p.width; x += 15) {
      let h = p.map(p.noise(x * 0.02, windOffset), 0, 1, p.height * 0.8, p.height * 0.9);
      p.vertex(x, h);
    }
    p.vertex(p.width, p.height);
    p.endShape(p.CLOSE);

    // Draw shattered door pieces if clicked
    if(doorShattered) {
      for(let piece of doorPieces) {
        p.push();
        p.translate(piece.x, piece.y);
        p.rotate(piece.rotation);
        p.fill(139, 69, 19, piece.alpha);
        p.stroke(101, 67, 33, piece.alpha);
        p.strokeWeight(2);
        p.rect(-piece.size/2, -piece.size/2, piece.size, piece.size * 0.6);
        p.pop();

        piece.x += piece.vx;
        piece.y += piece.vy;
        piece.vy += 0.1; // gravity
        piece.rotation += piece.rotSpeed;
        piece.alpha -= 2;

        if(piece.y > p.height + 50) {
          piece.y = p.height + 50;
          piece.vx *= 0.8;
          piece.vy *= -0.3;
        }
      }
      shatterTime++;
    } else {
      // Draw intact door in distance
      p.push();
      p.translate(200, 300);
      p.fill(139, 69, 19, 180);
      p.stroke(101, 67, 33, 180);
      p.strokeWeight(3);
      p.rect(-25, -35, 50, 70);

      // Door handle
      p.fill(200, 180, 120, 180);
      p.ellipse(15, 0, 6, 6);

      // Door's fading light
      p.fill(255, 200, 100, 50);
      p.noStroke();
      p.ellipse(0, 0, 80, 80);
      p.pop();
    }

    // Draw Sulley silhouette
    p.push();
    p.translate(sulleyPos.x, sulleyPos.y);
    let sulleyScale = 0.8 + p.sin(windOffset * 2) * 0.05;
    p.scale(sulleyScale);

    // Body
    p.fill(20, 60, 120);
    p.stroke(10, 40, 80);
    p.strokeWeight(2);
    p.ellipse(0, 0, 80, 100);

    // Head
    p.ellipse(0, -60, 60, 70);

    // Horns
    p.fill(40, 30, 20);
    p.triangle(-15, -85, -10, -95, -5, -85);
    p.triangle(5, -85, 10, -95, 15, -85);

    // Eyes (sad/lost)
    p.fill(255, 255, 255);
    p.ellipse(-12, -65, 15, 20);
    p.ellipse(12, -65, 15, 20);
    p.fill(20, 20, 20);
    p.ellipse(-12, -62, 8, 12);
    p.ellipse(12, -62, 8, 12);

    // Slumped shoulders/arms
    p.fill(20, 60, 120);
    p.stroke(10, 40, 80);
    p.ellipse(-35, -10, 25, 40);
    p.ellipse(35, -10, 25, 40);
    p.pop();

    // Draw Mike silhouette
    p.push();
    p.translate(mikePos.x, mikePos.y);
    let mikeScale = 0.7 + p.sin(windOffset * 2.5) * 0.08;
    p.scale(mikeScale);

    // Body/head (one sphere)
    p.fill(40, 120, 60);
    p.stroke(20, 80, 40);
    p.strokeWeight(2);
    p.ellipse(0, 0, 45, 50);

    // Big eye (looking down, defeated)
    p.fill(255, 255, 255);
    p.ellipse(0, -5, 35, 35);
    p.fill(20, 20, 20);
    p.ellipse(0, -2, 20, 25);

    // Small horns
    p.fill(40, 30, 20);
    p.triangle(-8, -25, -5, -32, -2, -25);
    p.triangle(2, -25, 5, -32, 8, -25);

    // Arms/legs barely visible
    p.fill(40, 120, 60);
    p.stroke(20, 80, 40);
    p.ellipse(-15, 15, 8, 20);
    p.ellipse(15, 15, 8, 20);
    p.pop();

    // Falling snow
    for(let flake of snowflakes) {
      p.fill(255, 255, 255, 200);
      p.noStroke();
      p.ellipse(flake.x, flake.y, flake.size, flake.size);

      flake.y += flake.speed;
      flake.x += flake.drift + p.sin(windOffset * 3 + flake.y * 0.01) * 0.5;

      if(flake.y > p.height) {
        flake.y = -10;
        flake.x = p.random(p.width);
      }
      if(flake.x > p.width + 10) flake.x = -10;
      if(flake.x < -10) flake.x = p.width + 10;
    }

    // Wind effect particles
    if(p.frameCount % 3 === 0) {
      p.fill(255, 255, 255, 100);
      for(let i = 0; i < 5; i++) {
        let x = p.random(p.width);
        let y = p.random(p.height * 0.7, p.height);
        p.ellipse(x, y, 1, 1);
      }
    }

    // Vignette effect for isolation
    for(let r = 0; r < 100; r++) {
      let alpha = p.map(r, 0, 100, 0, 150);
      p.stroke(15, 25, 40, alpha);
      p.strokeWeight(2);
      p.noFill();
      p.ellipse(p.width/2, p.height/2, p.width + r * 10, p.height + r * 10);
    }
  };

  p.mousePressed = function() {
    if(!doorShattered && p.dist(p.mouseX, p.mouseY, 200, 300) < 50) {
      doorShattered = true;
      shatterTime = 0;
    }
  };

  p.mouseMoved = function() {
    // Characters slightly react to mouse presence (looking toward hope)
    let mouseInfluence = p.constrain(p.map(p.mouseX, 0, p.width, -10, 10), -10, 10);
    sulleyPos.x = 150 + mouseInfluence * 0.3;
    mikePos.x = 280 + mouseInfluence * 0.2;
  };
}

function sketch(p) {
  let doorShards = [];
  let energyParticles = [];
  let mouseInfluence = 0;
  let pulsePhase = 0;
  let doorBreakPhase = 0;
  let sulleyX, sulleyY, mikeX, mikeY;
  let corporateLines = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize door shards
    for (let i = 0; i < 12; i++) {
      doorShards.push({
        x: 200 + p.random(-30, 30),
        y: 150 + p.random(-20, 20),
        vx: p.random(-3, 3),
        vy: p.random(-2, 4),
        rotation: p.random(p.TWO_PI),
        rotSpeed: p.random(-0.1, 0.1),
        size: p.random(15, 35)
      });
    }

    // Initialize energy particles
    for (let i = 0; i < 30; i++) {
      energyParticles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        life: p.random(1),
        maxLife: p.random(0.5, 1.5)
      });
    }

    // Corporate grid lines
    for (let i = 0; i < 8; i++) {
      corporateLines.push({
        x: p.random(400),
        y: p.random(600),
        length: p.random(50, 150),
        angle: p.random(p.TWO_PI),
        opacity: p.random(0.3, 0.7)
      });
    }

    sulleyX = 200;
    sulleyY = 300;
    mikeX = 150;
    mikeY = 350;
  };

  p.draw = function() {
    // Dynamic background - corporate to rebellious transition
    let bgR = p.map(p.sin(p.frameCount * 0.02), -1, 1, 15, 40);
    let bgG = p.map(p.sin(p.frameCount * 0.02 + 1), -1, 1, 25, 55);
    let bgB = p.map(p.sin(p.frameCount * 0.02 + 2), -1, 1, 35, 70);
    p.background(bgR, bgG, bgB);

    mouseInfluence = p.map(p.mouseX, 0, 400, 0, 1);
    pulsePhase += 0.05;
    doorBreakPhase = p.min(doorBreakPhase + 0.02, 1);

    // Corporate grid background - fading as rebellion grows
    p.stroke(100, 120, 140, 60 * (1 - mouseInfluence));
    p.strokeWeight(1);
    for (let line of corporateLines) {
      p.line(line.x, line.y, 
             line.x + p.cos(line.angle) * line.length,
             line.y + p.sin(line.angle) * line.length);
    }

    // Broken door frame - institutional barrier destroyed
    p.push();
    p.translate(200, 150);
    p.stroke(80, 60, 40);
    p.strokeWeight(8);
    p.noFill();

    // Door frame pieces scattered
    for (let shard of doorShards) {
      p.push();
      p.translate(shard.x, shard.y);
      p.rotate(shard.rotation);
      p.fill(120, 80, 40, 150);
      p.noStroke();
      p.rect(-shard.size/2, -shard.size/2, shard.size, shard.size/3);
      p.pop();

      shard.x += shard.vx;
      shard.y += shard.vy;
      shard.rotation += shard.rotSpeed;
      shard.vy += 0.1; // gravity

      if (shard.y > 600) {
        shard.y = -20;
        shard.x = 200 + p.random(-50, 50);
        shard.vy = p.random(-1, 1);
      }
    }
    p.pop();

    // Energy particles - transformation from fear to purpose
    for (let particle of energyParticles) {
      let intensity = p.map(p.sin(pulsePhase + particle.x * 0.01), -1, 1, 0.3, 1);

      // Color shifts from corporate blue to rebellious orange/red
      let r = p.map(mouseInfluence, 0, 1, 100, 255);
      let g = p.map(mouseInfluence, 0, 1, 150, 100);
      let b = p.map(mouseInfluence, 0, 1, 200, 50);

      p.fill(r, g, b, particle.life * 255 * intensity);
      p.noStroke();
      p.circle(particle.x, particle.y, 4 + intensity * 3);

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 0.01;

      if (particle.life <= 0) {
        particle.x = p.random(400);
        particle.y = p.random(600);
        particle.life = particle.maxLife;
        particle.vx = p.random(-1, 1);
        particle.vy = p.random(-1, 1);
      }
    }

    // Sulley silhouette - large, determined figure
    p.push();
    p.translate(sulleyX + p.sin(pulsePhase) * 2, sulleyY);

    // Body - powerful, forward-leaning stance
    p.fill(60, 120, 180, 200);
    p.noStroke();
    p.ellipse(0, 0, 80, 120);

    // Spots - defining characteristic
    p.fill(40, 80, 120);
    p.circle(-15, -20, 12);
    p.circle(20, -10, 15);
    p.circle(-10, 15, 10);
    p.circle(25, 20, 8);

    // Arms - reaching forward, breaking through
    p.fill(60, 120, 180, 200);
    p.ellipse(-40, -10, 25, 60);
    p.ellipse(40, -10, 25, 60);

    // Horns - iconic silhouette element
    p.fill(80, 100, 140);
    p.triangle(-8, -60, -15, -80, -5, -75);
    p.triangle(8, -60, 15, -80, 5, -75);

    // Eyes - determined, focused
    let eyeGlow = p.map(mouseInfluence, 0, 1, 50, 255);
    p.fill(255, 200, 100, eyeGlow);
    p.circle(-12, -35, 8);
    p.circle(12, -35, 8);

    p.pop();

    // Mike silhouette - smaller but equally determined
    p.push();
    p.translate(mikeX + p.cos(pulsePhase * 1.2) * 3, mikeY);

    // Body - round, compact
    p.fill(100, 180, 100, 200);
    p.noStroke();
    p.circle(0, 0, 45);

    // Large eye - his defining feature, now focused with purpose
    p.fill(255, 255, 255, 230);
    p.circle(0, -5, 30);
    p.fill(50, 100, 200);
    p.circle(0, -5, 15);
    p.fill(20, 50, 100);
    p.circle(2, -7, 8);

    // Eye glow - intensity of purpose
    let mikeGlow = p.map(mouseInfluence, 0, 1, 100, 255);
    p.fill(255, 255, 255, mikeGlow * 0.5);
    p.circle(0, -5, 35);

    // Arms - ready for action
    p.fill(100, 180, 100, 200);
    p.ellipse(-25, 5, 15, 35);
    p.ellipse(25, 5, 15, 35);

    // Legs - planted firmly, ready to charge
    p.ellipse(-10, 25, 12, 25);
    p.ellipse(10, 25, 12, 25);

    p.pop();

    // Directional energy burst - the force of their return
    p.push();
    p.translate(200, 200);
    for (let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI + pulsePhase * 0.5;
      let length = 30 + p.sin(pulsePhase + i) * 15;
      let intensity = p.map(mouseInfluence, 0, 1, 0.3, 1);

      p.stroke(255, 150, 50, 150 * intensity);
      p.strokeWeight(3);
      p.line(0, 0, p.cos(angle) * length, p.sin(angle) * length);
    }
    p.pop();

    // Interactive transformation glow
    if (p.mouseX > 0 && p.mouseX < 400 && p.mouseY > 0 && p.mouseY < 600) {
      p.push();
      p.translate(p.mouseX, p.mouseY);
      let glowSize = 50 + p.sin(pulsePhase * 2) * 20;

      p.fill(255, 100, 50, 30);
      p.noStroke();
      p.circle(0, 0, glowSize);

      p.fill(255, 200, 100, 60);
      p.circle(0, 0, glowSize * 0.6);
      p.pop();
    }

    // Foreground institutional shadows being pushed back
    p.fill(0, 0, 0, 20 * (1 - mouseInfluence));
    p.noStroke();
    p.rect(0, 0, 400, 100);
    p.rect(0, 500, 400, 100);
  };
}

function sketch(p) {
  let machine = {};
  let sparks = [];
  let screenLines = [];
  let pistonOffset = 0;
  let lightFlicker = 0;
  let smokeParticles = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize machine components
    machine.x = p.width / 2;
    machine.y = p.height / 2 + 50;
    machine.width = 280;
    machine.height = 200;

    // Initialize sparks
    for (let i = 0; i < 15; i++) {
      sparks.push({
        x: p.random(machine.x - machine.width/2, machine.x + machine.width/2),
        y: p.random(machine.y - machine.height/2, machine.y + machine.height/2),
        life: p.random(60, 120),
        maxLife: p.random(60, 120),
        size: p.random(2, 6)
      });
    }

    // Initialize screen interference lines
    for (let i = 0; i < 8; i++) {
      screenLines.push({
        y: p.random(0, p.height),
        speed: p.random(2, 5),
        alpha: p.random(100, 200)
      });
    }

    // Initialize smoke particles
    for (let i = 0; i < 25; i++) {
      smokeParticles.push({
        x: p.random(machine.x - 30, machine.x + 30),
        y: machine.y + machine.height/2,
        vx: p.random(-0.5, 0.5),
        vy: p.random(-2, -1),
        size: p.random(8, 20),
        life: p.random(100, 200),
        maxLife: p.random(100, 200)
      });
    }
  };

  p.draw = function() {
    // Dark industrial background
    p.background(15, 15, 20);

    // Flickering emergency lighting
    lightFlicker = p.noise(p.frameCount * 0.1) * 100 + 50;
    let redGlow = p.color(80, 20, 20, lightFlicker);

    // Background glow
    for (let i = 0; i < 5; i++) {
      p.fill(80 - i * 15, 20 - i * 3, 20 - i * 3, 20);
      p.noStroke();
      p.ellipse(p.width/2, p.height/2, (p.width + p.height) * (1 - i * 0.2));
    }

    // Screen interference lines
    p.stroke(120, 40, 40, 150);
    p.strokeWeight(1);
    for (let line of screenLines) {
      line.y += line.speed;
      if (line.y > p.height) line.y = -5;
      p.line(0, line.y, p.width, line.y);
      p.line(0, line.y + 2, p.width, line.y + 2);
    }

    // Main machine body - brutal industrial design
    p.fill(40, 40, 45);
    p.stroke(60, 60, 65);
    p.strokeWeight(3);
    p.rect(machine.x - machine.width/2, machine.y - machine.height/2, machine.width, machine.height, 10);

    // Machine details - pipes and vents
    p.fill(30, 30, 35);
    for (let i = 0; i < 6; i++) {
      let pipeX = machine.x - machine.width/2 + 40 + i * 35;
      p.rect(pipeX, machine.y - machine.height/2 - 20, 20, 40);
    }

    // Central extraction chamber
    pistonOffset = p.sin(p.frameCount * 0.3) * 8;
    p.fill(20, 20, 25);
    p.stroke(100, 30, 30);
    p.strokeWeight(4);
    p.rect(machine.x - 60, machine.y - 40 + pistonOffset, 120, 80, 5);

    // Mechanical pistons
    p.fill(70, 70, 75);
    p.stroke(90, 90, 95);
    p.strokeWeight(2);
    for (let i = 0; i < 4; i++) {
      let pistonX = machine.x - 40 + i * 25;
      p.rect(pistonX, machine.y - 60 + pistonOffset, 8, 40 + p.abs(pistonOffset));
    }

    // Boo's silhouette in the chamber (small and vulnerable)
    p.fill(200, 180, 160, 200);
    p.noStroke();
    p.ellipse(machine.x, machine.y + pistonOffset, 25, 35);

    // Scream energy extraction beams
    let beamIntensity = p.map(p.sin(p.frameCount * 0.5), -1, 1, 50, 200);
    p.stroke(255, 100, 100, beamIntensity);
    p.strokeWeight(3);
    for (let i = 0; i < 8; i++) {
      let angle = (p.TWO_PI / 8) * i;
      let startX = machine.x + p.cos(angle) * 15;
      let startY = machine.y + pistonOffset + p.sin(angle) * 15;
      let endX = machine.x + p.cos(angle) * 80;
      let endY = machine.y + pistonOffset + p.sin(angle) * 80;
      p.line(startX, startY, endX, endY);
    }

    // Control panels and warning lights
    p.fill(60, 20, 20);
    p.stroke(120, 40, 40);
    p.strokeWeight(2);
    for (let i = 0; i < 3; i++) {
      let panelX = machine.x - machine.width/2 + 30 + i * 80;
      p.rect(panelX, machine.y + machine.height/2 - 30, 40, 20, 3);

      // Blinking warning lights
      if (p.frameCount % 30 < 15) {
        p.fill(255, 50, 50);
        p.noStroke();
        p.ellipse(panelX + 20, machine.y + machine.height/2 - 15, 8, 8);
      }
    }

    // Update and draw sparks
    for (let i = sparks.length - 1; i >= 0; i--) {
      let spark = sparks[i];
      spark.life--;

      let alpha = p.map(spark.life, 0, spark.maxLife, 0, 255);
      p.fill(255, 150, 50, alpha);
      p.noStroke();
      p.ellipse(spark.x, spark.y, spark.size, spark.size);

      if (spark.life <= 0) {
        sparks[i] = {
          x: p.random(machine.x - machine.width/2, machine.x + machine.width/2),
          y: p.random(machine.y - machine.height/2, machine.y + machine.height/2),
          life: p.random(60, 120),
          maxLife: p.random(60, 120),
          size: p.random(2, 6)
        };
      }
    }

    // Update and draw smoke
    for (let smoke of smokeParticles) {
      smoke.x += smoke.vx;
      smoke.y += smoke.vy;
      smoke.life--;
      smoke.size += 0.1;

      let alpha = p.map(smoke.life, 0, smoke.maxLife, 0, 80);
      p.fill(60, 60, 60, alpha);
      p.noStroke();
      p.ellipse(smoke.x, smoke.y, smoke.size, smoke.size);

      if (smoke.life <= 0) {
        smoke.x = p.random(machine.x - 30, machine.x + 30);
        smoke.y = machine.y + machine.height/2;
        smoke.vx = p.random(-0.5, 0.5);
        smoke.vy = p.random(-2, -1);
        smoke.size = p.random(8, 20);
        smoke.life = p.random(100, 200);
        smoke.maxLife = p.random(100, 200);
      }
    }

    // Mouse interaction - intensify horror on hover
    let mouseDistance = p.dist(p.mouseX, p.mouseY, machine.x, machine.y);
    if (mouseDistance < 150) {
      // Intensify the horror
      p.fill(255, 0, 0, 100);
      p.noStroke();
      p.rect(0, 0, p.width, p.height);

      // Add extra sparks
      for (let i = 0; i < 3; i++) {
        p.fill(255, 100, 100, 200);
        p.ellipse(
          machine.x + p.random(-100, 100),
          machine.y + p.random(-100, 100),
          p.random(3, 8),
          p.random(3, 8)
        );
      }
    }

    // Corporate warning text overlay
    if (p.frameCount % 180 < 60) {
      p.fill(255, 50, 50, 150);
      p.noStroke();
      p.rect(0, p.height - 40, p.width, 40);
      p.fill(255);
      p.textAlign(p.CENTER, p.CENTER);
      p.textSize(12);
      p.text("SCREAM EXTRACTION IN PROGRESS", p.width/2, p.height - 20);
    }
  };
}

function sketch(p) {
  let doors = [];
  let particles = [];
  let sulleyX, sulleyY;
  let booX, booY;
  let machineBreaking = false;
  let breakIntensity = 0;
  let doorSpinSpeeds = [];
  let lightningFlashes = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize flying doors
    for(let i = 0; i < 8; i++) {
      doors.push({
        x: p.random(400),
        y: p.random(300, 500),
        rotation: p.random(p.TWO_PI),
        size: p.random(30, 60),
        vx: p.random(-3, 3),
        vy: p.random(-4, -1),
        color: p.color(p.random(100, 255), p.random(50, 200), p.random(100, 255))
      });
      doorSpinSpeeds.push(p.random(0.05, 0.2));
    }

    // Sulley position
    sulleyX = 200;
    sulleyY = 350;

    // Boo position
    booX = 250;
    booY = 280;

    // Initialize particles for chaos effect
    for(let i = 0; i < 50; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-2, 2),
        vy: p.random(-3, 1),
        life: p.random(100, 255),
        size: p.random(2, 8)
      });
    }
  };

  p.draw = function() {
    // Dark, chaotic background with corporate undertones
    p.background(20, 25, 40);

    // Add lightning flashes for dramatic effect
    if(p.random(100) < 5) {
      lightningFlashes.push(p.frameCount);
    }

    // Process lightning flashes
    for(let i = lightningFlashes.length - 1; i >= 0; i--) {
      let flashAge = p.frameCount - lightningFlashes[i];
      if(flashAge < 5) {
        let flashAlpha = p.map(flashAge, 0, 5, 80, 0);
        p.fill(255, 255, 200, flashAlpha);
        p.noStroke();
        p.rect(0, 0, 400, 600);
      } else {
        lightningFlashes.splice(i, 1);
      }
    }

    // Corporate/industrial background elements
    p.stroke(60, 80, 120, 100);
    p.strokeWeight(2);
    for(let i = 0; i < 10; i++) {
      let y = i * 60 + (p.frameCount * 0.5) % 60;
      p.line(0, y, 400, y);
    }

    // Scream extractor machine (broken/exploding)
    machineBreaking = p.dist(p.mouseX, p.mouseY, 250, 200) < 100;
    breakIntensity = machineBreaking ? p.min(breakIntensity + 0.1, 1) : p.max(breakIntensity - 0.05, 0);

    p.push();
    p.translate(250, 200);
    p.rotate(breakIntensity * p.random(-0.3, 0.3));

    // Machine base
    p.fill(80 - breakIntensity * 30, 90 - breakIntensity * 40, 100 - breakIntensity * 50);
    p.stroke(120, 140, 160);
    p.strokeWeight(3);
    p.rect(-60, -40, 120, 80, 10);

    // Machine details breaking apart
    p.fill(200 - breakIntensity * 100, 50, 50);
    p.noStroke();
    for(let i = 0; i < 5; i++) {
      let offset = breakIntensity * p.random(-20, 20);
      p.circle(p.random(-40, 40) + offset, p.random(-20, 20) + offset, 8);
    }

    p.pop();

    // Boo (small figure being rescued)
    p.push();
    p.translate(booX, booY);

    // Boo's glow (innocent, warm)
    p.fill(255, 220, 150, 80);
    p.noStroke();
    p.circle(0, 0, 40 + p.sin(p.frameCount * 0.1) * 5);

    // Boo's silhouette
    p.fill(255, 200, 150);
    p.circle(0, -10, 15); // head
    p.ellipse(0, 5, 12, 20); // body

    p.pop();

    // Sulley (heroic monster bursting in)
    p.push();
    p.translate(sulleyX + p.mouseX * 0.05, sulleyY + p.mouseY * 0.03);

    // Sulley's dramatic silhouette
    p.fill(60, 120, 180, 200);
    p.stroke(100, 160, 220);
    p.strokeWeight(2);

    // Body
    p.ellipse(0, 0, 80, 100);

    // Arms in action pose
    p.strokeWeight(8);
    p.line(-25, -10, -50, -30); // left arm reaching
    p.line(25, -10, 45, -25); // right arm

    // Legs in motion
    p.line(-15, 40, -30, 80);
    p.line(15, 40, 25, 75);

    // Head
    p.fill(80, 140, 200, 220);
    p.noStroke();
    p.circle(0, -40, 50);

    // Eyes (determined expression)
    p.fill(255, 255, 255);
    p.circle(-8, -45, 8);
    p.circle(8, -45, 8);
    p.fill(0);
    p.circle(-6, -43, 4);
    p.circle(10, -43, 4);

    p.pop();

    // Flying doors (chaos and destruction)
    for(let i = 0; i < doors.length; i++) {
      let door = doors[i];

      p.push();
      p.translate(door.x, door.y);
      p.rotate(door.rotation);

      // Door shadow/depth
      p.fill(0, 0, 0, 50);
      p.noStroke();
      p.rect(2, 2, door.size * 0.6, door.size, 3);

      // Door
      p.fill(door.color);
      p.stroke(255, 255, 255, 100);
      p.strokeWeight(1);
      p.rect(0, 0, door.size * 0.6, door.size, 3);

      // Door handle
      p.fill(200, 180, 100);
      p.noStroke();
      p.circle(door.size * 0.4, door.size * 0.5, 4);

      p.pop();

      // Update door movement
      door.x += door.vx;
      door.y += door.vy;
      door.rotation += doorSpinSpeeds[i];
      door.vy += 0.1; // gravity

      // Reset doors that fall off screen
      if(door.y > 700) {
        door.y = p.random(-100, -50);
        door.x = p.random(400);
        door.vy = p.random(-4, -1);
      }
    }

    // Chaos particles (debris, energy)
    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      p.fill(255, 200 + p.sin(particle.life * 0.1) * 50, 100, particle.life);
      p.noStroke();
      p.circle(particle.x, particle.y, particle.size);

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 2;

      if(particle.life <= 0) {
        particles.splice(i, 1);
        // Add new particle
        particles.push({
          x: p.random(400),
          y: p.random(600),
          vx: p.random(-2, 2),
          vy: p.random(-3, 1),
          life: p.random(100, 255),
          size: p.random(2, 8)
        });
      }
    }

    // Card border/frame
    p.noFill();
    p.stroke(100, 120, 150, 150);
    p.strokeWeight(3);
    p.rect(10, 10, 380, 580, 15);
  };

  p.mousePressed = function() {
    // Add explosion effect on click
    for(let i = 0; i < 20; i++) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-5, 5),
        vy: p.random(-5, 5),
        life: 255,
        size: p.random(3, 12)
      });
    }

    // Shake doors
    for(let door of doors) {
      door.vx += p.random(-2, 2);
      door.vy += p.random(-3, 1);
    }
  };
}

function sketch(p) {
  let monsters = [];
  let soundWaves = [];
  let stars = [];
  let confessionAlpha = 0;
  let truthSpread = 0;
  let realization = 0;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create monster silhouettes in crowd formation
    for (let i = 0; i < 25; i++) {
      let x = (i % 5) * 80 + 40;
      let y = 350 + Math.floor(i / 5) * 60;
      monsters.push({
        x: x,
        y: y,
        size: p.random(30, 50),
        type: Math.floor(p.random(3)),
        awareness: 0,
        maxAwareness: p.random(0.7, 1.0)
      });
    }

    // Initialize stars
    for (let i = 0; i < 15; i++) {
      stars.push({
        x: p.random(50, 350),
        y: p.random(50, 200),
        size: p.random(2, 8),
        alpha: 0,
        twinkle: p.random(0.02, 0.05)
      });
    }
  };

  p.draw = function() {
    time += 0.016;

    // Dark corporate background with gradient
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(20, 25, 40), p.color(60, 70, 90), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Central confession device - recording playing
    p.push();
    p.translate(200, 180);
    p.fill(100, 120, 150, 200);
    p.noStroke();
    p.rect(-60, -40, 120, 80, 10);

    // Pulsing recording light
    let pulseAlpha = 150 + 100 * p.sin(time * 8);
    p.fill(255, 50, 50, pulseAlpha);
    p.circle(30, -20, 12);
    p.pop();

    // Sound waves emanating from device
    confessionAlpha = p.min(255, confessionAlpha + 2);
    for (let i = 0; i < 5; i++) {
      let waveRadius = (time * 100 + i * 40) % 300;
      let waveAlpha = p.map(waveRadius, 0, 300, confessionAlpha, 0);
      p.noFill();
      p.stroke(200, 220, 255, waveAlpha);
      p.strokeWeight(3);
      p.circle(200, 180, waveRadius);
    }

    // Truth spreading through crowd
    truthSpread = p.min(1, truthSpread + 0.008);

    // Draw monster crowd with growing awareness
    for (let monster of monsters) {
      let distanceFromCenter = p.dist(monster.x, monster.y, 200, 180);
      let waveReached = truthSpread * 400;

      if (distanceFromCenter < waveReached) {
        monster.awareness = p.min(monster.maxAwareness, monster.awareness + 0.02);
      }

      // Monster silhouette with awareness glow
      p.push();
      p.translate(monster.x, monster.y);

      // Awareness glow
      if (monster.awareness > 0) {
        p.fill(255, 220, 100, monster.awareness * 100);
        p.noStroke();
        p.circle(0, 0, monster.size * 2);
      }

      // Monster body
      p.fill(40 + monster.awareness * 60, 50 + monster.awareness * 80, 70 + monster.awareness * 100);
      p.noStroke();

      // Different monster types
      if (monster.type === 0) {
        // Round monster
        p.circle(0, 0, monster.size);
        p.circle(-8, -8, 6); // eye
        p.circle(8, -8, 6);
      } else if (monster.type === 1) {
        // Tall monster
        p.rect(-monster.size/3, -monster.size/2, monster.size*2/3, monster.size);
        p.circle(-5, -monster.size/3, 4);
        p.circle(5, -monster.size/3, 4);
      } else {
        // Furry monster
        for (let j = 0; j < 8; j++) {
          let angle = (j / 8) * p.TWO_PI;
          let x = p.cos(angle) * monster.size/3;
          let y = p.sin(angle) * monster.size/3;
          p.circle(x, y, monster.size/2);
        }
      }
      p.pop();
    }

    // Collective realization effect
    realization = p.max(0, p.min(1, (truthSpread - 0.6) * 2.5));
    if (realization > 0) {
      p.fill(255, 255, 200, realization * 50);
      p.noStroke();
      p.rect(0, 0, p.width, p.height);
    }

    // Stars emerging as hope grows
    for (let star of stars) {
      star.alpha = p.min(255, realization * 255 * (1 + p.sin(time * star.twinkle)));
      if (star.alpha > 0) {
        p.push();
        p.translate(star.x, star.y);
        p.fill(255, 255, 200, star.alpha);
        p.noStroke();

        // Draw star shape
        p.beginShape();
        for (let i = 0; i < 5; i++) {
          let angle = (i * 4 * p.PI) / 5 - p.PI / 2;
          let x = p.cos(angle) * star.size;
          let y = p.sin(angle) * star.size;
          p.vertex(x, y);
        }
        p.endShape(p.CLOSE);
        p.pop();
      }
    }

    // Interactive mouse response - amplify nearest monster's awareness
    let mouseMonster = null;
    let minDist = Infinity;
    for (let monster of monsters) {
      let d = p.dist(p.mouseX, p.mouseY, monster.x, monster.y);
      if (d < minDist) {
        minDist = d;
        mouseMonster = monster;
      }
    }
    if (mouseMonster && minDist < 60) {
      mouseMonster.awareness = p.min(1, mouseMonster.awareness + 0.05);
    }
  };

  p.mousePressed = function() {
    // Accelerate truth spreading on click
    truthSpread = p.min(1, truthSpread + 0.3);
  };
}

function sketch(p) {
  let particles = [];
  let canisters = [];
  let powerMeter = { value: 0, target: 100, exploding: false };
  let booPosition = { x: 200, y: 450 };
  let laughPulse = 0;
  let energyWaves = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize canisters in industrial arrangement
    for (let i = 0; i < 6; i++) {
      canisters.push({
        x: 60 + (i % 3) * 140,
        y: 150 + Math.floor(i / 3) * 100,
        glow: 0,
        targetGlow: 0
      });
    }

    // Initialize energy particles
    for (let i = 0; i < 100; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: 0,
        vy: 0,
        brightness: p.random(100),
        size: p.random(2, 6),
        active: false
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Dark industrial background with corporate blues and grays
    p.background(15, 25, 40);

    // Draw factory floor with corporate aesthetic
    drawFactoryBackground();

    // Update power meter with explosive growth
    updatePowerMeter();
    drawPowerMeter();

    // Draw and update canisters with brilliant glow
    updateCanisters();
    drawCanisters();

    // Draw Boo (simple silhouette with laugh animation)
    drawBoo();

    // Create energy waves from laughter
    if (p.frameCount % 20 === 0 && laughPulse > 0.5) {
      energyWaves.push({
        x: booPosition.x,
        y: booPosition.y,
        radius: 0,
        alpha: 255
      });
    }

    // Update and draw energy waves
    updateEnergyWaves();

    // Update and draw particles
    updateParticles();
    drawParticles();

    // Draw theatrical lighting effects
    drawTheatricalLights();

    // Update laugh pulse
    laughPulse = (p.sin(time * 8) + 1) / 2;
  };

  function drawFactoryBackground() {
    // Industrial pipes and corporate structure
    p.stroke(40, 60, 80);
    p.strokeWeight(8);
    for (let i = 0; i < 3; i++) {
      p.line(50 + i * 150, 0, 50 + i * 150, 120);
      p.line(0, 80 + i * 40, 400, 80 + i * 40);
    }

    // Corporate grid pattern
    p.stroke(25, 35, 50);
    p.strokeWeight(1);
    for (let x = 0; x < 400; x += 20) {
      for (let y = 0; y < 200; y += 20) {
        p.point(x, y);
      }
    }
  }

  function updatePowerMeter() {
    let mouseDistance = p.dist(p.mouseX, p.mouseY, booPosition.x, booPosition.y);
    let laughIntensity = p.map(mouseDistance, 0, 200, 1, 0.3);
    laughIntensity = p.constrain(laughIntensity, 0, 1);

    powerMeter.target = 20 + laughIntensity * 180;
    powerMeter.value = p.lerp(powerMeter.value, powerMeter.target, 0.1);

    if (powerMeter.value > 150) {
      powerMeter.exploding = true;
    }
  }

  function drawPowerMeter() {
    // Corporate meter housing
    p.fill(60, 80, 100);
    p.stroke(100, 120, 140);
    p.strokeWeight(3);
    p.rect(320, 50, 60, 200, 10);

    // Meter fill with explosive energy
    let meterHeight = p.map(powerMeter.value, 0, 200, 0, 180);

    if (powerMeter.exploding) {
      // Explosive gold energy
      p.fill(255, 215, 0, 200 + p.sin(time * 20) * 50);
      p.noStroke();
      p.rect(325, 240 - meterHeight, 50, meterHeight, 5);

      // Overflow effect
      for (let i = 0; i < 10; i++) {
        let sparkX = 350 + p.sin(time * 10 + i) * 30;
        let sparkY = 60 + p.cos(time * 8 + i) * 20;
        p.fill(255, 255, 100, 150);
        p.ellipse(sparkX, sparkY, 3, 3);
      }
    } else {
      // Normal blue corporate energy
      p.fill(100, 150, 255, 180);
      p.noStroke();
      p.rect(325, 240 - meterHeight, 50, meterHeight, 5);
    }
  }

  function updateCanisters() {
    for (let canister of canisters) {
      let distance = p.dist(p.mouseX, p.mouseY, canister.x, canister.y);
      let intensity = p.map(distance, 0, 150, 255, 50);
      intensity = p.constrain(intensity, 50, 255);

      if (laughPulse > 0.7) {
        canister.targetGlow = intensity;
      } else {
        canister.targetGlow = 30;
      }

      canister.glow = p.lerp(canister.glow, canister.targetGlow, 0.15);
    }
  }

  function drawCanisters() {
    for (let canister of canisters) {
      // Corporate canister body
      p.fill(80, 90, 120);
      p.stroke(120, 130, 160);
      p.strokeWeight(2);
      p.rect(canister.x - 25, canister.y - 40, 50, 80, 10);

      // Brilliant glow effect
      p.noStroke();
      p.fill(255, 215, 0, canister.glow * 0.3);
      p.ellipse(canister.x, canister.y, 80, 80);

      p.fill(255, 255, 150, canister.glow * 0.6);
      p.ellipse(canister.x, canister.y, 50, 50);

      p.fill(255, 255, 200, canister.glow);
      p.ellipse(canister.x, canister.y, 30, 30);
    }
  }

  function drawBoo() {
    p.push();
    p.translate(booPosition.x, booPosition.y);

    // Boo's silhouette with laugh animation
    let bounceY = p.sin(time * 12) * 5 * laughPulse;
    p.translate(0, bounceY);

    // Body
    p.fill(200, 150, 200);
    p.noStroke();
    p.ellipse(0, 0, 40, 50);

    // Head
    p.ellipse(0, -35, 35, 35);

    // Hair tufts
    p.ellipse(-8, -48, 12, 15);
    p.ellipse(0, -50, 10, 12);
    p.ellipse(8, -48, 12, 15);

    // Laugh effect - radiating joy
    if (laughPulse > 0.5) {
      p.stroke(255, 255, 100, (laughPulse - 0.5) * 400);
      p.strokeWeight(2);
      for (let i = 0; i < 8; i++) {
        let angle = (i / 8) * p.TWO_PI;
        let length = 20 + laughPulse * 15;
        p.line(0, -20, p.cos(angle) * length, -20 + p.sin(angle) * length);
      }
    }

    p.pop();
  }

  function updateEnergyWaves() {
    for (let i = energyWaves.length - 1; i >= 0; i--) {
      let wave = energyWaves[i];
      wave.radius += 8;
      wave.alpha -= 5;

      if (wave.alpha <= 0) {
        energyWaves.splice(i, 1);
      }
    }

    // Draw waves
    p.noFill();
    for (let wave of energyWaves) {
      p.stroke(255, 215, 0, wave.alpha);
      p.strokeWeight(3);
      p.ellipse(wave.x, wave.y, wave.radius * 2);

      p.stroke(255, 255, 150, wave.alpha * 0.5);
      p.strokeWeight(1);
      p.ellipse(wave.x, wave.y, wave.radius * 2.5);
    }
  }

  function updateParticles() {
    let mouseForce = laughPulse * 0.1;

    for (let particle of particles) {
      if (laughPulse > 0.3) {
        particle.active = true;

        // Attract particles to mouse when laughing
        let dx = p.mouseX - particle.x;
        let dy = p.mouseY - particle.y;
        let distance = p.dist(particle.x, particle.y, p.mouseX, p.mouseY);

        if (distance > 0) {
          particle.vx += (dx / distance) * mouseForce;
          particle.vy += (dy / distance) * mouseForce;
        }

        // Add some upward drift
        particle.vy -= 0.02;
        particle.brightness = p.lerp(particle.brightness, 255, 0.1);
      } else {
        particle.active = false;
        particle.brightness = p.lerp(particle.brightness, 30, 0.05);
      }

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.vx *= 0.95;
      particle.vy *= 0.95;

      // Wrap around edges
      if (particle.x < 0) particle.x = 400;
      if (particle.x > 400) particle.x = 0;
      if (particle.y < 0) particle.y = 600;
      if (particle.y > 600) particle.y = 0;
    }
  }

  function drawParticles() {
    p.noStroke();
    for (let particle of particles) {
      p.fill(255, 215, 0, particle.brightness * 0.8);
      p.ellipse(particle.x, particle.y, particle.size);

      p.fill(255, 255, 200, particle.brightness);
      p.ellipse(particle.x, particle.y, particle.size * 0.5);
    }
  }

  function drawTheatricalLights() {
    // Spotlight effect from above
    p.fill(255, 255, 150, 30);
    p.noStroke();
    p.ellipse(200, 0, 200, 100);

    // Stage lighting on Boo
    let lightIntensity = 50 + laughPulse * 100;
    p.fill(255, 215, 0, lightIntensity);
    p.ellipse(booPosition.x, booPosition.y - 50, 100, 60);

    // Rim lighting effects
    if (powerMeter.exploding) {
      p.stroke(255, 255, 100, 100);
      p.strokeWeight(20);
      p.noFill();
      p.rect(10, 10, 380, 580, 20);
    }
  }

  p.mousePressed = function() {
    // Create burst of particles on click
    for (let i = 0; i < 20; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-3, 3),
        vy: p.random(-5, -1),
        brightness: 255,
        size: p.random(3, 8),
        active: true
      });
    }
  };
}

function sketch(p) {
  let monsters = [];
  let laughParticles = [];
  let spotlights = [];
  let mikeX = 200;
  let mikeY = 400;
  let bounceOffset = 0;
  let comedyTimer = 0;
  let doorFrames = [];
  let energyTubes = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize monsters on the laugh floor
    for(let i = 0; i < 6; i++) {
      monsters.push({
        x: 60 + i * 55,
        y: 350 + p.random(-20, 20),
        size: p.random(25, 40),
        color: p.color(p.random(100, 255), p.random(100, 255), p.random(100, 255)),
        bounce: p.random(0, p.TWO_PI),
        laughTimer: p.random(0, 100)
      });
    }

    // Initialize door frames
    for(let i = 0; i < 4; i++) {
      doorFrames.push({
        x: 50 + i * 80,
        y: 200,
        glowing: false
      });
    }

    // Initialize energy collection tubes
    for(let i = 0; i < 3; i++) {
      energyTubes.push({
        x: 100 + i * 100,
        y: 100,
        energy: 0
      });
    }

    // Initialize spotlights
    spotlights.push({x: 150, y: 50, intensity: 0.8});
    spotlights.push({x: 250, y: 50, intensity: 0.6});
  };

  p.draw = function() {
    // Bright, joyful gradient background
    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(255, 220, 100), p.color(100, 180, 255), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    bounceOffset += 0.05;
    comedyTimer += 0.03;

    // Draw energy collection system (bright and efficient)
    p.stroke(255, 255, 150);
    p.strokeWeight(3);
    for(let tube of energyTubes) {
      p.noFill();
      p.rect(tube.x - 15, tube.y, 30, 80);

      // Flowing yellow energy
      tube.energy = p.sin(p.frameCount * 0.02 + tube.x * 0.01) * 40 + 40;
      p.fill(255, 255, 100, 150);
      p.noStroke();
      p.rect(tube.x - 12, tube.y + 80 - tube.energy, 24, tube.energy);
    }

    // Draw door frames with warm light
    for(let i = 0; i < doorFrames.length; i++) {
      let door = doorFrames[i];

      // Door frame
      p.stroke(100, 50, 200);
      p.strokeWeight(4);
      p.fill(50, 30, 100);
      p.rect(door.x - 25, door.y - 40, 50, 80);

      // Warm light from children's rooms
      p.noStroke();
      p.fill(255, 200, 100, 100 + p.sin(p.frameCount * 0.05 + i) * 50);
      p.rect(door.x - 20, door.y - 35, 40, 70);

      // Occasional bright flash of laughter
      if(p.frameCount % 120 === i * 30) {
        door.glowing = true;
      }
      if(door.glowing) {
        p.fill(255, 255, 150, 200);
        p.rect(door.x - 30, door.y - 45, 60, 90);
        door.glowing = false;
      }
    }

    // Draw theatrical spotlights
    for(let light of spotlights) {
      p.noStroke();
      p.fill(255, 255, 200, light.intensity * 50);
      for(let r = 100; r > 0; r -= 10) {
        p.fill(255, 255, 200, light.intensity * (100 - r) * 0.5);
        p.ellipse(light.x, light.y, r * 2);
      }
    }

    // Draw laugh floor monsters
    for(let monster of monsters) {
      monster.laughTimer += 0.1;

      // Monster body with joyful colors
      p.fill(monster.color);
      p.stroke(255, 255, 255, 100);
      p.strokeWeight(2);
      let yBounce = p.sin(monster.bounce + bounceOffset) * 8;
      p.ellipse(monster.x, monster.y + yBounce, monster.size, monster.size * 0.8);

      // Happy eyes
      p.fill(255);
      p.noStroke();
      p.ellipse(monster.x - 8, monster.y - 5 + yBounce, 8, 8);
      p.ellipse(monster.x + 8, monster.y - 5 + yBounce, 8, 8);
      p.fill(0);
      p.ellipse(monster.x - 8, monster.y - 5 + yBounce, 4, 4);
      p.ellipse(monster.x + 8, monster.y - 5 + yBounce, 4, 4);

      // Smiling mouth
      p.noFill();
      p.stroke(50);
      p.strokeWeight(3);
      p.arc(monster.x, monster.y + yBounce, 15, 10, 0, p.PI);

      // Generate laugh particles
      if(p.random() < 0.1) {
        laughParticles.push({
          x: monster.x + p.random(-10, 10),
          y: monster.y + yBounce - 15,
          vx: p.random(-1, 1),
          vy: p.random(-3, -1),
          life: 60,
          size: p.random(3, 8),
          hue: p.random(40, 80)
        });
      }
    }

    // Mike Wazowski as star comedian
    p.fill(120, 200, 120);
    p.stroke(255, 255, 255, 150);
    p.strokeWeight(3);
    let mikeBounce = p.sin(comedyTimer * 3) * 15;
    p.ellipse(mikeX, mikeY + mikeBounce, 60, 60);

    // Mike's big eye
    p.fill(255);
    p.noStroke();
    p.ellipse(mikeX, mikeY - 5 + mikeBounce, 35, 35);
    p.fill(0, 150, 0);
    p.ellipse(mikeX, mikeY - 5 + mikeBounce, 20, 20);
    p.fill(0);
    p.ellipse(mikeX + 3, mikeY - 8 + mikeBounce, 8, 8);

    // Mike's arms in performance gesture
    p.stroke(120, 200, 120);
    p.strokeWeight(8);
    let armWave = p.sin(comedyTimer * 4) * 20;
    p.line(mikeX - 30, mikeY + mikeBounce, mikeX - 45 + armWave, mikeY - 10 + mikeBounce);
    p.line(mikeX + 30, mikeY + mikeBounce, mikeX + 45 - armWave, mikeY - 10 + mikeBounce);

    // Comedy stage spotlight on Mike
    p.noStroke();
    p.fill(255, 255, 150, 80);
    p.ellipse(mikeX, mikeY + mikeBounce, 120, 80);

    // Update and draw laugh particles (yellow energy)
    for(let i = laughParticles.length - 1; i >= 0; i--) {
      let particle = laughParticles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life--;
      particle.vy *= 0.98;

      p.noStroke();
      let alpha = p.map(particle.life, 0, 60, 0, 255);
      p.fill(255, 255, particle.hue, alpha);
      p.ellipse(particle.x, particle.y, particle.size);

      // Create sparkle effect
      if(p.random() < 0.3) {
        p.fill(255, 255, 255, alpha * 0.7);
        p.ellipse(particle.x + p.random(-3, 3), particle.y + p.random(-3, 3), 2);
      }

      if(particle.life <= 0) {
        laughParticles.splice(i, 1);
      }
    }

    // Interactive mouse effects
    if(p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      // Create extra sparkles near mouse
      if(p.random() < 0.2) {
        laughParticles.push({
          x: p.mouseX + p.random(-20, 20),
          y: p.mouseY + p.random(-20, 20),
          vx: p.random(-2, 2),
          vy: p.random(-4, -1),
          life: 40,
          size: p.random(4, 10),
          hue: p.random(60, 100)
        });
      }
    }

    // Bright overhead lighting system
    p.noStroke();
    for(let x = 0; x < p.width; x += 40) {
      p.fill(255, 255, 200, 30);
      p.rect(x, 0, 10, 40);
    }
  };

  p.mousePressed = function() {
    // Create burst of celebration particles
    for(let i = 0; i < 10; i++) {
      laughParticles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-4, 4),
        vy: p.random(-6, -2),
        life: 80,
        size: p.random(5, 12),
        hue: p.random(50, 100)
      });
    }
  };
}

function sketch(p) {
  let doorPieces = [];
  let doorShredProgress = 0;
  let sulleyX, sulleyY;
  let booX, booY;
  let doorX, doorY;
  let particles = [];
  let farewellGlow = 0;
  let heartParticles = [];
  let timeElapsed = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize positions
    sulleyX = 120;
    sulleyY = 350;
    booX = 280;
    booY = 320;
    doorX = 250;
    doorY = 200;

    // Create door pieces for shredding effect
    for (let i = 0; i < 20; i++) {
      doorPieces.push({
        x: doorX + p.random(-30, 30),
        y: doorY + p.random(0, 200),
        vx: p.random(-3, 3),
        vy: p.random(1, 5),
        size: p.random(5, 15),
        alpha: 255,
        rotation: p.random(0, p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    timeElapsed += 0.02;

    // Dark, emotional background with subtle corporate elements
    let bg1 = p.color(20, 25, 40);
    let bg2 = p.color(40, 35, 60);
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(bg1, bg2, inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Subtle factory lighting strips
    p.fill(60, 80, 120, 30);
    p.noStroke();
    p.rect(0, 50, p.width, 8);
    p.rect(0, 150, p.width, 6);

    // Door frame (intact initially, then damaged)
    let doorIntegrity = p.map(doorShredProgress, 0, 1, 1, 0);

    if (doorIntegrity > 0.3) {
      p.fill(139, 69, 19, doorIntegrity * 255);
      p.stroke(101, 67, 33, doorIntegrity * 255);
      p.strokeWeight(3);
      p.rect(doorX - 40, doorY, 80, 180);

      // Door details
      p.fill(160, 82, 45, doorIntegrity * 255);
      p.rect(doorX - 35, doorY + 10, 70, 160);

      // Door handle
      p.fill(200, 180, 120, doorIntegrity * 255);
      p.ellipse(doorX + 25, doorY + 90, 8, 8);

      // Flower decoration
      p.fill(255, 100, 150, doorIntegrity * 255);
      for (let i = 0; i < 6; i++) {
        let angle = i * p.PI / 3;
        let fx = doorX + p.cos(angle) * 8;
        let fy = doorY + 40 + p.sin(angle) * 8;
        p.ellipse(fx, fy, 6, 6);
      }
      p.fill(255, 200, 100, doorIntegrity * 255);
      p.ellipse(doorX, doorY + 40, 6, 6);
    }

    // Sulley silhouette - large, protective, gentle
    p.fill(64, 164, 223);
    p.stroke(44, 124, 183);
    p.strokeWeight(2);

    // Sulley's body
    p.ellipse(sulleyX, sulleyY, 80, 120);
    p.ellipse(sulleyX, sulleyY - 80, 60, 80);

    // Sulley's spots
    p.fill(44, 124, 183);
    p.noStroke();
    p.ellipse(sulleyX - 20, sulleyY - 20, 12, 12);
    p.ellipse(sulleyX + 15, sulleyY - 40, 8, 8);
    p.ellipse(sulleyX - 10, sulleyY + 10, 10, 10);

    // Sulley's arms - reaching toward Boo
    p.fill(64, 164, 223);
    p.stroke(44, 124, 183);
    p.strokeWeight(2);
    let armReach = p.sin(timeElapsed * 2) * 5;
    p.ellipse(sulleyX + 35 + armReach, sulleyY - 20, 25, 60);
    p.ellipse(sulleyX + 50 + armReach, sulleyY - 10, 15, 15);

    // Sulley's horns
    p.fill(44, 124, 183);
    p.triangle(sulleyX - 15, sulleyY - 110, sulleyX - 10, sulleyY - 95, sulleyX - 20, sulleyY - 95);
    p.triangle(sulleyX + 15, sulleyY - 110, sulleyX + 20, sulleyY - 95, sulleyX + 10, sulleyY - 95);

    // Boo silhouette - small, precious
    p.fill(255, 200, 180);
    p.stroke(220, 160, 140);
    p.strokeWeight(1);

    // Boo's body
    let booFloat = p.sin(timeElapsed * 3) * 3;
    p.ellipse(booX, booY + booFloat, 20, 30);
    p.ellipse(booX, booY - 15 + booFloat, 18, 18);

    // Boo's hair
    p.fill(101, 67, 33);
    p.ellipse(booX, booY - 20 + booFloat, 20, 12);

    // Connection between them - emotional energy
    farewellGlow = (p.sin(timeElapsed * 1.5) + 1) * 0.5;
    p.stroke(255, 150, 200, farewellGlow * 100);
    p.strokeWeight(2);
    p.line(sulleyX + 30, sulleyY - 30, booX - 10, booY + booFloat);

    // Heart particles - love being released
    if (p.frameCount % 10 === 0) {
      heartParticles.push({
        x: (sulleyX + booX) / 2,
        y: (sulleyY + booY) / 2,
        vx: p.random(-1, 1),
        vy: p.random(-3, -1),
        life: 255,
        size: p.random(3, 8)
      });
    }

    for (let i = heartParticles.length - 1; i >= 0; i--) {
      let h = heartParticles[i];
      h.x += h.vx;
      h.y += h.vy;
      h.life -= 3;

      if (h.life > 0) {
        p.fill(255, 100, 150, h.life);
        p.noStroke();
        p.ellipse(h.x, h.y, h.size, h.size);
        p.ellipse(h.x - h.size/3, h.y - h.size/3, h.size/1.5, h.size/1.5);
        p.ellipse(h.x + h.size/3, h.y - h.size/3, h.size/1.5, h.size/1.5);
      } else {
        heartParticles.splice(i, 1);
      }
    }

    // Door shredding animation
    doorShredProgress += 0.003;
    if (doorShredProgress > 1) doorShredProgress = 1;

    // Animated door pieces falling
    for (let i = 0; i < doorPieces.length; i++) {
      let piece = doorPieces[i];

      if (doorShredProgress > 0.3) {
        piece.y += piece.vy;
        piece.x += piece.vx;
        piece.vy += 0.1; // gravity
        piece.rotation += 0.1;
        piece.alpha -= 2;

        if (piece.alpha > 0) {
          p.push();
          p.translate(piece.x, piece.y);
          p.rotate(piece.rotation);
          p.fill(139, 69, 19, piece.alpha);
          p.noStroke();
          p.rect(-piece.size/2, -piece.size/2, piece.size, piece.size);
          p.pop();
        }
      }
    }

    // Emotional lighting - warm but melancholy
    let lightGlow = (p.sin(timeElapsed) + 1) * 0.3 + 0.4;
    p.fill(255, 200, 100, lightGlow * 30);
    p.noStroke();
    p.ellipse(doorX, doorY + 50, 200, 200);

    // Subtle corporate floor grid
    p.stroke(80, 90, 120, 50);
    p.strokeWeight(1);
    for (let x = 0; x < p.width; x += 40) {
      p.line(x, p.height - 100, x, p.height);
    }
    for (let y = p.height - 100; y < p.height; y += 20) {
      p.line(0, y, p.width, y);
    }
  };

  p.mousePressed = function() {
    // Reset the shredding animation
    doorShredProgress = 0;
    for (let i = 0; i < doorPieces.length; i++) {
      doorPieces[i].x = doorX + p.random(-30, 30);
      doorPieces[i].y = doorY + p.random(0, 200);
      doorPieces[i].alpha = 255;
      doorPieces[i].vy = p.random(1, 5);
    }

    // Add extra heart particles
    for (let i = 0; i < 10; i++) {
      heartParticles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-2, 2),
        vy: p.random(-4, -1),
        life: 255,
        size: p.random(4, 10)
      });
    }
  };

  p.mouseMoved = function() {
    // Subtle interaction - emotional energy follows mouse
    let distance = p.dist(p.mouseX, p.mouseY, (sulleyX + booX) / 2, (sulleyY + booY) / 2);
    farewellGlow = p.map(distance, 0, 200, 1, 0.3);
  };
}

function sketch(p) {
  let door;
  let doorOpen = false;
  let doorOpenness = 0;
  let particles = [];
  let heartParticles = [];
  let glowIntensity = 0;
  let reunionProgress = 0;
  let mike, sulley, boo;
  let doorLight;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize door
    door = {
      x: p.width * 0.6,
      y: p.height * 0.3,
      width: 80,
      height: 120,
      rebuilding: false,
      complete: false
    };

    // Initialize characters
    mike = { x: p.width * 0.25, y: p.height * 0.65, presenting: false };
    sulley = { x: p.width * 0.45, y: p.height * 0.55, reaching: false };
    boo = { x: door.x + 15, y: door.y + 80, visible: false, excitement: 0 };

    doorLight = 0;

    // Create initial magic particles
    for(let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(2, 6),
        speed: p.random(0.5, 2),
        color: p.random(['gold', 'purple', 'pink']),
        alpha: p.random(100, 255)
      });
    }
  };

  p.draw = function() {
    // Gradient background - warm reunion colors
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(20, 30, 60), p.color(60, 40, 80), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Update reunion progress
    reunionProgress += 0.005;
    if(reunionProgress > 1) reunionProgress = 1;

    // Door reconstruction animation
    if(reunionProgress > 0.3 && !door.complete) {
      door.rebuilding = true;
      if(reunionProgress > 0.6) {
        door.complete = true;
        doorLight = p.map(reunionProgress, 0.6, 1, 0, 255);
      }
    }

    // Draw floating particles
    drawParticles();

    // Draw Mike presenting the door
    drawMike();

    // Draw the magical door
    drawDoor();

    // Draw Sulley
    drawSulley();

    // Draw Boo if door is open
    if(doorOpenness > 0.3) {
      drawBoo();
    }

    // Draw heart particles when reunion happens
    if(reunionProgress > 0.8) {
      drawHeartParticles();
    }

    // Interactive glow effect
    let mouseDistance = p.dist(p.mouseX, p.mouseY, door.x, door.y);
    glowIntensity = p.map(mouseDistance, 0, 200, 100, 0);
    glowIntensity = p.constrain(glowIntensity, 0, 100);
  };

  function drawParticles() {
    for(let particle of particles) {
      p.push();
      p.translate(particle.x, particle.y);

      let colorMap = {
        'gold': [255, 215, 0],
        'purple': [147, 112, 219],
        'pink': [255, 182, 193]
      };

      let col = colorMap[particle.color];
      p.fill(col[0], col[1], col[2], particle.alpha);
      p.noStroke();

      let pulse = p.sin(p.millis() * 0.01 + particle.x) * 2;
      p.ellipse(0, 0, particle.size + pulse);

      particle.y -= particle.speed;
      particle.alpha -= 0.5;

      if(particle.y < -10 || particle.alpha <= 0) {
        particle.y = p.height + 10;
        particle.x = p.random(p.width);
        particle.alpha = p.random(100, 255);
      }

      p.pop();
    }
  }

  function drawMike() {
    p.push();
    p.translate(mike.x, mike.y);

    // Mike's presenting gesture
    let presentAnim = p.sin(p.millis() * 0.008) * 5;
    if(reunionProgress > 0.2) {
      mike.presenting = true;
    }

    // Mike's body (green circle)
    p.fill(100, 200, 100);
    p.stroke(80, 160, 80);
    p.strokeWeight(2);
    p.ellipse(0, 0, 40, 40);

    // Mike's eye
    p.fill(255);
    p.ellipse(0, -5, 25, 25);
    p.fill(0);
    p.ellipse(2, -3, 8, 8);

    // Arms - presenting gesture
    if(mike.presenting) {
      p.stroke(100, 200, 100);
      p.strokeWeight(4);
      p.line(-20, 5, -35 + presentAnim, -10);
      p.line(20, 5, door.x - mike.x - 10, door.y - mike.y);
    }

    p.pop();
  }

  function drawDoor() {
    p.push();
    p.translate(door.x, door.y);

    // Door glow
    if(door.complete || glowIntensity > 0) {
      p.fill(255, 255, 200, glowIntensity + doorLight * 0.3);
      p.noStroke();
      p.ellipse(0, door.height/2, door.width + 40, door.height + 40);
    }

    // Door frame - rebuilding effect
    if(door.rebuilding) {
      p.stroke(139, 69, 19);
      p.strokeWeight(6);
      p.fill(101, 67, 33);

      let buildProgress = p.map(reunionProgress, 0.3, 0.6, 0, 1);
      buildProgress = p.constrain(buildProgress, 0, 1);

      // Animated construction
      if(buildProgress < 1) {
        for(let i = 0; i < buildProgress * 20; i++) {
          let y = p.map(i, 0, 20, 0, door.height);
          p.rect(-door.width/2, y - 3, door.width, 6);
        }
      } else {
        p.rect(-door.width/2, 0, door.width, door.height);
      }

      // Door handle
      if(buildProgress > 0.7) {
        p.fill(255, 215, 0);
        p.ellipse(door.width/2 - 10, door.height/2, 8, 8);
      }
    }

    // Door opening effect
    if(door.complete && reunionProgress > 0.7) {
      doorOpenness = p.map(reunionProgress, 0.7, 0.9, 0, 1);
      doorOpenness = p.constrain(doorOpenness, 0, 1);

      // Light from other side
      if(doorOpenness > 0) {
        p.fill(255, 255, 200, doorOpenness * 200);
        p.noStroke();
        p.rect(-door.width/2 + (door.width * doorOpenness), 0, door.width * (1 - doorOpenness), door.height);
      }
    }

    p.pop();
  }

  function drawSulley() {
    p.push();
    p.translate(sulley.x, sulley.y);

    // Sulley's body (blue and furry)
    p.fill(70, 130, 180);
    p.stroke(50, 100, 150);
    p.strokeWeight(2);
    p.ellipse(0, 0, 60, 80);

    // Purple spots
    p.fill(138, 43, 226);
    p.noStroke();
    p.ellipse(-15, -10, 12, 12);
    p.ellipse(10, 5, 8, 8);
    p.ellipse(-5, 20, 10, 10);

    // Sulley reaching toward door
    if(reunionProgress > 0.75) {
      sulley.reaching = true;
      p.stroke(70, 130, 180);
      p.strokeWeight(8);
      let reachX = door.x - sulley.x - 20;
      let reachY = door.y - sulley.y + 10;
      p.line(25, -10, reachX, reachY);
    }

    // Horns
    p.fill(150, 75, 0);
    p.triangle(-8, -40, -12, -55, -4, -55);
    p.triangle(8, -40, 4, -55, 12, -55);

    p.pop();
  }

  function drawBoo() {
    if(!boo.visible && doorOpenness > 0.3) {
      boo.visible = true;
    }

    if(boo.visible) {
      p.push();
      p.translate(boo.x, boo.y);

      // Boo's excitement animation
      boo.excitement += 0.1;
      let bounce = p.sin(boo.excitement) * 3;

      // Boo's body
      p.fill(255, 182, 193);
      p.noStroke();
      p.ellipse(0, bounce, 20, 25);

      // Hair
      p.fill(139, 69, 19);
      p.ellipse(0, bounce - 15, 22, 15);

      // Arms reaching out
      if(reunionProgress > 0.85) {
        p.stroke(255, 182, 193);
        p.strokeWeight(3);
        p.line(-10, bounce - 5, -20, bounce - 15);
        p.line(10, bounce - 5, 20, bounce - 15);
      }

      p.pop();
    }
  }

  function drawHeartParticles() {
    // Create heart particles
    if(p.frameCount % 20 === 0) {
      heartParticles.push({
        x: door.x,
        y: door.y + 60,
        vx: p.random(-2, 2),
        vy: p.random(-3, -1),
        size: p.random(8, 15),
        life: 255
      });
    }

    for(let i = heartParticles.length - 1; i >= 0; i--) {
      let heart = heartParticles[i];

      p.push();
      p.translate(heart.x, heart.y);
      p.fill(255, 105, 180, heart.life);
      p.noStroke();

      // Draw heart shape
      p.scale(heart.size / 20);
      p.beginShape();
      for(let a = 0; a < p.TWO_PI; a += 0.1) {
        let x = 16 * p.pow(p.sin(a), 3);
        let y = -(13 * p.cos(a) - 5 * p.cos(2*a) - 2 * p.cos(3*a) - p.cos(4*a));
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);
      p.pop();

      heart.x += heart.vx;
      heart.y += heart.vy;
      heart.life -= 3;

      if(heart.life <= 0) {
        heartParticles.splice(i, 1);
      }
    }
  }

  p.mousePressed = function() {
    // Advance reunion when clicked
    if(reunionProgress < 1) {
      reunionProgress = p.min(reunionProgress + 0.2, 1);
    }
  };
}

function sketch(p) {
  let sparkPosition;
  let doorCrack = 0;
  let targetDoorCrack = 0;
  let meters = [];
  let gauges = [];
  let sparkIntensity = 0;
  let targetSparkIntensity = 0;
  let fluorescent;
  let particles = [];

  p.setup = function() {
    p.createCanvas(400, 600);
    sparkPosition = p.createVector(200, 300);

    // Create measurement meters along the sides
    for(let i = 0; i < 4; i++) {
      meters.push({
        x: 50,
        y: 100 + i * 120,
        value: p.random(0.3, 0.8),
        targetValue: p.random(0.3, 0.8),
        label: i
      });
    }

    // Create gauges
    for(let i = 0; i < 3; i++) {
      gauges.push({
        x: 350,
        y: 150 + i * 150,
        angle: p.random(-p.PI/3, p.PI/3),
        targetAngle: p.random(-p.PI/3, p.PI/3)
      });
    }

    // Fluorescent flicker setup
    fluorescent = {
      brightness: 255,
      flicker: 0
    };
  };

  p.draw = function() {
    // Corporate cold background
    p.background(220, 230, 235);

    // Fluorescent lighting effect
    fluorescent.flicker += 0.1;
    fluorescent.brightness = 240 + p.sin(fluorescent.flicker) * 15 + p.random(-5, 5);

    // Grid floor pattern
    p.stroke(180, 200, 210);
    p.strokeWeight(1);
    for(let x = 0; x < 400; x += 40) {
      p.line(x, 500, x, 600);
    }
    for(let y = 500; y < 600; y += 40) {
      p.line(0, y, 400, y);
    }

    // Yellow caution stripes
    p.fill(255, 220, 0);
    p.noStroke();
    for(let i = 0; i < 3; i++) {
      let y = 480 + i * 15;
      for(let x = 0; x < 400; x += 60) {
        p.rect(x, y, 30, 8);
      }
    }

    // Industrial ceiling
    p.fill(200, 210, 220);
    p.rect(0, 0, 400, 80);

    // Fluorescent light strips
    p.fill(fluorescent.brightness, fluorescent.brightness, fluorescent.brightness - 20);
    p.rect(50, 20, 300, 15);
    p.rect(50, 45, 300, 15);

    // Door outline (industrial metal)
    p.fill(120, 140, 160);
    p.stroke(80, 100, 120);
    p.strokeWeight(3);
    p.rect(150, 200, 100, 200);

    // Door crack opening based on mouse proximity
    let mouseDistance = p.dist(p.mouseX, p.mouseY, 200, 300);
    targetDoorCrack = p.map(mouseDistance, 0, 200, 15, 0);
    targetDoorCrack = p.constrain(targetDoorCrack, 0, 15);
    doorCrack = p.lerp(doorCrack, targetDoorCrack, 0.05);

    // The spark - central point of light
    targetSparkIntensity = p.map(doorCrack, 0, 15, 0, 1);
    sparkIntensity = p.lerp(sparkIntensity, targetSparkIntensity, 0.08);

    // Door crack
    if(doorCrack > 0) {
      p.fill(10, 5, 20);
      p.noStroke();
      p.rect(200 - doorCrack/2, 200, doorCrack, 200);

      // Light bleeding through
      p.fill(255, 255, 200, 150 * sparkIntensity);
      p.rect(200 - doorCrack/2, 200, doorCrack, 200);
    }

    // The spark itself
    if(sparkIntensity > 0) {
      p.push();
      p.translate(sparkPosition.x, sparkPosition.y);

      // Outer glow
      for(let r = 60; r > 0; r -= 5) {
        p.fill(100, 200, 255, (1 - r/60) * sparkIntensity * 30);
        p.noStroke();
        p.ellipse(0, 0, r * sparkIntensity);
      }

      // Core light
      p.fill(255, 255, 255, 255 * sparkIntensity);
      p.ellipse(0, 0, 8 * sparkIntensity);

      p.pop();

      // Particle system
      if(p.frameCount % 3 == 0 && sparkIntensity > 0.3) {
        particles.push({
          x: sparkPosition.x,
          y: sparkPosition.y,
          vx: p.random(-2, 2),
          vy: p.random(-3, -1),
          life: 1.0,
          size: p.random(2, 4)
        });
      }
    }

    // Update and draw particles
    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 0.02;

      if(particle.life <= 0) {
        particles.splice(i, 1);
        continue;
      }

      p.fill(150, 220, 255, particle.life * 200);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size * particle.life);
    }

    // Measurement meters
    p.stroke(60, 80, 100);
    p.strokeWeight(2);
    for(let meter of meters) {
      meter.value = p.lerp(meter.value, meter.targetValue, 0.02);

      // Meter housing
      p.fill(180, 190, 200);
      p.rect(meter.x - 15, meter.y - 25, 30, 50);

      // Meter fill
      let fillHeight = meter.value * 40;
      if(sparkIntensity > 0.5) {
        p.fill(255, 100, 100); // Red when active
      } else {
        p.fill(100, 150, 200);
      }
      p.rect(meter.x - 12, meter.y + 22 - fillHeight, 24, fillHeight);

      // Meter scale lines
      p.stroke(100, 120, 140);
      p.strokeWeight(1);
      for(let j = 0; j <= 4; j++) {
        let lineY = meter.y + 20 - j * 10;
        p.line(meter.x - 15, lineY, meter.x - 8, lineY);
      }
    }

    // Gauges
    for(let gauge of gauges) {
      gauge.angle = p.lerp(gauge.angle, gauge.targetAngle, 0.03);

      p.push();
      p.translate(gauge.x, gauge.y);

      // Gauge housing
      p.fill(160, 170, 180);
      p.stroke(120, 130, 140);
      p.strokeWeight(2);
      p.ellipse(0, 0, 40);

      // Gauge needle
      p.stroke(200, 50, 50);
      p.strokeWeight(3);
      p.line(0, 0, p.cos(gauge.angle - p.PI/2) * 15, p.sin(gauge.angle - p.PI/2) * 15);

      // Center dot
      p.fill(80, 90, 100);
      p.noStroke();
      p.ellipse(0, 0, 6);

      p.pop();
    }

    // Update meter targets based on spark activity
    if(p.frameCount % 60 == 0) {
      for(let meter of meters) {
        if(sparkIntensity > 0.3) {
          meter.targetValue = p.random(0.6, 1.0);
        } else {
          meter.targetValue = p.random(0.2, 0.5);
        }
      }

      for(let gauge of gauges) {
        if(sparkIntensity > 0.3) {
          gauge.targetAngle = p.random(0, p.PI/2);
        } else {
          gauge.targetAngle = p.random(-p.PI/3, 0);
        }
      }
    }

    // ID badge detail
    p.fill(240, 240, 240);
    p.stroke(150, 150, 150);
    p.strokeWeight(1);
    p.rect(20, 520, 60, 40);
    p.fill(100, 150, 200);
    p.noStroke();
    p.rect(25, 525, 10, 8);
    p.rect(40, 525, 30, 4);
    p.rect(40, 535, 20, 3);

    // Performance chart
    p.fill(240, 240, 240);
    p.stroke(150, 150, 150);
    p.strokeWeight(1);
    p.rect(320, 520, 60, 40);
    p.stroke(200, 80, 80);
    p.strokeWeight(2);
    p.noFill();
    p.beginShape();
    for(let i = 0; i < 6; i++) {
      let x = 325 + i * 8;
      let y = 550 - sparkIntensity * 20 - p.sin(p.frameCount * 0.1 + i) * 5;
      p.vertex(x, y);
    }
    p.endShape();
  };

  p.mousePressed = function() {
    // Spark reaction to clicks
    sparkPosition.x += p.random(-10, 10);
    sparkPosition.y += p.random(-10, 10);
    sparkPosition.x = p.constrain(sparkPosition.x, 180, 220);
    sparkPosition.y = p.constrain(sparkPosition.y, 280, 320);

    // Create burst of particles
    for(let i = 0; i < 8; i++) {
      particles.push({
        x: sparkPosition.x,
        y: sparkPosition.y,
        vx: p.random(-4, 4),
        vy: p.random(-5, -2),
        life: 1.0,
        size: p.random(3, 6)
      });
    }
  };
}

function sketch(p) {
  let scareMeters = [];
  let doors = [];
  let fluorescents = [];
  let gaugeNeedles = [];
  let particleSystem = [];
  let mouseInfluence = 0;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize scare meters
    for(let i = 0; i < 4; i++) {
      scareMeters.push({
        x: 50 + i * 80,
        y: 150,
        value: p.random(0.3, 0.9),
        target: p.random(0.3, 0.9)
      });
    }

    // Initialize doors (two paths)
    doors.push({
      x: 120,
      y: 300,
      width: 60,
      height: 120,
      color: p.color(255, 100, 100),
      glowing: false
    });

    doors.push({
      x: 220,
      y: 300,
      width: 60,
      height: 120,
      color: p.color(100, 255, 100),
      glowing: false
    });

    // Initialize fluorescent lights
    for(let i = 0; i < 3; i++) {
      fluorescents.push({
        x: 50 + i * 150,
        y: 40,
        width: 100,
        flicker: p.random(0.8, 1.0)
      });
    }

    // Initialize gauge needles
    for(let i = 0; i < 2; i++) {
      gaugeNeedles.push({
        x: 100 + i * 200,
        y: 480,
        angle: p.random(-p.PI/3, p.PI/3),
        targetAngle: p.random(-p.PI/3, p.PI/3)
      });
    }
  };

  p.draw = function() {
    time += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, 400, 0, 1);

    // Background - cold industrial gray
    p.background(220, 225, 230);

    // Fluorescent lighting effect
    p.push();
    p.noStroke();
    for(let light of fluorescents) {
      light.flicker = p.lerp(light.flicker, 0.9 + p.random(-0.1, 0.1), 0.1);
      p.fill(255, 255, 240, light.flicker * 100);
      p.rect(light.x, light.y, light.width, 20);

      // Light beam
      let alpha = light.flicker * 30;
      p.fill(255, 255, 240, alpha);
      p.rect(light.x, light.y + 20, light.width, 560);
    }
    p.pop();

    // Yellow caution stripes
    p.push();
    p.stroke(255, 220, 0);
    p.strokeWeight(8);
    for(let i = 0; i < 400; i += 40) {
      if((i / 20) % 2 === 0) {
        p.line(i, 250, i + 20, 250);
        p.line(i, 450, i + 20, 450);
      }
    }
    p.pop();

    // Scare meters at top
    p.push();
    for(let meter of scareMeters) {
      meter.value = p.lerp(meter.value, meter.target, 0.02);

      if(p.random() < 0.01) {
        meter.target = p.random(0.2, 0.95);
      }

      // Meter housing
      p.fill(50);
      p.rect(meter.x - 15, meter.y - 40, 30, 80);

      // Meter fill
      let meterHeight = meter.value * 70;
      p.fill(255, 50, 50, 180);
      p.rect(meter.x - 12, meter.y + 30 - meterHeight, 24, meterHeight);

      // Meter glass reflection
      p.fill(255, 255, 255, 60);
      p.rect(meter.x - 15, meter.y - 40, 10, 80);
    }
    p.pop();

    // Two doors (the choice)
    p.push();
    for(let i = 0; i < doors.length; i++) {
      let door = doors[i];
      let distToMouse = p.dist(p.mouseX, p.mouseY, door.x + door.width/2, door.y + door.height/2);
      door.glowing = distToMouse < 60;

      // Door shadow
      p.fill(0, 50);
      p.rect(door.x + 5, door.y + 5, door.width, door.height);

      // Door body
      if(door.glowing) {
        p.fill(p.red(door.color) + 50, p.green(door.color) + 50, p.blue(door.color) + 50);

        // Glow effect
        p.push();
        p.drawingContext.shadowColor = door.color;
        p.drawingContext.shadowBlur = 20;
        p.rect(door.x, door.y, door.width, door.height);
        p.pop();
      } else {
        p.fill(door.color);
      }

      p.rect(door.x, door.y, door.width, door.height);

      // Door handle
      p.fill(220, 220, 100);
      p.ellipse(door.x + door.width - 10, door.y + door.height/2, 8, 8);

      // Door number
      p.fill(255);
      p.textAlign(p.CENTER, p.CENTER);
      p.textSize(24);
      p.text(i + 1, door.x + door.width/2, door.y + door.height/2);
    }
    p.pop();

    // Performance gauges at bottom
    p.push();
    for(let i = 0; i < gaugeNeedles.length; i++) {
      let gauge = gaugeNeedles[i];
      gauge.angle = p.lerp(gauge.angle, gauge.targetAngle, 0.03);

      if(p.random() < 0.008) {
        gauge.targetAngle = p.random(-p.PI/3, p.PI/3);
      }

      // Gauge face
      p.fill(40);
      p.ellipse(gauge.x, gauge.y, 80, 80);

      // Gauge markings
      p.stroke(255);
      p.strokeWeight(1);
      for(let a = -p.PI/3; a <= p.PI/3; a += p.PI/12) {
        let x1 = gauge.x + p.cos(a - p.PI/2) * 30;
        let y1 = gauge.y + p.sin(a - p.PI/2) * 30;
        let x2 = gauge.x + p.cos(a - p.PI/2) * 35;
        let y2 = gauge.y + p.sin(a - p.PI/2) * 35;
        p.line(x1, y1, x2, y2);
      }

      // Gauge needle
      p.stroke(255, 100, 100);
      p.strokeWeight(3);
      let needleX = gauge.x + p.cos(gauge.angle - p.PI/2) * 25;
      let needleY = gauge.y + p.sin(gauge.angle - p.PI/2) * 25;
      p.line(gauge.x, gauge.y, needleX, needleY);

      // Center dot
      p.fill(255);
      p.noStroke();
      p.ellipse(gauge.x, gauge.y, 8, 8);
    }
    p.pop();

    // Leaderboard display
    p.push();
    p.fill(20, 120);
    p.rect(20, 50, 120, 80);
    p.fill(0, 255, 0);
    p.textAlign(p.LEFT, p.TOP);
    p.textSize(10);
    p.text("LEADERBOARD", 25, 55);
    p.text("1. SULLIVAN", 25, 70);
    p.text("2. WAZOWSKI", 25, 85);
    p.text("3. RANDALL", 25, 100);
    p.text("4. FUNGUS", 25, 115);
    p.pop();

    // ID badge effect
    p.push();
    p.fill(255);
    p.rect(280, 50, 60, 40);
    p.fill(0);
    p.textAlign(p.LEFT, p.TOP);
    p.textSize(8);
    p.text("EMPLOYEE", 285, 55);
    p.text("ID: 2319", 285, 65);
    p.text("SCARE FL.", 285, 75);
    p.pop();

    // Energy particles between choices
    if(p.frameCount % 10 === 0) {
      particleSystem.push({
        x: 200,
        y: 260,
        vx: p.random(-2, 2),
        vy: p.random(-1, 1),
        life: 60,
        maxLife: 60
      });
    }

    for(let i = particleSystem.length - 1; i >= 0; i--) {
      let particle = particleSystem[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life--;

      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 255);
      p.fill(255, 255, 0, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, 4, 4);

      if(particle.life <= 0) {
        particleSystem.splice(i, 1);
      }
    }

    // Central division line
    p.push();
    p.stroke(100);
    p.strokeWeight(2);
    p.line(200, 280, 200, 420);
    p.pop();
  };

  p.mousePressed = function() {
    // Reset all meter targets on click
    for(let meter of scareMeters) {
      meter.target = p.random(0.1, 1.0);
    }

    // Reset gauge targets
    for(let gauge of gaugeNeedles) {
      gauge.targetAngle = p.random(-p.PI/3, p.PI/3);
    }
  };
}

function sketch(p) {
  let monsters = [];
  let connections = [];
  let meters = [];
  let particles = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create three main monster positions in triangular formation
    let positions = [
      {x: 200, y: 180},
      {x: 120, y: 320},
      {x: 280, y: 320}
    ];

    // Initialize monsters
    for (let i = 0; i < 3; i++) {
      monsters.push({
        x: positions[i].x,
        y: positions[i].y,
        size: p.random(30, 45),
        color: p.color(p.random([52, 255, 100]), p.random([165, 87, 255]), p.random([255, 52, 165])),
        energy: p.random(0.8, 1.2),
        badge: p.random(100, 999),
        quota: p.random(50, 150)
      });
    }

    // Initialize connections
    for (let i = 0; i < monsters.length; i++) {
      for (let j = i + 1; j < monsters.length; j++) {
        connections.push({
          from: i,
          to: j,
          strength: p.random(0.3, 0.8),
          pulse: p.random(0, p.TWO_PI)
        });
      }
    }

    // Initialize meters
    for (let i = 0; i < 5; i++) {
      meters.push({
        x: 30 + i * 70,
        y: 520,
        value: p.random(0.3, 0.9),
        target: p.random(0.3, 0.9),
        label: p.floor(p.random(100, 999))
      });
    }
  };

  p.draw = function() {
    time += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);

    // Industrial background
    p.background(35, 45, 55);

    // Fluorescent lighting effect
    p.fill(240, 255, 245, 20);
    p.noStroke();
    for (let i = 0; i < 3; i++) {
      p.rect(0, i * 200, p.width, 100);
    }

    // Warning stripes
    p.stroke(255, 200, 0);
    p.strokeWeight(8);
    for (let i = 0; i < 6; i++) {
      let y = 450 + i * 20;
      for (let x = 0; x < p.width; x += 40) {
        p.line(x, y, x + 20, y);
      }
    }

    // Draw connections first (behind monsters)
    p.strokeWeight(3);
    for (let conn of connections) {
      let m1 = monsters[conn.from];
      let m2 = monsters[conn.to];

      let alpha = 100 + 80 * p.sin(time * 2 + conn.pulse);
      alpha *= conn.strength;
      alpha += mouseInfluence * 50;

      p.stroke(0, 255, 150, alpha);
      p.line(m1.x, m1.y, m2.x, m2.y);

      // Connection nodes
      let midX = (m1.x + m2.x) / 2;
      let midY = (m1.y + m2.y) / 2;
      p.fill(0, 255, 150, alpha);
      p.noStroke();
      p.circle(midX, midY, 6 + 3 * p.sin(time * 3 + conn.pulse));
    }

    // Draw expanding network lines
    p.stroke(0, 200, 255, 30);
    p.strokeWeight(1);
    for (let monster of monsters) {
      let radius = 80 + 30 * p.sin(time + monster.energy);
      radius *= (1 + mouseInfluence * 0.5);

      for (let angle = 0; angle < p.TWO_PI; angle += p.PI / 6) {
        let x2 = monster.x + p.cos(angle + time) * radius;
        let y2 = monster.y + p.sin(angle + time) * radius;
        p.line(monster.x, monster.y, x2, y2);
      }
    }

    // Draw monsters
    for (let i = 0; i < monsters.length; i++) {
      let monster = monsters[i];

      // Monster body
      p.fill(monster.color);
      p.noStroke();
      let bobY = monster.y + 5 * p.sin(time * 2 + monster.energy);
      p.circle(monster.x, bobY, monster.size);

      // Eyes
      p.fill(255);
      let eyeSize = monster.size * 0.3;
      p.circle(monster.x - monster.size * 0.2, bobY - monster.size * 0.1, eyeSize);
      p.circle(monster.x + monster.size * 0.2, bobY - monster.size * 0.1, eyeSize);

      // Pupils
      p.fill(0);
      let pupilOffset = mouseInfluence * 3;
      p.circle(monster.x - monster.size * 0.2 + pupilOffset, bobY - monster.size * 0.1, eyeSize * 0.5);
      p.circle(monster.x + monster.size * 0.2 + pupilOffset, bobY - monster.size * 0.1, eyeSize * 0.5);

      // ID Badge
      p.fill(255, 255, 255, 200);
      p.stroke(100);
      p.strokeWeight(1);
      p.rect(monster.x - 15, bobY + monster.size * 0.3, 30, 15, 2);

      // Badge number
      p.fill(0);
      p.noStroke();
      p.textAlign(p.CENTER, p.CENTER);
      p.textSize(8);
      p.text(monster.badge, monster.x, bobY + monster.size * 0.37);
    }

    // Performance meters at bottom
    p.fill(40, 50, 60);
    p.noStroke();
    p.rect(10, 500, p.width - 20, 80, 5);

    for (let meter of meters) {
      // Update meter values
      meter.value = p.lerp(meter.value, meter.target, 0.02);
      if (p.random() < 0.01) {
        meter.target = p.random(0.2, 0.95);
      }

      // Meter background
      p.fill(20, 25, 30);
      p.rect(meter.x - 25, meter.y, 50, 40, 3);

      // Meter fill
      let meterHeight = meter.value * 35;
      let meterColor = p.color(
        p.lerp(255, 0, meter.value),
        p.lerp(0, 255, meter.value),
        0
      );
      p.fill(meterColor);
      p.rect(meter.x - 23, meter.y + 35 - meterHeight, 46, meterHeight);

      // Meter label
      p.fill(200);
      p.textAlign(p.CENTER, p.CENTER);
      p.textSize(10);
      p.text(meter.label, meter.x, meter.y + 50);
    }

    // Title area with corporate styling
    p.fill(0, 0, 0, 100);
    p.noStroke();
    p.rect(0, 0, p.width, 80);

    // Leaderboard display
    p.fill(0, 255, 100);
    p.textAlign(p.LEFT, p.CENTER);
    p.textSize(12);
    p.text("SCARE METRICS", 20, 30);

    p.fill(255, 200);
    p.textSize(10);
    for (let i = 0; i < 3; i++) {
      p.text(`#${i + 1}: ${monsters[i].quota} pts`, 20, 50 + i * 15);
    }

    // Particle system for energy
    if (p.frameCount % 3 === 0) {
      for (let monster of monsters) {
        particles.push({
          x: monster.x + p.random(-20, 20),
          y: monster.y + p.random(-20, 20),
          vx: p.random(-1, 1),
          vy: p.random(-2, -0.5),
          life: 1,
          size: p.random(2, 6)
        });
      }
    }

    // Update and draw particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 0.02;

      if (particle.life <= 0) {
        particles.splice(i, 1);
        continue;
      }

      p.fill(0, 255, 150, particle.life * 200);
      p.noStroke();
      p.circle(particle.x, particle.y, particle.size * particle.life);
    }
  };

  p.mousePressed = function() {
    // Pulse effect on click
    for (let conn of connections) {
      conn.pulse += p.random(-0.5, 0.5);
      conn.strength = p.min(1, conn.strength + 0.3);
    }
  };
}

