      // Gauge background
      p.fill(40, 50, 60);
      p.stroke(80, 90, 100);
      p.strokeWeight(2);
      p.ellipse(gauge.x, gauge.y, gauge.size * 2);

      // Gauge fill
      p.fill(255, 100, 100, 150);
      p.noStroke();
      p.arc(gauge.x, gauge.y, gauge.size * 1.5, gauge.size * 1.5, -p.PI/2, -p.PI/2 + gauge.value * p.TWO_PI);

      // Gauge needle
      let angle = -p.PI/2 + gauge.value * p.TWO_PI;
      p.stroke(255);
      p.strokeWeight(2);
      p.line(gauge.x, gauge.y, 
             gauge.x + p.cos(angle) * gauge.size * 0.7, 
             gauge.y + p.sin(angle) * gauge.size * 0.7);
    }

    // Performance metrics leaderboard
    leaderboardY = p.sin(p.millis() * 0.001) * 5;
    p.fill(20, 30, 40, 200);
    p.stroke(100, 120, 140);
    p.strokeWeight(2);
    p.rect(20, 200 + leaderboardY, 120, 80);

    p.fill(0, 255, 150);
    p.noStroke();
    p.textSize(8);
    p.text("SCARE METRICS", 25, 215 + leaderboardY);
    p.text("Target: 2319", 25, 230 + leaderboardY);
    p.text("Current: " + p.int(2000 + mouseInfluence * 319), 25, 245 + leaderboardY);
    p.text("Efficiency: " + p.int(85 + mouseInfluence * 15) + "%", 25, 260 + leaderboardY);

    // Quota tracking system
    p.fill(255, 220, 0, 180);
    p.noStroke();
    p.rect(250, 180, 130, 20);
    p.fill(0);
    p.textSize(10);
    p.text("DAILY QUOTA", 255, 195);

    let quotaFill = p.map(p.mouseY, 600, 0, 0, 130);
    p.fill(255, 100, 100);
    p.rect(250, 200, quotaFill, 15);
    p.fill(200);
    p.rect(250 + quotaFill, 200, 130 - quotaFill, 15);

    // Efficiency particle system
    for (let particle of particles) {
      particle.x += particle.vx + mouseInfluence * 0.5;
      particle.y += particle.vy;

      if (particle.x < 0 || particle.x > 400) particle.vx *= -1;
      if (particle.y < 0 || particle.y > 600) particle.vy *= -1;

      p.fill(100, 200, 255, particle.alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Corporate construction framework
    p.stroke(255, 220, 0);
    p.strokeWeight(4);
    p.noFill();
    p.rect(40, 300, 320, 200);

    // Diagonal support beams
    p.line(40, 300, 360, 500);
    p.line(360, 300, 40, 500);

    // Interactive response - system stress visualization
    if (p.mouseIsPressed) {
      for (let i = 0; i < 10; i++) {
        p.fill(255, 0, 0, 100);
        p.noStroke();
        p.ellipse(p.mouseX + p.random(-20, 20), p.mouseY + p.random(-20, 20), p.random(5, 15));
      }

      // Update gauge targets when stressed
      for (let gauge of gauges) {
        gauge.targetValue = p.random(0.8, 1.0);
      }
    }
  };

  p.mousePressed = function() {
    // Reset efficiency when clicking
    foundationAlpha = 255;
    for (let gauge of gauges) {
      gauge.targetValue = p.random(0.1, 0.4);
    }
  };
}

function sketch(p) {
  let crackLines = [];
  let gauges = [];
  let particles = [];
  let leaderboard = [];
  let glitchOffset = 0;
  let crackProgress = 0;
  let warningLights = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize crack lines
    for(let i = 0; i < 5; i++) {
      crackLines.push({
        x: 200 + p.random(-30, 30),
        y: 300 + p.random(-50, 50),
        segments: [],
        growing: false,
        maxLength: p.random(80, 120)
      });
    }

    // Initialize gauges
    for(let i = 0; i < 4; i++) {
      gauges.push({
        x: 50 + i * 80,
        y: 150,
        value: p.random(0.7, 0.9),
        target: p.random(0.7, 0.9),
        glitching: false
      });
    }

    // Initialize leaderboard entries
    for(let i = 0; i < 5; i++) {
      leaderboard.push({
        score: Math.floor(p.random(800, 999)),
        glitching: false,
        originalScore: 0
      });
    }

    // Initialize warning lights
    for(let i = 0; i < 3; i++) {
      warningLights.push({
        x: 60 + i * 140,
        y: 50,
        on: false,
        timer: p.random(60, 120)
      });
    }

    // Generate initial crack segments
    for(let crack of crackLines) {
      let angle = p.random(p.TWO_PI);
      for(let j = 0; j < 8; j++) {
        crack.segments.push({
          x: crack.x + p.cos(angle) * j * 10,
          y: crack.y + p.sin(angle) * j * 10,
          visible: false
        });
        angle += p.random(-0.3, 0.3);
      }
    }
  };

  p.draw = function() {
    // Industrial background
    p.background(240, 245, 250);

    // Grid pattern
    p.stroke(200, 210, 220);
    p.strokeWeight(1);
    for(let i = 0; i < 400; i += 20) {
      p.line(i, 0, i, 600);
    }
    for(let i = 0; i < 600; i += 20) {
      p.line(0, i, 400, i);
    }

    // Yellow caution stripes
    p.fill(255, 220, 0);
    p.noStroke();
    for(let i = 0; i < 3; i++) {
      let y = 80 + i * 200;
      for(let x = -20; x < 420; x += 40) {
        p.rect(x, y, 20, 8);
      }
    }

    // Warning lights
    for(let light of warningLights) {
      light.timer--;
      if(light.timer <= 0) {
        light.on = !light.on;
        light.timer = p.random(30, 90);
      }

      p.fill(light.on ? p.color(255, 50, 50) : p.color(100, 30, 30));
      p.noStroke();
      p.circle(light.x, light.y, 15);

      if(light.on) {
        p.fill(255, 50, 50, 50);
        p.circle(light.x, light.y, 25);
      }
    }

    // Performance gauges
    for(let gauge of gauges) {
      // Gauge background
      p.fill(50);
      p.noStroke();
      p.rect(gauge.x - 25, gauge.y - 15, 50, 30, 5);

      // Gauge fill
      let displayValue = gauge.value;
      if(gauge.glitching) {
        displayValue += p.random(-0.3, 0.3);
      }

      p.fill(displayValue > 0.8 ? p.color(50, 255, 50) : p.color(255, 200, 50));
      p.rect(gauge.x - 23, gauge.y - 13, 46 * displayValue, 26, 3);

      // Gauge border
      p.noFill();
      p.stroke(200);
      p.strokeWeight(2);
      p.rect(gauge.x - 25, gauge.y - 15, 50, 30, 5);
    }

    // Leaderboard
    p.fill(40);
    p.noStroke();
    p.rect(280, 200, 110, 150, 5);

    p.fill(255);
    p.textAlign(p.LEFT);
    p.textSize(10);
    p.text("SCARE LEADERS", 285, 215);

    for(let i = 0; i < leaderboard.length; i++) {
      let entry = leaderboard[i];
      let displayScore = entry.score;

      if(entry.glitching) {
        displayScore = Math.floor(p.random(100, 999));
      }

      p.fill(200);
      p.text(`${i + 1}. ${displayScore}`, 285, 230 + i * 15);
    }

    // Mouse interaction triggers disruption
    let mouseNear = p.dist(p.mouseX, p.mouseY, 200, 300) < 100;
    if(mouseNear) {
      crackProgress = p.min(crackProgress + 0.02, 1);

      // Start glitching systems
      if(p.random() < 0.1) {
        gauges[p.floor(p.random(gauges.length))].glitching = true;
      }
      if(p.random() < 0.05) {
        leaderboard[p.floor(p.random(leaderboard.length))].glitching = true;
      }
    } else {
      crackProgress = p.max(crackProgress - 0.005, 0);

      // Reset glitching
      for(let gauge of gauges) {
        if(p.random() < 0.1) gauge.glitching = false;
      }
      for(let entry of leaderboard) {
        if(p.random() < 0.1) entry.glitching = false;
      }
    }

    // Draw cracks
    p.stroke(255, 0, 100);
    p.strokeWeight(3);
    for(let crack of crackLines) {
      let visibleSegments = Math.floor(crack.segments.length * crackProgress);

      for(let i = 0; i < visibleSegments - 1; i++) {
        let current = crack.segments[i];
        let next = crack.segments[i + 1];

        // Glitch effect
        let glitchX = p.random(-2, 2) * crackProgress;
        let glitchY = p.random(-2, 2) * crackProgress;

        p.line(
          current.x + glitchX, 
          current.y + glitchY,
          next.x + glitchX, 
          next.y + glitchY
        );
      }
    }

    // Disruption particles
    if(crackProgress > 0.5) {
      for(let i = 0; i < 5; i++) {
        particles.push({
          x: 200 + p.random(-50, 50),
          y: 300 + p.random(-50, 50),
          vx: p.random(-3, 3),
          vy: p.random(-3, 3),
          life: 60,
          size: p.random(3, 8)
        });
      }
    }

    // Update and draw particles
    p.fill(255, 0, 100, 150);
    p.noStroke();
    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life--;
      particle.size *= 0.98;

      let alpha = p.map(particle.life, 0, 60, 0, 150);
      p.fill(255, 0, 100, alpha);
      p.circle(particle.x, particle.y, particle.size);

      if(particle.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Central disruption point
    if(crackProgress > 0.2) {
      p.fill(255, 0, 100, 100);
      p.noStroke();
      let pulseSize = 20 + p.sin(p.frameCount * 0.2) * 10;
      p.circle(200, 300, pulseSize * crackProgress);

      p.fill(255, 255, 255, 200);
      p.circle(200, 300, pulseSize * 0.3 * crackProgress);
    }

    // Screen glitch effect when highly disrupted
    if(crackProgress > 0.8) {
      p.loadPixels();
      for(let i = 0; i < p.pixels.length; i += 4) {
        if(p.random() < 0.01) {
          p.pixels[i] = p.random(255);
          p.pixels[i + 1] = p.random(255);
          p.pixels[i + 2] = p.random(255);
        }
      }
      p.updatePixels();
    }
  };

  p.mousePressed = function() {
    // Click creates immediate disruption burst
    for(let i = 0; i < 20; i++) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-5, 5),
        vy: p.random(-5, 5),
        life: 90,
        size: p.random(5, 12)
      });
    }

    // Trigger system glitches
    for(let gauge of gauges) {
      if(p.random() < 0.7) gauge.glitching = true;
    }
    for(let entry of leaderboard) {
      if(p.random() < 0.5) entry.glitching = true;
    }
  };
}

function sketch(p) {
  let meters = [];
  let gauges = [];
  let particles = [];
  let leaderboard = [];
  let time = 0;
  let balancePhase = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize 6 performance meters (the six elements)
    for(let i = 0; i < 6; i++) {
      meters.push({
        x: 60 + (i % 3) * 140,
        y: 150 + Math.floor(i / 3) * 120,
        value: p.random(0.3, 0.9),
        targetValue: p.random(0.4, 0.8),
        label: ['FEAR', 'QUOTA', 'EFFICIENCY', 'OUTPUT', 'METRICS', 'BALANCE'][i],
        oscillation: p.random(0.02, 0.05),
        phase: p.random(0, p.TWO_PI)
      });
    }

    // Initialize circular gauges
    for(let i = 0; i < 3; i++) {
      gauges.push({
        x: 100 + i * 100,
        y: 450,
        value: p.random(0.2, 0.8),
        targetValue: p.random(0.3, 0.7),
        size: 60
      });
    }

    // Initialize leaderboard scores
    for(let i = 0; i < 6; i++) {
      leaderboard.push({
        score: Math.floor(p.random(850, 999)),
        targetScore: Math.floor(p.random(880, 950)),
        y: 50 + i * 25
      });
    }
  };

  p.draw = function() {
    // Corporate background gradient
    for(let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(240, 245, 255), p.color(200, 220, 240), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    time += 0.02;
    balancePhase = (Math.sin(time * 0.5) + 1) * 0.5;

    // Draw caution stripes at top and bottom
    p.drawCautionStripes(0, 0, p.width, 20);
    p.drawCautionStripes(0, p.height - 20, p.width, 20);

    // Draw fluorescent light bars
    p.drawFluorescentLights();

    // Draw title area with ID badge aesthetic
    p.fill(245, 245, 245);
    p.stroke(180);
    p.strokeWeight(2);
    p.rect(20, 30, 360, 80, 5);

    p.fill(50);
    p.noStroke();
    p.textAlign(p.CENTER, p.CENTER);
    p.textSize(16);
    p.text("PERFORMANCE MONITORING SYSTEM", 200, 55);
    p.textSize(12);
    p.text("SIX METRICS BALANCED", 200, 75);
    p.text("ADAPTATION PROTOCOL ACTIVE", 200, 90);

    // Update and draw performance meters
    for(let i = 0; i < meters.length; i++) {
      let meter = meters[i];

      // Smooth transition toward balance
      meter.value = p.lerp(meter.value, meter.targetValue, 0.02);

      // Add subtle oscillation showing the "new balance"
      let oscillation = Math.sin(time + meter.phase) * meter.oscillation * balancePhase;
      let displayValue = meter.value + oscillation;

      // Meter housing
      p.fill(220, 220, 220);
      p.stroke(120);
      p.strokeWeight(2);
      p.rect(meter.x - 40, meter.y - 30, 80, 60, 3);

      // Meter fill based on performance
      let fillHeight = displayValue * 50;
      if(displayValue > 0.7) {
        p.fill(46, 204, 113); // Green for good performance
      } else if(displayValue > 0.4) {
        p.fill(241, 196, 15); // Yellow for moderate
      } else {
        p.fill(231, 76, 60); // Red for poor performance
      }
      p.noStroke();
      p.rect(meter.x - 35, meter.y + 20 - fillHeight, 70, fillHeight);

      // Meter scale lines
      p.stroke(100);
      p.strokeWeight(1);
      for(let j = 0; j < 5; j++) {
        let lineY = meter.y - 20 + j * 10;
        p.line(meter.x - 35, lineY, meter.x - 30, lineY);
        p.line(meter.x + 30, lineY, meter.x + 35, lineY);
      }

      // Digital readout
      p.fill(0, 100, 0);
      p.noStroke();
      p.rect(meter.x - 25, meter.y + 25, 50, 15, 2);
      p.fill(0, 255, 0);
      p.textAlign(p.CENTER, p.CENTER);
      p.textSize(10);
      p.text((displayValue * 100).toFixed(1) + "%", meter.x, meter.y + 32);

      // Label
      p.fill(60);
      p.textAlign(p.CENTER, p.CENTER);
      p.textSize(9);
      p.text(meter.label, meter.x, meter.y + 50);
    }

    // Draw circular gauges
    for(let i = 0; i < gauges.length; i++) {
      let gauge = gauges[i];
      gauge.value = p.lerp(gauge.value, gauge.targetValue, 0.03);

      // Gauge background
      p.fill(240);
      p.stroke(150);
      p.strokeWeight(3);
      p.circle(gauge.x, gauge.y, gauge.size);

      // Gauge arc
      p.noFill();
      p.stroke(52, 152, 219);
      p.strokeWeight(8);
      p.arc(gauge.x, gauge.y, gauge.size - 10, gauge.size - 10, 
            -p.PI, -p.PI + gauge.value * p.TWO_PI);

      // Center dot
      p.fill(52, 152, 219);
      p.noStroke();
      p.circle(gauge.x, gauge.y, 8);

      // Value text
      p.fill(40);
      p.textAlign(p.CENTER, p.CENTER);
      p.textSize(10);
      p.text(Math.floor(gauge.value * 100), gauge.x, gauge.y + 40);
    }

    // Draw leaderboard showing balanced scores
    p.fill(30, 30, 50);
    p.noStroke();
    p.rect(300, 150, 90, 160, 5);

    p.fill(0, 255, 100);
    p.textAlign(p.LEFT, p.CENTER);
    p.textSize(8);
    p.text("RANKINGS", 305, 165);

    for(let i = 0; i < leaderboard.length; i++) {
      let entry = leaderboard[i];
      entry.score = Math.floor(p.lerp(entry.score, entry.targetScore, 0.01));

      p.fill(150, 255, 150);
      p.text("#" + (i + 1) + ": " + entry.score, 305, entry.y + 140);
    }

    // Particle system showing data flow and balance
    if(p.frameCount % 20 === 0) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        life: 255,
        size: p.random(2, 4)
      });
    }

    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 2;

      p.fill(100, 200, 255, particle.life);
      p.noStroke();
      p.circle(particle.x, particle.y, particle.size);

      if(particle.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Interactive element - mouse affects balance
    let mouseInfluence = p.map(p.mouseX, 0, p.width, -0.1, 0.1);
    for(let meter of meters) {
      meter.targetValue = p.constrain(meter.targetValue + mouseInfluence * 0.001, 0.2, 0.9);
    }
  };

  p.drawCautionStripes = function(x, y, w, h) {
    let stripeWidth = 20;
    p.noStroke();
    for(let i = x; i < x + w; i += stripeWidth * 2) {
      p.fill(255, 215, 0);
      p.rect(i, y, stripeWidth, h);
      p.fill(50, 50, 50);
      p.rect(i + stripeWidth, y, stripeWidth, h);
    }
  };

  p.drawFluorescentLights = function() {
    p.fill(255, 255, 240, 150);
    p.noStroke();
    p.rect(0, 0, p.width, 40);
    p.rect(0, p.height - 40, p.width, 40);

    // Light fixtures
    p.fill(200, 200, 210);
    p.stroke(150);
    p.strokeWeight(1);
    for(let i = 50; i < p.width; i += 100) {
      p.rect(i - 30, 5, 60, 10, 15);
      p.rect(i - 30, p.height - 15, 60, 10, 15);
    }
  };

  p.mousePressed = function() {
    // Click creates ripple effect showing system response
    particles.push({
      x: p.mouseX,
      y: p.mouseY,
      vx: 0,
      vy: 0,
      life: 300,
      size: 50,
      isRipple: true
    });
  };
}

