    p.stroke(100, 150, 200);
    p.strokeWeight(2);
    p.rect(20, 50, 120, 120);

    p.fill(100, 200, 255);
    p.noStroke();
    p.textSize(10);
    p.textAlign(p.LEFT);
    p.text("SCARE LEADERBOARD", 25, 70);

    for(let i = 0; i < leaderboard.length; i++) {
      let entry = leaderboard[i];
      let y = 85 + i * 15;

      p.fill(entry.color);
      p.text("#" + entry.rank, 25, y);
      p.fill(200, 220, 240);
      p.text(entry.score.toString(), 90, y);

      if(entry.rank === 7) {
        p.fill(255, 100, 100, 150 + p.sin(p.millis() * 0.01) * 50);
        p.rect(22, y - 10, 115, 12);
      }
    }
  }

  function drawPaths() {
    for(let i = 0; i < paths.length; i++) {
      let path = paths[i];

      // Check if mouse is near this path
      let distance = p.dist(p.mouseX, p.mouseY, path.x, path.y);
      path.active = distance < 40;

      if(path.active) {
        path.glowIntensity = p.lerp(path.glowIntensity, 1, 0.1);
      } else {
        path.glowIntensity = p.lerp(path.glowIntensity, 0, 0.05);
      }

      // Door frame
      p.fill(60, 80, 100);
      p.stroke(100, 150, 200);
      p.strokeWeight(2);
      p.rect(path.x - path.width/2, path.y, path.width, path.height);

      // Door glow effect when active
      if(path.glowIntensity > 0) {
        p.fill(255, 100, 150, path.glowIntensity * 100);
        p.noStroke();
        p.rect(path.x - path.width/2 - 3, path.y - 3, path.width + 6, path.height + 6);
      }

      // Scream meter above each door
      p.fill(255, 200, 100);
      p.noStroke();
      p.textSize(8);
      p.textAlign(p.CENTER);
      p.text(path.screamLevel.toFixed(0), path.x, path.y - 10);

      // Path number
      p.fill(255, 215, 0);
      p.textSize(12);
      p.text((i + 1).toString(), path.x, path.y + path.height + 15);
    }
  }

  function drawFigure() {
    p.push();
    p.translate(figure.x, figure.y);

    // Body sway based on contemplation
    let sway = p.sin(p.millis() * 0.003) * 5;
    p.rotate(p.radians(sway));

    // Figure shadow
    p.fill(0, 0, 0, 50);
    p.noStroke();
    p.ellipse(0, 40, 60, 15);

    // Main body
    p.fill(figure.bodyColor);
    p.stroke(30, 40, 60);
    p.strokeWeight(2);
    p.ellipse(0, 0, 50, 70);

    // Arms (one pointing back, one forward)
    p.strokeWeight(6);
    p.stroke(figure.bodyColor);
    // Left arm pointing toward paths
    p.line(-15, -10, -35 - mouseInfluence * 10, -20);
    // Right arm gesturing back at what's built
    p.line(15, -10, 40 + contemplationPhase * 10, -15);

    // Employee badge
    p.fill(255, 255, 255);
    p.stroke(200, 200, 200);
    p.strokeWeight(1);
    p.rect(-8, 15, 16, 12);
    p.fill(255, 100, 100);
    p.noStroke();
    p.textSize(6);
    p.textAlign(p.CENTER);
    p.text("ID: 2319", 0, 23);

    // Eyes showing contemplation
    figure.eyeGlow = 150 + contemplationPhase * 100;
    p.fill(255, 255, 100, figure.eyeGlow);
    p.noStroke();
    p.ellipse(-8, -15, 8, 8);
    p.ellipse(8, -15, 8, 8);

    // Thought bubble indicators
    if(mouseInfluence > 0.5) {
      p.fill(255, 255, 255, 150);
      p.ellipse(-20, -40, 8, 8);
      p.ellipse(-15, -50, 6, 6);
      p.ellipse(-10, -58, 4, 4);
    }

    p.pop();
  }

  function drawParticles() {
    for(let particle of particles) {
      particle.x += p.sin(p.millis() * 0.001 + particle.y * 0.01) * particle.speed;
      particle.y -= particle.speed * 0.3;

      if(particle.y < 0) {
        particle.y = 600;
        particle.x = p.random(400);
      }

      p.fill(100, 150, 255, particle.alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size, particle.size);
    }
  }

  function drawMeasurementOverlays() {
    // Efficiency rating
    p.fill(255, 215, 0);
    p.noStroke();
    p.textSize(10);
    p.textAlign(p.RIGHT);
    p.text("EFFICIENCY: " + (78 + mouseInfluence * 15).toFixed(1) + "%", 390, 580);

    // Current quota
    p.fill(255, 100, 100);
    p.text("QUOTA: 847/1000", 390, 560);

    // Performance indicator
    let performance = "EXCEEDS STANDARDS";
    if(contemplationPhase > 0.6) performance = "QUESTIONING METRICS";
    if(mouseInfluence > 0.8) performance = "NEEDS RECALIBRATION";

    p.fill(100, 255, 150);
    if(performance !== "EXCEEDS STANDARDS") p.fill(255, 150, 100);
    p.text("STATUS: " + performance, 390, 540);
  }

  p.mousePressed = function() {
    // Create burst of particles on click
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        size: p.random(3, 8),
        speed: p.random(2, 4),
        alpha: p.random(150, 255)
      });
    }

    // Update figure's eye glow
    figure.eyeGlow = 255;
  };
}

function sketch(p) {
  let workers = [];
  let meters = [];
  let charts = [];
  let particles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create 8 workers on the scare floor
    for(let i = 0; i < 8; i++) {
      workers.push({
        x: 60 + (i % 4) * 80,
        y: 250 + Math.floor(i / 4) * 120,
        phase: i * 0.3,
        scareLevel: p.random(0.5, 1),
        targetScare: p.random(0.5, 1),
        doorColor: p.color(p.random(200, 255), p.random(100, 200), p.random(50, 150))
      });
    }

    // Create performance meters
    for(let i = 0; i < 4; i++) {
      meters.push({
        x: 50 + i * 80,
        y: 80,
        value: p.random(0.3, 0.9),
        targetValue: p.random(0.3, 0.9)
      });
    }

    // Create performance charts
    for(let i = 0; i < 3; i++) {
      let chartData = [];
      for(let j = 0; j < 12; j++) {
        chartData.push(p.random(0.2, 0.8));
      }
      charts.push({
        x: 280 + i * 35,
        y: 80,
        data: chartData
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Dark industrial background
    p.background(25, 35, 45);

    // Floor grid pattern
    p.stroke(60, 80, 100);
    p.strokeWeight(1);
    for(let i = 0; i < 20; i++) {
      p.line(0, i * 30, 400, i * 30);
      p.line(i * 20, 0, i * 20, 600);
    }

    // Yellow caution stripes
    p.fill(255, 220, 0);
    p.noStroke();
    for(let i = 0; i < 3; i++) {
      let y = 200 + i * 150;
      p.rect(0, y, 400, 8);
    }

    // Fluorescent lighting effect
    p.fill(200, 220, 255, 30);
    p.rect(0, 0, 400, 600);

    // Draw performance meters
    for(let meter of meters) {
      meter.value = p.lerp(meter.value, meter.targetValue, 0.02);
      if(p.random() < 0.01) {
        meter.targetValue = p.random(0.3, 0.9);
      }

      // Meter background
      p.fill(40, 50, 60);
      p.stroke(100, 120, 140);
      p.strokeWeight(2);
      p.rect(meter.x, meter.y, 60, 80);

      // Meter fill
      let fillHeight = meter.value * 70;
      p.fill(255, 100 + meter.value * 100, 0);
      p.noStroke();
      p.rect(meter.x + 5, meter.y + 75 - fillHeight, 50, fillHeight);

      // Meter markings
      p.stroke(200);
      p.strokeWeight(1);
      for(let i = 0; i < 5; i++) {
        let markY = meter.y + 15 + i * 14;
        p.line(meter.x + 50, markY, meter.x + 55, markY);
      }
    }

    // Draw performance charts
    for(let chart of charts) {
      // Update chart data occasionally
      if(p.random() < 0.005) {
        chart.data.shift();
        chart.data.push(p.random(0.2, 0.8));
      }

      // Chart background
      p.fill(40, 50, 60);
      p.stroke(100, 120, 140);
      p.strokeWeight(1);
      p.rect(chart.x, chart.y, 30, 60);

      // Chart bars
      p.noStroke();
      for(let i = 0; i < chart.data.length; i++) {
        let barHeight = chart.data[i] * 50;
        let hue = chart.data[i] * 60;
        p.fill(255, 200 - hue, hue);
        p.rect(chart.x + 2 + i * 2, chart.y + 58 - barHeight, 2, barHeight);
      }
    }

    // Draw workers
    for(let worker of workers) {
      worker.scareLevel = p.lerp(worker.scareLevel, worker.targetScare, 0.05);
      if(p.random() < 0.02) {
        worker.targetScare = p.random(0.4, 1);
      }

      let bounce = p.sin(time * 3 + worker.phase) * 5 * worker.scareLevel;
      let currentY = worker.y + bounce;

      // Worker shadow
      p.fill(0, 0, 0, 30);
      p.noStroke();
      p.ellipse(worker.x, worker.y + 25, 25, 8);

      // Door behind worker
      p.fill(worker.doorColor);
      p.stroke(200, 220, 255);
      p.strokeWeight(2);
      p.rect(worker.x - 15, currentY - 35, 30, 45, 5);

      // Door handle
      p.fill(255, 220, 0);
      p.noStroke();
      p.circle(worker.x + 8, currentY - 12, 4);

      // Worker body (simplified monster silhouette)
      p.fill(80 + worker.scareLevel * 100, 60, 120);
      p.stroke(150);
      p.strokeWeight(1);
      p.ellipse(worker.x, currentY, 20, 25);

      // Worker arms in action pose
      let armAngle = p.sin(time * 4 + worker.phase) * 0.5 * worker.scareLevel;
      p.stroke(80 + worker.scareLevel * 100, 60, 120);
      p.strokeWeight(3);
      p.line(worker.x - 8, currentY - 5, worker.x - 15 + p.cos(armAngle) * 8, currentY + p.sin(armAngle) * 8);
      p.line(worker.x + 8, currentY - 5, worker.x + 15 + p.cos(armAngle + 1) * 8, currentY + p.sin(armAngle + 1) * 8);

      // Eyes
      p.fill(255, 255, 0);
      p.noStroke();
      p.circle(worker.x - 3, currentY - 8, 4);
      p.circle(worker.x + 3, currentY - 8, 4);

      // Scare energy particles
      if(worker.scareLevel > 0.6) {
        for(let j = 0; j < 3; j++) {
          let px = worker.x + p.cos(time * 2 + j) * 20;
          let py = currentY + p.sin(time * 2 + j) * 15;
          p.fill(255, 100, 0, 150);
          p.circle(px, py, 3);
        }
      }
    }

    // Mouse interaction - boost nearby workers
    for(let worker of workers) {
      let dist = p.dist(p.mouseX, p.mouseY, worker.x, worker.y);
      if(dist < 50) {
        worker.targetScare = p.min(1, worker.targetScare + 0.02);
      }
    }

    // ID badge overlay
    p.fill(255, 255, 255, 200);
    p.stroke(0);
    p.strokeWeight(1);
    p.rect(10, 10, 80, 30, 3);
    p.fill(0);
    p.noStroke();
    p.textAlign(p.LEFT);
    p.textSize(8);
    p.text("SCARE FLOOR", 15, 25);
    p.text("SECTOR 8", 15, 35);

    // Performance indicator
    let avgPerformance = meters.reduce((sum, m) => sum + m.value, 0) / meters.length;
    p.fill(255, 200 - avgPerformance * 200, avgPerformance * 200);
    p.circle(85, 25, 8);
  };
}

function sketch(p) {
  let screamMeters = [];
  let gauges = [];
  let monsterFigure;
  let leaderboard = [];
  let particles = [];
  let pulsePhase = 0;
  let achievementGlow = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize 9 scream meters arranged in completion pattern
    for (let i = 0; i < 9; i++) {
      let angle = (i * p.TWO_PI / 8) - p.PI/2;
      let radius = 120;
      let x = 200 + p.cos(angle) * radius;
      let y = 250 + p.sin(angle) * radius;

      screamMeters.push({
        x: x,
        y: y,
        value: p.random(0.7, 1.0), // High achievement levels
        maxValue: 1.0,
        width: 40,
        height: 8,
        id: i + 1,
        flicker: p.random(p.TWO_PI)
      });
    }

    // Central monitoring figure
    monsterFigure = {
      x: 200,
      y: 250,
      satisfactionLevel: 0.85,
      bobPhase: 0
    };

    // Leaderboard numbers
    for (let i = 0; i < 5; i++) {
      leaderboard.push({
        rank: i + 1,
        score: p.int(p.random(8500, 9999)),
        isPlayer: i === 0,
        y: 80 + i * 25
      });
    }

    // Success particles
    for (let i = 0; i < 20; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.5, 0.5),
        size: p.random(2, 4),
        alpha: p.random(100, 255)
      });
    }
  };

  p.draw = function() {
    // Corporate fluorescent background
    p.background(240, 245, 250);

    // Grid pattern overlay
    p.stroke(220, 230, 240);
    p.strokeWeight(1);
    for (let x = 0; x < 400; x += 20) {
      p.line(x, 0, x, 600);
    }
    for (let y = 0; y < 600; y += 20) {
      p.line(0, y, 400, y);
    }

    pulsePhase += 0.02;
    achievementGlow = p.map(p.sin(pulsePhase), -1, 1, 0.5, 1.0);

    // Draw leaderboard
    drawLeaderboard();

    // Draw caution stripes at bottom
    drawCautionStripes();

    // Draw scream meters in completion formation
    drawScreamMeters();

    // Draw central monitoring figure
    drawMonitoringFigure();

    // Draw achievement particles
    drawParticles();

    // Draw completion indicator
    drawCompletionIndicator();

    // Interactive hover effects
    handleInteraction();
  };

  function drawLeaderboard() {
    // Leaderboard background
    p.fill(45, 55, 65);
    p.noStroke();
    p.rect(20, 60, 160, 140, 5);

    // Header
    p.fill(255, 215, 0);
    p.textAlign(p.CENTER);
    p.textSize(12);
    p.text("SCARE LEADERBOARD", 100, 80);

    // Entries
    for (let entry of leaderboard) {
      p.fill(entry.isPlayer ? p.color(0, 255, 100) : p.color(220, 230, 240));
      p.textAlign(p.LEFT);
      p.textSize(10);
      p.text(`${entry.rank}. ${entry.score}`, 30, entry.y);

      if (entry.isPlayer) {
        p.fill(0, 255, 100, 100);
        p.rect(25, entry.y - 12, 130, 15, 3);
      }
    }
  }

  function drawCautionStripes() {
    p.fill(255, 215, 0);
    p.noStroke();
    for (let i = 0; i < 10; i++) {
      if (i % 2 === 0) {
        p.rect(i * 40, 580, 40, 20);
      }
    }

    p.fill(0);
    p.textAlign(p.CENTER);
    p.textSize(10);
    for (let i = 1; i < 10; i += 2) {
      p.text("CAUTION", i * 40 + 20, 593);
    }
  }

  function drawScreamMeters() {
    for (let meter of screamMeters) {
      meter.flicker += 0.1;

      // Meter housing
      p.fill(60, 70, 80);
      p.stroke(40, 50, 60);
      p.strokeWeight(2);
      p.rect(meter.x - meter.width/2, meter.y - meter.height/2, meter.width, meter.height, 2);

      // Fill level with achievement glow
      let fillWidth = (meter.width - 4) * meter.value;
      let glowIntensity = achievementGlow;

      if (meter.value > 0.9) {
        p.fill(p.red(p.color(0, 255, 100)) * glowIntensity, 
               p.green(p.color(0, 255, 100)) * glowIntensity, 
               p.blue(p.color(0, 255, 100)) * glowIntensity);
      } else if (meter.value > 0.7) {
        p.fill(255, 215, 0);
      } else {
        p.fill(255, 100, 100);
      }

      p.noStroke();
      p.rect(meter.x - meter.width/2 + 2, meter.y - meter.height/2 + 2, fillWidth, meter.height - 4);

      // ID number
      p.fill(220, 230, 240);
      p.textAlign(p.CENTER);
      p.textSize(8);
      p.text(meter.id, meter.x, meter.y - 15);

      // Percentage
      p.text(p.int(meter.value * 100) + "%", meter.x, meter.y + 20);
    }
  }

  function drawMonitoringFigure() {
    monsterFigure.bobPhase += 0.03;
    let bobOffset = p.sin(monsterFigure.bobPhase) * 2;

    let figureY = monsterFigure.y + bobOffset;

    // Monster silhouette (satisfied supervisor)
    p.fill(80, 120, 160, 180);
    p.noStroke();

    // Body
    p.ellipse(monsterFigure.x, figureY, 30, 40);

    // Head
    p.ellipse(monsterFigure.x, figureY - 25, 25, 25);

    // Arms crossed in satisfaction
    p.stroke(80, 120, 160);
    p.strokeWeight(3);
    p.line(monsterFigure.x - 15, figureY - 5, monsterFigure.x + 10, figureY - 10);
    p.line(monsterFigure.x + 15, figureY - 5, monsterFigure.x - 10, figureY - 10);

    // Employee badge
    p.fill(255);
    p.stroke(100);
    p.strokeWeight(1);
    p.rect(monsterFigure.x - 6, figureY + 5, 12, 8, 2);
    p.fill(0);
    p.noStroke();
    p.textAlign(p.CENTER);
    p.textSize(6);
    p.text("ID", monsterFigure.x, figureY + 11);

    // Satisfaction glow
    let satisfaction = monsterFigure.satisfactionLevel * achievementGlow;
    p.fill(255, 215, 0, satisfaction * 100);
    p.noStroke();
    p.ellipse(monsterFigure.x, figureY - 25, 35, 35);
  }

  function drawParticles() {
    for (let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;

      if (particle.x < 0) particle.x = 400;
      if (particle.x > 400) particle.x = 0;
      if (particle.y < 0) particle.y = 600;
      if (particle.y > 600) particle.y = 0;

      p.fill(0, 255, 100, particle.alpha * achievementGlow);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }
  }

  function drawCompletionIndicator() {
    // "GOAL ACHIEVED" indicator
    p.fill(0, 255, 100, achievementGlow * 255);
    p.stroke(0, 200, 80);
    p.strokeWeight(2);
    p.rect(250, 400, 130, 30, 5);

    p.fill(0, 50, 20);
    p.noStroke();
    p.textAlign(p.CENTER);
    p.textSize(12);
    p.text("GOAL ACHIEVED", 315, 418);

    // Progress bar at 90%
    p.fill(60, 70, 80);
    p.stroke(40, 50, 60);
    p.strokeWeight(1);
    p.rect(250, 440, 130, 12, 3);

    p.fill(0, 255, 100, achievementGlow * 255);
    p.noStroke();
    p.rect(252, 442, 117, 8, 2); // 90% filled

    p.fill(220, 230, 240);
    p.textAlign(p.CENTER);
    p.textSize(10);
    p.text("90% COMPLETE", 315, 465);
  }

  function handleInteraction() {
    // Hover effects on meters
    for (let meter of screamMeters) {
      let distance = p.dist(p.mouseX, p.mouseY, meter.x, meter.y);
      if (distance < 30) {
        // Boost meter reading on hover
        meter.value = p.min(1.0, meter.value + 0.01);

        // Add extra particles
        if (p.frameCount % 10 === 0) {
          particles.push({
            x: meter.x,
            y: meter.y,
            vx: p.random(-2, 2),
            vy: p.random(-2, 2),
            size: p.random(1, 3),
            alpha: 200
          });
        }
      }
    }

    // Click to boost satisfaction
    if (p.mouseIsPressed) {
      let distance = p.dist(p.mouseX, p.mouseY, monsterFigure.x, monsterFigure.y);
      if (distance < 50) {
        monsterFigure.satisfactionLevel = p.min(1.0, monsterFigure.satisfactionLevel + 0.005);
      }
    }
  }
}

function sketch(p) {
  let screamMeters = [];
  let particles = [];
  let warningStripes = [];
  let leaderboardData = [];
  let overflowEffect = 0;
  let fluoroFlicker = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize 10 scream meters in grid formation
    for (let i = 0; i < 10; i++) {
      let x = (i % 5) * 70 + 50;
      let y = p.floor(i / 5) * 120 + 150;
      screamMeters.push({
        x: x,
        y: y,
        level: p.random(0.7, 1.0),
        maxLevel: p.random(0.8, 1.0),
        flickering: p.random(0, p.TWO_PI),
        id: p.floor(p.random(1000, 9999))
      });
    }

    // Initialize warning stripes
    for (let i = 0; i < 8; i++) {
      warningStripes.push({
        x: i * 50,
        offset: p.random(0, 20)
      });
    }

    // Initialize leaderboard data
    for (let i = 0; i < 5; i++) {
      leaderboardData.push({
        rank: i + 1,
        score: p.floor(p.random(8000, 9999)),
        declining: p.random() > 0.5
      });
    }
  };

  p.draw = function() {
    // Cold fluorescent background with flicker
    fluoroFlicker += 0.1;
    let flicker = p.sin(fluoroFlicker) * 0.02 + 0.98;
    let bgColor = p.color(240 * flicker, 245 * flicker, 250 * flicker);
    p.background(bgColor);

    // Mouse influence calculation
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0.8, 1.2);

    // Draw warning stripes at top
    p.noStroke();
    for (let stripe of warningStripes) {
      for (let y = 0; y < 40; y += 20) {
        p.fill(y % 40 === 0 ? p.color(255, 220, 0) : p.color(30, 30, 30));
        p.rect(stripe.x + stripe.offset, y, 25, 10);
      }
    }

    // Draw header panel
    p.fill(45, 50, 55);
    p.rect(0, 40, 400, 60);
    p.fill(0, 255, 255);
    p.textAlign(p.CENTER);
    p.textSize(16);
    p.text("SCARE FLOOR METRICS - SECTOR 10", 200, 70);

    // Draw 10 scream collection meters
    for (let i = 0; i < screamMeters.length; i++) {
      let meter = screamMeters[i];

      // Meter housing
      p.fill(60, 65, 70);
      p.stroke(0);
      p.strokeWeight(2);
      p.rect(meter.x - 25, meter.y - 40, 50, 80, 5);

      // Meter fill (overflowing effect)
      meter.flickering += 0.05;
      let dynamicLevel = meter.level * mouseInfluence + p.sin(meter.flickering) * 0.05;

      // Overflow particles when meter is full
      if (dynamicLevel > 0.95) {
        for (let j = 0; j < 2; j++) {
          particles.push({
            x: meter.x + p.random(-10, 10),
            y: meter.y - 40,
            vx: p.random(-1, 1),
            vy: p.random(-3, -1),
            life: 60,
            maxLife: 60
          });
        }
      }

      // Meter fill color based on level
      let fillHeight = p.constrain(dynamicLevel * 76, 0, 76);
      if (dynamicLevel > 1.0) {
        p.fill(255, 100, 100); // Red overflow
      } else if (dynamicLevel > 0.8) {
        p.fill(255, 200, 0); // Yellow high
      } else {
        p.fill(100, 255, 100); // Green normal
      }

      p.noStroke();
      p.rect(meter.x - 23, meter.y + 38 - fillHeight, 46, fillHeight);

      // Meter scale lines
      p.stroke(200);
      p.strokeWeight(1);
      for (let tick = 0; tick <= 10; tick++) {
        let tickY = meter.y + 38 - (tick / 10) * 76;
        p.line(meter.x + 20, tickY, meter.x + 25, tickY);
      }

      // ID badge
      p.fill(255);
      p.noStroke();
      p.rect(meter.x - 15, meter.y + 45, 30, 12, 2);
      p.fill(0);
      p.textAlign(p.CENTER);
      p.textSize(8);
      p.text(meter.id, meter.x, meter.y + 54);
    }

    // Draw overflow particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.vy += 0.1; // gravity
      particle.life--;

      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 255);
      p.fill(255, 150, 50, alpha);
      p.noStroke();
      p.circle(particle.x, particle.y, 4);

      if (particle.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Draw leaderboard panel
    p.fill(40, 45, 50);
    p.stroke(0, 255, 255);
    p.strokeWeight(2);
    p.rect(50, 450, 300, 120, 5);

    p.fill(0, 255, 255);
    p.textAlign(p.CENTER);
    p.textSize(14);
    p.noStroke();
    p.text("TOP SCARERS LEADERBOARD", 200, 470);

    // Leaderboard entries
    for (let i = 0; i < leaderboardData.length; i++) {
      let entry = leaderboardData[i];
      let y = 485 + i * 15;

      // Animate scores
      if (p.frameCount % 60 === 0) {
        if (entry.declining) {
          entry.score = p.max(entry.score - p.floor(p.random(1, 50)), 5000);
        } else {
          entry.score += p.floor(p.random(1, 30));
        }
      }

      p.fill(entry.declining ? p.color(255, 100, 100) : p.color(150, 255, 150));
      p.textAlign(p.LEFT);
      p.textSize(10);
      p.text(`${entry.rank}. MONSTER #${1000 + i}`, 60, y);
      p.textAlign(p.RIGHT);
      p.text(`${entry.score} SCREAMS`, 340, y);
    }

    // Draw overflow indicator
    overflowEffect = p.sin(p.frameCount * 0.1) * 0.5 + 0.5;
    p.fill(255, 50, 50, 100 * overflowEffect);
    p.noStroke();
    p.rect(0, 0, 400, 600);

    // System status indicator
    p.fill(mouseInfluence > 1.1 ? p.color(255, 0, 0) : p.color(0, 255, 0));
    p.circle(370, 580, 12);
    p.fill(255);
    p.textAlign(p.LEFT);
    p.textSize(8);
    p.text(mouseInfluence > 1.1 ? "OVERFLOW" : "NOMINAL", 10, 585);
  };

  p.mousePressed = function() {
    // Reset all meters to create completion cycle
    for (let meter of screamMeters) {
      meter.level = p.random(0.3, 0.7);
    }

    // Clear overflow particles
    particles = [];

    // Refresh leaderboard
    for (let entry of leaderboardData) {
      entry.score = p.floor(p.random(7000, 9500));
      entry.declining = p.random() > 0.6;
    }
  };
}

