    let brightness = 240 + p.sin(lightFlicker) * 15;
    p.background(brightness, brightness, brightness + 10);

    // Draw industrial grid floor
    p.stroke(200, 200, 220);
    p.strokeWeight(1);
    for (let i = 0; i < 20; i++) {
      p.line(0, i * 30, 400, i * 30);
      p.line(i * 20, 0, i * 20, 600);
    }

    // Yellow caution stripes
