    p.noStroke();
    for (let i = 0; i < 8; i++) {
      if (i % 2 === 0) {
        p.rect(0, 420 + i * 8, 400, 8);
      }
    }

    // Draw performance charts
    p.fill(50, 150, 255);
    p.noStroke();
    for (let chart of charts) {
      p.rect(chart.x, chart.y, 12, chart.height);
    }

    // Draw meters with animated values
    for (let meter of meters) {
      // Meter background
      p.fill(40);
      p.rect(meter.x - 15, meter.y - 40, 30, 80);

      // Meter fill
      let fillHeight = meter.value * 75;
      if (meter.value < 0.3) p.fill(255, 100, 100);
      else if (meter.value < 0.7) p.fill(255, 200, 100);
      else p.fill(100, 255, 100);

      p.rect(meter.x - 12, meter.y + 35 - fillHeight, 24, fillHeight);

      // Meter labels
      p.fill(40);
      p.textAlign(p.CENTER);
      p.textSize(8);
      p.text(meter.label, meter.x, meter.y + 55);

      // Animate meter values
      meter.value = p.lerp(meter.value, meter.target, 0.02);
      if (p.abs(meter.value - meter.target) < 0.05) {
        meter.target = p.random(0.2, 0.9);
      }
    }

    // Draw leaderboard
    p.fill(40);
    p.rect(320, 80, 70, 120);
    p.fill(255);
    p.textAlign(p.LEFT);
    p.textSize(8);
    p.text("RANKINGS", 325, 95);

    for (let i = 0; i < leaderboard.length; i++) {
