    // Draw trainer monster (experienced)
    p.fill(100, 200, 100);
    p.ellipse(trainer.x, trainer.y, 80, 90);

    // Trainer eyes
    p.fill(255);
    p.ellipse(trainer.x - 15, trainer.y - 10, 20, 25);
    p.ellipse(trainer.x + 15, trainer.y - 10, 20, 25);
    p.fill(0);
    p.ellipse(trainer.x - 15, trainer.y - 10, 8, 12);
    p.ellipse(trainer.x + 15, trainer.y - 10, 8, 12);

    // Trainer gesture (pointing)
    trainer.gesture += 0.05;
    let armX = trainer.x + 30 + p.sin(trainer.gesture) * 10;
    let armY = trainer.y - 5 + p.cos(trainer.gesture) * 5;
    p.stroke(80, 180, 80);
    p.strokeWeight(8);
    p.line(trainer.x + 20, trainer.y, armX, armY);
    p.noStroke();

    // Draw trainee monster (nervous, eager)
    trainee.nervousness += 0.1;
    let shake = p.sin(trainee.nervousness) * 2;

    p.fill(150, 100, 255);
    p.ellipse(trainee.x + shake, trainee.y, 70, 85);

    // Trainee eyes (wide with enthusiasm/nervousness)
    let eyeExpand = 1 + p.sin(trainee.nervousness * 2) * 0.2;
    p.fill(255);
    p.ellipse(trainee.x - 12 + shake, trainee.y - 15, trainee.eyeSize * eyeExpand, trainee.eyeSize * 1.5 * eyeExpand);
    p.ellipse(trainee.x + 12 + shake, trainee.y - 15, trainee.eyeSize * eyeExpand, trainee.eyeSize * 1.5 * eyeExpand);
    p.fill(0);
    p.ellipse(trainee.x - 12 + shake, trainee.y - 15, 6, 10);
    p.ellipse(trainee.x + 12 + shake, trainee.y - 15, 6, 10);

    // Trainee notepad
    p.fill(255, 255, 220);
    p.rect(trainee.x + 25, trainee.y + 20, 30, 40);
    p.fill(0);
    for (let i = 0; i < 8; i++) {
      p.line(trainee.x + 28, trainee.y + 25 + i * 4, trainee.x + 50, trainee.y + 25 + i * 4);
    }

    // Draw ID badges
    for (let badge of badges) {
      p.fill(badge.color);
      p.rect(badge.x, badge.y, 40, 25);
      p.fill(255);
      p.textAlign(p.CENTER);
      p.textSize(8);
      p.text(`ID: ${badge.id}`, badge.x + 20, badge.y + 12);
      p.text("TRAINEE", badge.x + 20, badge.y + 20);
    }

    // Interactive elements - mouse hover effects
    if (p.mouseX > trainee.x - 35 && p.mouseX < trainee.x + 35 && 
        p.mouseY > trainee.y - 40 && p.mouseY < trainee.y + 40) {
      trainee.enthusiasm += 0.1;
      trainee.eyeSize = p.lerp(trainee.eyeSize, 18, 0.1);

      // Show thought bubble with metrics
      p.fill(255, 255, 255, 200);
      p.ellipse(trainee.x - 60, trainee.y - 80, 60, 40);
      p.fill(0);
      p.textAlign(p.CENTER);
      p.textSize(8);
      p.text("Must hit", trainee.x - 60, trainee.y - 85);
      p.text("targets!", trainee.x - 60, trainee.y - 75);
    } else {
      trainee.eyeSize = p.lerp(trainee.eyeSize, 15, 0.05);
    }

    // Click interaction - cycle through orientation materials
    if (p.mouseIsPressed) {
      pageTimer++;
      if (pageTimer > 30) {
        currentPage = (currentPage + 1) % 4;
        pageTimer = 0;
      }

      // Show orientation manual
      p.fill(255, 255, 255, 240);
      p.rect(150, 200, 100, 120);
      p.fill(0);
      p.textAlign(p.CENTER);
      p.textSize(10);

      let pages = [
        "ORIENTATION\nDAY 1",
        "SCARE FLOOR\nPROTOCOLS",
        "PERFORMANCE\nMETRICS",
        "SAFETY\nGUIDELINES"
      ];

      p.text(pages[currentPage], 200, 250);

      p.textSize(8);
      p.text(`Page ${currentPage + 1}/4`, 200, 300);
    }
  };
}

function sketch(p) {
  let monster;
  let screamParticles = [];
  let meters = [];
  let clockHand = 0;
  let performanceGauge = 0.7;
  let eyeGlow = 0;
  let doorFrames = [];
  let quotaNumbers = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize monster
    monster = {
      x: 200,
      y: 250,
      eyeSize: 40,
      breathing: 0,
      scarePose: 0,
      tired: 0
    };

    // Initialize performance meters
    for(let i = 0; i < 3; i++) {
      meters.push({
        x: 50 + i * 100,
        y: 450,
        value: p.random(0.4, 0.9),
        target: p.random(0.4, 0.9),
        label: ['FEAR', 'QUOTA', 'RANK'][i]
      });
    }

    // Initialize door frames (representing the grind)
    for(let i = 0; i < 4; i++) {
      doorFrames.push({
        x: 80 + i * 80,
        y: 500,
        active: p.random() > 0.5
      });
    }

    // Initialize floating quota numbers
    for(let i = 0; i < 6; i++) {
      quotaNumbers.push({
        x: p.random(50, 350),
        y: p.random(80, 150),
        value: p.floor(p.random(100, 999)),
        opacity: p.random(0.3, 0.8),
        drift: p.random(-0.5, 0.5)
      });
    }
  };

  p.draw = function() {
    // Dark corporate background with subtle gradient
    for(let i = 0; i < p.height; i++) {
      let alpha = p.map(i, 0, p.height, 0.2, 0.8);
      p.stroke(20, 30, 50, alpha * 255);
      p.line(0, i, p.width, i);
    }

    // Floating quota numbers (the numbers game)
    p.fill(150, 100, 200, 120);
    p.textAlign(p.CENTER);
    p.textSize(14);
    for(let num of quotaNumbers) {
      p.text(num.value, num.x, num.y);
      num.y += p.sin(p.frameCount * 0.01 + num.x * 0.01) * 0.3;
      num.x += num.drift;

      if(num.x < 0) num.x = p.width;
      if(num.x > p.width) num.x = 0;
    }

    // Corporate time clock
    p.push();
    p.translate(350, 80);
    p.stroke(80, 120, 160);
    p.strokeWeight(3);
    p.noFill();
    p.circle(0, 0, 40);

    // Clock hand showing endless work
    clockHand += 0.05;
    p.stroke(200, 100, 100);
    p.line(0, 0, p.cos(clockHand) * 15, p.sin(clockHand) * 15);
    p.pop();

    // Main monster (professional but conflicted)
    p.push();
    p.translate(monster.x, monster.y);

    // Breathing animation (stress/exhaustion)
    monster.breathing = p.sin(p.frameCount * 0.03) * 5;
    monster.tired = p.map(p.sin(p.frameCount * 0.01), -1, 1, 0, 20);

    // Monster body (professional suit-like)
    p.fill(60, 80, 120);
    p.stroke(40, 60, 100);
    p.strokeWeight(2);
    p.ellipse(0, 20 + monster.breathing, 80, 100);

    // Professional collar/tie suggestion
    p.fill(40, 50, 80);
    p.triangle(-15, -10, 15, -10, 0, 20);

    // Eyes showing the internal conflict
    eyeGlow = p.map(p.sin(p.frameCount * 0.02), -1, 1, 180, 255);
    p.fill(eyeGlow, 100, 100);
    p.noStroke();
    p.ellipse(-15, -20 + monster.tired, monster.eyeSize * 0.8, monster.eyeSize);
    p.ellipse(15, -20 + monster.tired, monster.eyeSize * 0.8, monster.eyeSize);

    // Eye pupils (tracking performance pressure)
    let mouseInfluence = p.map(p.mouseX, 0, p.width, -5, 5);
    p.fill(0);
    p.ellipse(-15 + mouseInfluence, -20 + monster.tired, 8, 12);
    p.ellipse(15 + mouseInfluence, -20 + monster.tired, 8, 12);

    // Mouth showing strain of performance
    p.stroke(200, 150, 150);
    p.strokeWeight(3);
    p.noFill();
    let mouthCurve = p.map(p.sin(p.frameCount * 0.02), -1, 1, 5, -5);
    p.arc(0, 10, 30, 20, 0, p.PI);

    p.pop();

    // Scream particles (the product being manufactured)
    if(p.frameCount % 20 === 0) {
      screamParticles.push({
        x: monster.x + p.random(-30, 30),
        y: monster.y - 50,
        size: p.random(8, 15),
        life: 255,
        vx: p.random(-2, 2),
        vy: p.random(-3, -1)
      });
    }

    // Update and draw scream particles
    for(let i = screamParticles.length - 1; i >= 0; i--) {
      let particle = screamParticles[i];

      p.fill(255, 100, 150, particle.life);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 3;
      particle.size *= 0.98;

      if(particle.life <= 0) {
        screamParticles.splice(i, 1);
      }
    }

    // Performance meters (the metrics that rule everything)
    p.textAlign(p.CENTER);
    p.textSize(10);

    for(let meter of meters) {
      // Meter background
      p.fill(40, 40, 60);
      p.stroke(80, 80, 120);
      p.strokeWeight(2);
      p.rect(meter.x - 25, meter.y, 50, 80);

      // Meter fill (constantly fluctuating pressure)
      meter.value = p.lerp(meter.value, meter.target, 0.02);
      if(p.random() < 0.01) {
        meter.target = p.random(0.3, 0.95);
      }

      let fillHeight = meter.value * 70;
      let meterColor = meter.value > 0.8 ? [255, 100, 100] : 
                      meter.value > 0.6 ? [255, 200, 100] : 
                      [100, 200, 255];

      p.fill(meterColor[0], meterColor[1], meterColor[2], 180);
      p.noStroke();
      p.rect(meter.x - 23, meter.y + 78 - fillHeight, 46, fillHeight);

      // Meter label
      p.fill(180, 180, 200);
      p.text(meter.label, meter.x, meter.y + 95);
    }

    // Door frames representing the endless grind
    for(let i = 0; i < doorFrames.length; i++) {
      let door = doorFrames[i];

      p.stroke(80, 100, 120);
      p.strokeWeight(3);
      p.noFill();
      p.rect(door.x - 15, door.y, 30, 40);

      // Flickering lights suggesting constant activity
      if(door.active && p.frameCount % 60 < 30) {
        p.fill(255, 200, 100, 100);
        p.noStroke();
        p.rect(door.x - 13, door.y + 2, 26, 36);
      }

      // Randomly toggle door activity
      if(p.random() < 0.02) {
        door.active = !door.active;
      }
    }

    // Interactive element: mouse proximity increases pressure
    let mouseDistance = p.dist(p.mouseX, p.mouseY, monster.x, monster.y);
    let pressure = p.map(mouseDistance, 0, 200, 1, 0);
    pressure = p.constrain(pressure, 0, 1);

    // Pressure visualization around monster
    if(pressure > 0.3) {
      p.push();
      p.translate(monster.x, monster.y);
      p.stroke(255, 100, 100, pressure * 100);
      p.strokeWeight(2);
      p.noFill();

      for(let i = 0; i < 3; i++) {
        let radius = 80 + i * 20 + p.sin(p.frameCount * 0.05 + i) * 10;
        p.circle(0, 0, radius);
      }
      p.pop();
    }

    // Success metrics display (the hollow achievement)
    p.fill(100, 255, 150, 150);
    p.textAlign(p.LEFT);
    p.textSize(12);
    p.text("EFFICIENCY: 94.7%", 20, 30);
    p.text("RANK: #" + p.floor(p.map(p.sin(p.frameCount * 0.01), -1, 1, 3, 12)), 20, 50);

    // Warning signs of burnout (when mouse is clicked)
    if(p.mouseIsPressed) {
      p.fill(255, 50, 50, 200);
      p.textAlign(p.CENTER);
      p.textSize(16);
      p.text("SYSTEM OVERLOAD", 200, 350);

      // Glitch effect
      for(let i = 0; i < 5; i++) {
        p.stroke(255, 0, 0, 100);
        p.line(p.random(p.width), p.random(p.height), 
               p.random(p.width), p.random(p.height));
      }
    }
  };
}

function sketch(p) {
  let cracks = [];
  let whistleParticles = [];
  let monsterEye = {};
  let screamBars = [];
  let glitchOffset = 0;
  let whistleSound = false;
  let maskFragments = [];
  let performanceMetrics = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize monster eye
    monsterEye = {
      x: 200,
      y: 180,
      size: 80,
      pupilX: 0,
      pupilY: 0,
      blinkTimer: 0,
      isBlinking: false
    };

    // Initialize cracks in the system
    for (let i = 0; i < 8; i++) {
      cracks.push({
        x1: p.random(50, 350),
        y1: p.random(100, 500),
        x2: p.random(50, 350),
        y2: p.random(100, 500),
        opacity: p.random(30, 100),
        growth: 0
      });
    }

    // Initialize performance bars
    for (let i = 0; i < 5; i++) {
      screamBars.push({
        x: 80 + i * 48,
        y: 450,
        height: p.random(20, 80),
        targetHeight: p.random(20, 80),
        color: p.color(180 + i * 15, 50, 70)
      });
    }

    // Initialize mask fragments
    for (let i = 0; i < 12; i++) {
      maskFragments.push({
        x: p.random(150, 250),
        y: p.random(250, 350),
        vx: p.random(-2, 2),
        vy: p.random(-1, 3),
        size: p.random(8, 20),
        angle: p.random(p.TWO_PI),
        rotation: p.random(-0.1, 0.1)
      });
    }

    // Initialize metrics display
    for (let i = 0; i < 4; i++) {
      performanceMetrics.push({
        value: p.random(75, 99),
        targetValue: p.random(75, 99),
        label: ['FEAR', 'QUOTA', 'EFFICIENCY', 'SCREAMS'][i],
        y: 350 + i * 25
      });
    }
  };

  p.draw = function() {
    // Corporate gradient background
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(25, 35, 60), p.color(15, 20, 40), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Update glitch effect
    glitchOffset = p.sin(p.frameCount * 0.1) * 3;

    // Draw industrial background elements
    p.stroke(60, 70, 90);
    p.strokeWeight(1);
    p.noFill();
    for (let i = 0; i < 6; i++) {
      let y = 80 + i * 80;
      p.line(20 + glitchOffset, y, 380 + glitchOffset, y);
    }

    // Draw and update cracks
    p.stroke(255, 100, 100, 150);
    p.strokeWeight(2);
    for (let crack of cracks) {
      crack.growth += 0.01;
      let endX = p.lerp(crack.x1, crack.x2, p.constrain(crack.growth, 0, 1));
      let endY = p.lerp(crack.y1, crack.y2, p.constrain(crack.growth, 0, 1));

      p.stroke(255, 100, 100, crack.opacity);
      p.line(crack.x1, crack.y1, endX, endY);

      if (crack.growth > 1) {
        crack.growth = 0;
        crack.x1 = crack.x2;
        crack.y1 = crack.y2;
        crack.x2 = p.random(50, 350);
        crack.y2 = p.random(100, 500);
      }
    }

    // Draw monster eye (the observer/whistleblower)
    let eyeX = monsterEye.x + p.sin(p.frameCount * 0.05) * 5;
    let eyeY = monsterEye.y + p.cos(p.frameCount * 0.03) * 3;

    // Eye tracking mouse
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, eyeX, eyeY) < 100 ? 1 : 0.3;
    monsterEye.pupilX = p.lerp(monsterEye.pupilX, (p.mouseX - eyeX) * 0.3 * mouseInfluence, 0.1);
    monsterEye.pupilY = p.lerp(monsterEye.pupilY, (p.mouseY - eyeY) * 0.3 * mouseInfluence, 0.1);

    // Eye outer glow
    p.drawingContext.shadowBlur = 30;
    p.drawingContext.shadowColor = 'rgba(100, 200, 255, 0.8)';
    p.fill(40, 60, 90);
    p.noStroke();
    p.ellipse(eyeX, eyeY, monsterEye.size * 1.2);

    p.drawingContext.shadowBlur = 0;

    // Eye white
    p.fill(200, 220, 240);
    p.ellipse(eyeX, eyeY, monsterEye.size);

    // Pupil
    p.fill(20, 30, 50);
    p.ellipse(eyeX + monsterEye.pupilX, eyeY + monsterEye.pupilY, monsterEye.size * 0.4);

    // Iris reflection
    p.fill(150, 200, 255, 180);
    p.ellipse(eyeX + monsterEye.pupilX - 8, eyeY + monsterEye.pupilY - 6, 12);

    // Draw performance metrics (the system being questioned)
    p.fill(100, 150, 200);
    p.textAlign(p.LEFT);
    p.textSize(12);
    p.text("PERFORMANCE METRICS", 50, 340);

    for (let metric of performanceMetrics) {
      metric.value = p.lerp(metric.value, metric.targetValue, 0.02);
      if (p.random() < 0.01) {
        metric.targetValue = p.random(60, 99);
      }

      // Glitchy bars when mouse is near eye (system breaking down)
      let glitchFactor = p.dist(p.mouseX, p.mouseY, eyeX, eyeY) < 80 ? p.random(0.8, 1.2) : 1;
      let displayValue = metric.value * glitchFactor;

      p.fill(80, 100, 120);
      p.rect(50, metric.y, 150, 15);

      let barColor = displayValue > 90 ? p.color(255, 100, 100) : p.color(100, 255, 150);
      p.fill(barColor);
      p.rect(50, metric.y, (displayValue / 100) * 150, 15);

      p.fill(200, 220, 240);
      p.textAlign(p.RIGHT);
      p.text(metric.label + ": " + Math.floor(displayValue) + "%", 45, metric.y + 12);
    }

    // Draw scream visualization bars
    p.fill(120, 140, 160);
    p.textAlign(p.CENTER);
    p.textSize(10);
    p.text("DAILY SCREAM QUOTA", 200, 440);

    for (let bar of screamBars) {
      bar.height = p.lerp(bar.height, bar.targetHeight, 0.05);
      if (p.random() < 0.02) {
        bar.targetHeight = p.random(20, 80);
      }

      p.fill(bar.color);
      p.rect(bar.x, bar.y, 30, -bar.height);

      // Glitch effect when questioning the system
      if (p.dist(p.mouseX, p.mouseY, eyeX, eyeY) < 100) {
        p.fill(255, 150, 150, 100);
        p.rect(bar.x + p.random(-3, 3), bar.y, 30, -bar.height * p.random(0.8, 1.2));
      }
    }

    // Draw mask fragments (the performance falling apart)
    for (let fragment of maskFragments) {
      fragment.x += fragment.vx;
      fragment.y += fragment.vy;
      fragment.angle += fragment.rotation;
      fragment.vy += 0.02; // gravity

      if (fragment.x < 0 || fragment.x > p.width) fragment.vx *= -0.8;
      if (fragment.y > p.height) {
        fragment.y = 250;
        fragment.vy = p.random(-1, 1);
      }

      p.push();
      p.translate(fragment.x, fragment.y);
      p.rotate(fragment.angle);
      p.fill(80, 60, 120, 150);
      p.noStroke();
      p.rect(-fragment.size/2, -fragment.size/2, fragment.size, fragment.size/3);
      p.pop();
    }

    // Create whistle particles when mouse is clicked
    if (whistleSound) {
      for (let i = 0; i < 5; i++) {
        whistleParticles.push({
          x: eyeX,
          y: eyeY,
          vx: p.random(-3, 3),
          vy: p.random(-5, -2),
          life: 255,
          size: p.random(3, 8)
        });
      }
      whistleSound = false;
    }

    // Update and draw whistle particles
    for (let i = whistleParticles.length - 1; i >= 0; i--) {
      let particle = whistleParticles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 3;
      particle.vy -= 0.1; // float upward

      p.fill(255, 200, 100, particle.life);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);

      if (particle.life <= 0) {
        whistleParticles.splice(i, 1);
      }
    }

    // Warning text that appears when system is being questioned
    if (p.dist(p.mouseX, p.mouseY, eyeX, eyeY) < 60) {
      p.fill(255, 100, 100, 150 + p.sin(p.frameCount * 0.2) * 50);
      p.textAlign(p.CENTER);
      p.textSize(14);
      p.text("SYSTEM INTEGRITY COMPROMISED", 200, 100);

      p.textSize(10);
      p.fill(255, 150, 150);
      p.text("QUESTIONING PROTOCOLS DETECTED", 200, 120);
    }
  };

  p.mousePressed = function() {
    if (p.dist(p.mouseX, p.mouseY, monsterEye.x, monsterEye.y) < 100) {
      whistleSound = true;

      // Cause system glitch
      for (let metric of performanceMetrics) {
        metric.targetValue = p.random(40, 80);
      }

      // Scatter mask fragments
      for (let fragment of maskFragments) {
        fragment.vx = p.random(-5, 5);
        fragment.vy = p.random(-3, -1);
      }
    }
  };
}

function sketch(p) {
  let particles = [];
  let meters = [];
  let constructionBlocks = [];
  let leaderFigure = {};
  let followers = [];
  let constructionProgress = 0;
  let fluorescents = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize fluorescent lights
    for (let i = 0; i < 4; i++) {
      fluorescents.push({
        x: 20 + i * 90,
        y: 30,
        flicker: p.random(0.8, 1.0)
      });
    }

    // Initialize construction blocks (old system rubble)
    for (let i = 0; i < 20; i++) {
      constructionBlocks.push({
        x: p.random(50, 350),
        y: p.random(350, 550),
        size: p.random(15, 35),
        isOld: p.random() > 0.4,
        targetY: p.random(150, 300),
        moving: false,
        alpha: 255
      });
    }

    // Initialize leader figure
    leaderFigure = {
      x: 200,
      y: 250,
      armAngle: 0,
      glowIntensity: 100
    };

    // Initialize follower figures
    for (let i = 0; i < 6; i++) {
      followers.push({
        x: 80 + i * 50,
        y: 450 + p.random(-20, 20),
        bobOffset: p.random(0, p.TWO_PI),
        lookingUp: false
      });
    }

    // Initialize progress meters
    for (let i = 0; i < 3; i++) {
      meters.push({
        x: 320 + i * 25,
        y: 100 + i * 60,
        value: p.random(0.3, 0.8),
        targetValue: p.random(0.5, 0.9),
        label: ['TRANSFORM', 'REBUILD', 'PROGRESS'][i]
      });
    }

    // Initialize transformation particles
    for (let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        size: p.random(2, 6),
        alpha: p.random(100, 255),
        color: p.random(['#FF6B35', '#F7931E', '#FFD23F'])
      });
    }
  };

  p.draw = function() {
    // Industrial background with fluorescent lighting
    p.background(220, 225, 230);

    // Draw fluorescent lighting strips
    for (let light of fluorescents) {
      light.flicker = p.lerp(light.flicker, p.random(0.85, 1.0), 0.1);
      p.fill(255, 255, 240, 180 * light.flicker);
      p.noStroke();
      p.rect(light.x - 30, light.y - 5, 60, 10, 5);

      // Light glow effect
      p.fill(255, 255, 200, 30 * light.flicker);
      p.rect(0, light.y + 10, p.width, 80);
    }

    // Draw caution stripes on floor
    p.stroke(255, 208, 0);
    p.strokeWeight(4);
    for (let i = 0; i < 10; i++) {
      if (i % 2 === 0) {
        p.line(i * 40, 500, i * 40 + 20, 500);
      }
    }

    // Update construction progress based on mouse interaction
    let mouseInfluence = p.map(p.mouseY, 0, p.height, 1, 0);
    constructionProgress = p.lerp(constructionProgress, mouseInfluence, 0.02);

    // Draw old system rubble transforming into new structures
    for (let block of constructionBlocks) {
      if (constructionProgress > 0.3 && !block.moving) {
        block.moving = true;
      }

      if (block.moving) {
        block.y = p.lerp(block.y, block.targetY, 0.03);
        block.alpha = p.lerp(block.alpha, block.isOld ? 100 : 255, 0.02);
      }

      if (block.isOld) {
        p.fill(120, 120, 120, block.alpha);
      } else {
        p.fill(255, 107, 53, block.alpha); // Scare floor orange
      }

      p.noStroke();
      p.rect(block.x, block.y, block.size, block.size, 3);

      // Add measurement numbers on new blocks
      if (!block.isOld && block.alpha > 200) {
        p.fill(255);
        p.textAlign(p.CENTER, p.CENTER);
        p.textSize(8);
        p.text(p.floor(p.random(10, 99)), block.x + block.size/2, block.y + block.size/2);
      }
    }

    // Draw leader figure
    leaderFigure.armAngle = p.sin(p.millis() * 0.003) * 0.3;
    leaderFigure.glowIntensity = p.map(p.mouseX, 0, p.width, 50, 150);

    // Leader glow effect
    p.fill(247, 147, 30, leaderFigure.glowIntensity);
    p.noStroke();
    p.ellipse(leaderFigure.x, leaderFigure.y, 80, 80);

    // Leader body
    p.fill(255, 107, 53);
    p.stroke(0, 100);
    p.strokeWeight(2);
    p.ellipse(leaderFigure.x, leaderFigure.y, 50, 50);

    // Leader arms (directing construction)
    p.line(leaderFigure.x - 15, leaderFigure.y - 10, 
           leaderFigure.x - 35 + p.cos(leaderFigure.armAngle) * 20, 
           leaderFigure.y - 20 + p.sin(leaderFigure.armAngle) * 10);
    p.line(leaderFigure.x + 15, leaderFigure.y - 10, 
           leaderFigure.x + 35 + p.cos(leaderFigure.armAngle + p.PI) * 20, 
           leaderFigure.y - 20 + p.sin(leaderFigure.armAngle + p.PI) * 10);

    // ID badge
    p.fill(255);
    p.rect(leaderFigure.x - 8, leaderFigure.y + 15, 16, 12, 2);
    p.fill(247, 147, 30);
    p.rect(leaderFigure.x - 6, leaderFigure.y + 17, 12, 3);

    // Draw followers looking up to leader
    for (let i = 0; i < followers.length; i++) {
      let follower = followers[i];
      let bob = p.sin(p.millis() * 0.005 + follower.bobOffset) * 3;

      // Check if follower should look up (based on construction progress)
      follower.lookingUp = constructionProgress > 0.2;

      p.fill(100, 150, 200);
      p.stroke(0, 100);
      p.strokeWeight(1);
      p.ellipse(follower.x, follower.y + bob, 25, 25);

      // Eyes looking up at leader
      if (follower.lookingUp) {
        p.fill(255);
        p.noStroke();
        p.ellipse(follower.x - 4, follower.y + bob - 5, 4, 4);
        p.ellipse(follower.x + 4, follower.y + bob - 5, 4, 4);
        p.fill(0);
        p.ellipse(follower.x - 4, follower.y + bob - 6, 2, 2);
        p.ellipse(follower.x + 4, follower.y + bob - 6, 2, 2);
      }
    }

    // Draw progress meters and gauges
    for (let meter of meters) {
      meter.value = p.lerp(meter.value, meter.targetValue * constructionProgress, 0.02);

      // Meter background
      p.fill(50);
      p.noStroke();
      p.rect(meter.x, meter.y, 15, 80, 3);

      // Meter fill
      let fillHeight = meter.value * 75;
      p.fill(255, 208 - meter.value * 100, 0);
      p.rect(meter.x + 1, meter.y + 80 - fillHeight - 1, 13, fillHeight, 2);

      // Meter value text
      p.fill(0);
      p.textAlign(p.CENTER);
      p.textSize(6);
      p.text(p.floor(meter.value * 100), meter.x + 7, meter.y + 95);
    }

    // Draw transformation particles
    for (let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;

      if (particle.x < 0 || particle.x > p.width) particle.vx *= -1;
      if (particle.y < 0 || particle.y > p.height) particle.vy *= -1;

      p.fill(particle.color + p.hex(p.floor(particle.alpha)));
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);

      particle.alpha = p.lerp(particle.alpha, 150 + constructionProgress * 100, 0.02);
    }

    // Draw leaderboard display
    p.fill(0, 100);
    p.noStroke();
    p.rect(20, 80, 120, 60, 5);
    p.fill(0, 200, 0);
    p.textAlign(p.LEFT);
    p.textSize(10);
    p.text("TRANSFORMATION", 25, 95);
    p.text("METRICS", 25, 108);

    for (let i = 0; i < 3; i++) {
      let score = p.floor((constructionProgress + p.random(-0.1, 0.1)) * 1000);
      p.fill(255, 208, 0);
      p.textSize(8);
      p.text(score, 25, 120 + i * 8);
    }

    // Mouse interaction indicator
    if (p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      p.stroke(255, 107, 53);
      p.strokeWeight(2);
      p.noFill();
      p.line(p.mouseX - 10, p.mouseY, p.mouseX + 10, p.mouseY);
      p.line(p.mouseX, p.mouseY - 10, p.mouseX, p.mouseY + 10);
    }
  };

  p.mousePressed = function() {
    // Trigger construction acceleration
    for (let block of constructionBlocks) {
      if (!block.isOld && p.dist(p.mouseX, p.mouseY, block.x, block.y) < 50) {
        block.targetY -= 20;
        block.alpha = 255;
      }
    }

    // Update meter target values
    for (let meter of meters) {
      meter.targetValue = p.random(0.7, 1.0);
    }
  };
}

function sketch(p) {
  let sparkX, sparkY;
  let sparkBrightness = 0;
  let sparkPulse = 0;
  let doorCrack = 0;
  let time = 0;
  let particles = [];
  let doorRows = [];
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    sparkX = p.width * 0.3;
    sparkY = p.height * 0.6;

    // Initialize door rows in background
    for (let i = 0; i < 15; i++) {
      doorRows.push({
        y: i * 40 + 50,
        offset: p.random(1000),
        opacity: p.map(i, 0, 14, 25, 5)
      });
    }

    // Initialize particles
    for (let i = 0; i < 30; i++) {
      particles.push({
        x: sparkX + p.random(-20, 20),
        y: sparkY + p.random(-20, 20),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-1, -0.3),
        life: p.random(100),
        maxLife: p.random(50, 150),
        size: p.random(1, 3)
      });
    }
  };

  p.draw = function() {
    // Deep purple-black gradient background
    for (let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(280, 80, 5), p.color(260, 60, 2), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    time += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);

    // Draw distant door vault rows
    p.noFill();
    for (let row of doorRows) {
      let waveOffset = p.sin(time + row.offset) * 10;
      p.stroke(280, 40, 15, row.opacity);
      p.strokeWeight(1);

      for (let x = -50; x < p.width + 50; x += 60) {
        let doorX = x + waveOffset;
        let doorWidth = 8;
        let doorHeight = 25;
        p.rect(doorX, row.y, doorWidth, doorHeight);
      }
    }

    // Create fog/atmosphere
    for (let i = 0; i < 5; i++) {
      let fogY = p.height * 0.4 + p.sin(time + i) * 30;
      let fogAlpha = 8 + p.sin(time * 0.5 + i) * 3;
      p.fill(280, 30, 20, fogAlpha);
      p.noStroke();
      p.ellipse(p.width * 0.1 + i * 80, fogY, 200, 100);
    }

    // The spark - central focus
    sparkPulse = p.sin(time * 3) * 0.3 + 0.7;
    sparkBrightness = 40 + sparkPulse * 60;

    // Door crack effect
    doorCrack = p.map(p.mouseY, 0, p.height, 0, 50) * sparkPulse;

    // Draw the door crack
    if (doorCrack > 5) {
      p.stroke(45, 80, sparkBrightness, 60);
      p.strokeWeight(doorCrack * 0.1);
      p.line(sparkX - doorCrack, sparkY - 40, sparkX - doorCrack, sparkY + 40);

      // Light spilling from crack
      for (let i = 0; i < 3; i++) {
        p.fill(45, 60 - i * 15, sparkBrightness - i * 20, 20 - i * 5);
        p.noStroke();
        p.ellipse(sparkX - doorCrack, sparkY, (doorCrack + i * 10) * 2, 100 - i * 20);
      }
    }

    // Main spark point
    for (let i = 4; i >= 0; i--) {
      let size = (5 - i) * 4 * sparkPulse;
      let brightness = sparkBrightness - i * 10;
      let alpha = 80 - i * 15;

      p.fill(45, 80 - i * 10, brightness, alpha);
      p.noStroke();
      p.ellipse(sparkX, sparkY, size, size);
    }

    // Core spark
    p.fill(60, 60, 95, 90);
    p.noStroke();
    p.ellipse(sparkX, sparkY, 4 * sparkPulse, 4 * sparkPulse);

    // Update and draw particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life--;

      let lifeRatio = particle.life / particle.maxLife;
      let alpha = lifeRatio * 60;
      let size = particle.size * lifeRatio;

      p.fill(50, 70, 80, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, size, size);

      if (particle.life <= 0) {
        particles.splice(i, 1);
        particles.push({
          x: sparkX + p.random(-10, 10),
          y: sparkY + p.random(-10, 10),
          vx: p.random(-0.5, 0.5),
          vy: p.random(-1, -0.3),
          life: p.random(50, 150),
          maxLife: p.random(50, 150),
          size: p.random(1, 3)
        });
      }
    }

    // Shadows and negative space
    let shadowIntensity = 1 - mouseInfluence * 0.3;
    p.fill(280, 40, 5, 30 * shadowIntensity);
    p.noStroke();

    // Left shadow
    p.beginShape();
    p.vertex(0, 0);
    p.vertex(sparkX - 100, 0);
    p.vertex(sparkX - 50, sparkY);
    p.vertex(sparkX - 100, p.height);
    p.vertex(0, p.height);
    p.endShape(p.CLOSE);

    // Right shadow
    p.beginShape();
    p.vertex(sparkX + 50, sparkY);
    p.vertex(p.width, 0);
    p.vertex(p.width, p.height);
    p.vertex(sparkX + 100, p.height);
    p.endShape(p.CLOSE);

    // Subtle watching eyes effect
    if (p.random() < 0.02) {
      let eyeX = p.random(p.width);
      let eyeY = p.random(p.height * 0.3);
      p.fill(280, 60, 30, 40);
      p.noStroke();
      p.ellipse(eyeX, eyeY, 3, 3);
    }
  };

  p.mousePressed = function() {
    // Create burst of particles on click
    for (let i = 0; i < 10; i++) {
      particles.push({
        x: sparkX + p.random(-20, 20),
        y: sparkY + p.random(-20, 20),
        vx: p.random(-2, 2),
        vy: p.random(-3, -0.5),
        life: p.random(100, 200),
        maxLife: p.random(100, 200),
        size: p.random(2, 5)
      });
    }
  };
}

function sketch(p) {
  let doors = [];
  let fogParticles = [];
  let glowPulse = 0;
  let doorVault = [];
  let leftFigure, rightFigure;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create the two main doors
    doors.push({
      x: 120,
      y: 200,
      width: 60,
      height: 120,
      glow: 0,
      color: p.color(80, 50, 120),
      shadow: p.color(20, 10, 40)
    });

    doors.push({
      x: 220,
      y: 200,
      width: 60,
      height: 120,
      glow: 0,
      color: p.color(60, 80, 100),
      shadow: p.color(15, 20, 30)
    });

    // Create background door vault rows
    for(let row = 0; row < 8; row++) {
      for(let col = 0; col < 12; col++) {
        doorVault.push({
          x: col * 35 - 20,
          y: row * 40 + 80,
          width: 20,
          height: 30,
          depth: row,
          flicker: p.random(100)
        });
      }
    }

    // Initialize fog particles
    for(let i = 0; i < 150; i++) {
      fogParticles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(3, 15),
        opacity: p.random(10, 40),
        speed: p.random(0.2, 0.8),
        drift: p.random(-0.1, 0.1)
      });
    }

    // Create silhouette figures
    leftFigure = {
      x: 90,
      y: 350,
      sway: 0,
      fear: 0
    };

    rightFigure = {
      x: 310,
      y: 350,
      sway: 0,
      fear: 0
    };
  };

  p.draw = function() {
    // Dark gradient background
    for(let y = 0; y < p.height; y++) {
      let alpha = p.map(y, 0, p.height, 0.2, 1);
      p.stroke(15 * alpha, 5 * alpha, 25 * alpha);
      p.line(0, y, p.width, y);
    }

    glowPulse += 0.03;
    mouseInfluence = p.map(p.mouseX, 0, p.width, -0.5, 0.5);

    // Draw background door vault
    p.push();
    for(let door of doorVault) {
      let distanceAlpha = p.map(door.depth, 0, 7, 0.8, 0.1);
      let flickerIntensity = p.sin(p.millis() * 0.001 + door.flicker) * 0.3 + 0.7;

      p.fill(25 * distanceAlpha, 15 * distanceAlpha, 35 * distanceAlpha);
      p.noStroke();
      p.rect(door.x, door.y, door.width, door.height);

      // Subtle glow on some doors
      if(door.flicker > 80) {
        p.fill(40 * distanceAlpha * flickerIntensity, 25 * distanceAlpha * flickerIntensity, 60 * distanceAlpha * flickerIntensity, 30);
        p.rect(door.x - 2, door.y - 2, door.width + 4, door.height + 4);
      }
    }
    p.pop();

    // Update and draw fog
    for(let particle of fogParticles) {
      particle.x += particle.speed + particle.drift + mouseInfluence * 0.5;
      particle.y += p.sin(p.millis() * 0.001 + particle.x * 0.01) * 0.3;

      if(particle.x > p.width + particle.size) particle.x = -particle.size;
      if(particle.x < -particle.size) particle.x = p.width + particle.size;

      p.fill(40, 30, 60, particle.opacity);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Draw the two main doors with enhanced glow
    for(let i = 0; i < doors.length; i++) {
      let door = doors[i];
      let mouseDistance = p.dist(p.mouseX, p.mouseY, door.x + door.width/2, door.y + door.height/2);
      let glowIntensity = p.map(mouseDistance, 0, 200, 1.5, 0.3);
      glowIntensity = p.constrain(glowIntensity, 0.3, 1.5);

      // Door glow effect
      p.push();
      p.drawingContext.shadowColor = door.color;
      p.drawingContext.shadowBlur = 20 * glowIntensity;
      p.fill(p.red(door.color) * 0.6, p.green(door.color) * 0.6, p.blue(door.color) * 0.6);
      p.noStroke();
      p.rect(door.x, door.y, door.width, door.height);
      p.pop();

      // Door frame
      p.stroke(p.red(door.color) * 1.2, p.green(door.color) * 1.2, p.blue(door.color) * 1.2);
      p.strokeWeight(2);
      p.noFill();
      p.rect(door.x, door.y, door.width, door.height);

      // Door handle
      p.fill(80, 70, 90);
      p.noStroke();
      p.ellipse(door.x + door.width - 10, door.y + door.height/2, 4, 4);

      // Light spill from door
      p.push();
      p.fill(p.red(door.color), p.green(door.color), p.blue(door.color), 20 * glowIntensity);
      p.triangle(door.x, door.y + door.height, 
                door.x + door.width, door.y + door.height,
                door.x + door.width/2, door.y + door.height + 40);
      p.pop();
    }

    // Draw path indicators - subtle lines leading to doors
    p.stroke(60, 50, 80, 100);
    p.strokeWeight(1);
    for(let i = 0; i < 2; i++) {
      let door = doors[i];
      let startX = door.x + door.width/2;
      let endX = i === 0 ? leftFigure.x : rightFigure.x;

      p.line(startX, door.y + door.height + 20, endX, 340);
    }

    // Update figure positions
    leftFigure.sway = p.sin(p.millis() * 0.002) * 3;
    rightFigure.sway = p.sin(p.millis() * 0.0025 + p.PI) * 3;

    leftFigure.fear = p.map(p.mouseX, 0, p.width/2, 0, 1);
    rightFigure.fear = p.map(p.mouseX, p.width/2, p.width, 0, 1);

    // Draw silhouette figures
    drawFigure(leftFigure);
    drawFigure(rightFigure);

    // Add subtle scanning effect
    let scanLine = (p.millis() * 0.1) % p.height;
    p.stroke(40, 30, 60, 60);
    p.strokeWeight(2);
    p.line(0, scanLine, p.width, scanLine);

    // Overlay darkness at edges for vignette
    p.push();
    p.fill(0, 0, 0, 80);
    p.noStroke();
    p.rect(0, 0, 30, p.height);
    p.rect(p.width - 30, 0, 30, p.height);
    p.rect(0, 0, p.width, 40);
    p.rect(0, p.height - 40, p.width, 40);
    p.pop();
  };

  function drawFigure(figure) {
    p.push();
    p.translate(figure.x + figure.sway, figure.y);

    let fearScale = 1 + figure.fear * 0.1;
    let tension = figure.fear * 10;

    // Shadow beneath
    p.fill(10, 5, 15, 100);
    p.noStroke();
    p.ellipse(0, 60, 40, 15);

    // Main silhouette body
    p.fill(25 + tension, 15 + tension, 35 + tension);
    p.noStroke();

    // Body
    p.ellipse(0, 30, 25 * fearScale, 45 * fearScale);

    // Head
    p.ellipse(0, 0, 20 * fearScale, 20 * fearScale);

    // Arms (slightly different positions based on fear)
    p.ellipse(-15 - figure.fear * 2, 25, 8, 25);
    p.ellipse(15 + figure.fear * 2, 25, 8, 25);

    // Legs
    p.ellipse(-8, 50, 6, 20);
    p.ellipse(8, 50, 6, 20);

    // Eyes - subtle glow
    if(figure.fear > 0.3) {
      p.fill(60, 40, 80, 150);
      p.ellipse(-3, -2, 2, 2);
      p.ellipse(3, -2, 2, 2);
    }

    p.pop();
  }

  p.mousePressed = function() {
    // Add ripple effect when clicked
    for(let i = 0; i < 20; i++) {
      fogParticles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        size: p.random(2, 8),
        opacity: p.random(30, 80),
        speed: p.random(-1, 1),
        drift: p.random(-0.2, 0.2)
      });
    }
  };
}

function sketch(p) {
  let doors = [];
  let connections = [];
  let figures = [];
  let particles = [];
  let doorGlow = 0;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create background doors in grid
    for(let x = 0; x < 8; x++) {
      for(let y = 0; y < 12; y++) {
        doors.push({
          x: x * 50 + 25,
          y: y * 50 + 25,
          glowing: p.random() < 0.1,
          glowIntensity: p.random(0.3, 1.0)
        });
      }
    }

    // Create three main figures forming triangle
    figures.push({
      x: 200,
      y: 150,
      size: 25,
      connections: [],
      pulseOffset: 0
    });
    figures.push({
      x: 120,
      y: 350,
      size: 25,
      connections: [],
      pulseOffset: p.PI * 0.67
    });
    figures.push({
      x: 280,
      y: 350,
      size: 25,
      connections: [],
      pulseOffset: p.PI * 1.33
    });

    // Add secondary figures
    for(let i = 0; i < 4; i++) {
      figures.push({
        x: p.random(80, 320),
        y: p.random(200, 500),
        size: p.random(12, 20),
        connections: [],
        pulseOffset: p.random(p.TWO_PI)
      });
    }

    // Create connections between figures
    for(let i = 0; i < figures.length; i++) {
      for(let j = i + 1; j < figures.length; j++) {
        let dist = p.dist(figures[i].x, figures[i].y, figures[j].x, figures[j].y);
        if(dist < 200) {
          connections.push({
            from: i,
            to: j,
            strength: p.map(dist, 0, 200, 1, 0.2),
            phase: p.random(p.TWO_PI)
          });
        }
      }
    }

    // Create atmospheric particles
    for(let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.3, 0.3),
        size: p.random(1, 3),
        alpha: p.random(20, 80)
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Dark gradient background
    for(let y = 0; y < p.height; y++) {
      let alpha = p.map(y, 0, p.height, 0.9, 0.3);
      p.stroke(15, 5, 25, alpha * 255);
      p.line(0, y, p.width, y);
    }

    // Draw door vault in background
    p.push();
    p.translate(0, 0);
    for(let door of doors) {
      if(door.glowing) {
        let glowPulse = p.sin(time * 2 + door.x * 0.01) * 0.5 + 0.5;
        let intensity = door.glowIntensity * glowPulse;

        // Door glow
        p.fill(80, 60, 120, intensity * 30);
        p.noStroke();
        p.ellipse(door.x, door.y, 40, 50);

        // Door outline
        p.stroke(120, 100, 180, intensity * 100);
        p.strokeWeight(1);
        p.noFill();
        p.rect(door.x - 8, door.y - 12, 16, 24);
      } else {
        // Dim doors
        p.stroke(40, 30, 60, 40);
        p.strokeWeight(0.5);
        p.noFill();
        p.rect(door.x - 6, door.y - 10, 12, 20);
      }
    }
    p.pop();

    // Atmospheric fog
    p.push();
    p.blendMode(p.SCREEN);
    for(let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;

      if(particle.x < 0) particle.x = p.width;
      if(particle.x > p.width) particle.x = 0;
      if(particle.y < 0) particle.y = p.height;
      if(particle.y > p.height) particle.y = 0;

      let mouseInfluence = p.dist(p.mouseX, p.mouseY, particle.x, particle.y);
      let alpha = p.map(mouseInfluence, 0, 150, particle.alpha * 2, particle.alpha);

      p.fill(60, 40, 80, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }
    p.pop();

    // Draw connections with energy flow
    p.strokeWeight(1);
    for(let conn of connections) {
      let from = figures[conn.from];
      let to = figures[conn.to];

      let pulse = p.sin(time * 3 + conn.phase) * 0.5 + 0.5;
      let mouseDistance = p.dist(p.mouseX, p.mouseY, (from.x + to.x) / 2, (from.y + to.y) / 2);
      let mouseEffect = p.map(mouseDistance, 0, 100, 2, 0.5);

      // Main connection line
      p.stroke(100, 80, 140, (conn.strength * 60 + pulse * 40) * mouseEffect);
      p.line(from.x, from.y, to.x, to.y);

      // Energy flow particles
      let flowPos = (time * 2 + conn.phase) % 1;
      let flowX = p.lerp(from.x, to.x, flowPos);
      let flowY = p.lerp(from.y, to.y, flowPos);

      p.fill(150, 120, 200, pulse * 150 * mouseEffect);
      p.noStroke();
      p.ellipse(flowX, flowY, 3);
    }

    // Draw figures as shadowy forms
    for(let i = 0; i < figures.length; i++) {
      let fig = figures[i];
      let pulse = p.sin(time * 2 + fig.pulseOffset) * 0.3 + 0.7;
      let mouseDistance = p.dist(p.mouseX, p.mouseY, fig.x, fig.y);
      let mouseEffect = p.map(mouseDistance, 0, 80, 1.5, 0.8);

      // Shadow aura
      p.fill(40, 20, 60, 60 * pulse * mouseEffect);
      p.noStroke();
      p.ellipse(fig.x, fig.y, fig.size * 2.5 * mouseEffect);

      // Core figure
      p.fill(80, 60, 120, 120 * pulse);
      p.ellipse(fig.x, fig.y, fig.size * mouseEffect);

      // Highlight for main triangle figures
      if(i < 3) {
        p.stroke(140, 120, 180, pulse * 80);
        p.strokeWeight(1);
        p.noFill();
        p.ellipse(fig.x, fig.y, fig.size * 1.3 * mouseEffect);
      }
    }

    // Interactive fear response
    if(p.mouseIsPressed) {
      // Ripple effect from mouse
      let rippleSize = (p.frameCount % 60) * 8;
      p.stroke(150, 100, 200, 255 - rippleSize * 4);
      p.strokeWeight(2);
      p.noFill();
      p.ellipse(p.mouseX, p.mouseY, rippleSize);

      // Disturb nearby particles
      for(let particle of particles) {
        let dist = p.dist(p.mouseX, p.mouseY, particle.x, particle.y);
        if(dist < 100) {
          particle.vx += p.random(-0.2, 0.2);
          particle.vy += p.random(-0.2, 0.2);
        }
      }
    }

    // Subtle vignette
    p.push();
    p.blendMode(p.MULTIPLY);
    for(let r = p.width; r > 0; r -= 20) {
      p.fill(0, 255 - r * 0.3);
      p.noStroke();
      p.ellipse(p.width/2, p.height/2, r * 2);
    }
    p.pop();
  };
}

function sketch(p) {
  let pillars = [];
  let doors = [];
  let fogParticles = [];
  let glowIntensity = 0;
  let foundationProgress = 0;
  let watchingEyes = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create four pillars positioned in corners of center square
    pillars = [
      {x: 150, y: 200, height: 0, targetHeight: 280, built: false},
      {x: 250, y: 200, height: 0, targetHeight: 280, built: false},
      {x: 150, y: 300, height: 0, targetHeight: 180, built: false},
      {x: 250, y: 300, height: 0, targetHeight: 180, built: false}
    ];

    // Create door vault rows in background
    for(let row = 0; row < 8; row++) {
      for(let col = 0; col < 15; col++) {
        doors.push({
          x: col * 30 - 20,
          y: row * 80 + 50,
          glow: p.random(0.3, 0.8),
          flickerSpeed: p.random(0.02, 0.05)
        });
      }
    }

    // Create fog particles
    for(let i = 0; i < 150; i++) {
      fogParticles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(2, 8),
        alpha: p.random(10, 40),
        drift: p.random(-0.3, 0.3),
        rise: p.random(0.1, 0.5)
      });
    }

    // Create watching eyes
    for(let i = 0; i < 6; i++) {
      watchingEyes.push({
        x: p.random(50, 350),
        y: p.random(50, 150),
        size: p.random(3, 8),
        blink: p.random(100, 300),
        blinkTimer: 0,
        visible: true
      });
    }
  };

  p.draw = function() {
    // Deep purple/black gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 5, 25), p.color(5, 2, 15), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Draw door vault in background
    drawDoorVault();

    // Draw fog
    drawFog();

    // Draw foundation square
    drawFoundation();

    // Draw pillars
    drawPillars();

    // Draw walls being built
    drawWalls();

    // Draw watching eyes
    drawWatchingEyes();

    // Add subtle glow effect
    p.drawingContext.shadowBlur = 0;

    // Update animations
    updateAnimations();
  };

  function drawDoorVault() {
    p.stroke(40, 30, 60, 100);
    p.strokeWeight(1);

    doors.forEach(door => {
      door.glow += door.flickerSpeed;
      let glowAmount = (p.sin(door.glow) + 1) * 0.5;

      // Door frame
      p.fill(20, 15, 35, 80);
      p.rect(door.x, door.y, 25, 45);

      // Door glow
      let glowColor = p.color(100, 50, 150, glowAmount * 30);
      p.fill(glowColor);
      p.noStroke();
      p.rect(door.x + 2, door.y + 2, 21, 41);
    });
  };

  function drawFog() {
    p.noStroke();

    fogParticles.forEach(particle => {
      particle.x += particle.drift;
      particle.y -= particle.rise;

      if(particle.y < -10) particle.y = p.height + 10;
      if(particle.x < -10) particle.x = p.width + 10;
      if(particle.x > p.width + 10) particle.x = -10;

      p.fill(80, 60, 120, particle.alpha);
      p.ellipse(particle.x, particle.y, particle.size);
    });
  };

  function drawFoundation() {
    foundationProgress += 0.005;
    let progress = p.constrain(foundationProgress, 0, 1);

    p.stroke(60, 40, 90, 200);
    p.strokeWeight(3);
    p.fill(25, 15, 45, 150);

    let size = 140 * progress;
    let centerX = 200;
    let centerY = 320;

    p.rect(centerX - size/2, centerY - size/2, size, size);

    // Foundation details
    if(progress > 0.7) {
      p.stroke(80, 50, 120, 100);
      p.strokeWeight(1);
      for(let i = 0; i < 4; i++) {
        let lineY = centerY - size/2 + (i + 1) * size/5;
        p.line(centerX - size/2, lineY, centerX + size/2, lineY);
      }
    }
  };

  function drawPillars() {
    pillars.forEach((pillar, index) => {
      if(foundationProgress > 0.5 && !pillar.built) {
        pillar.height += 2;
        if(pillar.height >= pillar.targetHeight) {
          pillar.built = true;
          pillar.height = pillar.targetHeight;
        }
      }

      // Pillar shadow
      p.fill(5, 2, 10, 100);
      p.noStroke();
      p.rect(pillar.x + 3, pillar.y - pillar.height + 3, 15, pillar.height);

      // Main pillar
      p.fill(40, 25, 70);
      p.stroke(60, 40, 100);
      p.strokeWeight(2);
      p.rect(pillar.x, pillar.y - pillar.height, 15, pillar.height);

      // Pillar details
      if(pillar.built) {
        p.stroke(80, 50, 120);
        p.strokeWeight(1);
        for(let i = 1; i < 4; i++) {
          let segmentY = pillar.y - (pillar.height * i / 4);
          p.line(pillar.x, segmentY, pillar.x + 15, segmentY);
        }
      }
    });
  };

  function drawWalls() {
    let allPillarsBuilt = pillars.every(p => p.built);

    if(allPillarsBuilt) {
      p.stroke(45, 30, 80, 150);
      p.strokeWeight(2);

      // Connecting walls between pillars
      let wallAlpha = p.map(p.sin(p.millis() * 0.003), -1, 1, 50, 100);
      p.fill(30, 20, 55, wallAlpha);

      // Top wall
      p.rect(150, 200 - 280, 115, 10);

      // Bottom wall
      p.rect(150, 300, 115, 10);

      // Left wall
      p.rect(150, 200 - 280, 10, 180);

      // Right wall
      p.rect(255, 200 - 280, 10, 180);
    }
  };

  function drawWatchingEyes() {
    watchingEyes.forEach(eye => {
      eye.blinkTimer++;

      if(eye.blinkTimer > eye.blink) {
        eye.visible = !eye.visible;
        eye.blinkTimer = 0;
        eye.blink = p.random(60, 200);
      }

      if(eye.visible) {
        // Eye glow
        p.fill(120, 80, 200, 60);
        p.noStroke();
        p.ellipse(eye.x, eye.y, eye.size * 2);

        // Eye
        p.fill(150, 100, 255, 180);
        p.ellipse(eye.x, eye.y, eye.size);

        // Pupil that follows mouse
        let angle = p.atan2(p.mouseY - eye.y, p.mouseX - eye.x);
        let pupilX = eye.x + p.cos(angle) * (eye.size * 0.2);
        let pupilY = eye.y + p.sin(angle) * (eye.size * 0.2);

        p.fill(20, 10, 40);
        p.ellipse(pupilX, pupilY, eye.size * 0.4);
      }
    });
  };

  function updateAnimations() {
    // Mouse interaction - intensify atmosphere near cursor
    let mouseInfluence = p.map(p.mouseY, 0, p.height, 1, 0.3);

    // Affect fog near mouse
    fogParticles.forEach(particle => {
      let distance = p.dist(p.mouseX, p.mouseY, particle.x, particle.y);
      if(distance < 80) {
        particle.drift += (p.mouseX - particle.x) * 0.0001;
        particle.rise += 0.1;
      }
    });
  };

  p.mousePressed = function() {
    // Add disturbing ripple effect
    for(let i = 0; i < 20; i++) {
      fogParticles.push({
        x: p.mouseX + p.random(-30, 30),
        y: p.mouseY + p.random(-30, 30),
        size: p.random(3, 12),
        alpha: p.random(20, 60),
        drift: p.random(-1, 1),
        rise: p.random(0.5, 1.5)
      });
    }

    // Keep fog particle count manageable
    if(fogParticles.length > 200) {
      fogParticles.splice(0, 50);
    }
  };
}

function sketch(p) {
  let crack = [];
  let doorGlow;
  let fogParticles = [];
  let crackProgress = 0;
  let glowIntensity = 0;
  let watcherEyes = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize the crack points
    for(let i = 0; i < 8; i++) {
      crack.push({
        x: 200 + p.random(-30, 30),
        y: 100 + i * 60 + p.random(-20, 20),
        offset: p.random(-15, 15)
      });
    }

    // Initialize fog particles
    for(let i = 0; i < 40; i++) {
      fogParticles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(20, 80),
        speed: p.random(0.3, 0.8),
        alpha: p.random(10, 40)
      });
    }

    // Initialize watcher eyes
    for(let i = 0; i < 6; i++) {
      watcherEyes.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        blinkTimer: p.random(60, 300),
        isBlinking: false
      });
    }
  };

  p.draw = function() {
    // Dark gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 5, 25), p.color(5, 0, 15), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Door vault rows in background
    p.stroke(30, 20, 40, 60);
    p.strokeWeight(1);
    for(let y = 80; y < p.height - 100; y += 40) {
      for(let x = 30; x < p.width - 30; x += 60) {
        p.noFill();
        p.rect(x, y, 50, 30);
        // Subtle door glow
        if(p.random() < 0.02) {
          p.fill(80, 60, 120, 20);
          p.noStroke();
          p.ellipse(x + 25, y + 15, 20, 20);
        }
      }
    }

    // Animate crack progress
    crackProgress += 0.008;
    if(crackProgress > 1) crackProgress = 1;

    // Draw the main crack
    p.stroke(60, 40, 80);
    p.strokeWeight(3);
    p.noFill();

    // Jagged crack line
    p.beginShape();
    for(let i = 0; i < crack.length * crackProgress; i++) {
      let point = crack[i];
      if(point) {
        let x = point.x + p.sin(p.frameCount * 0.01 + i) * 2;
        let y = point.y + point.offset * p.sin(p.frameCount * 0.02 + i);
        p.vertex(x, y);
      }
    }
    p.endShape();

    // Crack glow effect
    glowIntensity = p.sin(p.frameCount * 0.03) * 30 + 40;
    p.stroke(120, 80, 160, glowIntensity);
    p.strokeWeight(8);
    p.beginShape();
    for(let i = 0; i < crack.length * crackProgress; i++) {
      let point = crack[i];
      if(point) {
        let x = point.x + p.sin(p.frameCount * 0.01 + i) * 2;
        let y = point.y + point.offset * p.sin(p.frameCount * 0.02 + i);
        p.vertex(x, y);
      }
    }
    p.endShape();

    // Something emerging from the crack
    if(crackProgress > 0.7) {
      let emergenceAlpha = p.map(crackProgress, 0.7, 1, 0, 100);
      p.fill(200, 180, 220, emergenceAlpha);
      p.noStroke();
      let emergenceY = 300 + p.sin(p.frameCount * 0.02) * 20;
      p.ellipse(200, emergenceY, 40, 60);

      // Tendrils of light
      p.stroke(180, 160, 200, emergenceAlpha * 0.8);
      p.strokeWeight(2);
      for(let i = 0; i < 5; i++) {
        let angle = i * p.PI * 0.4 - p.PI * 0.8;
        let length = 30 + p.sin(p.frameCount * 0.03 + i) * 10;
        let endX = 200 + p.cos(angle) * length;
        let endY = emergenceY + p.sin(angle) * length;
        p.line(200, emergenceY, endX, endY);
      }
    }

    // Fog particles
    for(let particle of fogParticles) {
      particle.x += particle.speed;
      particle.y += p.sin(p.frameCount * 0.01 + particle.x * 0.01) * 0.5;

      if(particle.x > p.width + particle.size) {
        particle.x = -particle.size;
        particle.y = p.random(p.height);
      }

      p.fill(40, 30, 60, particle.alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size, particle.size * 0.6);
    }

    // Watching eyes
    for(let eye of watcherEyes) {
      eye.blinkTimer--;
      if(eye.blinkTimer <= 0) {
        eye.isBlinking = !eye.isBlinking;
        eye.blinkTimer = eye.isBlinking ? p.random(5, 15) : p.random(60, 300);
      }

      if(!eye.isBlinking) {
        // Eye glow
        p.fill(80, 60, 100, 40);
        p.noStroke();
        p.ellipse(eye.x, eye.y, 12, 8);

        // Pupil that follows mouse
        let eyeToMouse = p.createVector(p.mouseX - eye.x, p.mouseY - eye.y);
        eyeToMouse.normalize();
        eyeToMouse.mult(2);

        p.fill(150, 120, 180, 80);
        p.ellipse(eye.x + eyeToMouse.x, eye.y + eyeToMouse.y, 4, 4);
      }
    }

    // Interactive disruption effect
    if(p.mouseIsPressed) {
      let disruptionStrength = p.dist(p.mouseX, p.mouseY, 200, 300) / 100;

      // Ripple effect from mouse
      p.noFill();
      p.stroke(100, 70, 140, 60);
      p.strokeWeight(2);
      let rippleSize = (p.frameCount % 60) * 5;
      p.ellipse(p.mouseX, p.mouseY, rippleSize, rippleSize);

      // Distortion around the crack
      if(disruptionStrength < 2) {
        for(let i = 0; i < crack.length; i++) {
          crack[i].offset += p.random(-2, 2);
          crack[i].offset = p.constrain(crack[i].offset, -25, 25);
        }
      }
    }

    // Subtle frame vignette
    p.noFill();
    p.stroke(0, 0, 0, 80);
    p.strokeWeight(20);
    p.rect(0, 0, p.width, p.height);
  };
}

function sketch(p) {
  let doors = [];
  let shadowOrbs = [];
  let fog = [];
  let glowPulse = 0;
  let balanceAngle = 0;
  let mouseInfluence = 0;
  let transitionProgress = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Create six floating shadow orbs representing the six elements finding balance
    for (let i = 0; i < 6; i++) {
      let angle = (p.TWO_PI / 6) * i;
      shadowOrbs.push({
        x: 200 + p.cos(angle) * 80,
        y: 300 + p.sin(angle) * 60,
        targetX: 200 + p.cos(angle) * 80,
        targetY: 300 + p.sin(angle) * 60,
        size: 25 + p.random(10),
        glow: p.random(20, 40),
        phase: p.random(p.TWO_PI),
        settled: false
      });
    }

    // Create door vault background elements
    for (let i = 0; i < 15; i++) {
      doors.push({
        x: p.random(-50, 450),
        y: p.random(50, 550),
        width: p.random(20, 35),
        height: p.random(40, 60),
        glow: p.random(5, 25),
        flickerSpeed: p.random(0.01, 0.03)
      });
    }

    // Create fog particles
    for (let i = 0; i < 80; i++) {
      fog.push({
        x: p.random(-20, 420),
        y: p.random(0, 600),
        size: p.random(30, 80),
        alpha: p.random(3, 12),
        drift: p.random(-0.3, 0.3)
      });
    }
  };

  p.draw = function() {
    // Deep purple-black gradient background
    for (let y = 0; y < p.height; y++) {
      let alpha = p.map(y, 0, p.height, 0.8, 0.3);
      p.stroke(270, 80, 8, alpha * 100);
      p.line(0, y, p.width, y);
    }

    glowPulse += 0.02;
    balanceAngle += 0.008;
    transitionProgress = p.min(transitionProgress + 0.01, 1);

    // Mouse influence for subtle interaction
    mouseInfluence = p.lerp(mouseInfluence, p.dist(p.mouseX, p.mouseY, 200, 300) / 200, 0.05);

    // Draw distant door vault atmosphere
    p.noStroke();
    for (let door of doors) {
      let flicker = p.noise(p.frameCount * door.flickerSpeed, door.x * 0.01) * 0.5 + 0.5;
      let doorGlow = door.glow * flicker * (1 - mouseInfluence * 0.3);

      // Door silhouette
      p.fill(270, 60, 5, 40);
      p.rect(door.x, door.y, door.width, door.height, 3);

      // Door glow
      p.fill(280, 70, 30, doorGlow);
      p.rect(door.x + 2, door.y + 2, door.width - 4, door.height - 4, 2);
    }

    // Draw moving fog
    for (let f of fog) {
      f.x += f.drift + p.sin(glowPulse + f.y * 0.01) * 0.2;
      if (f.x > 430) f.x = -30;
      if (f.x < -30) f.x = 430;

      p.fill(260, 40, 15, f.alpha * (1 + mouseInfluence * 0.5));
      p.ellipse(f.x, f.y, f.size);
    }

    // Draw the six shadow orbs finding their new balance
    for (let i = 0; i < shadowOrbs.length; i++) {
      let orb = shadowOrbs[i];

      // Settling into new positions based on transition progress
      let disturbance = (1 - transitionProgress) * 30 * p.sin(glowPulse * 2 + i);
      let mouseDisturbance = mouseInfluence * 20 * p.sin(p.frameCount * 0.1 + i);

      orb.targetX = 200 + p.cos(balanceAngle + (p.TWO_PI / 6) * i) * (70 + disturbance);
      orb.targetY = 300 + p.sin(balanceAngle + (p.TWO_PI / 6) * i) * (50 + disturbance) + mouseDisturbance;

      orb.x = p.lerp(orb.x, orb.targetX, 0.03);
      orb.y = p.lerp(orb.y, orb.targetY, 0.03);

      // Check if orb has settled
      if (p.abs(orb.x - orb.targetX) < 2 && p.abs(orb.y - orb.targetY) < 2) {
        orb.settled = true;
      }

      // Draw orb glow
      let glowIntensity = orb.glow * (0.7 + 0.3 * p.sin(glowPulse + orb.phase));
      if (orb.settled) glowIntensity *= 1.3;

      p.fill(290, 70, 25, glowIntensity * 0.8);
      p.ellipse(orb.x, orb.y, orb.size * 2);

      p.fill(290, 60, 35, glowIntensity);
      p.ellipse(orb.x, orb.y, orb.size * 1.5);

      // Core shadow orb
      p.fill(280, 80, 45, 80);
      p.ellipse(orb.x, orb.y, orb.size);

      // Inner darkness
      p.fill(270, 90, 8, 60);
      p.ellipse(orb.x, orb.y, orb.size * 0.6);
    }

    // Draw connecting lines between orbs when they're settling
    p.stroke(285, 50, 20, 30 * transitionProgress);
    p.strokeWeight(1);
    for (let i = 0; i < shadowOrbs.length; i++) {
      let next = (i + 1) % shadowOrbs.length;
      p.line(shadowOrbs[i].x, shadowOrbs[i].y, shadowOrbs[next].x, shadowOrbs[next].y);
    }

    // Central convergence point - the new balance
    let centralGlow = 20 + 15 * p.sin(glowPulse * 1.5);
    centralGlow *= (0.5 + 0.5 * transitionProgress);

    p.noStroke();
    p.fill(275, 60, 30, centralGlow * 0.6);
    p.ellipse(200, 300, 40);

    p.fill(275, 70, 40, centralGlow);
    p.ellipse(200, 300, 25);

    // Subtle vignette effect
    for (let r = 0; r < 100; r++) {
      p.noFill();
      p.stroke(270, 80, 5, (100 - r) * 0.3);
      p.strokeWeight(2);
      p.ellipse(200, 300, r * 8);
    }
  };

  p.mousePressed = function() {
    // Reset transition on click - things fall back into chaos briefly
    transitionProgress = 0;
    for (let orb of shadowOrbs) {
      orb.settled = false;
      orb.x += p.random(-20, 20);
      orb.y += p.random(-20, 20);
    }
  };
}

function sketch(p) {
  let figure;
  let doors = [];
  let fogParticles = [];
  let paths = [];
  let glowIntensity = 0;
  let figureY;
  let contemplationPhase = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize figure position
    figure = {
      x: 200,
      y: 400,
      lookBack: 0
    };

    figureY = figure.y;

    // Create seven doors/paths in the background
    for(let i = 0; i < 7; i++) {
      doors.push({
        x: (i % 3) * 120 + 60,
        y: (Math.floor(i / 3)) * 80 + 80,
        glow: p.random(0.3, 0.8),
        pulseOffset: p.random(0, p.TWO_PI),
        depth: p.random(0.5, 1.5)
      });
    }

    // Create seven diverging paths
    for(let i = 0; i < 7; i++) {
      paths.push({
        angle: p.map(i, 0, 6, -p.PI/3, p.PI/3),
        opacity: 0.3,
        chosen: false
      });
    }

    // Initialize fog particles
    for(let i = 0; i < 60; i++) {
      fogParticles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(20, 80),
        drift: p.random(-0.5, 0.5),
        opacity: p.random(0.1, 0.4),
        speed: p.random(0.2, 0.8)
      });
    }
  };

  p.draw = function() {
    // Deep purple-black gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(20, 10, 40), p.color(5, 0, 15), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Mouse influence for atmosphere
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0.5, 1.5);

    // Draw distant door vault rows
    p.push();
    p.translate(0, -50);
    for(let row = 0; row < 4; row++) {
      for(let col = 0; col < 8; col++) {
        let x = col * 50 + 25;
        let y = row * 60 + 30;
        let distance = p.dist(x, y, p.mouseX, p.mouseY + 50);
        let glow = p.map(distance, 0, 300, 0.8, 0.2);

        p.fill(60, 40, 120, glow * 80);
        p.noStroke();
        p.rect(x, y, 30, 40, 3);

        // Door glow
        if(p.random() < 0.01) {
          p.fill(180, 120, 255, 60);
          p.rect(x-2, y-2, 34, 44, 3);
        }
      }
    }
    p.pop();

    // Draw fog layers
    for(let particle of fogParticles) {
      particle.x += particle.drift * mouseInfluence;
      particle.y += particle.speed * 0.3;

      if(particle.y > p.height + 50) {
        particle.y = -50;
        particle.x = p.random(p.width);
      }

      if(particle.x > p.width + 50) particle.x = -50;
      if(particle.x < -50) particle.x = p.width + 50;

      p.fill(30, 20, 60, particle.opacity * 255 * mouseInfluence);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Draw the seven paths ahead
    p.push();
    p.translate(figure.x, figure.y + 50);
    p.stroke(80, 60, 140, 100);
    p.strokeWeight(2);

    for(let i = 0; i < paths.length; i++) {
      let path = paths[i];
      let mouseDistance = p.dist(p.mouseX, p.mouseY, figure.x + p.cos(path.angle) * 100, figure.y + 50 + p.sin(path.angle) * 100);

      if(mouseDistance < 50) {
        path.opacity = p.lerp(path.opacity, 0.8, 0.05);
        p.strokeWeight(3);
      } else {
        path.opacity = p.lerp(path.opacity, 0.3, 0.02);
        p.strokeWeight(2);
      }

      p.stroke(120, 80, 200, path.opacity * 255);
      p.line(0, 0, p.cos(path.angle) * 150, p.sin(path.angle) * 150);
    }
    p.pop();

    // Contemplation phase based on time
    contemplationPhase = p.sin(p.millis() * 0.001) * 0.5 + 0.5;

    // Figure looking back gesture
    let mouseInfluenceX = p.map(p.mouseX, 0, p.width, -0.3, 0.3);
    figure.lookBack = p.lerp(figure.lookBack, mouseInfluenceX, 0.05);

    // Draw the questioning figure
    p.push();
    p.translate(figure.x, figure.y);

    // Figure shadow
    p.fill(0, 0, 0, 80);
    p.noStroke();
    p.ellipse(5, 60, 40, 15);

    // Body silhouette
    p.fill(25, 15, 45);
    p.stroke(60, 40, 100, 150);
    p.strokeWeight(1);

    // Torso with slight turn
    p.push();
    p.rotate(figure.lookBack * 0.2);
    p.rect(-15, 10, 30, 50, 5);
    p.pop();

    // Head turning back
    p.push();
    p.rotate(figure.lookBack * 0.5 + contemplationPhase * 0.1);
    p.ellipse(0, -5, 25, 30);

    // Contemplative glow around head
    p.fill(100, 70, 150, contemplationPhase * 50);
    p.noStroke();
    p.ellipse(0, -5, 35, 40);
    p.pop();

    // Arms in questioning gesture
    p.stroke(60, 40, 100, 150);
    p.strokeWeight(3);
    p.line(-10, 20, -20 + figure.lookBack * 10, 10);
    p.line(10, 20, 20 + figure.lookBack * 10, 10);

    // Legs
    p.line(-8, 55, -12, 85);
    p.line(8, 55, 12, 85);

    p.pop();

    // What's been built behind - institutional structures
    p.push();
    p.translate(figure.x, figure.y);
    p.rotate(p.PI);

    for(let i = 0; i < 5; i++) {
      let x = i * 30 - 60;
      let height = 40 + i * 10;

      p.fill(40, 25, 70, 120);
      p.stroke(80, 50, 120, 100);
      p.strokeWeight(1);
      p.rect(x, 50, 25, height);

      // Windows suggesting corporate structure
      for(let w = 0; w < 3; w++) {
        let windowY = 60 + w * 15;
        p.fill(100, 80, 150, 80);
        p.noStroke();
        p.rect(x + 5, windowY, 15, 8);
      }
    }
    p.pop();

    // Atmospheric lighting effects
    glowIntensity = p.sin(p.millis() * 0.002) * 0.3 + 0.7;

    // Ambient fear/uncertainty particles
    if(p.frameCount % 30 === 0) {
      fogParticles.push({
        x: p.random(p.width),
        y: p.height + 20,
        size: p.random(10, 30),
        drift: p.random(-0.3, 0.3),
        opacity: p.random(0.05, 0.2),
        speed: p.random(0.5, 1.2)
      });
    }

    // Remove excess particles
    if(fogParticles.length > 80) {
      fogParticles.splice(0, 10);
    }

    // Interactive glow on mouse proximity
    let distanceToFigure = p.dist(p.mouseX, p.mouseY, figure.x, figure.y);
    if(distanceToFigure < 100) {
      p.fill(150, 100, 200, 30);
      p.noStroke();
      p.ellipse(figure.x, figure.y, 120, 120);
    }
  };
}

function sketch(p) {
  let doors = [];
  let fog = [];
  let shadows = [];
  let glowIntensity = 0;
  let coordinated = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create door vault in background
    for(let i = 0; i < 12; i++) {
      for(let j = 0; j < 8; j++) {
        doors.push({
          x: j * 50 + 25,
          y: i * 45 + 100,
          glow: p.random(0.1, 0.3),
          phase: p.random(p.TWO_PI)
        });
      }
    }

    // Create fog particles
    for(let i = 0; i < 60; i++) {
      fog.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(30, 80),
        speed: p.random(0.2, 0.8),
        opacity: p.random(0.05, 0.15)
      });
    }

    // Create eight shadow figures in formation
    let centerX = p.width / 2;
    let centerY = p.height / 2;
    let radius = 120;
    for(let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI - p.PI/2;
      shadows.push({
        x: centerX + p.cos(angle) * radius,
        y: centerY + p.sin(angle) * radius + 50,
        baseX: centerX + p.cos(angle) * radius,
        baseY: centerY + p.sin(angle) * radius + 50,
        angle: angle,
        height: p.random(40, 70),
        width: p.random(15, 25),
        phase: i * 0.8,
        tool: i % 3 // Different tool types
      });
    }
  };

  p.draw = function() {
    // Deep purple-black gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(20, 10, 40), p.color(5, 0, 15), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Mouse interaction affects coordination
    let mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);
    coordinated = p.lerp(coordinated, mouseInfluence, 0.05);

    // Draw door vault with subtle glow
    p.noStroke();
    for(let door of doors) {
      let distance = p.dist(p.mouseX, p.mouseY, door.x, door.y);
      let intensity = p.map(distance, 0, 200, 0.4, 0.1);
      intensity = p.constrain(intensity, 0.1, 0.4);

      let glowSize = 8 + p.sin(p.millis() * 0.001 + door.phase) * 2;
      p.fill(100, 60, 150, intensity * 255);
      p.rect(door.x - 2, door.y - 3, 4, 6);

      // Door glow
      p.fill(120, 80, 200, intensity * 80);
      p.rect(door.x - glowSize/2, door.y - glowSize/2, glowSize, glowSize);
    }

    // Draw moving fog
    for(let f of fog) {
      f.x += f.speed;
      f.y += p.sin(p.millis() * 0.001 + f.x * 0.01) * 0.3;

      if(f.x > p.width + f.size) f.x = -f.size;

      p.fill(80, 60, 120, f.opacity * 255);
      p.ellipse(f.x, f.y, f.size);
    }

    // Draw eight shadow figures working in coordination
    for(let i = 0; i < shadows.length; i++) {
      let shadow = shadows[i];

      // Coordinated movement - they work together
      let time = p.millis() * 0.002;
      let coordination = p.sin(time + shadow.phase) * coordinated * 20;
      let workMotion = p.sin(time * 2 + shadow.phase) * 5;

      shadow.x = shadow.baseX + coordination;
      shadow.y = shadow.baseY + workMotion;

      // Mouse interaction - shadows lean toward cursor
      if(p.mouseIsPressed) {
        let lean = p.map(p.dist(p.mouseX, p.mouseY, shadow.x, shadow.y), 0, 200, 10, 0);
        let leanAngle = p.atan2(p.mouseY - shadow.y, p.mouseX - shadow.x);
        shadow.x += p.cos(leanAngle) * lean;
        shadow.y += p.sin(leanAngle) * lean;
      }

      // Draw shadow figure
      p.fill(0, 0, 0, 180);
      p.noStroke();

      // Body
      p.ellipse(shadow.x, shadow.y, shadow.width, shadow.height);

      // Tool/implement being used
      p.stroke(40, 20, 80, 200);
      p.strokeWeight(2);
      let toolAngle = time + shadow.phase + shadow.angle;
      let toolLength = 25;

      if(shadow.tool === 0) {
        // Scare tool
        p.line(shadow.x, shadow.y, 
               shadow.x + p.cos(toolAngle) * toolLength,
               shadow.y + p.sin(toolAngle) * toolLength);
      } else if(shadow.tool === 1) {
        // Energy collector
        p.fill(60, 40, 100, 150);
        p.noStroke();
        p.ellipse(shadow.x + p.cos(toolAngle) * 15, 
                  shadow.y + p.sin(toolAngle) * 15, 8);
      } else {
        // Door key
        p.stroke(80, 50, 120, 180);
        p.strokeWeight(3);
        p.point(shadow.x + p.cos(toolAngle) * 12, 
                shadow.y + p.sin(toolAngle) * 12);
      }
    }

    // Atmospheric glow effect
    glowIntensity = 50 + p.sin(p.millis() * 0.003) * 20;
    p.fill(60, 30, 100, glowIntensity);
    p.noStroke();
    p.ellipse(p.width/2, p.height/2, 300, 300);

    // Vignette effect
    for(let r = 0; r < 100; r++) {
      let alpha = p.map(r, 0, 100, 0, 0.8);
      p.fill(0, 0, 0, alpha);
      p.noStroke();
      p.rect(0, 0, p.width, r);
      p.rect(0, p.height - r, p.width, r);
      p.rect(0, 0, r, p.height);
      p.rect(p.width - r, 0, r, p.height);
    }
  };
}

