    for(let door of doors) {
      // Door glow effect
      let glowPulse = p.sin(p.frameCount * door.flickerSpeed) * 0.3 + 0.7;
      let glowAlpha = door.glowIntensity * glowPulse * 0.6;

      // Purple door glow
      p.fill(80, 40, 120, glowAlpha * 255);
      p.ellipse(door.x + door.width/2, door.y + door.height/2, door.width * 2, door.height * 1.5);

      // Door rectangle
      p.fill(25, 15, 35);
      p.rect(door.x, door.y, door.width, door.height);

      // Door handle glow
      p.fill(100, 60, 150, glowAlpha * 200);
      p.ellipse(door.x + door.width - 5, door.y + door.height/2, 3, 3);
    }

    // Draw fog particles
    p.noStroke();
    for(let fog of fogParticles) {
      fog.x += fog.drift;
      fog.y += p.sin(p.frameCount * 0.01 + fog.x * 0.01) * 0.2;

      if(fog.x > p.width + 10) fog.x = -10;
      if(fog.x < -10) fog.x = p.width + 10;

      let mouseInfluence = p.dist(p.mouseX, p.mouseY, fog.x, fog.y);
      let influenced = p.map(mouseInfluence, 0, 100, 0.8, 0.3);
      influenced = p.constrain(influenced, 0.3, 0.8);

      p.fill(40, 30, 60, fog.alpha * 255 * influenced);
      p.ellipse(fog.x, fog.y, fog.size, fog.size);
    }

    // Draw achievement elements (9 glowing orbs in formation)
    for(let i = 0; i < achievementElements.length; i++) {
      let element = achievementElements[i];
      let pulse = p.sin(p.frameCount * 0.02 + element.pulse) * 0.3 + 0.7;
      let mouseDistance = p.dist(p.mouseX, p.mouseY, element.x, element.y);
      let mouseEffect = p.map(mouseDistance, 0, 100, 2, 1);
      mouseEffect = p.constrain(mouseEffect, 1, 2);

      // Outer glow
      p.fill(120, 80, 180, 80 * pulse);
      p.ellipse(element.x, element.y, element.size * 3 * mouseEffect, element.size * 3 * mouseEffect);

      // Inner orb
      p.fill(150, 100, 220, 180 * pulse);
      p.ellipse(element.x, element.y, element.size * mouseEffect, element.size * mouseEffect);

      // Core light
      p.fill(200, 160, 255, 120);
      p.ellipse(element.x, element.y, element.size * 0.5, element.size * 0.5);
    }

    // Draw figure silhouette
    figure.sway = p.sin(p.frameCount * 0.01) * 2;
    p.fill(10, 5, 15);
    p.stroke(60, 40, 80);
    p.strokeWeight(1);

    // Body
    p.ellipse(figure.x + figure.sway, figure.y, 40, 80);
    // Head
    p.ellipse(figure.x + figure.sway, figure.y - 50, 25, 30);
    // Arms (surveying gesture)
    p.noFill();
    p.strokeWeight(3);
    p.stroke(20, 15, 30);
    // Left arm pointing toward achievement
    p.line(figure.x - 15 + figure.sway, figure.y - 20, figure.x - 35 + figure.sway, figure.y - 35);
    // Right arm on hip (satisfied stance)
    p.line(figure.x + 15 + figure.sway, figure.y - 20, figure.x + 25 + figure.sway, figure.y - 5);

    // Draw watching eyes in the darkness
    p.noStroke();
    for(let eye of watchingEyes) {
      eye.blinkTimer++;
      if(eye.blinkTimer > eye.blink) {
        eye.blinkTimer = 0;
        eye.blink = p.random(100, 300);
      }

      let eyeOpen = eye.blinkTimer < 10 ? 0 : 1;
      let mouseDistance = p.dist(p.mouseX, p.mouseY, eye.x, eye.y);
      let watching = p.map(mouseDistance, 0, 200, 1, 0.3);
      watching = p.constrain(watching, 0.3, 1);

      if(eyeOpen > 0) {
        // Eye glow
        p.fill(100, 60, 80, 60 * watching);
        p.ellipse(eye.x, eye.y, 12, 12);

        // Eye
        p.fill(180, 120, 140, 120 * watching);
        p.ellipse(eye.x, eye.y, 6, 6);

        // Pupil following mouse
        let pupilX = eye.x + (p.mouseX - eye.x) * 0.02;
        let pupilY = eye.y + (p.mouseY - eye.y) * 0.02;
        p.fill(80, 40, 60);
        p.ellipse(pupilX, pupilY, 3, 3);
      }
    }

    // Liminal lighting effect
    let liminalGlow = p.sin(p.frameCount * 0.005) * 30 + 50;
    p.fill(60, 30, 90, liminalGlow);
    p.rect(0, 0, p.width, p.height);

    // Mouse interaction - create disturbance in fog when clicked
    if(p.mouseIsPressed) {
      for(let i = 0; i < 5; i++) {
        fogParticles.push({
          x: p.mouseX + p.random(-20, 20),
          y: p.mouseY + p.random(-20, 20),
          size: p.random(3, 12),
          alpha: p.random(0.2, 0.6),
          drift: p.random(-2, 2)
        });
      }

      // Remove excess particles
      if(fogParticles.length > 200) {
        fogParticles.splice(0, 50);
      }
    }
  };
}

function sketch(p) {
  let doors = [];
  let overflow = [];
  let fog = [];
  let glowIntensity = 0;
  let completionCycle = 0;
  let watchingEyes = [];
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create ten door structures in a completion pattern
    for(let i = 0; i < 10; i++) {
      let angle = (i / 10) * p.TWO_PI;
      let radius = 120;
      doors.push({
        x: 200 + p.cos(angle) * radius,
        y: 300 + p.sin(angle) * radius * 0.6,
        glowPhase: i * 0.6,
        energy: 0,
        overflowing: false,
        depth: p.random(0.3, 1)
      });
    }

    // Create overflow particles
    for(let i = 0; i < 200; i++) {
      overflow.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-1, 1),
        vy: p.random(-2, 0.5),
        life: p.random(1),
        maxLife: p.random(100, 300),
        size: p.random(2, 8)
      });
    }

    // Create fog layers
    for(let i = 0; i < 100; i++) {
      fog.push({
        x: p.random(-50, 450),
        y: p.random(600),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.2, 0.2),
        size: p.random(30, 100),
        alpha: p.random(10, 40)
      });
    }

    // Create watching eyes in the shadows
    for(let i = 0; i < 15; i++) {
      watchingEyes.push({
        x: p.random(50, 350),
        y: p.random(50, 550),
        blink: p.random(100),
        intensity: p.random(0.3, 0.8)
      });
    }
  };

  p.draw = function() {
    // Deep purple-black gradient background
    for(let y = 0; y < 600; y++) {
      let inter = p.map(y, 0, 600, 0, 1);
      let c = p.lerpColor(p.color(15, 5, 25), p.color(5, 0, 15), inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    // Mouse influence for unease
    mouseInfluence = p.lerp(mouseInfluence, p.map(p.mouseX + p.mouseY, 0, 1000, 0, 1), 0.05);

    // Draw fog layers
    p.noStroke();
    for(let f of fog) {
      f.x += f.vx + mouseInfluence * 0.1;
      f.y += f.vy;

      if(f.x > 450) f.x = -50;
      if(f.x < -50) f.x = 450;
      if(f.y > 650) f.y = -50;
      if(f.y < -50) f.y = 650;

      p.fill(20, 10, 40, f.alpha);
      p.ellipse(f.x, f.y, f.size, f.size * 0.6);
    }

    // Draw watching eyes
    for(let eye of watchingEyes) {
      eye.blink += 1;
      let blinkCycle = p.sin(eye.blink * 0.02) * 0.5 + 0.5;

      if(p.random(1) < 0.003) {
        eye.blink += 30; // Random blinks
      }

      let eyeGlow = eye.intensity * (0.5 + mouseInfluence * 0.5);
      p.fill(80, 20, 120, eyeGlow * 100);
      p.ellipse(eye.x, eye.y, 4, 4 * blinkCycle);
      p.fill(150, 80, 200, eyeGlow * 150);
      p.ellipse(eye.x, eye.y, 2, 2 * blinkCycle);
    }

    // Calculate completion cycle
    completionCycle += 0.01;
    glowIntensity = p.sin(completionCycle) * 0.3 + 0.7;

    // Draw the ten doors in completion formation
    for(let i = 0; i < doors.length; i++) {
      let door = doors[i];
      door.energy = p.sin(completionCycle + door.glowPhase) * 0.4 + 0.6;

      // Check if structure is overflowing (completion state)
      let overflow = completionCycle % (p.TWO_PI) > p.PI * 1.5;
      door.overflowing = overflow && door.energy > 0.8;

      p.push();
      p.translate(door.x, door.y);
      p.scale(door.depth);

      // Door glow effect
      let glowSize = 25 + door.energy * 15 + mouseInfluence * 10;
      let glowColor = door.overflowing ? 
        p.color(120, 60, 200, door.energy * 100) : 
        p.color(60, 40, 150, door.energy * 80);

      // Outer glow
      p.fill(p.red(glowColor), p.green(glowColor), p.blue(glowColor), 30);
      p.noStroke();
      p.ellipse(0, 0, glowSize * 2, glowSize * 2);

      // Door frame silhouette
      p.fill(40, 20, 60);
      p.rect(-8, -15, 16, 30, 3);

      // Door glow
      p.fill(glowColor);
      p.rect(-6, -12, 12, 24, 2);

      // Handle
      p.fill(80, 60, 100);
      p.ellipse(4, 0, 2, 2);

      p.pop();
    }

    // Draw overflow energy particles when completion is reached
    for(let particle of overflow) {
      particle.life++;

      if(particle.life > particle.maxLife) {
        particle.life = 0;
        particle.x = 200 + p.random(-150, 150);
        particle.y = 300 + p.random(-150, 150);
        particle.vx = p.random(-2, 2);
        particle.vy = p.random(-3, 1);
      }

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.vy += 0.02; // gravity

      let alpha = p.map(particle.life, 0, particle.maxLife, 255, 0);
      let overflowActive = completionCycle % (p.TWO_PI) > p.PI * 1.5;

      if(overflowActive) {
        p.fill(150, 100, 255, alpha * 0.6);
        p.noStroke();
        p.ellipse(particle.x, particle.y, particle.size, particle.size);
      }
    }

    // Center completion symbol - the overflowing cup
    p.push();
    p.translate(200, 300);

    let centerGlow = glowIntensity + mouseInfluence * 0.3;

    // Cup base
    p.fill(30, 15, 50);
    p.noStroke();
    p.arc(0, 0, 40, 40, 0, p.PI);

    // Cup overflow
    let overflowHeight = p.map(p.sin(completionCycle * 2), -1, 1, -10, 10);
    p.fill(100, 60, 180, centerGlow * 200);
    p.ellipse(0, overflowHeight - 15, 30, 8);

    // Overflow streams
    if(overflowHeight > -5) {
      for(let i = 0; i < 5; i++) {
        let streamX = p.map(i, 0, 4, -15, 15);
        p.fill(80, 40, 160, centerGlow * 100);
        p.rect(streamX, -10, 2, 30);
      }
    }

    p.pop();

    // Liminal space effect - vertical scanning lines
    p.stroke(60, 30, 100, 30 + mouseInfluence * 50);
    for(let x = 0; x < 400; x += 20) {
      let offset = p.sin(x * 0.05 + completionCycle * 3) * 5;
      p.line(x, 0, x + offset, 600);
    }
  };

  p.mousePressed = function() {
    // Disturb the watching eyes
    for(let eye of watchingEyes) {
      let d = p.dist(p.mouseX, p.mouseY, eye.x, eye.y);
      if(d < 50) {
        eye.blink += 60;
        eye.intensity = p.random(0.8, 1.2);
      }
    }

    // Intensify door energy near mouse
    for(let door of doors) {
      let d = p.dist(p.mouseX, p.mouseY, door.x, door.y);
      if(d < 80) {
        door.glowPhase += p.random(-0.5, 0.5);
        door.energy += 0.3;
      }
    }
  };
}

function sketch(p) {
  let doors = [];
  let trainee;
  let mentor;
  let fogParticles = [];
  let doorGlow = 0;
  let watchingEyes = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create door vault rows
    for (let row = 0; row < 8; row++) {
      for (let col = 0; col < 6; col++) {
        doors.push({
          x: col * 65 + 10,
          y: row * 70 + 50,
          w: 50,
          h: 60,
          glow: p.random(0.2, 0.8),
          glowSpeed: p.random(0.01, 0.03)
        });
      }
    }

    // Trainee position (eager, attentive)
    trainee = {
      x: 120,
      y: 450,
      bobOffset: 0
    };

    // Mentor position (experienced, showing the ropes)
    mentor = {
      x: 250,
      y: 430,
      armAngle: 0
    };

    // Create fog particles
    for (let i = 0; i < 80; i++) {
      fogParticles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(20, 60),
        alpha: p.random(10, 30),
        speed: p.random(0.2, 0.8),
        direction: p.random(p.TWO_PI)
      });
    }

    // Create watching eyes
    for (let i = 0; i < 12; i++) {
      watchingEyes.push({
        x: p.random(p.width),
        y: p.random(50, 300),
        blinkTimer: p.random(60, 180),
        isBlinking: false
      });
    }
  };

  p.draw = function() {
    // Deep purple/black gradient background
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(20, 15, 40), p.color(5, 5, 15), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Draw fog atmosphere
    p.noStroke();
    for (let fog of fogParticles) {
      p.fill(80, 60, 120, fog.alpha);
      p.ellipse(fog.x, fog.y, fog.size);

      fog.x += p.cos(fog.direction) * fog.speed;
      fog.y += p.sin(fog.direction) * fog.speed;

      if (fog.x < -fog.size) fog.x = p.width + fog.size;
      if (fog.x > p.width + fog.size) fog.x = -fog.size;
      if (fog.y < -fog.size) fog.y = p.height + fog.size;
      if (fog.y > p.height + fog.size) fog.y = -fog.size;
    }

    // Draw door vault with subtle glow
    for (let door of doors) {
      door.glow += door.glowSpeed;
      if (door.glow > 1 || door.glow < 0.2) door.glowSpeed *= -1;

      // Door glow effect
      p.fill(100, 80, 150, 20 * door.glow);
      p.noStroke();
      p.rect(door.x - 5, door.y - 5, door.w + 10, door.h + 10);

      // Door silhouette
      p.fill(15, 10, 25);
      p.stroke(60, 50, 100, 100 * door.glow);
      p.strokeWeight(1);
      p.rect(door.x, door.y, door.w, door.h);

      // Door handle
      p.fill(80, 70, 120, 150 * door.glow);
      p.noStroke();
      p.ellipse(door.x + door.w - 10, door.y + door.h/2, 4, 4);
    }

    // Draw watching eyes in the darkness
    for (let eye of watchingEyes) {
      eye.blinkTimer--;
      if (eye.blinkTimer <= 0) {
        eye.isBlinking = true;
        if (eye.blinkTimer <= -10) {
          eye.isBlinking = false;
          eye.blinkTimer = p.random(60, 200);
        }
      }

      if (!eye.isBlinking) {
        let distToMouse = p.dist(p.mouseX, p.mouseY, eye.x, eye.y);
        let intensity = p.map(distToMouse, 0, 200, 255, 50);
        intensity = p.constrain(intensity, 50, 255);

        p.fill(150, 100, 200, intensity * 0.8);
        p.noStroke();
        p.ellipse(eye.x - 3, eye.y, 6, 8);
        p.ellipse(eye.x + 3, eye.y, 6, 8);

        // Pupils tracking mouse subtly
        let pupilX = p.map(p.mouseX, 0, p.width, -1, 1);
        let pupilY = p.map(p.mouseY, 0, p.height, -1, 1);

        p.fill(0);
        p.ellipse(eye.x - 3 + pupilX, eye.y + pupilY * 0.5, 2, 3);
        p.ellipse(eye.x + 3 + pupilX, eye.y + pupilY * 0.5, 2, 3);
      }
    }

    // Draw mentor figure (experienced, guiding)
    mentor.armAngle += 0.02;

    p.push();
    p.translate(mentor.x, mentor.y);

    // Mentor body silhouette
    p.fill(25, 20, 45);
    p.noStroke();
    p.ellipse(0, 20, 60, 80);  // body
    p.ellipse(0, -20, 45, 50); // head

    // Mentor arm pointing/gesturing
    p.stroke(40, 30, 60);
    p.strokeWeight(6);
    let armX = 30 * p.cos(mentor.armAngle);
    let armY = 15 * p.sin(mentor.armAngle);
    p.line(20, 0, 20 + armX, armY);

    // Subtle mentor glow
    p.fill(60, 50, 100, 30);
    p.noStroke();
    p.ellipse(0, 0, 100, 140);

    p.pop();

    // Draw trainee figure (eager, bobbing slightly)
    trainee.bobOffset += 0.05;
    let bobY = p.sin(trainee.bobOffset) * 3;

    p.push();
    p.translate(trainee.x, trainee.y + bobY);

    // Trainee body silhouette (smaller, more nervous energy)
    p.fill(20, 15, 35);
    p.noStroke();
    p.ellipse(0, 15, 45, 65);  // body
    p.ellipse(0, -15, 35, 40); // head

    // Trainee eyes (wide, attentive)
    p.fill(100, 80, 150, 180);
    p.ellipse(-8, -18, 8, 10);
    p.ellipse(8, -18, 8, 10);

    // Looking toward mentor
    p.fill(0);
    p.ellipse(-6, -18, 3, 4);
    p.ellipse(10, -18, 3, 4);

    // Subtle trainee glow (less experienced, more uncertain)
    p.fill(40, 30, 80, 20);
    p.noStroke();
    p.ellipse(0, 0, 80, 110);

    p.pop();

    // Interactive door glow on mouse proximity
    let nearestDoor = null;
    let minDist = Infinity;

    for (let door of doors) {
      let dist = p.dist(p.mouseX, p.mouseY, door.x + door.w/2, door.y + door.h/2);
      if (dist < minDist) {
        minDist = dist;
        nearestDoor = door;
      }
    }

    if (nearestDoor && minDist < 80) {
      p.fill(120, 100, 200, 40);
      p.noStroke();
      p.rect(nearestDoor.x - 10, nearestDoor.y - 10, nearestDoor.w + 20, nearestDoor.h + 20);

      // Add some uncertainty particles around the door
      for (let i = 0; i < 5; i++) {
        let px = nearestDoor.x + p.random(nearestDoor.w);
        let py = nearestDoor.y + p.random(nearestDoor.h);
        p.fill(150, 120, 200, p.random(20, 60));
        p.ellipse(px, py, p.random(2, 8));
      }
    }

    // Overlay of liminal atmosphere
    p.fill(10, 5, 20, 30);
    p.noStroke();
    p.rect(0, 0, p.width, p.height);
  };
}

function sketch(p) {
  let doors = [];
  let figure;
  let particles = [];
  let glowIntensity = 0;
  let breathingPhase = 0;
  let doorGlowPhase = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize doors in endless rows
    for (let row = 0; row < 8; row++) {
      for (let col = 0; col < 6; col++) {
        doors.push({
          x: col * 70 + 35,
          y: row * 80 + 100,
          width: 50,
          height: 70,
          glow: p.random(0.3, 1.0),
          glowPhase: p.random(p.TWO_PI)
        });
      }
    }

    // Professional figure position
    figure = {
      x: 200,
      y: 450,
      width: 80,
      height: 120
    };

    // Initialize atmospheric particles
    for (let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.3, 0.3),
        size: p.random(2, 8),
        opacity: p.random(0.1, 0.4)
      });
    }
  };

  p.draw = function() {
    // Deep atmospheric background
    p.background(8, 5, 15);

    // Update phases
    breathingPhase += 0.02;
    doorGlowPhase += 0.015;
    mouseInfluence = p.lerp(mouseInfluence, p.dist(p.mouseX, p.mouseY, 200, 300) / 200, 0.05);

    // Gradient overlay for depth
    for (let i = 0; i < p.height; i++) {
      let alpha = p.map(i, 0, p.height, 0.8, 0.2);
      p.stroke(20, 15, 35, alpha * 255);
      p.line(0, i, p.width, i);
    }

    // Draw atmospheric particles (fog/uncertainty)
    p.noStroke();
    for (let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;

      if (particle.x < 0) particle.x = p.width;
      if (particle.x > p.width) particle.x = 0;
      if (particle.y < 0) particle.y = p.height;
      if (particle.y > p.height) particle.y = 0;

      let distToMouse = p.dist(p.mouseX, p.mouseY, particle.x, particle.y);
      let mouseEffect = p.map(distToMouse, 0, 100, 0.8, 0.3);

      p.fill(45, 35, 80, particle.opacity * 255 * mouseEffect);
      p.ellipse(particle.x, particle.y, particle.size);
    }

    // Draw endless rows of doors (negative space emphasis)
    for (let door of doors) {
      let glowPulse = p.sin(doorGlowPhase + door.glowPhase) * 0.3 + 0.7;
      let doorBrightness = door.glow * glowPulse;

      // Door glow effect
      p.fill(120, 80, 200, doorBrightness * 40);
      p.noStroke();
      p.rect(door.x - 5, door.y - 5, door.width + 10, door.height + 10);

      // Door silhouette
      p.fill(15, 10, 25);
      p.stroke(80, 60, 150, doorBrightness * 120);
      p.strokeWeight(1);
      p.rect(door.x, door.y, door.width, door.height);

      // Door handle glow
      p.fill(150, 100, 250, doorBrightness * 180);
      p.noStroke();
      p.ellipse(door.x + door.width - 8, door.y + door.height/2, 3);
    }

    // Professional figure - skilled practitioner
    let breathingScale = 1 + p.sin(breathingPhase) * 0.05;
    let confidenceGlow = p.map(p.sin(breathingPhase * 2), -1, 1, 0.6, 1.0);

    p.pushMatrix();
    p.translate(figure.x, figure.y);
    p.scale(breathingScale);

    // Figure's mastery aura
    p.fill(80, 40, 120, confidenceGlow * 60);
    p.noStroke();
    p.ellipse(0, 0, figure.width + 40, figure.height + 40);

    // Professional silhouette
    p.fill(25, 20, 40);
    p.stroke(100, 70, 180, confidenceGlow * 150);
    p.strokeWeight(2);

    // Body
    p.rect(-figure.width/3, -20, figure.width * 2/3, figure.height * 2/3);

    // Head
    p.ellipse(0, -figure.height/3, figure.width/2, figure.width/2);

    // Arms positioned confidently
    p.line(-figure.width/3, -10, -figure.width/2, 10);
    p.line(figure.width/3, -10, figure.width/2, 10);

    // Tools of mastery (scare equipment)
    p.stroke(150, 100, 250, confidenceGlow * 200);
    p.strokeWeight(3);
    p.line(figure.width/2, 10, figure.width/2 + 15, 5);

    p.popMatrix();

    // Interactive shadow response
    if (p.mouseIsPressed) {
      // Genuine unease spreads
      p.fill(0, 0, 0, 60);
      let shadowSize = p.map(p.frameCount % 60, 0, 60, 50, 150);
      p.ellipse(p.mouseX, p.mouseY, shadowSize);

      // Distortion effect
      for (let i = 0; i < 5; i++) {
        p.fill(40, 20, 80, 30 - i * 5);
        p.ellipse(p.mouseX + p.random(-10, 10), p.mouseY + p.random(-10, 10), shadowSize - i * 20);
      }
    }

    // Performance indicators - peak efficiency
    p.stroke(120, 80, 200, 150);
    p.strokeWeight(1);
    p.noFill();

    // Status indicators around figure
    for (let i = 0; i < 3; i++) {
      let angle = breathingPhase + i * p.TWO_PI / 3;
      let x = figure.x + p.cos(angle) * 60;
      let y = figure.y + p.sin(angle) * 40;

      p.fill(100, 200, 150, confidenceGlow * 120);
      p.noStroke();
      p.ellipse(x, y, 8);
    }

    // Liminal space atmosphere
    let liminality = p.map(p.sin(breathingPhase * 0.5), -1, 1, 0.2, 0.8);
    p.fill(60, 40, 100, liminality * 30);
    p.noStroke();
    p.rect(0, 0, p.width, p.height);

    // Edge vignette for depth
    for (let i = 0; i < 50; i++) {
      let alpha = p.map(i, 0, 50, 200, 0);
      p.stroke(5, 3, 12, alpha);
      p.strokeWeight(2);
      p.noFill();
      p.rect(i, i, p.width - i * 2, p.height - i * 2);
    }
  };

  p.mousePressed = function() {
    // Add new particles at mouse position for interaction
    for (let i = 0; i < 5; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        size: p.random(3, 10),
        opacity: p.random(0.2, 0.6)
      });
    }

    // Limit particle count
    if (particles.length > 60) {
      particles.splice(0, 5);
    }
  };
}

function sketch(p) {
  let doors = [];
  let fogParticles = [];
  let whistleblowerX = 200;
  let whistleblowerY = 400;
  let documentOpacity = 0;
  let authorityGlow = 0;
  let doorGlows = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create door vault rows
    for(let row = 0; row < 8; row++) {
      for(let col = 0; col < 12; col++) {
        doors.push({
          x: col * 35 - 20,
          y: row * 40 + 50,
          width: 25,
          height: 35,
          glow: p.random(0.1, 0.3)
        });
      }
    }

    // Initialize door glows
    for(let i = 0; i < doors.length; i++) {
      doorGlows.push(p.random(0, p.TWO_PI));
    }

    // Create fog particles
    for(let i = 0; i < 150; i++) {
      fogParticles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(2, 8),
        speed: p.random(0.2, 0.8),
        opacity: p.random(0.1, 0.4),
        phase: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Dark gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 10, 25), p.color(5, 5, 15), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Draw door vault in perspective
    p.push();
    p.translate(p.width/2, 0);
    for(let i = 0; i < doors.length; i++) {
      let door = doors[i];
      doorGlows[i] += 0.005;

      // Perspective effect
      let perspective = 1 - (door.y / 400) * 0.3;
      let doorX = door.x * perspective;
      let doorY = door.y;

      // Door glow effect
      let glowIntensity = door.glow + p.sin(doorGlows[i]) * 0.1;
      p.fill(60 + glowIntensity * 40, 40 + glowIntensity * 60, 100 + glowIntensity * 80, 50);
      p.noStroke();
      p.rect(doorX - 2, doorY - 2, door.width * perspective + 4, door.height * perspective + 4, 2);

      // Door silhouette
      p.fill(25, 20, 35);
      p.rect(doorX, doorY, door.width * perspective, door.height * perspective, 1);

      // Subtle door light
      if(p.random() < 0.001) {
        p.fill(80, 60, 120, 30);
        p.rect(doorX, doorY, door.width * perspective, door.height * perspective, 1);
      }
    }
    p.pop();

    // Fog layer
    p.noStroke();
    for(let fog of fogParticles) {
      fog.x += fog.speed + p.sin(time + fog.phase) * 0.3;
      fog.y += p.sin(time * 0.7 + fog.phase) * 0.2;

      if(fog.x > p.width + fog.size) fog.x = -fog.size;

      let mouseInfluence = p.dist(p.mouseX, p.mouseY, fog.x, fog.y);
      let pushX = mouseInfluence < 50 ? (fog.x - p.mouseX) * 0.02 : 0;
      let pushY = mouseInfluence < 50 ? (fog.y - p.mouseY) * 0.02 : 0;

      fog.x += pushX;
      fog.y += pushY;

      p.fill(40, 35, 60, fog.opacity * 255);
      p.ellipse(fog.x, fog.y, fog.size);
    }

    // Authority figure silhouette (looming presence at top)
    authorityGlow = p.sin(time * 2) * 0.3 + 0.7;
    p.fill(20, 15, 25);
    p.noStroke();
    p.ellipse(200, 100, 80, 40); // head
    p.rect(160, 120, 80, 100, 5); // body

    // Authority intimidation glow
    p.fill(80, 40, 40, authorityGlow * 30);
    p.ellipse(200, 140, 120, 160);

    // Whistleblower figure
    let mouseDistance = p.dist(p.mouseX, p.mouseY, whistleblowerX, whistleblowerY);
    let courage = p.map(mouseDistance, 0, 200, 0.5, 1.0, true);

    // Whistleblower trembling effect
    let tremble = p.sin(time * 8) * (1 - courage) * 2;
    let figureX = whistleblowerX + tremble;

    // Whistleblower silhouette
    p.fill(30, 25, 45);
    p.ellipse(figureX, whistleblowerY - 40, 25, 30); // head
    p.rect(figureX - 15, whistleblowerY - 25, 30, 60, 3); // body
    p.rect(figureX - 20, whistleblowerY - 10, 15, 40, 2); // arm holding documents

    // Documents/evidence
    documentOpacity = p.lerp(documentOpacity, courage * 255, 0.05);
    p.fill(200, 180, 120, documentOpacity);
    p.rect(figureX - 35, whistleblowerY - 15, 12, 20, 1);
    p.rect(figureX - 34, whistleblowerY - 13, 10, 2);
    p.rect(figureX - 34, whistleblowerY - 9, 8, 2);
    p.rect(figureX - 34, whistleblowerY - 5, 9, 2);

    // Spotlight effect on whistleblower when mouse is near
    if(mouseDistance < 100) {
      p.fill(100, 80, 140, 20);
      p.ellipse(figureX, whistleblowerY, 80, 100);
    }

    // Truth revelation rays
    if(p.mouseIsPressed) {
      p.stroke(120, 100, 180, 100);
      p.strokeWeight(2);
      for(let i = 0; i < 8; i++) {
        let angle = (p.TWO_PI / 8) * i + time;
        let rayLength = 60 + p.sin(time * 3 + i) * 20;
        p.line(figureX, whistleblowerY - 20, 
               figureX + p.cos(angle) * rayLength, 
               whistleblowerY - 20 + p.sin(angle) * rayLength);
      }
    }

    // Watching eyes in the darkness
    for(let i = 0; i < 6; i++) {
      let eyeX = 50 + i * 60 + p.sin(time + i) * 10;
      let eyeY = 500 + p.sin(time * 0.5 + i) * 20;

      p.fill(120, 60, 60, 80);
      p.noStroke();
      p.ellipse(eyeX, eyeY, 6, 8);
      p.fill(200, 100, 100, 60);
      p.ellipse(eyeX, eyeY, 3, 4);
    }

    // Institutional pressure visualization
    if(mouseDistance > 150) {
      p.fill(60, 30, 30, 20);
      p.noStroke();
      for(let ring = 1; ring < 5; ring++) {
        p.ellipse(200, 100, ring * 100, ring * 60);
      }
    }
  };
}

function sketch(p) {
  let doors = [];
  let fog = [];
  let leader;
  let followers = [];
  let construction = [];
  let mouseInfluence = 0;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize door vault in background
    for (let i = 0; i < 30; i++) {
      doors.push({
        x: p.random(p.width),
        y: p.random(p.height),
        glow: p.random(20, 80),
        flickerSpeed: p.random(0.02, 0.08)
      });
    }

    // Fog particles
    for (let i = 0; i < 100; i++) {
      fog.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(20, 60),
        speed: p.random(0.5, 2),
        alpha: p.random(10, 40)
      });
    }

    // Leader figure
    leader = {
      x: p.width * 0.6,
      y: p.height * 0.4,
      armAngle: 0,
      buildProgress: 0
    };

    // Follower silhouettes
    for (let i = 0; i < 5; i++) {
      followers.push({
        x: p.random(p.width * 0.1, p.width * 0.4),
        y: p.random(p.height * 0.5, p.height * 0.8),
        size: p.random(0.6, 0.9),
        watchIntensity: 0
      });
    }

    // Construction elements
    for (let i = 0; i < 15; i++) {
      construction.push({
        x: p.random(p.width * 0.4, p.width * 0.9),
        y: p.random(p.height * 0.3, p.height * 0.7),
        width: p.random(30, 80),
        height: p.random(10, 40),
        opacity: p.random(100, 200),
        buildDelay: i * 0.3
      });
    }
  };

  p.draw = function() {
    // Deep atmospheric background
    p.background(8, 5, 15);

    time += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);

    // Draw fog layers
    p.noStroke();
    for (let f of fog) {
      let alpha = f.alpha + p.sin(time + f.x * 0.01) * 10;
      p.fill(25, 15, 35, alpha);
      p.ellipse(f.x, f.y, f.size);

      f.x += f.speed * (0.5 + mouseInfluence * 0.5);
      if (f.x > p.width + f.size) {
        f.x = -f.size;
        f.y = p.random(p.height);
      }
    }

    // Door vault glow in far background
    for (let door of doors) {
      let glow = door.glow + p.sin(time * door.flickerSpeed) * 20;

      // Door light
      p.fill(85, 45, 120, glow * 0.3);
      p.ellipse(door.x, door.y, 40);

      // Actual door silhouette
      p.fill(45, 25, 65, 150);
      p.rect(door.x - 8, door.y - 12, 16, 24);

      // Door frame glow
      p.stroke(85, 45, 120, glow * 0.5);
      p.strokeWeight(1);
      p.noFill();
      p.rect(door.x - 8, door.y - 12, 16, 24);
      p.noStroke();
    }

    // Construction/transformation elements
    p.strokeWeight(2);
    for (let i = 0; i < construction.length; i++) {
      let c = construction[i];
      let buildProgress = p.constrain((time - c.buildDelay) * 2, 0, 1);

      if (buildProgress > 0) {
        // New structure being built
        let alpha = c.opacity * buildProgress;
        p.fill(120, 80, 160, alpha);
        p.stroke(160, 120, 200, alpha * 0.7);

        let currentHeight = c.height * buildProgress;
        p.rect(c.x, c.y + c.height - currentHeight, c.width, currentHeight);

        // Construction glow
        if (buildProgress < 1) {
          p.fill(180, 140, 220, 50);
          p.noStroke();
          p.ellipse(c.x + c.width/2, c.y + c.height - currentHeight, 60);
        }
      }
    }

    // Leader figure
    p.noStroke();
    let leaderGlow = 50 + mouseInfluence * 30;

    // Leader aura
    p.fill(140, 100, 180, leaderGlow * 0.4);
    p.ellipse(leader.x, leader.y, 120);

    // Leader silhouette
    p.fill(20, 15, 30);
    // Body
    p.ellipse(leader.x, leader.y + 10, 35, 60);
    // Head
    p.ellipse(leader.x, leader.y - 25, 25, 30);

    // Animated building arm
    leader.armAngle = p.sin(time * 2) * 0.5 + mouseInfluence;
    p.stroke(140, 100, 180, 150);
    p.strokeWeight(3);
    let armX = leader.x + p.cos(leader.armAngle) * 25;
    let armY = leader.y + p.sin(leader.armAngle) * 25;
    p.line(leader.x + 5, leader.y, armX, armY);

    // Energy emanating from leader
    for (let i = 0; i < 5; i++) {
      let angle = time + i * p.TWO_PI / 5;
      let dist = 40 + p.sin(time * 3 + i) * 10;
      let energyX = leader.x + p.cos(angle) * dist;
      let energyY = leader.y + p.sin(angle) * dist;

      p.fill(160, 120, 200, 100 - dist);
      p.noStroke();
      p.ellipse(energyX, energyY, 8);
    }

    // Follower silhouettes watching
    for (let f of followers) {
      // Calculate intensity based on mouse proximity and leader activity
      let dist = p.dist(p.mouseX, p.mouseY, f.x, f.y);
      f.watchIntensity = p.lerp(f.watchIntensity, 
        p.map(dist, 0, 200, 1, 0.3) + mouseInfluence * 0.5, 0.1);

      // Follower glow
      p.fill(80, 50, 110, f.watchIntensity * 60);
      p.ellipse(f.x, f.y, 80 * f.size);

      // Follower silhouette
      p.fill(15, 10, 25);
      p.ellipse(f.x, f.y + 5 * f.size, 20 * f.size, 40 * f.size);
      p.ellipse(f.x, f.y - 15 * f.size, 15 * f.size, 20 * f.size);

      // Eyes watching the leader
      p.fill(100, 60, 140, f.watchIntensity * 200);
      let eyeOffset = 4 * f.size;
      p.ellipse(f.x - eyeOffset, f.y - 15 * f.size, 3, 4);
      p.ellipse(f.x + eyeOffset, f.y - 15 * f.size, 3, 4);
    }

    // Atmospheric overlay
    p.fill(5, 2, 10, 30 - mouseInfluence * 20);
    p.rect(0, 0, p.width, p.height);

    // Liminal space effects - things half-seen
    if (mouseInfluence > 0.7) {
      for (let i = 0; i < 3; i++) {
        let ghostX = p.random(p.width);
        let ghostY = p.random(p.height);
        p.fill(60, 40, 80, 20);
        p.ellipse(ghostX, ghostY, 40, 60);
      }
    }
  };

  p.mousePressed = function() {
    // Add construction element at mouse position
    if (construction.length < 20) {
      construction.push({
        x: p.mouseX - 20,
        y: p.mouseY - 10,
        width: p.random(20, 60),
        height: p.random(8, 30),
        opacity: 180,
        buildDelay: time
      });
    }

    // Ripple effect
    for (let i = 0; i < 10; i++) {
      fog.push({
        x: p.mouseX + p.random(-50, 50),
        y: p.mouseY + p.random(-50, 50),
        size: p.random(10, 30),
        speed: p.random(1, 3),
        alpha: p.random(40, 80)
      });
    }
  };
}

function sketch(p) {
  let particles = [];
  let spotlights = [];
  let curtainWave = 0;
  let energyPulse = 0;
  let centralSpark;
  let laughMeter = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize central spark
    centralSpark = {
      x: p.width/2,
      y: p.height/2,
      energy: 0,
      maxEnergy: 100
    };

    // Create spotlight positions
    for(let i = 0; i < 3; i++) {
      spotlights.push({
        x: p.random(50, p.width-50),
        y: p.random(50, 200),
        angle: p.random(p.TWO_PI),
        intensity: p.random(0.3, 0.8)
      });
    }

    // Initialize particles
    for(let i = 0; i < 50; i++) {
      particles.push(createEnergyParticle());
    }
  };

  function createEnergyParticle() {
    return {
      x: p.random(p.width),
      y: p.random(p.height),
      vx: p.random(-1, 1),
      vy: p.random(-1, 1),
      life: p.random(100, 255),
      maxLife: p.random(100, 255),
      size: p.random(2, 8),
      hue: p.random(45, 65)
    };
  }

  p.draw = function() {
    // Dark background with slight gradient
    for(let i = 0; i < p.height; i++) {
      let alpha = p.map(i, 0, p.height, 0.1, 0.05);
      p.stroke(20, 20, 40, alpha * 255);
      p.line(0, i, p.width, i);
    }

    // Update time-based animations
    curtainWave += 0.02;
    energyPulse += 0.03;

    // Mouse influence
    let mouseDistance = p.dist(p.mouseX, p.mouseY, centralSpark.x, centralSpark.y);
    mouseInfluence = p.map(mouseDistance, 0, 200, 1.5, 0.5);
    mouseInfluence = p.constrain(mouseInfluence, 0.5, 2);

    // Draw stage curtains
    drawCurtains();

    // Draw spotlights
    drawSpotlights();

    // Update and draw energy particles
    updateParticles();

    // Draw the central spark (ace energy)
    drawCentralSpark();

    // Draw laugh meter
    drawLaughMeter();

    // Draw comedy masks in corners
    drawComedyMasks();

    // Theatrical border
    drawBorder();
  };

  function drawCurtains() {
    p.fill(120, 20, 30, 200);
    p.noStroke();

    // Left curtain
    p.beginShape();
    p.vertex(0, 0);
    for(let y = 0; y <= p.height; y += 10) {
      let wave = p.sin(curtainWave + y * 0.05) * 15;
      p.vertex(80 + wave, y);
    }
    p.vertex(0, p.height);
    p.endShape(p.CLOSE);

    // Right curtain
    p.beginShape();
    p.vertex(p.width, 0);
    for(let y = 0; y <= p.height; y += 10) {
      let wave = p.sin(curtainWave + y * 0.05) * 15;
      p.vertex(p.width - 80 - wave, y);
    }
    p.vertex(p.width, p.height);
    p.endShape(p.CLOSE);
  }

  function drawSpotlights() {
    for(let spotlight of spotlights) {
      let pulseIntensity = spotlight.intensity + p.sin(energyPulse) * 0.2;

      // Spotlight cone
      p.push();
      p.translate(spotlight.x, spotlight.y);
      p.rotate(spotlight.angle);

      let gradient = p.drawingContext.createRadialGradient(0, 0, 0, 0, 0, 150);
      gradient.addColorStop(0, `rgba(255, 220, 100, ${pulseIntensity * 0.6})`);
      gradient.addColorStop(0.7, `rgba(255, 200, 80, ${pulseIntensity * 0.3})`);
      gradient.addColorStop(1, 'rgba(255, 180, 60, 0)');

      p.drawingContext.fillStyle = gradient;
      p.noStroke();
      p.ellipse(0, 0, 300, 300);
      p.pop();
    }
  }

  function updateParticles() {
    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      // Attract to central spark
      let dx = centralSpark.x - particle.x;
      let dy = centralSpark.y - particle.y;
      let distance = p.sqrt(dx * dx + dy * dy);

      if(distance > 0) {
        particle.vx += (dx / distance) * 0.02 * mouseInfluence;
        particle.vy += (dy / distance) * 0.02 * mouseInfluence;
      }

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 1;

      // Draw particle
      p.push();
      p.colorMode(p.HSB, 360, 100, 100, 255);
      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 255);
      p.fill(particle.hue, 80, 100, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
      p.pop();

      // Remove dead particles
      if(particle.life <= 0) {
        particles.splice(i, 1);
        particles.push(createEnergyParticle());
      }
    }
  }

  function drawCentralSpark() {
    // Main energy orb
    let sparkSize = 40 + p.sin(energyPulse * 2) * 10;
    sparkSize *= mouseInfluence;

    // Outer glow
    for(let i = 0; i < 5; i++) {
      let glowSize = sparkSize + i * 15;
      let glowAlpha = p.map(i, 0, 4, 150, 20);
      p.fill(255, 220, 100, glowAlpha);
      p.noStroke();
      p.ellipse(centralSpark.x, centralSpark.y, glowSize);
    }

    // Core spark
    p.fill(255, 255, 255, 255);
    p.ellipse(centralSpark.x, centralSpark.y, sparkSize * 0.3);

    // Radiating lines
    p.push();
    p.translate(centralSpark.x, centralSpark.y);
    p.stroke(255, 220, 100, 180);
    p.strokeWeight(2);

    for(let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI + energyPulse;
      let length = 30 + p.sin(energyPulse * 3) * 15;
      length *= mouseInfluence;

      p.push();
      p.rotate(angle);
      p.line(sparkSize * 0.3, 0, sparkSize * 0.3 + length, 0);
      p.pop();
    }
    p.pop();
  }

  function drawLaughMeter() {
    // Meter background
    p.fill(40, 40, 60, 180);
    p.stroke(200, 180, 100);
    p.strokeWeight(2);
    p.rect(p.width - 60, 50, 30, 200, 5);

    // Meter fill
    laughMeter = p.lerp(laughMeter, mouseInfluence * 100, 0.05);
    let fillHeight = p.map(laughMeter, 0, 200, 0, 190);

    p.fill(255, 220, 100, 200);
    p.noStroke();
    p.rect(p.width - 58, 52 + (190 - fillHeight), 26, fillHeight, 3);

    // Meter labels
    p.fill(200, 180, 100);
    p.textAlign(p.CENTER);
    p.textSize(8);
    p.text("JOY", p.width - 45, 40);
  }

  function drawComedyMasks() {
    // Happy mask (top left)
    p.push();
    p.translate(60, 80);
    p.fill(220, 200, 100, 100);
    p.stroke(255, 220, 100, 150);
    p.strokeWeight(2);
    p.ellipse(0, 0, 30, 35);

    // Eyes
    p.fill(50);
    p.noStroke();
    p.ellipse(-6, -5, 4, 6);
    p.ellipse(6, -5, 4, 6);

    // Smile
    p.noFill();
    p.stroke(50);
    p.strokeWeight(2);
    p.arc(0, 5, 15, 10, 0, p.PI);
    p.pop();

    // Microphone (bottom right)
    p.push();
    p.translate(340, 520);
