function sketch(p) {
  let spotlights = [];
  let connections = [];
  let performers = [];
  let particles = [];
  let applauseMeters = [];
  let curtainOffset = 0;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create three main spotlights in triangle formation
    spotlights.push({x: 200, y: 150, radius: 80, brightness: 1});
    spotlights.push({x: 120, y: 350, radius: 70, brightness: 0.8});
    spotlights.push({x: 280, y: 350, radius: 75, brightness: 0.9});

    // Create performer figures at spotlight centers
    performers.push({x: 200, y: 150, type: 'comedian', energy: 0});
    performers.push({x: 120, y: 350, type: 'dancer', energy: 0});
    performers.push({x: 280, y: 350, type: 'singer', energy: 0});

    // Create applause meters
    for(let i = 0; i < 3; i++) {
      applauseMeters.push({
        x: 50 + i * 150,
        y: 500,
        level: 0.5,
        targetLevel: 0.5
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Dark stage background
    p.background(15, 10, 25);

    // Draw stage curtains
    drawCurtains();

    // Draw stage floor with energy lines
    drawStageFloor();

    // Draw connection web
    drawConnections();

    // Draw spotlights
    drawSpotlights();

    // Draw performers
    drawPerformers();

    // Draw applause meters
    drawApplauseMeters();

    // Draw floating joy particles
    updateParticles();
    drawParticles();

    // Interactive elements
    handleInteraction();
  };

  function drawCurtains() {
    curtainOffset = p.sin(time * 0.5) * 5;

    // Left curtain
    p.fill(120, 20, 40);
    p.noStroke();
    for(let i = 0; i < 8; i++) {
      let wave = p.sin(time + i * 0.5) * 3;
      p.rect(-10 + wave + curtainOffset, i * 75, 60, 80);
    }

    // Right curtain  
    for(let i = 0; i < 8; i++) {
      let wave = p.sin(time + i * 0.5) * 3;
      p.rect(350 - wave - curtainOffset, i * 75, 60, 80);
    }

    // Top curtain
    p.rect(0, 0, 400, 40);
  };

  function drawStageFloor() {
    // Stage floor with energy grid
    p.stroke(80, 60, 20);
    p.strokeWeight(1);
    for(let x = 0; x < 400; x += 20) {
      let alpha = p.map(p.sin(time + x * 0.1), -1, 1, 50, 150);
      p.stroke(255, 200, 80, alpha);
      p.line(x, 480, x, 600);
    }

    for(let y = 480; y < 600; y += 15) {
      let alpha = p.map(p.sin(time * 2 + y * 0.1), -1, 1, 30, 120);
      p.stroke(255, 200, 80, alpha);
      p.line(0, y, 400, y);
    }
  };

  function drawConnections() {
    p.stroke(255, 220, 100, 80);
    p.strokeWeight(2);

    // Draw connections between performers
    for(let i = 0; i < performers.length; i++) {
      for(let j = i + 1; j < performers.length; j++) {
        let p1 = performers[i];
        let p2 = performers[j];

        let midX = (p1.x + p2.x) / 2;
        let midY = (p1.y + p2.y) / 2;
        let curve = p.sin(time * 2 + i + j) * 20;

        p.noFill();
        p.bezier(p1.x, p1.y, 
                midX + curve, midY - 30,
                midX - curve, midY - 30,
                p2.x, p2.y);
      }
    }

    // Radiating connections
    for(let performer of performers) {
      let numRays = 8;
      for(let i = 0; i < numRays; i++) {
        let angle = (i / numRays) * p.TWO_PI + time;
        let length = 40 + p.sin(time * 3 + i) * 20;
        let x2 = performer.x + p.cos(angle) * length;
        let y2 = performer.y + p.sin(angle) * length;

        let alpha = p.map(p.sin(time * 2 + i), -1, 1, 20, 80);
        p.stroke(255, 220, 100, alpha);
        p.strokeWeight(1);
        p.line(performer.x, performer.y, x2, y2);
      }
    }
  };

  function drawSpotlights() {
    for(let spot of spotlights) {
      // Spotlight glow
      let pulse = p.sin(time * 2) * 0.1 + 0.9;
      spot.brightness = pulse;

      // Outer glow
      for(let r = spot.radius; r > 0; r -= 5) {
        let alpha = p.map(r, 0, spot.radius, 150, 0) * spot.brightness;
        p.fill(255, 220, 100, alpha);
        p.noStroke();
        p.ellipse(spot.x, spot.y, r * 2);
      }

      // Core light
      p.fill(255, 250, 200, 200);
      p.ellipse(spot.x, spot.y, 20);
    }
  };

  function drawPerformers() {
    for(let i = 0; i < performers.length; i++) {
      let performer = performers[i];

      p.push();
      p.translate(performer.x, performer.y);

      // Monster body
      let bounce = p.sin(time * 4 + i) * 3;
      p.translate(0, bounce);

      // Body colors based on type
      if(performer.type === 'comedian') {
        p.fill(80, 150, 255); // Blue monster
      } else if(performer.type === 'dancer') {
        p.fill(255, 100, 150); // Pink monster  
      } else {
        p.fill(150, 255, 100); // Green monster
      }

      p.noStroke();
      p.ellipse(0, 0, 40, 50);

      // Eyes
      p.fill(255);
      p.ellipse(-8, -10, 12);
      p.ellipse(8, -10, 12);
      p.fill(0);
      p.ellipse(-8, -10, 6);
      p.ellipse(8, -10, 6);

      // Performance elements
      if(performer.type === 'comedian') {
        // Comedy mask
        p.stroke(255, 200, 0);
        p.strokeWeight(2);
        p.noFill();
        p.arc(0, 5, 15, 10, 0, p.PI);
      } else if(performer.type === 'dancer') {
        // Dance motion lines
        p.stroke(255, 150, 200);
        p.strokeWeight(3);
        for(let j = 0; j < 3; j++) {
          let angle = time * 3 + j * p.TWO_PI / 3;
          let x1 = p.cos(angle) * 25;
          let y1 = p.sin(angle) * 25;
          let x2 = p.cos(angle) * 35;
          let y2 = p.sin(angle) * 35;
          p.line(x1, y1, x2, y2);
        }
      } else {
        // Musical notes
        p.fill(255, 200, 100);
        p.noStroke();
        let noteY = p.sin(time * 6 + i) * 10 - 20;
        p.ellipse(15, noteY, 6);
        p.ellipse(20, noteY - 5, 5);
      }

      p.pop();
    }
  };

  function drawApplauseMeters() {
    for(let i = 0; i < applauseMeters.length; i++) {
      let meter = applauseMeters[i];

      // Meter case
      p.stroke(100, 80, 50);
      p.strokeWeight(2);
      p.fill(20, 15, 10);
      p.rect(meter.x - 15, meter.y - 30, 30, 60);

      // Energy level
      meter.targetLevel = 0.3 + p.sin(time * 2 + i) * 0.3 + 0.4;
      meter.level = p.lerp(meter.level, meter.targetLevel, 0.1);

      let barHeight = meter.level * 50;
      p.fill(255, 200, 50);
      p.noStroke();
      p.rect(meter.x - 12, meter.y + 25 - barHeight, 24, barHeight);

      // Glowing top
      if(meter.level > 0.7) {
        p.fill(255, 255, 200, 150);
        p.rect(meter.x - 12, meter.y + 25 - barHeight, 24, 5);
      }
    }
  };

  function updateParticles() {
    // Generate joy particles
    if(p.frameCount % 3 === 0) {
      for(let performer of performers) {
        particles.push({
          x: performer.x + p.random(-20, 20),
          y: performer.y + p.random(-10, 10),
          vx: p.random(-1, 1),
          vy: p.random(-2, 0),
          life: 60,
          maxLife: 60,
          color: p.color(255, 220 + p.random(-50, 50), 100 + p.random(-50, 50))
        });
      }
    }

    // Update existing particles
    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life--;

      if(particle.life <= 0) {
        particles.splice(i, 1);
      }
    }
  };

  function drawParticles() {
    p.noStroke();
    for(let particle of particles) {
      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 150);
      let size = p.map(particle.life, 0, particle.maxLife, 1, 6);

      particle.color.setAlpha(alpha);
      p.fill(particle.color);
      p.ellipse(particle.x, particle.y, size);
    }
  };

  function handleInteraction() {
    // Mouse interaction creates more particles
    if(p.mouseIsPressed) {
      for(let i = 0; i < 3; i++) {
        particles.push({
          x: p.mouseX + p.random(-10, 10),
          y: p.mouseY + p.random(-10, 10),
          vx: p.random(-2, 2),
          vy: p.random(-3, -1),
          life: 40,
          maxLife: 40,
          color: p.color(255, 200 + p.random(-30, 30), 80 + p.random(-30, 30))
        });
      }
    }
  };
}

