    // Draw pillars
    drawPillars();

    // Draw walls connecting pillars
    drawWalls();

    // Draw comedy masks
    drawComedyMasks();

    // Draw applause meters
    drawApplauseMeters(time);

    // Add sparkle effects
    addSparkles();
  };

  function drawCurtains() {
    p.fill(120, 20, 40, 180);
    p.noStroke();

    // Left curtain
    p.beginShape();
    for(let y = 0; y <= 600; y += 20) {
      let wave = p.sin(curtainWave + y * 0.02) * 15;
      p.vertex(wave + 30, y);
    }
    p.vertex(0, 600);
    p.vertex(0, 0);
    p.endShape(p.CLOSE);

    // Right curtain
    p.beginShape();
    for(let y = 0; y <= 600; y += 20) {
      let wave = p.sin(curtainWave + y * 0.02) * 15;
      p.vertex(400 - wave - 30, y);
    }
    p.vertex(400, 600);
    p.vertex(400, 0);
    p.endShape(p.CLOSE);
  }

  function drawSpotlights() {
    for(let spotlight of spotlights) {
      let mouseInfluence = p.map(p.mouseX, 0, 400, -0.2, 0.2);
      let currentAngle = spotlight.angle + mouseInfluence;
      let intensity = spotlight.intensity * energyPulse;

      p.push();
      p.translate(spotlight.x, spotlight.y);
      p.rotate(currentAngle);

      // Beam gradient
      for(let i = 0; i < 200; i += 10) {
        let alpha = p.map(i, 0, 200, intensity * 60, 0);
        let width = p.map(i, 0, 200, 10, 80);
        spotlight.color.setAlpha(alpha);
        p.fill(spotlight.color);
        p.noStroke();
        p.ellipse(0, i, width, 20);
      }
      p.pop();
    }
  }

  function updateParticles() {
    // Add new particles
    if(p.random() < 0.3) {
      particles.push({
        x: p.random(400),
        y: p.random(300, 600),
        vx: p.random(-2, 2),
        vy: p.random(-3, -1),
        life: 255,
        size: p.random(3, 8),
        color: p.color(255, 220, 100)
      });
    }

    // Update and draw particles
    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 3;

      particle.color.setAlpha(particle.life);
      p.fill(particle.color);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);

      if(particle.life <= 0) {
        particles.splice(i, 1);
      }
    }
  }

  function drawFoundation() {
    foundationProgress = p.min(foundationProgress + 0.01, 1);

    p.stroke(255, 200, 80);
    p.strokeWeight(6);
    p.fill(40, 35, 60, 150);

    let size = 280 * foundationProgress;
    let centerX = 200;
    let centerY = 500;

    p.rect(centerX - size/2, centerY - size/8, size, size/4);

    // Foundation glow
    p.stroke(255, 220, 100, 100);
    p.strokeWeight(2);
    p.noFill();
    p.rect(centerX - size/2 - 5, centerY - size/8 - 5, size + 10, size/4 + 10);
  }

  function updatePillars(time) {
    for(let pillar of pillars) {
      if(time > pillar.startTime && !pillar.growing) {
        pillar.growing = true;
      }

      if(pillar.growing && pillar.height < pillar.targetHeight) {
        pillar.height += 2;
      }
    }
  }

  function drawPillars() {
    for(let pillar of pillars) {
      if(pillar.height > 0) {
        // Main pillar
        p.fill(200, 180, 120);
        p.stroke(255, 220, 100);
        p.strokeWeight(3);
        p.rect(pillar.x - 20, pillar.y - pillar.height, 40, pillar.height);

        // Industrial details
        p.fill(150, 140, 100);
        p.noStroke();
        for(let i = 0; i < pillar.height; i += 20) {
          p.rect(pillar.x - 18, pillar.y - i - 5, 36, 3);
        }

        // Energy glow at top
        if(pillar.height >= pillar.targetHeight) {
          p.fill(255, 220, 100, 100 * energyPulse);
          p.noStroke();
          p.ellipse(pillar.x, pillar.y - pillar.height, 60, 20);
        }
      }
    }
  }

  function drawWalls() {
    wallProgress = p.min(wallProgress + 0.005, 1);

    if(pillars.every(pillar => pillar.height >= pillar.targetHeight)) {
      p.stroke(180, 160, 100, 150);
      p.strokeWeight(4);

      let progress = wallProgress;

      // Horizontal walls
      if(progress > 0.2) {
        let p1 = pillars[0], p2 = pillars[1];
        p.line(p1.x, p1.y - p1.height/2, p2.x, p2.y - p2.height/2);

        let p3 = pillars[2], p4 = pillars[3];
        p.line(p3.x, p3.y - p3.height/2, p4.x, p4.y - p4.height/2);
      }

      // Vertical walls
      if(progress > 0.5) {
        let p1 = pillars[0], p3 = pillars[2];
        p.line(p1.x, p1.y - p1.height/2, p3.x, p3.y - p3.height/2);

        let p2 = pillars[1], p4 = pillars[3];
        p.line(p2.x, p2.y - p2.height/2, p4.x, p4.y - p4.height/2);
      }
    }
  }

  function drawComedyMasks() {
    for(let mask of comedyMasks) {
      mask.rotation += 0.01;
      mask.scale = 1 + p.sin(p.millis() * 0.003 + mask.x) * 0.1;

      p.push();
      p.translate(mask.x, mask.y);
      p.rotate(mask.rotation);
      p.scale(mask.scale);

      // Happy mask
      p.fill(240, 220, 180);
      p.stroke(200, 180, 120);
      p.strokeWeight(2);
      p.ellipse(0, 0, 40, 50);

      // Eyes
      p.fill(50);
      p.noStroke();
      p.ellipse(-8, -8, 6, 8);
      p.ellipse(8, -8, 6, 8);

      // Smile
      p.noFill();
      p.stroke(50);
      p.strokeWeight(3);
      p.arc(0, 5, 25, 20, 0, p.PI);

      p.pop();
    }
  }

  function drawApplauseMeters() {
    for(let meter of applauseMeters) {
      meter.oscillation += 0.05;
      meter.targetLevel = 0.5 + p.sin(meter.oscillation) * 0.3;
      meter.level = p.lerp(meter.level, meter.targetLevel, 0.1);

      // Meter housing
      p.fill(60, 50, 80);
      p.stroke(120, 100, 150);
      p.strokeWeight(2);
      p.rect(meter.x - 15, meter.y - 30, 30, 60);

      // Meter fill
      let fillHeight = meter.level * 50;
      p.fill(255, 200 + meter.level * 55, 100);
      p.noStroke();
      p.rect(meter.x - 12, meter.y + 25 - fillHeight, 24, fillHeight);

      // Meter markings
      p.stroke(200);
      p.strokeWeight(1);
      for(let i = 0; i < 5; i++) {
        let markY = meter.y - 20 + i * 10;
        p.line(meter.x + 12, markY, meter.x + 18, markY);
      }
    }
  }

  function addSparkles() {
    for(let i = 0; i < 5; i++) {
      if(p.random() < 0.1) {
        p.fill(255, 255, 200, 200);
        p.noStroke();
        let x = p.random(100, 300);
        let y = p.random(150, 400);
        let size = p.random(2, 6);

        p.push();
        p.translate(x, y);
        p.rotate(p.millis() * 0.01);
        p.rect(-size/2, -1, size, 2);
        p.rect(-1, -size/2, 2, size);
        p.pop();
      }
    }
  }

  p.mousePressed = function() {
    // Add burst of particles on click
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-5, 5),
        vy: p.random(-8, -2),
        life: 255,
        size: p.random(4, 10),
        color: p.color(255, 220, 100)
      });
    }
  };
}

function sketch(p) {
  let crack = [];
  let lights = [];
  let particles = [];
  let applauseMeters = [];
  let curtainOffset = 0;
  let spotlightAngle = 0;
  let crackProgress = 0;
  let comedyMasks = [];
  let microphones = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize crack points
    for (let i = 0; i < 25; i++) {
      crack.push({
        x: 200 + p.random(-30, 30),
        y: p.map(i, 0, 24, 150, 450),
        width: p.random(2, 8),
        glowing: p.random() > 0.7
      });
    }

    // Initialize stage lights
    for (let i = 0; i < 4; i++) {
      lights.push({
        x: p.map(i, 0, 3, 50, 350),
        y: 50,
        intensity: p.random(0.7, 1.0),
        color: p.random(['gold', 'yellow', 'orange'])
      });
    }

    // Initialize applause meters (industrial gauges)
    for (let i = 0; i < 2; i++) {
      applauseMeters.push({
        x: 50 + i * 300,
        y: 100,
        value: p.random(0.3, 0.9),
        target: p.random(0.3, 0.9)
      });
    }

    // Initialize comedy masks
    comedyMasks.push({x: 80, y: 200, type: 'happy'});
    comedyMasks.push({x: 320, y: 180, type: 'sad'});

    // Initialize microphones
    microphones.push({x: 120, y: 350, angle: 0});
    microphones.push({x: 280, y: 330, angle: 0});
  };

  p.draw = function() {
    // Industrial background with theatrical warmth
    let bg = p.color(25, 30, 45);
    p.background(bg);

    // Stage curtains (partially drawn)
    p.fill(120, 40, 60);
    p.rect(0, 0, 60 + curtainOffset, p.height);
    p.rect(340 - curtainOffset, 0, 60 + curtainOffset, p.height);

    // Industrial wall pattern
    p.stroke(60, 70, 90);
    p.strokeWeight(2);
    for (let x = 0; x < p.width; x += 40) {
      for (let y = 0; y < p.height; y += 40) {
        p.noFill();
        p.rect(x, y, 40, 40);
      }
    }

    // Spotlights from above
    for (let light of lights) {
      let lightColor = p.color(255, 215, 0, 80);
      if (light.color === 'orange') lightColor = p.color(255, 165, 0, 80);
      if (light.color === 'yellow') lightColor = p.color(255, 255, 0, 80);

      p.fill(lightColor);
      p.noStroke();
      p.triangle(light.x - 30, light.y, light.x + 30, light.y, 
                 light.x + p.sin(spotlightAngle + light.x * 0.01) * 20, 
                 light.y + 200 * light.intensity);
    }

    // Applause meters (industrial gauges measuring joy)
    for (let meter of applauseMeters) {
      // Meter housing
      p.fill(80, 90, 100);
      p.stroke(120);
      p.strokeWeight(2);
      p.rect(meter.x - 25, meter.y - 15, 50, 30, 5);

      // Meter display
      p.fill(20);
      p.rect(meter.x - 20, meter.y - 10, 40, 20);

      // Meter needle
      p.stroke(255, 215, 0);
      p.strokeWeight(3);
      let angle = p.map(meter.value, 0, 1, -p.PI/3, p.PI/3);
      p.line(meter.x, meter.y, 
             meter.x + p.cos(angle - p.PI/2) * 15, 
             meter.y + p.sin(angle - p.PI/2) * 15);

      meter.value = p.lerp(meter.value, meter.target, 0.02);
      if (p.abs(meter.value - meter.target) < 0.01) {
        meter.target = p.random(0.3, 0.9);
      }
    }

    // Comedy masks
    for (let mask of comedyMasks) {
      p.fill(255, 245, 200);
      p.stroke(150);
      p.strokeWeight(2);
      p.ellipse(mask.x, mask.y, 40, 45);

      // Eyes
      p.fill(0);
      p.noStroke();
      p.ellipse(mask.x - 8, mask.y - 8, 4);
      p.ellipse(mask.x + 8, mask.y - 8, 4);

      // Mouth
      p.stroke(0);
      p.strokeWeight(3);
      p.noFill();
      if (mask.type === 'happy') {
        p.arc(mask.x, mask.y + 5, 20, 15, 0, p.PI);
      } else {
        p.arc(mask.x, mask.y + 15, 20, 15, p.PI, p.TWO_PI);
      }
    }

    // Microphones
    for (let mic of microphones) {
      // Stand
      p.stroke(100);
      p.strokeWeight(4);
      p.line(mic.x, mic.y + 20, mic.x, mic.y + 80);

      // Microphone head
      p.fill(180);
      p.stroke(120);
      p.strokeWeight(2);
      p.ellipse(mic.x, mic.y, 25, 35);

      // Sound waves
      if (p.frameCount % 60 < 30) {
        p.noFill();
        p.stroke(255, 215, 0, 150);
        p.strokeWeight(2);
        for (let i = 0; i < 3; i++) {
          let radius = 30 + i * 15;
          p.arc(mic.x, mic.y, radius, radius, -p.PI/4, p.PI/4);
        }
      }
    }

    // The main crack - the disruption
    p.stroke(255, 215, 0);
    p.strokeWeight(1);
    for (let i = 1; i < crack.length; i++) {
      if (i < crackProgress) {
        let prev = crack[i-1];
        let curr = crack[i];

        // Glowing effect for some segments
        if (curr.glowing) {
          p.stroke(255, 255, 100, 200);
          p.strokeWeight(curr.width + 4);
          p.line(prev.x, prev.y, curr.x, curr.y);
        }

        // Main crack line
        p.stroke(255, 215, 0);
        p.strokeWeight(curr.width);
        p.line(prev.x, prev.y, curr.x, curr.y);

        // Light bleeding through
        if (curr.glowing) {
          p.fill(255, 255, 150, 100);
          p.noStroke();
          p.ellipse(curr.x, curr.y, curr.width * 3);
        }
      }
    }

    // Joy particles escaping from the crack
    if (crackProgress > 15) {
      for (let i = particles.length - 1; i >= 0; i--) {
        let particle = particles[i];
        p.fill(255, 215 + p.random(-30, 30), p.random(50, 150), particle.alpha);
        p.noStroke();
        p.ellipse(particle.x, particle.y, particle.size);

        particle.x += particle.vx;
        particle.y += particle.vy;
        particle.vy += 0.1; // gravity
        particle.alpha -= 2;
        particle.size *= 0.98;

        if (particle.alpha <= 0) {
          particles.splice(i, 1);
        }
      }

      // Spawn new particles from crack
      if (p.random() > 0.7) {
        let crackPoint = crack[p.floor(p.random(10, crackProgress))];
        particles.push({
          x: crackPoint.x,
          y: crackPoint.y,
          vx: p.random(-2, 2),
          vy: p.random(-3, -1),
          size: p.random(3, 8),
          alpha: 255
        });
      }
    }

    // Animation updates
    curtainOffset = p.sin(p.millis() * 0.001) * 10;
    spotlightAngle += 0.02;
    crackProgress = p.min(crack.length, p.millis() * 0.01);

    // Interactive elements
    if (p.dist(p.mouseX, p.mouseY, 200, 300) < 100) {
      // Mouse near crack causes more intense glowing
      for (let point of crack) {
        if (p.random() > 0.8) {
          point.glowing = true;
        }
      }

      // More particles when mouse is near
      if (p.random() > 0.5 && crackProgress > 10) {
        particles.push({
          x: p.mouseX,
          y: p.mouseY,
          vx: p.random(-3, 3),
          vy: p.random(-4, -1),
          size: p.random(2, 6),
          alpha: 200
        });
      }
    } else {
      // Reset glowing
      for (let point of crack) {
        if (p.random() > 0.95) {
          point.glowing = p.random() > 0.7;
        }
      }
    }

    // Click interaction
    if (p.mouseIsPressed) {
      // Applause meters react to clicks
      for (let meter of applauseMeters) {
        meter.target = p.random(0.7, 1.0);
      }
    }
  };
}

function sketch(p) {
  let spotlights = [];
  let comedyMasks = [];
  let applauseMeters = [];
  let particles = [];
  let curtainOffset = 0;
  let balanceElements = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create six spotlight sources for the six elements
    for (let i = 0; i < 6; i++) {
      spotlights.push({
        x: 100 + (i % 2) * 200,
        y: 100 + Math.floor(i / 2) * 150,
        radius: 60 + p.sin(i) * 20,
        intensity: 0.8,
        hue: 45 + i * 15,
        angle: i * 60
      });
    }

    // Comedy masks positioned around the card
    for (let i = 0; i < 3; i++) {
      comedyMasks.push({
        x: 80 + i * 120,
        y: 450,
        scale: 0.8 + p.sin(i) * 0.2,
        rotation: p.sin(i * 2) * 0.3,
        type: i % 2 === 0 ? 'happy' : 'laughing'
      });
    }

    // Applause meters on sides
    applauseMeters.push({x: 50, y: 200, level: 0.7});
    applauseMeters.push({x: 350, y: 200, level: 0.8});

    // Balance elements - six orbs that represent the new order
    for (let i = 0; i < 6; i++) {
      balanceElements.push({
        x: 200 + p.cos(i * p.PI / 3) * 80,
        y: 250 + p.sin(i * p.PI / 3) * 60,
        originalX: 200 + p.cos(i * p.PI / 3) * 80,
        originalY: 250 + p.sin(i * p.PI / 3) * 60,
        energy: 0,
        hue: 40 + i * 20
      });
    }
  };

  p.draw = function() {
    // Theatrical gradient background
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 5, 35), p.color(45, 25, 15), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Draw stage curtains
    curtainOffset = p.sin(p.millis() * 0.001) * 20;
    p.fill(120, 20, 30);
    p.noStroke();

    // Left curtain
    p.beginShape();
    p.vertex(0, 0);
    p.vertex(80 + curtainOffset, 0);
    p.vertex(60 + curtainOffset, p.height);
    p.vertex(0, p.height);
    p.endShape();

    // Right curtain
    p.beginShape();
    p.vertex(p.width, 0);
    p.vertex(320 - curtainOffset, 0);
    p.vertex(340 - curtainOffset, p.height);
    p.vertex(p.width, p.height);
    p.endShape();

    // Draw warm spotlight beams
    p.blendMode(p.ADD);
    for (let spotlight of spotlights) {
      let pulse = 0.8 + p.sin(p.millis() * 0.003 + spotlight.angle) * 0.3;

      p.fill(spotlight.hue, 60, 25, pulse * 30);
      p.noStroke();
      p.ellipse(spotlight.x, spotlight.y, spotlight.radius * 2 * pulse);

      // Beam effect
      p.fill(spotlight.hue, 40, 15, pulse * 15);
      for (let i = 0; i < 3; i++) {
        p.ellipse(spotlight.x, spotlight.y, (spotlight.radius + i * 30) * pulse);
      }
    }
    p.blendMode(p.BLEND);

    // Draw balance elements - the six elements finding new harmony
    for (let i = 0; i < balanceElements.length; i++) {
      let element = balanceElements[i];

      // Mouse interaction - elements respond to cursor
      let mouseInfluence = p.dist(p.mouseX, p.mouseY, element.originalX, element.originalY);
      let influence = p.map(p.constrain(mouseInfluence, 0, 100), 0, 100, 1, 0);

      element.energy = p.lerp(element.energy, influence, 0.1);
      element.x = p.lerp(element.x, element.originalX + (p.mouseX - element.originalX) * element.energy * 0.1, 0.1);
      element.y = p.lerp(element.y, element.originalY + (p.mouseY - element.originalY) * element.energy * 0.1, 0.1);

      // Draw energy orb
      let orbPulse = 1 + p.sin(p.millis() * 0.005 + i) * 0.2;

      p.push();
      p.translate(element.x, element.y);
      p.rotate(p.millis() * 0.002 + i);

      // Outer glow
      p.fill(element.hue, 70, 90, 30);
      p.noStroke();
      p.ellipse(0, 0, 40 * orbPulse);

      // Core
      p.fill(element.hue, 50, 100);
      p.ellipse(0, 0, 20 * orbPulse);

      // Inner spark
      p.fill(60, 30, 100);
      p.ellipse(0, 0, 8);

      p.pop();

      // Connection lines between elements showing harmony
      if (i < balanceElements.length - 1) {
        p.stroke(element.hue, 40, 60, 40);
        p.strokeWeight(2);
        p.line(element.x, element.y, balanceElements[i + 1].x, balanceElements[i + 1].y);
      }
    }

    // Connect last to first
    if (balanceElements.length > 0) {
      let first = balanceElements[0];
      let last = balanceElements[balanceElements.length - 1];
      p.stroke(first.hue, 40, 60, 40);
      p.strokeWeight(2);
      p.line(first.x, first.y, last.x, last.y);
    }

    // Draw applause meters
    for (let meter of applauseMeters) {
      // Meter housing
      p.fill(30);
      p.stroke(60, 30, 80);
      p.strokeWeight(2);
      p.rect(meter.x - 15, meter.y - 50, 30, 100);

      // Meter level
      let meterHeight = meter.level * 80 + p.sin(p.millis() * 0.01) * 10;
      p.fill(50, 80, 90);
      p.noStroke();
      p.rect(meter.x - 12, meter.y + 40 - meterHeight, 24, meterHeight);

      // Peak indicators
      for (let i = 0; i < 5; i++) {
        let peakY = meter.y - 40 + i * 20;
        p.fill(50 + i * 10, 70, 80);
        if (meterHeight > i * 20) {
          p.ellipse(meter.x, peakY, 6);
        }
      }
    }

    // Draw comedy masks
    for (let mask of comedyMasks) {
      p.push();
      p.translate(mask.x, mask.y);
      p.scale(mask.scale);
      p.rotate(mask.rotation + p.sin(p.millis() * 0.003) * 0.1);

      // Mask base
      p.fill(50, 20, 95);
      p.stroke(45, 40, 70);
      p.strokeWeight(2);
      p.ellipse(0, 0, 60, 70);

      // Eyes
      p.fill(0);
      p.noStroke();
      if (mask.type === 'happy') {
        // Happy curved eyes
        p.arc(-12, -10, 12, 8, 0, p.PI);
        p.arc(12, -10, 12, 8, 0, p.PI);
      } else {
        // Laughing squinted eyes
        p.ellipse(-12, -10, 15, 4);
        p.ellipse(12, -10, 15, 4);
      }

      // Mouth
      p.stroke(0);
      p.strokeWeight(3);
      p.noFill();
      if (mask.type === 'happy') {
        p.arc(0, 5, 30, 25, 0, p.PI);
      } else {
        p.arc(0, 0, 40, 35, 0, p.PI);
        // Extra laugh lines
        p.arc(-15, 0, 20, 15, 0, p.PI);
        p.arc(15, 0, 20, 15, 0, p.PI);
      }

      p.pop();
    }

    // Generate joy particles when mouse is clicked
    if (p.mouseIsPressed) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-3, 3),
        vy: p.random(-5, -2),
        life: 255,
        hue: p.random(35, 65),
        size: p.random(4, 12)
      });
    }

    // Update and draw particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.vy += 0.1; // gravity
      particle.life -= 3;

      if (particle.life <= 0) {
        particles.splice(i, 1);
        continue;
      }

      p.push();
      p.translate(particle.x, particle.y);
      p.rotate(p.millis() * 0.01 + i);

      p.fill(particle.hue, 70, 90, particle.life);
      p.noStroke();

      // Star shape
      p.beginShape();
      for (let a = 0; a < p.TWO_PI; a += p.TWO_PI / 10) {
        let r = (a % (p.TWO_PI / 5) === 0) ? particle.size : particle.size * 0.5;
        let x = r * p.cos(a);
        let y = r * p.sin(a);
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);
      p.pop();
    }

    // Central harmony indicator
    let centralPulse = 1 + p.sin(p.millis() * 0.004) * 0.3;
    p.push();
    p.translate(200, 250);
    p.rotate(p.millis() * 0.001);

    p.stroke(55, 60, 80, 100);
    p.strokeWeight(3);
    p.noFill();
    p.ellipse(0, 0, 120 * centralPulse);

    p.stroke(45, 40, 90, 60);
    p.strokeWeight(1);
    p.ellipse(0, 0, 160 * centralPulse);

    p.pop();
  };

  p.mousePressed = function() {
    // Create burst of joy particles
    for (let i = 0; i < 15; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-4, 4),
        vy: p.random(-6, -1),
        life: 255,
        hue: p.random(35, 65),
        size: p.random(6, 14)
      });
    }
  };
}

function sketch(p) {
  let figure;
  let paths = [];
  let spotlights = [];
  let particles = [];
  let comedyMasks = [];
  let meters = [];
  let curtainOffset = 0;
  let contemplationTime = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize figure position
    figure = {
      x: 200,
      y: 400,
      lookBack: false,
      contemplationLevel: 0
    };

    // Create seven paths radiating outward
    for (let i = 0; i < 7; i++) {
      let angle = p.map(i, 0, 6, -p.PI/3, p.PI/3);
      paths.push({
        angle: angle,
        x: 200 + p.cos(angle) * 150,
        y: 300 + p.sin(angle) * 100,
        brightness: p.random(0.6, 1.0),
        pulsing: p.random(0.02, 0.05)
      });
    }

    // Create spotlights
    for (let i = 0; i < 5; i++) {
      spotlights.push({
        x: p.random(50, 350),
        y: p.random(50, 150),
        size: p.random(80, 120),
        intensity: p.random(0.3, 0.8),
        color: p.color(255, 220 + p.random(-30, 30), 100 + p.random(-50, 100))
      });
    }

    // Comedy masks
    for (let i = 0; i < 3; i++) {
      comedyMasks.push({
        x: 50 + i * 150,
        y: 100 + p.random(-20, 20),
        rotation: p.random(-0.2, 0.2),
        scale: p.random(0.8, 1.2)
      });
    }

    // Applause meters
    for (let i = 0; i < 2; i++) {
      meters.push({
        x: 80 + i * 240,
        y: 180,
        level: p.random(0.4, 0.9),
        fluctuation: p.random(0.01, 0.03)
      });
    }
  };

  p.draw = function() {
    // Dark stage background
    p.background(20, 15, 30);

    // Stage curtains
    curtainOffset = p.sin(p.millis() * 0.001) * 10;
    p.fill(120, 30, 50);
    p.rect(-10, 0, 60 + curtainOffset, 600);
    p.rect(350 - curtainOffset, 0, 60, 600);

    // Draw spotlights
    for (let spotlight of spotlights) {
      p.push();
      p.blendMode(p.ADD);
      let alpha = spotlight.intensity * (0.8 + 0.2 * p.sin(p.millis() * 0.003));
      p.fill(p.red(spotlight.color), p.green(spotlight.color), p.blue(spotlight.color), alpha * 255);
      p.ellipse(spotlight.x, spotlight.y, spotlight.size * 2);
      p.pop();
    }

    // Floor lighting
    p.push();
    p.blendMode(p.ADD);
    for (let x = 0; x < 400; x += 20) {
      let brightness = 30 + 20 * p.sin(p.millis() * 0.005 + x * 0.1);
      p.fill(255, 200, 80, brightness);
      p.rect(x, 500, 20, 100);
    }
    p.pop();

    // Draw comedy masks
    for (let mask of comedyMasks) {
      p.push();
      p.translate(mask.x, mask.y);
      p.rotate(mask.rotation + p.sin(p.millis() * 0.002) * 0.1);
      p.scale(mask.scale);

      // Happy mask
      p.fill(255, 220, 150);
      p.stroke(200, 150, 50);
      p.strokeWeight(2);
      p.ellipse(0, 0, 40, 50);
      p.fill(50);
      p.ellipse(-8, -8, 6);
      p.ellipse(8, -8, 6);
      p.noFill();
      p.strokeWeight(3);
      p.arc(0, 5, 20, 15, 0, p.PI);
      p.pop();
    }

    // Draw applause meters
    for (let meter of meters) {
      meter.level += p.sin(p.millis() * meter.fluctuation) * 0.01;
      meter.level = p.constrain(meter.level, 0.2, 1.0);

      p.push();
      p.translate(meter.x, meter.y);

      // Meter housing
      p.fill(60, 60, 80);
      p.stroke(100, 100, 120);
      p.rect(-15, -40, 30, 80);

      // Meter fill
      let fillHeight = meter.level * 70;
      p.fill(255, 180 + meter.level * 75, 100);
      p.noStroke();
      p.rect(-12, 35 - fillHeight, 24, fillHeight);

      // Needle
      p.push();
      p.rotate(p.map(meter.level, 0, 1, -p.PI/4, p.PI/4));
      p.stroke(255, 100, 100);
      p.strokeWeight(2);
      p.line(0, 0, 0, -25);
      p.pop();
      p.pop();
    }

    // Draw the seven paths
    for (let i = 0; i < paths.length; i++) {
      let path = paths[i];
      path.brightness += p.sin(p.millis() * path.pulsing) * 0.1;

      p.push();
      let alpha = p.map(p.abs(p.mouseX - path.x) + p.abs(p.mouseY - path.y), 0, 300, 255, 100);
      p.stroke(255, 200 + path.brightness * 55, 120, alpha);
      p.strokeWeight(8);
      p.line(figure.x, figure.y, path.x, path.y);

      // Path endpoint glow
      p.fill(255, 220, 150, alpha * 0.8);
      p.noStroke();
      p.ellipse(path.x, path.y, 20 + path.brightness * 10);

      // Roman numeral at path end
      p.fill(255, 255, 200);
      p.textAlign(p.CENTER);
      p.textSize(12);
      p.text(romanNumerals()[i], path.x, path.y + 25);
      p.pop();
    }

    // Draw contemplative figure
    contemplationTime += 0.02;
    figure.lookBack = p.sin(contemplationTime) > 0.3;

    p.push();
    p.translate(figure.x, figure.y);

    // Shadow
    p.fill(0, 0, 0, 100);
    p.ellipse(0, 40, 60, 20);

    // Body
    p.fill(80, 120, 180);
    p.stroke(60, 100, 160);
    p.strokeWeight(2);
    p.ellipse(0, 0, 40, 60);

    // Arms in contemplative pose
    p.strokeWeight(6);
    p.stroke(60, 100, 160);
    if (figure.lookBack) {
      p.line(-15, -10, -25, 5);
      p.line(15, -10, 25, -5);
    } else {
      p.line(-15, -10, -20, 10);
      p.line(15, -10, 10, 15);
    }

    // Head
    p.fill(100, 140, 200);
    p.noStroke();
    p.ellipse(0, -30, 25, 30);

    // Eyes
    p.fill(255, 255, 150);
    if (figure.lookBack) {
      p.ellipse(-6, -32, 8);
      p.ellipse(6, -32, 8);
    } else {
      p.ellipse(-4, -32, 8);
      p.ellipse(4, -32, 8);
    }

    p.pop();

    // Interactive particles
    if (p.mouseIsPressed) {
      for (let i = 0; i < 3; i++) {
        particles.push({
          x: p.mouseX + p.random(-10, 10),
          y: p.mouseY + p.random(-10, 10),
          vx: p.random(-2, 2),
          vy: p.random(-3, -1),
          life: 255,
          color: p.color(255, p.random(150, 255), p.random(80, 150))
        });
      }
    }

    // Update and draw particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 3;

      p.push();
      p.fill(p.red(particle.color), p.green(particle.color), p.blue(particle.color), particle.life);
      p.noStroke();
      p.ellipse(particle.x, particle.y, 8);
      p.pop();

      if (particle.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Mouse interaction glow
    if (p.dist(p.mouseX, p.mouseY, figure.x, figure.y) < 50) {
      p.push();
      p.blendMode(p.ADD);
      p.fill(255, 200, 100, 50);
      p.ellipse(figure.x, figure.y, 100);
      p.pop();
    }
  };

  function romanNumerals() {
    return ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII'];
  }
}

function sketch(p) {
  let performers = [];
  let spotlights = [];
  let applauseMeters = [];
  let curtainWave = 0;
  let baseHue = 45; // Golden base

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Create eight performer positions in a coordinated formation
    let positions = [
      {x: 100, y: 200}, {x: 300, y: 200},
      {x: 150, y: 280}, {x: 250, y: 280},
      {x: 75, y: 360}, {x: 200, y: 360}, {x: 325, y: 360},
      {x: 200, y: 440}
    ];

    for (let i = 0; i < 8; i++) {
      performers.push({
        x: positions[i].x,
        y: positions[i].y,
        size: p.random(20, 30),
        hue: (baseHue + p.random(-30, 30)) % 360,
        phase: i * 0.8,
        energy: p.random(0.8, 1.2),
        tool: p.floor(p.random(3)) // 0: microphone, 1: comedy mask, 2: spotlight
      });
    }

    // Create spotlight effects
    for (let i = 0; i < 5; i++) {
      spotlights.push({
        x: p.random(50, 350),
        y: p.random(100, 150),
        intensity: p.random(0.3, 0.7),
        phase: p.random(p.TWO_PI)
      });
    }

    // Create applause meters
    for (let i = 0; i < 3; i++) {
      applauseMeters.push({
        x: 30 + i * 170,
        y: 80,
        level: p.random(0.4, 0.9),
        targetLevel: p.random(0.4, 0.9)
      });
    }
  };

  p.draw = function() {
    // Dark stage background
    p.background(240, 30, 15);

    // Draw curtains at top
    p.fill(0, 60, 40);
    curtainWave += 0.02;
    for (let x = 0; x < p.width; x += 20) {
      let waveHeight = p.sin(curtainWave + x * 0.05) * 10;
      p.rect(x, 0, 20, 60 + waveHeight);
    }

    // Draw stage floor with warm lighting
    p.fill(baseHue, 40, 80);
    p.rect(0, p.height - 100, p.width, 100);

    // Draw spotlights
    for (let spotlight of spotlights) {
      spotlight.phase += 0.03;
      let brightness = 40 + p.sin(spotlight.phase) * 20;

      p.fill(60, 80, brightness, spotlight.intensity * 30);
      p.noStroke();
      p.ellipse(spotlight.x, spotlight.y + 100, 120, 200);

      // Spotlight source
      p.fill(60, 100, 90);
      p.ellipse(spotlight.x, spotlight.y, 8, 8);
    }

    // Draw applause meters
    for (let meter of applauseMeters) {
      // Meter background
      p.stroke(0, 0, 80);
      p.strokeWeight(2);
      p.fill(0, 0, 20);
      p.rect(meter.x, meter.y, 30, 80);

      // Meter fill
      meter.level = p.lerp(meter.level, meter.targetLevel, 0.02);
      if (p.frameCount % 120 === 0) {
        meter.targetLevel = p.random(0.4, 0.9);
      }

      let fillHeight = meter.level * 75;
      let meterHue = p.map(meter.level, 0, 1, 120, 60);
      p.fill(meterHue, 80, 90);
      p.noStroke();
      p.rect(meter.x + 2, meter.y + 80 - fillHeight, 26, fillHeight);

      // Meter label
      p.fill(0, 0, 90);
      p.textAlign(p.CENTER);
      p.textSize(8);
      p.text("JOY", meter.x + 15, meter.y + 95);
    }

    // Mouse interaction - increase energy when mouse is nearby
    let mouseInfluence = p.map(p.mouseY, 0, p.height, 1.5, 0.8);

    // Draw performers in coordinated action
    for (let i = 0; i < performers.length; i++) {
      let performer = performers[i];

      // Calculate distance to mouse for interaction
      let distToMouse = p.dist(p.mouseX, p.mouseY, performer.x, performer.y);
      let interaction = p.map(distToMouse, 0, 100, 2, 1);
      interaction = p.constrain(interaction, 1, 2);

      // Coordinated movement pattern
      let time = p.frameCount * 0.05;
      let coordX = performer.x + p.sin(time + performer.phase) * 15;
      let coordY = performer.y + p.cos(time + performer.phase * 0.7) * 8;

      // Energy glow
      let glowSize = performer.size * performer.energy * interaction * mouseInfluence;
      p.fill(performer.hue, 60, 80, 30);
      p.noStroke();
      p.ellipse(coordX, coordY, glowSize * 1.5, glowSize * 1.5);

      // Main performer body
      p.fill(performer.hue, 80, 85);
      p.ellipse(coordX, coordY, performer.size, performer.size);

      // Draw tools/props
      p.stroke(0, 0, 90);
      p.strokeWeight(2);

      if (performer.tool === 0) { // Microphone
        p.line(coordX + 15, coordY - 10, coordX + 15, coordY + 15);
        p.fill(0, 0, 80);
        p.ellipse(coordX + 15, coordY - 15, 8, 12);
      } else if (performer.tool === 1) { // Comedy mask
        p.fill(60, 20, 95);
        p.ellipse(coordX - 18, coordY - 8, 16, 20);
        p.fill(0, 0, 10);
        p.ellipse(coordX - 22, coordY - 12, 3, 3);
        p.ellipse(coordX - 14, coordY - 12, 3, 3);
        p.arc(coordX - 18, coordY - 5, 8, 6, 0, p.PI);
      } else { // Handheld spotlight
        p.fill(60, 100, 90);
        p.ellipse(coordX - 20, coordY, 6, 6);
        p.line(coordX - 20, coordY, coordX - 35, coordY - 5);
      }

      // Energy particles
      if (p.random() < 0.3 * interaction) {
        p.fill(performer.hue + 60, 100, 100, 80);
        p.noStroke();
        let px = coordX + p.random(-20, 20);
        let py = coordY + p.random(-20, 20);
        p.ellipse(px, py, p.random(2, 6), p.random(2, 6));
      }
    }

    // Coordinated action lines showing purposeful movement
    p.stroke(60, 40, 90, 40);
    p.strokeWeight(1);
    for (let i = 0; i < performers.length - 1; i++) {
      let p1 = performers[i];
      let p2 = performers[i + 1];
      let alpha = p.sin(p.frameCount * 0.05 + i) * 20 + 40;
      p.stroke(60, 60, 90, alpha);
      p.line(p1.x, p1.y, p2.x, p2.y);
    }

    // Title glow effect at bottom
    let titleY = p.height - 40;
    p.fill(baseHue, 60, 90, 20);
    p.noStroke();
    for (let i = 0; i < 3; i++) {
      p.ellipse(p.width/2, titleY, 200 - i * 30, 30 - i * 5);
    }
  };
}

function sketch(p) {
  let lights = [];
  let spotlights = [];
  let particles = [];
  let figure;
  let curtains = [];
  let applauseMeter;
  let stage;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize nine lights arranged in a completion pattern
    let positions = [
      {x: 200, y: 120}, // top center
      {x: 120, y: 180}, {x: 280, y: 180}, // second row
      {x: 80, y: 250}, {x: 200, y: 250}, {x: 320, y: 250}, // third row
      {x: 120, y: 320}, {x: 280, y: 320}, // fourth row
      {x: 200, y: 380} // bottom center
    ];

    for(let i = 0; i < 9; i++) {
      lights.push({
        x: positions[i].x,
        y: positions[i].y,
        brightness: p.random(0.7, 1.0),
        phase: p.random(p.TWO_PI),
        size: p.random(25, 35),
        achieved: i < 7 // 7 out of 9 achieved
      });
    }

    // Spotlights
    for(let i = 0; i < 3; i++) {
      spotlights.push({
        x: p.random(50, 350),
        y: p.random(50, 150),
        angle: p.random(p.PI/4, 3*p.PI/4),
        intensity: p.random(0.3, 0.6),
        sweep: p.random(-0.02, 0.02)
      });
    }

    // Central figure
    figure = {
      x: 200,
      y: 450,
      satisfaction: 0.8,
      gesturePhase: 0
    };

    // Stage curtains
    curtains = [
      {x: 0, sway: 0, phase: 0},
      {x: 350, sway: 0, phase: p.PI}
    ];

    // Applause meter
    applauseMeter = {
      x: 320,
      y: 100,
      level: 0.75,
      target: 0.75,
      pulse: 0
    };

    // Stage platform
    stage = {
      y: 480,
      glow: 0
    };
  };

  p.draw = function() {
    // Rich theatrical background
    let bg1 = p.color(20, 10, 40);
    let bg2 = p.color(60, 30, 80);

    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(bg1, bg2, inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Spotlight effects
    p.drawingContext.save();
    p.drawingContext.globalCompositeOperation = 'screen';

    for(let spotlight of spotlights) {
      spotlight.angle += spotlight.sweep;

      p.push();
      p.translate(spotlight.x, spotlight.y);
      p.rotate(spotlight.angle);

      let gradient = p.drawingContext.createLinearGradient(0, 0, 0, 300);
      gradient.addColorStop(0, `rgba(255, 220, 120, ${spotlight.intensity})`);
      gradient.addColorStop(1, 'rgba(255, 220, 120, 0)');

      p.drawingContext.fillStyle = gradient;
      p.noStroke();
      p.triangle(-40, 0, 40, 0, 0, 300);
      p.pop();
    }

    p.drawingContext.restore();

    // Stage curtains with theatrical sway
    for(let curtain of curtains) {
      curtain.sway = p.sin(p.millis() * 0.001 + curtain.phase) * 15;

      p.fill(120, 20, 40, 200);
      p.noStroke();

      for(let i = 0; i < 8; i++) {
        let x = curtain.x + curtain.sway + i * 2;
        let width = 40 - i * 3;
        p.rect(x, 0, width, p.height * 0.7);
      }
    }

    // Stage platform with warm glow
    stage.glow = 0.3 + p.sin(p.millis() * 0.002) * 0.1;

    p.fill(80, 60, 40, 100);
    p.noStroke();
    p.ellipse(p.width/2, stage.y + 40, 380, 80);

    p.fill(200, 180, 120, stage.glow * 255);
    p.rect(0, stage.y, p.width, p.height - stage.y);

    // Nine lights in completion pattern
    for(let i = 0; i < lights.length; i++) {
      let light = lights[i];

      // Pulsing brightness
      let pulse = p.sin(p.millis() * 0.003 + light.phase) * 0.2 + 0.8;
      let brightness = light.brightness * pulse;

      if(light.achieved) {
        // Achieved lights - warm golden glow
        p.fill(255, 220, 100, brightness * 255);
        p.stroke(255, 180, 50, 200);
        p.strokeWeight(3);

        // Multiple layers for richness
        p.ellipse(light.x, light.y, light.size * 1.5);
        p.fill(255, 240, 150, brightness * 180);
        p.noStroke();
        p.ellipse(light.x, light.y, light.size);

        // Sparkle effect
        if(p.random() < 0.1) {
          particles.push({
            x: light.x + p.random(-20, 20),
            y: light.y + p.random(-20, 20),
            vx: p.random(-1, 1),
            vy: p.random(-2, -0.5),
            life: 60,
            maxLife: 60
          });
        }
      } else {
        // Unachieved lights - dimmer, cooler
        p.fill(150, 150, 200, brightness * 100);
        p.stroke(100, 100, 150, 100);
        p.strokeWeight(2);
        p.ellipse(light.x, light.y, light.size * 0.8);
      }
    }

    // Particle sparkles
    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life--;

      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 255);
      p.fill(255, 240, 100, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, 4);

      if(particle.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Central figure surveying achievement
    figure.gesturePhase += 0.02;

    let armRaise = p.sin(figure.gesturePhase) * 10;
    let satisfaction = 0.8 + p.sin(figure.gesturePhase * 0.5) * 0.1;

    p.push();
    p.translate(figure.x, figure.y);

    // Figure silhouette with warm glow
    p.fill(100, 80, 60);
    p.stroke(200, 180, 120, 150);
    p.strokeWeight(2);

    // Body
    p.ellipse(0, 0, 40, 60);

    // Head looking up at achievement
    p.ellipse(0, -35, 25, 30);

    // Arms - one pointing toward the lights
    p.strokeWeight(6);
    p.line(-15, -10, -25 + armRaise, -30);
    p.line(15, -10, 25, -20 + armRaise);

    // Eyes looking at achievement
    p.fill(255, 220, 100);
    p.noStroke();
    p.ellipse(-5, -35, 4, 6);
    p.ellipse(5, -35, 4, 6);

    p.pop();

    // Applause meter - industrial but warm
    applauseMeter.pulse += 0.05;
    applauseMeter.level += (applauseMeter.target - applauseMeter.level) * 0.02;

    // Meter housing
    p.fill(60, 50, 40);
    p.stroke(120, 100, 80);
    p.strokeWeight(2);
    p.rect(applauseMeter.x - 20, applauseMeter.y, 15, 80);

    // Meter fill
    let meterHeight = applauseMeter.level * 70;
    for(let i = 0; i < meterHeight; i += 5) {
      let intensity = p.map(i, 0, 70, 0.3, 1.0);
      p.fill(255, 200 * intensity, 100 * intensity, 200);
      p.noStroke();
      p.rect(applauseMeter.x - 18, applauseMeter.y + 75 - i, 11, 4);
    }

    // Meter glow
    p.fill(255, 220, 100, 50 + p.sin(applauseMeter.pulse) * 30);
    p.noStroke();
    p.rect(applauseMeter.x - 25, applauseMeter.y - 5, 21, 90);

    // Interactive response - mouse affects satisfaction and lighting
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, figure.x, figure.y);
    if(mouseInfluence < 100) {
      figure.satisfaction = p.min(1.0, figure.satisfaction + 0.01);
      applauseMeter.target = p.min(1.0, applauseMeter.target + 0.02);

      // Add extra sparkles near mouse
      if(p.random() < 0.3) {
        particles.push({
          x: p.mouseX + p.random(-30, 30),
          y: p.mouseY + p.random(-30, 30),
          vx: p.random(-2, 2),
          vy: p.random(-3, -1),
          life: 40,
          maxLife: 40
        });
      }
    }
  };
}

function sketch(p) {
  let spotlights = [];
  let energyMeter = { value: 0, target: 8.5 };
  let curtains = { leftOpen: 0.3, rightOpen: 0.3 };
  let particles = [];
  let laughBubbles = [];
  let maskRotation = 0;
  let overflow = 0;
  let stage = { x: 50, y: 450, w: 300, h: 100 };

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize spotlights
    for(let i = 0; i < 4; i++) {
      spotlights.push({
        x: p.random(100, 300),
        y: p.random(50, 150),
        intensity: p.random(0.5, 1),
        color: p.color(255, 220 + p.random(-20, 20), 100 + p.random(-30, 30))
      });
    }

    // Initialize energy particles
    for(let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-1, 1),
        vy: p.random(-2, -0.5),
        size: p.random(2, 6),
        life: 1
      });
    }
  };

  p.draw = function() {
    // Dynamic background with stage lighting
    p.background(20, 15, 35);

    // Spotlight effects
    for(let spot of spotlights) {
      let gradient = p.drawingContext.createRadialGradient(spot.x, spot.y, 0, spot.x, spot.y, 120);
      gradient.addColorStop(0, `rgba(255, 220, 100, ${spot.intensity * 0.3})`);
      gradient.addColorStop(1, 'rgba(255, 220, 100, 0)');
      p.drawingContext.fillStyle = gradient;
      p.drawingContext.fillRect(0, 0, 400, 600);

      spot.intensity += p.sin(p.frameCount * 0.02 + spot.x) * 0.005;
      spot.intensity = p.constrain(spot.intensity, 0.3, 1);
    }

    // Stage curtains
    p.fill(120, 30, 40);
    p.rect(0, 0, 50 + curtains.leftOpen * 100, 600);
    p.rect(350 - curtains.rightOpen * 100, 0, 50 + curtains.rightOpen * 100, 600);

    // Main stage platform
    p.fill(80, 50, 20);
    p.rect(stage.x, stage.y, stage.w, stage.h);
    p.fill(200, 160, 80);
    p.rect(stage.x, stage.y, stage.w, 10);

    // Ten light elements arranged in completion pattern
    drawTenLights();

    // Comedy masks (dynamic)
    maskRotation += 0.01;
    drawComedyMask(120, 200, 40, maskRotation);
    drawComedyMask(280, 220, 35, -maskRotation * 0.8);

    // Energy meter showing overflow
    drawEnergyMeter();

    // Microphone center stage
    drawMicrophone(200, 400);

    // Overflow effect - laughing energy particles
    updateParticles();

    // Laugh bubbles rising from stage
    if(p.frameCount % 15 == 0) {
      laughBubbles.push({
        x: p.random(stage.x, stage.x + stage.w),
        y: stage.y,
        size: p.random(15, 30),
        vy: p.random(-2, -4),
        alpha: 255
      });
    }

    updateLaughBubbles();

    // Interactive curtain response
    let mouseNear = p.dist(p.mouseX, p.mouseY, 200, 300) < 100;
    curtains.leftOpen = p.lerp(curtains.leftOpen, mouseNear ? 0.6 : 0.3, 0.05);
    curtains.rightOpen = p.lerp(curtains.rightOpen, mouseNear ? 0.6 : 0.3, 0.05);

    // Energy meter responds to interaction
    energyMeter.target = mouseNear ? 10 : 8.5;
    energyMeter.value = p.lerp(energyMeter.value, energyMeter.target, 0.03);
  };

  function drawTenLights() {
    // Arranged in sacred geometry - tree of life inspired
    let positions = [
      {x: 200, y: 80},   // Crown
      {x: 160, y: 120}, {x: 240, y: 120}, // Wisdom & Understanding
      {x: 200, y: 160},  // Beauty/Harmony
      {x: 140, y: 200}, {x: 260, y: 200}, // Severity & Mercy
      {x: 200, y: 240},  // Foundation
      {x: 120, y: 300}, {x: 200, y: 280}, {x: 280, y: 300} // Kingdom trio
    ];

    for(let i = 0; i < positions.length; i++) {
      let pos = positions[i];
      let pulse = p.sin(p.frameCount * 0.05 + i * 0.5) * 0.3 + 0.7;

      // Light glow
      p.fill(255, 240, 150, 100 * pulse);
      p.ellipse(pos.x, pos.y, 40, 40);

      // Core light
      p.fill(255, 220, 100, 255 * pulse);
      p.ellipse(pos.x, pos.y, 20, 20);

      // Connecting energy lines
      if(i < positions.length - 1) {
        p.stroke(255, 240, 150, 50);
        p.strokeWeight(2);
        let next = positions[(i + 1) % positions.length];
        p.line(pos.x, pos.y, next.x, next.y);
        p.noStroke();
      }
    }
  }

  function drawComedyMask(x, y, size, rotation) {
    p.push();
    p.translate(x, y);
    p.rotate(rotation);

    // Mask base
    p.fill(240, 230, 200);
    p.ellipse(0, 0, size, size * 1.2);

    // Happy expression
    p.fill(50);
    p.ellipse(-size * 0.2, -size * 0.1, size * 0.15, size * 0.2);
    p.ellipse(size * 0.2, -size * 0.1, size * 0.15, size * 0.2);

    // Smile
    p.noFill();
    p.stroke(50);
    p.strokeWeight(3);
    p.arc(0, size * 0.1, size * 0.4, size * 0.3, 0, p.PI);
    p.noStroke();

    p.pop();
  }

  function drawEnergyMeter() {
    // Meter housing
    p.fill(60, 60, 80);
    p.rect(320, 50, 60, 200, 10);

    // Meter scale
    p.fill(40);
    for(let i = 0; i <= 10; i++) {
      let y = 240 - (i / 10) * 180;
      p.rect(325, y, 10, 2);
    }

    // Energy level with overflow effect
    let meterHeight = (energyMeter.value / 10) * 180;
    let overflowHeight = p.max(0, meterHeight - 180);

    // Normal range
    p.fill(100, 255, 100);
    p.rect(330, 240 - p.min(meterHeight, 180), 40, p.min(meterHeight, 180));

    // Overflow - golden energy
    if(overflowHeight > 0) {
      p.fill(255, 215, 0);
      p.rect(330, 60 - overflowHeight, 40, overflowHeight);

      // Overflow sparkles
      for(let i = 0; i < overflowHeight / 5; i++) {
        p.fill(255, 255, 100, p.random(100, 255));
        let sx = 350 + p.random(-20, 20);
        let sy = 60 + p.random(-overflowHeight, 0);
        p.ellipse(sx, sy, 3, 3);
      }
    }

    // Meter label
    p.fill(200);
    p.textAlign(p.CENTER);
    p.textSize(8);
    p.text("JOY", 350, 270);
  }

  function drawMicrophone(x, y) {
    // Microphone stand
    p.stroke(120);
    p.strokeWeight(4);
    p.line(x, y, x, stage.y);

    // Mic head
    p.fill(80, 80, 100);
    p.noStroke();
    p.ellipse(x, y - 20, 20, 30);

    // Sound waves
    let waveIntensity = p.sin(p.frameCount * 0.1) * 0.5 + 0.5;
    p.stroke(255, 215, 0, 100 * waveIntensity);
    p.strokeWeight(2);
    p.noFill();
    for(let i = 1; i <= 3; i++) {
      p.arc(x, y - 20, 20 + i * 15, 20 + i * 15, p.PI, p.TWO_PI);
    }
    p.noStroke();
  }

  function updateParticles() {
    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 0.01;

      p.fill(255, 215 + p.random(-20, 20), 100, particle.life * 255);
      p.ellipse(particle.x, particle.y, particle.size, particle.size);

      if(particle.life <= 0 || particle.y < 0) {
        particles.splice(i, 1);
        // Respawn
        particles.push({
          x: p.random(400),
          y: 600,
          vx: p.random(-1, 1),
          vy: p.random(-2, -0.5),
          size: p.random(2, 6),
          life: 1
        });
      }
    }
  }

  function updateLaughBubbles() {
    for(let i = laughBubbles.length - 1; i >= 0; i--) {
      let bubble = laughBubbles[i];

      bubble.y += bubble.vy;
      bubble.alpha -= 3;
      bubble.x += p.sin(bubble.y * 0.01) * 0.5;

      p.fill(255, 255, 255, bubble.alpha);
      p.textAlign(p.CENTER);
      p.textSize(bubble.size * 0.6);

      let laughs = ['HA', 'HE', 'HO', '😄', '😂'];
      p.text(p.random(laughs), bubble.x, bubble.y);

      if(bubble.alpha <= 0) {
        laughBubbles.splice(i, 1);
      }
    }
  }

  p.mousePressed = function() {
    // Add burst of joy particles on click
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-3, 3),
        vy: p.random(-4, -1),
        size: p.random(4, 8),
        life: 1
      });
    }
  };
}

function sketch(p) {
  let spotlights = [];
  let curtains = [];
  let traineeY = 0;
  let mentorY = 0;
