      });
    }

    // Initialize comedy masks
    comedyMasks.push({x: 50, y: 150, rotation: 0, type: 'happy'});
    comedyMasks.push({x: 350, y: 180, rotation: 0, type: 'excited'});

    traineeY = 350;
    mentorY = 280;
