  p.draw = function() {
    // Background gradient
    for(let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(25, 20, 60), p.color(80, 40, 20), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Mouse influence
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);

    // Draw stage floor with grid pattern
    p.stroke(255, 200, 100, 100);
    p.strokeWeight(1);
    for(let i = 0; i < 6; i++) {
      let y = 450 + i * 20;
      p.line(0, y, p.width, y);
    }
    for(let i = 0; i < 8; i++) {
      let x = i * 50;
      p.line(x, 450, x, p.height);
    }

    // Draw curtains
    p.fill(120, 20, 40);
    p.noStroke();
    for(let curtain of curtains) {
      curtain.wave += curtain.speed;
      let waveOffset = p.sin(curtain.wave) * 15;
      p.beginShape();
      p.vertex(curtain.x, 0);
      p.vertex(curtain.x + 50, 0);
      p.vertex(curtain.x + 50 + waveOffset, 200);
      p.vertex(curtain.x + waveOffset, 200);
      p.endShape(p.CLOSE);
    }

    // Draw spotlights
