      light.angle += 0.01;
      light.intensity = 0.3 + 0.4 * (1 + p.sin(light.angle)) / 2;

      // Spotlight beam
      let gradient = p.drawingContext.createRadialGradient(
        light.x, light.y, 0,
        light.x, light.y + 200, 150
      );
      gradient.addColorStop(0, `rgba(255, 220, 100, ${light.intensity * 0.3})`);
      gradient.addColorStop(1, 'rgba(255, 220, 100, 0)');

      p.drawingContext.fillStyle = gradient;
      p.noStroke();
      p.ellipse(light.x, light.y + 100, 300, 200);

      // Spotlight source
      p.fill(255, 240, 150);
      p.ellipse(light.x, light.y, 20, 15);
    }

    // Draw comedy masks
    for(let mask of comedyMasks) {
      mask.rotation += 0.005;
      p.push();
      p.translate(mask.x, mask.y);
      p.rotate(p.sin(mask.rotation) * 0.2);

      // Mask face
      p.fill(255, 240, 200);
      p.stroke(200, 180, 100);
      p.strokeWeight(2);
      p.ellipse(0, 0, 40, 45);

      // Eyes
