      p.noStroke();
      p.ellipse(-8, -8, 6, 8);
      p.ellipse(8, -8, 6, 8);

      // Mouth
      if(mask.type === 'happy') {
        p.noFill();
        p.stroke(50);
        p.strokeWeight(3);
        p.arc(0, 5, 20, 15, 0, p.PI);
      } else {
        p.fill(50);
        p.noStroke();
        p.ellipse(0, 8, 25, 12);
      }
      p.pop();
    }

    // Draw applause meter
    applauseMeter = 0.3 + 0.4 * mouseInfluence + 0.2 * p.sin(p.frameCount * 0.05);
    p.stroke(100);
    p.strokeWeight(3);
    p.fill(40, 40, 50);
    p.rect(320, 350, 60, 150, 5);

    // Meter fill
