    let armAngle = p.sin(p.frameCount * 0.1) * 0.3;
    p.line(-25, 20, -45 + armAngle * 20, 10 + armAngle * 10);
    p.line(25, 20, 45 - armAngle * 20, 10 - armAngle * 10);

    // Head
