    // Speech bubbles from mentor
    p.fill(255, 240, 200, 200);
    p.stroke(200, 180, 100);
    p.strokeWeight(2);
    p.ellipse(200, mentorY - 50, 120, 60);
    p.fill(100, 200, 150);
    p.textAlign(p.CENTER);
    p.textSize(12);
    p.text('Welcome to\nLaugh Floor!', 200, mentorY - 55);

    // Draw trainee monster (smaller, eager)
    p.push();
    p.translate(280, traineeY + p.sin(p.frameCount * 0.08) * 3);

    // Body - more animated, nervous energy
    p.fill(200, 150, 255);
    p.stroke(180, 130, 235);
    p.strokeWeight(2);
