    p.noStroke();
    p.ellipse(-10, -18, 14, 16);
    p.ellipse(10, -18, 14, 16);
    p.fill(50);
    p.ellipse(-10, -16, 6, 8);
    p.ellipse(10, -16, 6, 8);

    // Mouth - attentive
    p.fill(100);
    p.ellipse(0, -5, 12, 8);
    p.pop();

    // Thought bubble from trainee
    p.fill(255, 250, 240, 180);
    p.stroke(220, 200, 150);
    p.strokeWeight(1);
    for(let i = 0; i < 3; i++) {
      let size = 15 - i * 3;
      p.ellipse(320 - i * 15, traineeY - 30 - i * 10, size, size);
    }
    p.ellipse(350, traineeY - 80, 80, 50);

    // Training manual/clipboard
    p.fill(255, 250, 240);
    p.stroke(150);
    p.strokeWeight(2);
    p.rect(40, 400, 80, 100, 3);
    p.fill(100);
    p.textAlign(p.LEFT);
    p.textSize(8);
    p.text('ORIENTATION\nDAY 1\n\nLaugh Protocol\n☐ Setup\n☐ Practice\n☐ Execute', 45, 420);

    // Microphone stand
    p.stroke(150);
    p.strokeWeight(6);
    p.line(200, 420, 200, 500);
    p.fill(80);
    p.ellipse(200, 415, 25, 30);

    // Particle system for sparkles/energy
    if(p.frameCount % 3 === 0) {
      particles.push({
        x: p.random(p.width),
        y: p.random(200, 400),
        vx: p.random(-1, 1),
        vy: p.random(-2, 0),
        life: 60,
        size: p.random(2, 6),
        color: p.random(['yellow', 'orange', 'pink'])
      });
    }

    for(let i = particles.length - 1; i >= 0; i--) {
      let part = particles[i];
      part.x += part.vx;
      part.y += part.vy;
      part.life--;

      let alpha = p.map(part.life, 0, 60, 0, 255);
      if(part.color === 'yellow') p.fill(255, 255, 100, alpha);
      else if(part.color === 'orange') p.fill(255, 150, 100, alpha);
      else p.fill(255, 100, 200, alpha);

      p.noStroke();
      p.ellipse(part.x, part.y, part.size, part.size);

      if(part.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Interactive glow effect around mouse
    if(p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      p.fill(255, 220, 100, 30);
      p.noStroke();
      p.ellipse(p.mouseX, p.mouseY, 100, 100);
    }
  };
}

function sketch(p) {
