      performanceMeters.push({
        x: 50 + i * 150,
        y: 450,
        value: p.random(0.7, 1.0),
        target: p.random(0.7, 1.0)
      });
    }

    // Initialize particles for energy
    for (let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        size: p.random(3, 8),
        hue: p.random(40, 60),
        life: 1.0
      });
    }
  };

  p.draw = function() {
