    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(35, 45, 85), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Stage curtains
    p.fill(120, 30, 40);
    p.noStroke();
    curtainOffset = p.sin(p.millis() * 0.001) * 5;

    // Left curtain
    p.beginShape();
    p.vertex(0, 0);
    p.vertex(60 + curtainOffset, 0);
    for (let y = 0; y <= p.height; y += 20) {
      let wave = p.sin(y * 0.02 + p.millis() * 0.003) * 8;
      p.vertex(60 + curtainOffset + wave, y);
    }
    p.vertex(0, p.height);
    p.endShape(p.CLOSE);

    // Right curtain
    p.beginShape();
    p.vertex(p.width, 0);
    p.vertex(340 - curtainOffset, 0);
    for (let y = 0; y <= p.height; y += 20) {
      let wave = p.sin(y * 0.02 + p.millis() * 0.003) * 8;
      p.vertex(340 - curtainOffset - wave, y);
    }
    p.vertex(p.width, p.height);
    p.endShape(p.CLOSE);

    // Background spotlights
    p.drawingContext.shadowBlur = 40;
    p.drawingContext.shadowColor = 'rgba(255, 220, 100, 0.3)';

    for (let light of spotlights) {
      let pulse = 0.8 + p.sin(p.millis() * 0.002 + light.x * 0.01) * 0.2;
      p.fill(255, 220, 100, light.intensity * pulse * 60);
      p.noStroke();
      p.ellipse(light.x, light.y, light.radius * pulse, light.radius * pulse * 1.5);
    }

    p.drawingContext.shadowBlur = 0;

    // Main performance area spotlight
    let mainPulse = 0.9 + p.sin(p.millis() * 0.003) * 0.1;
    applauseLevel = p.lerp(applauseLevel, p.map(p.mouseX, 0, p.width, 0.3, 1.0), 0.05);

    p.fill(255, 235, 150, 100 * mainPulse * applauseLevel);
    p.ellipse(mainSpotlight.x, mainSpotlight.y, mainSpotlight.radius * 2, mainSpotlight.radius * 2.5);

    // Central performer figure
    p.push();
    p.translate(200, 280);

    // Professional monster silhouette
    p.fill(80, 150, 200);
    p.stroke(255, 200);
    p.strokeWeight(2);

    // Body
    p.ellipse(0, 0, 80, 120);

    // Arms in performance gesture
    let armWave = p.sin(p.millis() * 0.004) * 0.3;
    p.push();
    p.rotate(-0.5 + armWave);
    p.ellipse(-30, -20, 15, 60);
    p.pop();

    p.push();
    p.rotate(0.5 - armWave);
    p.ellipse(30, -20, 15, 60);
    p.pop();

    // Head
    p.ellipse(0, -70, 50, 50);

    // Eyes with sparkle
    p.fill(255);
    p.ellipse(-10, -75, 12, 12);
    p.ellipse(10, -75, 12, 12);
    p.fill(50);
    p.ellipse(-8, -75, 6, 6);
    p.ellipse(12, -75, 6, 6);

    // Smile
    p.noFill();
    p.stroke(255);
    p.strokeWeight(3);
    p.arc(0, -60, 30, 20, 0, p.PI);

    p.pop();

    // Comedy/tragedy masks floating
    let maskFloat = p.sin(p.millis() * 0.002) * 10;

    // Comedy mask
    p.push();
    p.translate(120, 150 + maskFloat);
    p.rotate(p.sin(p.millis() * 0.001) * 0.1);
    p.fill(255, 215, 100, 200);
    p.stroke(200, 150, 50);
    p.strokeWeight(2);
    p.ellipse(0, 0, 40, 50);
    p.fill(50);
    p.ellipse(-8, -8, 6, 6);
    p.ellipse(8, -8, 6, 6);
    p.noFill();
    p.stroke(50);
    p.strokeWeight(3);
    p.arc(0, 5, 20, 15, 0, p.PI);
    p.pop();

    // Tragedy mask
    p.push();
    p.translate(280, 180 - maskFloat);
    p.rotate(p.sin(p.millis() * 0.001 + p.PI) * 0.1);
    p.fill(150, 180, 255, 200);
    p.stroke(100, 130, 200);
    p.strokeWeight(2);
    p.ellipse(0, 0, 40, 50);
    p.fill(50);
    p.ellipse(-8, -8, 6, 6);
    p.ellipse(8, -8, 6, 6);
    p.noFill();
    p.stroke(50);
    p.strokeWeight(3);
    p.arc(0, 15, 20, 15, p.PI, p.TWO_PI);
    p.pop();

    // Performance meters
    for (let i = 0; i < performanceMeters.length; i++) {
      let meter = performanceMeters[i];
      meter.value = p.lerp(meter.value, meter.target, 0.02);

      if (p.random() < 0.01) {
        meter.target = p.random(0.7, 1.0);
      }

      // Meter housing
      p.fill(60, 80, 120);
      p.stroke(100, 150, 200);
      p.strokeWeight(2);
      p.rect(meter.x - 25, meter.y - 40, 50, 80, 5);

      // Meter fill
      let meterHeight = meter.value * 70;
      p.fill(255, 200 + meter.value * 55, 100, 200);
      p.noStroke();
      p.rect(meter.x - 20, meter.y + 30 - meterHeight, 40, meterHeight, 2);

      // Meter labels
      p.fill(255, 200);
      p.textAlign(p.CENTER);
      p.textSize(10);
      let labels = ["JOY", "CRAFT", "PEAK"];
      p.text(labels[i], meter.x, meter.y + 55);
    }

    // Energy particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      // Update position
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 0.01;

      // Mouse attraction
      let dx = p.mouseX - particle.x;
      let dy = p.mouseY - particle.y;
      let dist = p.sqrt(dx * dx + dy * dy);
      if (dist < 100) {
        particle.vx += dx * 0.0001;
        particle.vy += dy * 0.0001;
      }

      // Wrap around edges
      if (particle.x < 0) particle.x = p.width;
      if (particle.x > p.width) particle.x = 0;
      if (particle.y < 0) particle.y = p.height;
      if (particle.y > p.height) particle.y = 0;

      // Draw particle
      p.push();
      p.colorMode(p.HSB);
      p.fill(particle.hue, 80, 100, particle.life);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size * particle.life, particle.size * particle.life);
      p.pop();

      // Remove dead particles
      if (particle.life <= 0) {
        particles.splice(i, 1);
        // Add new particle
        particles.push({
          x: p.random(p.width),
          y: p.random(p.height),
          vx: p.random(-1, 1),
          vy: p.random(-1, 1),
          size: p.random(3, 8),
          hue: p.random(40, 60),
          life: 1.0
        });
      }
    }

    // Microphone stand
    p.stroke(150);
    p.strokeWeight(3);
    p.line(200, 350, 200, 400);
    p.fill(100);
    p.ellipse(200, 340, 20, 30);
    p.fill(80);
    p.ellipse(200, 405, 30, 10);

    // Stage lights reflection
    p.stroke(255, 200, 100, 100);
    p.strokeWeight(1);
    for (let i = 0; i < 5; i++) {
      let x = 80 + i * 60;
      p.line(x, 520, x, 540 + p.sin(p.millis() * 0.003 + i) * 10);
    }
  };

  p.mousePressed = function() {
    // Add burst of particles on click
    for (let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-3, 3),
        vy: p.random(-3, 3),
        size: p.random(5, 12),
        hue: p.random(40, 60),
        life: 1.0
      });
    }
  };
}

function sketch(p) {
  let whistleblower;
  let spotlights = [];
  let particles = [];
  let applauseMeters = [];
  let documents = [];
  let curtainWave = 0;
  let revealProgress = 0;
  let glowIntensity = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize whistleblower figure
    whistleblower = {
      x: 200,
      y: 400,
      armAngle: 0,
      stepForward: 0
    };

    // Create spotlights
    for (let i = 0; i < 3; i++) {
      spotlights.push({
        x: 100 + i * 100,
        y: 50,
        intensity: p.random(0.5, 1),
        angle: p.random(-0.3, 0.3),
        targetAngle: 0
      });
    }

    // Create applause meters
    for (let i = 0; i < 2; i++) {
      applauseMeters.push({
        x: 50 + i * 300,
        y: 200,
        level: p.random(0.3, 0.8),
        targetLevel: 0.9
      });
    }

    // Initialize documents
    for (let i = 0; i < 5; i++) {
      documents.push({
        x: 180 + i * 8,
        y: 350 + i * 3,
        rotation: p.random(-0.2, 0.2),
        floatOffset: p.random(0, p.TWO_PI)
      });
    }

    // Create energy particles
    for (let i = 0; i < 50; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(2, 6),
        speed: p.random(0.5, 2),
        hue: p.random(40, 60),
        alpha: p.random(100, 255)
      });
    }
  };

  p.draw = function() {
    // Dynamic background gradient
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(20, 10, 60), p.color(80, 40, 20), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Update reveal progress based on mouse interaction
    let targetReveal = p.map(p.mouseX, 0, p.width, 0, 1);
    revealProgress += (targetReveal - revealProgress) * 0.05;

    // Draw stage curtains
    drawCurtains();

    // Draw spotlight beams
    drawSpotlights();

    // Draw energy particles
    drawParticles();

    // Draw applause meters
    drawApplauseMeters();

    // Draw the whistleblower figure
    drawWhistleblower();

    // Draw documents
    drawDocuments();

    // Draw comedy masks in background
    drawComedyMasks();

    // Update animation values
    curtainWave += 0.02;
    whistleblower.armAngle = p.sin(p.frameCount * 0.03) * 0.1;
    whistleblower.stepForward = p.map(revealProgress, 0, 1, 0, 20);
    glowIntensity = p.sin(p.frameCount * 0.05) * 50 + 200;
  };

  function drawCurtains() {
    p.fill(120, 20, 80, 180);
    p.noStroke();

    // Left curtain
    p.beginShape();
    for (let y = 0; y < p.height; y += 20) {
      let wave = p.sin(curtainWave + y * 0.01) * 10;
      p.vertex(wave + revealProgress * -100, y);
    }
    p.vertex(-100, p.height);
    p.vertex(-100, 0);
    p.endShape(p.CLOSE);

    // Right curtain
    p.beginShape();
    for (let y = 0; y < p.height; y += 20) {
      let wave = p.sin(curtainWave + y * 0.01) * -10;
      p.vertex(p.width + wave - revealProgress * -100, y);
    }
    p.vertex(p.width + 100, p.height);
    p.vertex(p.width + 100, 0);
    p.endShape(p.CLOSE);
  }

  function drawSpotlights() {
    for (let spotlight of spotlights) {
      // Update spotlight angle based on reveal
      spotlight.targetAngle = (p.mouseX - spotlight.x) * 0.001;
      spotlight.angle += (spotlight.targetAngle - spotlight.angle) * 0.1;

      // Spotlight beam
      p.push();
      p.translate(spotlight.x, spotlight.y);
      p.rotate(spotlight.angle);

      let beamColor = p.color(255, 220, 100, 60);
      p.fill(beamColor);
      p.noStroke();
      p.triangle(0, 0, -50, 400, 50, 400);

      // Spotlight source
      p.fill(255, 255, 150, glowIntensity);
      p.ellipse(0, 0, 20, 20);
      p.pop();
    }
  }

  function drawParticles() {
    for (let particle of particles) {
      particle.y -= particle.speed;
      if (particle.y < 0) particle.y = p.height;

      p.fill(particle.hue, 80, 90, particle.alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size, particle.size);

      // Add sparkle effect near mouse
      let distance = p.dist(particle.x, particle.y, p.mouseX, p.mouseY);
      if (distance < 50) {
        particle.size = p.lerp(particle.size, 8, 0.1);
        particle.alpha = p.lerp(particle.alpha, 255, 0.1);
      } else {
        particle.size = p.lerp(particle.size, 3, 0.1);
        particle.alpha = p.lerp(particle.alpha, 150, 0.1);
      }
    }
  }

  function drawApplauseMeters() {
    for (let meter of applauseMeters) {
      // Update meter level based on reveal progress
      meter.level += (revealProgress - meter.level) * 0.03;

      // Meter housing
      p.fill(60, 60, 80);
      p.stroke(200);
      p.strokeWeight(2);
      p.rect(meter.x - 20, meter.y, 40, 150, 5);

      // Meter fill
      let meterHeight = meter.level * 140;
      let meterColor = p.lerpColor(p.color(255, 100, 100), p.color(100, 255, 100), meter.level);
      p.fill(meterColor);
      p.noStroke();
      p.rect(meter.x - 15, meter.y + 145 - meterHeight, 30, meterHeight, 3);

      // Meter markings
      p.stroke(255);
      p.strokeWeight(1);
      for (let i = 0; i < 5; i++) {
        let markY = meter.y + 20 + i * 25;
        p.line(meter.x + 15, markY, meter.x + 25, markY);
      }
    }
  }

  function drawWhistleblower() {
    p.push();
    p.translate(whistleblower.x - whistleblower.stepForward, whistleblower.y);

    // Shadow
    p.fill(0, 0, 0, 100);
    p.noStroke();
    p.ellipse(0, 50, 60, 20);

    // Body
    p.fill(80, 150, 200);
    p.stroke(255);
    p.strokeWeight(2);
    p.ellipse(0, 0, 40, 80);

    // Head
    p.fill(150, 200, 150);
    p.ellipse(0, -50, 35, 35);

    // Eyes showing determination
    p.fill(255);
    p.noStroke();
    p.ellipse(-8, -55, 8, 8);
    p.ellipse(8, -55, 8, 8);
    p.fill(0);
    p.ellipse(-6, -55, 4, 4);
    p.ellipse(10, -55, 4, 4);

    // Mouth - determined expression
    p.stroke(0);
    p.strokeWeight(2);
    p.noFill();
    p.arc(0, -45, 15, 10, 0, p.PI);

    // Arm holding documents
    p.push();
    p.rotate(whistleblower.armAngle - 0.3);
    p.stroke(150, 200, 150);
    p.strokeWeight(6);
    p.line(0, -20, 30, -10);
    p.pop();

    // Other arm pointing forward
    p.push();
    p.rotate(-0.5 + whistleblower.armAngle);
    p.stroke(150, 200, 150);
    p.strokeWeight(6);
    p.line(0, -20, 35, 5);
    p.pop();

    // Legs in stepping pose
    p.stroke(80, 150, 200);
    p.strokeWeight(8);
    p.line(0, 30, -10, 70);
    p.line(0, 30, 15, 70);

    p.pop();
  }

  function drawDocuments() {
    for (let doc of documents) {
      p.push();
      p.translate(doc.x - whistleblower.stepForward * 0.8, doc.y + p.sin(p.frameCount * 0.02 + doc.floatOffset) * 2);
      p.rotate(doc.rotation + p.sin(p.frameCount * 0.01) * 0.1);

      // Document glow
      p.fill(255, 255, 100, 150);
      p.noStroke();
      p.rect(-12, -17, 24, 34, 2);

      // Document paper
      p.fill(255, 255, 200);
      p.stroke(200);
      p.strokeWeight(1);
      p.rect(-10, -15, 20, 30, 2);

      // Text lines
      p.stroke(100);
      p.strokeWeight(1);
      for (let i = 0; i < 6; i++) {
        p.line(-8, -10 + i * 4, 8, -10 + i * 4);
      }

      p.pop();
    }
  }

  function drawComedyMasks() {
    // Happy mask (background left)
    p.push();
    p.translate(80, 500);
    p.rotate(0.2);
    p.fill(255, 220, 100, 80 + revealProgress * 100);
    p.stroke(200, 150, 50);
    p.strokeWeight(3);
    p.ellipse(0, 0, 50, 60);

    // Happy face
    p.fill(0, 50);
    p.noStroke();
    p.ellipse(-10, -10, 8, 8);
    p.ellipse(10, -10, 8, 8);
    p.arc(0, 5, 25, 20, 0, p.PI);
    p.pop();

    // Sad mask (background right)
    p.push();
    p.translate(320, 500);
    p.rotate(-0.2);
    p.fill(100, 150, 255, 80 + revealProgress * 100);
    p.stroke(50, 100, 200);
    p.strokeWeight(3);
    p.ellipse(0, 0, 50, 60);

    // Sad face
    p.fill(0, 50);
    p.noStroke();
    p.ellipse(-10, -10, 8, 8);
    p.ellipse(10, -10, 8, 8);
    p.arc(0, 15, 25, 15, p.PI, p.TWO_PI);
    p.pop();
  }

  p.mousePressed = function() {
    // Create burst of particles on click
    for (let i = 0; i < 20; i++) {
      particles.push({
        x: p.mouseX + p.random(-50, 50),
        y: p.mouseY + p.random(-50, 50),
        size: p.random(3, 8),
        speed: p.random(1, 3),
        hue: p.random(40, 60),
        alpha: 255
      });
    }
  };
}

function sketch(p) {
  let spotlights = [];
  let particles = [];
  let oldStructures = [];
  let newStructures = [];
  let leader;
  let followers = [];
  let applauseMeters = [];
  let curtainOffset = 0;
  let lightIntensity = 1.0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.RGB, 255);

    // Initialize spotlights
    for (let i = 0; i < 4; i++) {
      spotlights.push({
        x: p.random(100, 300),
        y: p.random(50, 150),
        angle: p.random(0, p.TWO_PI),
        intensity: p.random(0.7, 1.0)
      });
    }

    // Initialize old structures (broken/fading)
    for (let i = 0; i < 6; i++) {
      oldStructures.push({
        x: p.random(50, 350),
        y: p.random(400, 550),
        width: p.random(20, 40),
        height: p.random(30, 60),
        decay: p.random(0.3, 0.7)
      });
    }

    // Initialize new structures (building up)
    for (let i = 0; i < 8; i++) {
      newStructures.push({
        x: p.random(80, 320),
        y: p.random(350, 500),
        width: p.random(25, 45),
        height: p.random(40, 80),
        growth: p.random(0.2, 0.8),
        targetHeight: p.random(60, 100)
      });
    }

    // Initialize leader
    leader = {
      x: 200,
      y: 280,
      armAngle: 0,
      bobOffset: 0
    };

    // Initialize followers
    for (let i = 0; i < 5; i++) {
      followers.push({
        x: p.random(100, 300),
        y: p.random(320, 400),
        bobOffset: p.random(0, p.TWO_PI),
        enthusiasm: p.random(0.5, 1.0)
      });
    }

    // Initialize applause meters
    for (let i = 0; i < 3; i++) {
      applauseMeters.push({
        x: 50 + i * 150,
        y: 100,
        level: p.random(0.4, 0.9),
        targetLevel: p.random(0.6, 1.0)
      });
    }
  };

  p.draw = function() {
    // Background with stage atmosphere
    p.background(20, 10, 40);

    // Stage curtains
    curtainOffset = p.sin(p.millis() * 0.002) * 10;
    p.fill(120, 20, 40, 200);
    p.rect(-10, 0, 80 + curtainOffset, 600);
    p.rect(330 - curtainOffset, 0, 80, 600);

    // Spotlight beams
    lightIntensity = 0.8 + p.sin(p.millis() * 0.003) * 0.2;
    for (let spot of spotlights) {
      spot.angle += 0.01;

      // Beam gradient
      for (let r = 120; r > 0; r -= 10) {
        let alpha = (120 - r) * 2 * lightIntensity * spot.intensity;
        p.fill(255, 220, 100, alpha);
        p.noStroke();
        p.ellipse(spot.x, spot.y, r * 2);
      }

      // Beam direction
      p.stroke(255, 240, 150, 100);
      p.strokeWeight(3);
      let beamX = spot.x + p.cos(spot.angle) * 200;
      let beamY = spot.y + p.sin(spot.angle) * 200;
      p.line(spot.x, spot.y, beamX, beamY);
    }

    // Applause meters
    for (let meter of applauseMeters) {
      meter.level = p.lerp(meter.level, meter.targetLevel, 0.02);
      if (p.random() < 0.01) {
        meter.targetLevel = p.random(0.4, 1.0);
      }

      // Meter frame
      p.stroke(200, 180, 100);
      p.strokeWeight(2);
      p.fill(40, 30, 20);
      p.rect(meter.x - 15, meter.y, 30, 60);

      // Meter fill
      let fillHeight = meter.level * 55;
      p.fill(255, 220 - meter.level * 100, 100 - meter.level * 80);
      p.noStroke();
      p.rect(meter.x - 12, meter.y + 57 - fillHeight, 24, fillHeight);

      // Meter label
      p.fill(200, 180, 100);
      p.textAlign(p.CENTER);
      p.textSize(8);
      p.text("JOY", meter.x, meter.y + 75);
    }

    // Old structures (decaying)
    for (let structure of oldStructures) {
      p.fill(80 * structure.decay, 60 * structure.decay, 40 * structure.decay, 150);
      p.stroke(100 * structure.decay, 80 * structure.decay, 60 * structure.decay);
      p.strokeWeight(1);
      p.rect(structure.x, structure.y, structure.width, structure.height);

      // Decay effect
      if (p.random() < 0.02) {
        particles.push({
          x: structure.x + p.random(structure.width),
          y: structure.y,
          vx: p.random(-1, 1),
          vy: p.random(-3, -1),
          life: 60,
          color: [100, 80, 60]
        });
      }
    }

    // New structures (growing)
    for (let structure of newStructures) {
      if (structure.height < structure.targetHeight) {
        structure.height = p.lerp(structure.height, structure.targetHeight, 0.01);
      }

      let brightness = 100 + structure.growth * 155;
      p.fill(brightness, brightness * 0.8, brightness * 0.4, 200);
      p.stroke(255, 220, 100);
      p.strokeWeight(2);
      p.rect(structure.x, structure.y + structure.targetHeight - structure.height, 
             structure.width, structure.height);

      // Construction sparkles
      if (p.random() < 0.05) {
        particles.push({
          x: structure.x + p.random(structure.width),
          y: structure.y + structure.targetHeight - structure.height,
          vx: p.random(-2, 2),
          vy: p.random(-2, 0),
          life: 40,
          color: [255, 220, 100]
        });
      }
    }

    // Leader figure
    leader.armAngle += 0.05;
    leader.bobOffset += 0.03;
    let bobY = p.sin(leader.bobOffset) * 5;

    // Leader body
    p.fill(100, 200, 255);
    p.stroke(80, 160, 200);
    p.strokeWeight(2);
    p.ellipse(leader.x, leader.y + bobY, 40, 60);

    // Leader head
    p.fill(120, 220, 255);
    p.ellipse(leader.x, leader.y - 35 + bobY, 30, 30);

    // Leader arms (gesturing)
    p.stroke(100, 200, 255);
    p.strokeWeight(6);
    let armX = leader.x + p.cos(leader.armAngle) * 25;
    let armY = leader.y - 10 + p.sin(leader.armAngle) * 15 + bobY;
    p.line(leader.x - 15, leader.y - 10 + bobY, armX, armY);
    p.line(leader.x + 15, leader.y - 10 + bobY, leader.x + 30, leader.y - 20 + bobY);

    // Followers
    for (let follower of followers) {
      follower.bobOffset += 0.02 * follower.enthusiasm;
      let fBobY = p.sin(follower.bobOffset) * 3;

      p.fill(80 + follower.enthusiasm * 100, 150 + follower.enthusiasm * 80, 200);
      p.stroke(60, 120, 160);
      p.strokeWeight(1);
      p.ellipse(follower.x, follower.y + fBobY, 25, 35);
      p.ellipse(follower.x, follower.y - 20 + fBobY, 20, 20);

      // Follower enthusiasm particles
      if (p.random() < follower.enthusiasm * 0.02) {
        particles.push({
          x: follower.x,
          y: follower.y - 25 + fBobY,
          vx: p.random(-1, 1),
          vy: p.random(-3, -1),
          life: 30,
          color: [255, 200, 100]
        });
      }
    }

    // Comedy masks in background
    p.fill(255, 220, 100, 100);
    p.noStroke();
    p.ellipse(80, 200, 40, 50);
    p.ellipse(320, 180, 40, 50);
    p.fill(50, 30, 20, 150);
    // Happy mask
    p.arc(80, 205, 20, 15, 0, p.PI);
    p.ellipse(75, 195, 4, 6);
    p.ellipse(85, 195, 4, 6);
    // Sad mask
    p.arc(320, 190, 20, 15, p.PI, p.TWO_PI);
    p.ellipse(315, 175, 4, 6);
    p.ellipse(325, 175, 4, 6);

    // Particles system
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life--;

      p.fill(particle.color[0], particle.color[1], particle.color[2], 
             particle.life * 4);
      p.noStroke();
      p.ellipse(particle.x, particle.y, 6, 6);

      if (particle.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Interactive microphone (follows mouse)
    let micX = p.lerp(200, p.mouseX, 0.1);
    let micY = p.lerp(150, p.mouseY, 0.1);

    p.stroke(180, 160, 120);
    p.strokeWeight(4);
    p.line(micX, micY, micX, micY + 40);
    p.fill(200, 180, 140);
    p.ellipse(micX, micY - 10, 20, 25);

    // Sound waves from microphone
    if (p.dist(p.mouseX, p.mouseY, micX, micY) < 50) {
      for (let r = 20; r < 80; r += 20) {
        p.stroke(255, 220, 100, 150 - r);
        p.strokeWeight(2);
        p.noFill();
        p.ellipse(micX, micY - 10, r, r);
      }
    }
  };

  p.mousePressed = function() {
    // Create burst of joy particles when clicked
    for (let i = 0; i < 15; i++) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-5, 5),
        vy: p.random(-8, -2),
        life: 60,
        color: [255, p.random(180, 255), p.random(50, 150)]
      });
    }

    // Boost applause meters
    for (let meter of applauseMeters) {
      meter.targetLevel = p.min(1.0, meter.targetLevel + 0.2);
    }
  };
}

function sketch(p) {
  let sparkle;
  let particles = [];
  let doorOpen = 0;
  let targetDoorOpen = 0;
  let heartPulse = 0;
  let photos = [];
  let toys = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    sparkle = {
      x: 200,
      y: 300,
      brightness: 0,
      targetBrightness: 255
    };

    // Create scattered photos and toys
    for(let i = 0; i < 5; i++) {
      photos.push({
        x: p.random(50, 350),
        y: p.random(400, 550),
        rotation: p.random(-0.3, 0.3),
        size: p.random(30, 50)
      });
    }

    for(let i = 0; i < 3; i++) {
      toys.push({
        x: p.random(60, 340),
        y: p.random(450, 580),
        type: p.floor(p.random(3))
      });
    }
  };

  p.draw = function() {
    // Dark background with subtle gradient
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 10, 25), p.color(35, 25, 45), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Door crack effect
    let mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);
    targetDoorOpen = p.constrain(mouseInfluence * 80, 0, 80);
    doorOpen = p.lerp(doorOpen, targetDoorOpen, 0.02);

    // Draw door frame
    p.fill(45, 35, 25);
    p.noStroke();
    p.rect(150, 150, 100, 200);

    // Door crack with warm light
    if(doorOpen > 5) {
      let warmGlow = p.color(255, 200, 150, 180);
      p.fill(warmGlow);
      p.rect(200, 150, doorOpen, 200);

      // Light rays from crack
      for(let i = 0; i < 5; i++) {
        let rayAlpha = p.map(doorOpen, 0, 80, 0, 150);
        p.stroke(255, 220, 180, rayAlpha - i * 20);
        p.strokeWeight(2);
        let rayX = 200 + doorOpen/2;
        p.line(rayX, 250 + i * 20, rayX + 50 + i * 10, 250 + i * 20);
      }
    }

    // Central spark/heart
    heartPulse += 0.1;
    let pulseSize = 15 + p.sin(heartPulse) * 5;

    // Spark glow
    for(let r = 60; r > 0; r -= 10) {
      let alpha = p.map(r, 0, 60, 255, 0);
      p.fill(255, 150, 100, alpha * 0.3);
      p.noStroke();
      p.ellipse(sparkle.x, sparkle.y, r, r);
    }

    // Core spark
    p.fill(255, 200, 150);
    p.noStroke();
    p.ellipse(sparkle.x, sparkle.y, pulseSize, pulseSize);

    // Floating heart particles
    if(p.frameCount % 20 === 0 && doorOpen > 20) {
      particles.push({
        x: sparkle.x + p.random(-30, 30),
        y: sparkle.y + p.random(-20, 20),
        vx: p.random(-1, 1),
        vy: p.random(-2, -0.5),
        life: 255,
        size: p.random(3, 8)
      });
    }

    // Update and draw particles
    for(let i = particles.length - 1; i >= 0; i--) {
      let part = particles[i];
      part.x += part.vx;
      part.y += part.vy;
      part.life -= 3;

      p.fill(255, 180, 120, part.life);
      p.noStroke();

      // Draw small hearts
      let x = part.x;
      let y = part.y;
      let s = part.size;

      p.ellipse(x - s/4, y - s/4, s/2, s/2);
      p.ellipse(x + s/4, y - s/4, s/2, s/2);
      p.triangle(x - s/2, y, x + s/2, y, x, y + s/2);

      if(part.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Scattered photos (polaroid style)
    for(let photo of photos) {
      p.push();
      p.translate(photo.x, photo.y);
      p.rotate(photo.rotation);

      p.fill(240, 235, 220);
      p.stroke(200, 190, 180);
      p.strokeWeight(1);
      p.rect(-photo.size/2, -photo.size/2, photo.size, photo.size * 1.2);

      p.fill(180, 160, 140);
      p.noStroke();
      p.rect(-photo.size/2 + 3, -photo.size/2 + 3, photo.size - 6, photo.size - 6);
      p.pop();
    }

    // Scattered toys
    for(let toy of toys) {
      p.push();
      p.translate(toy.x, toy.y);

      if(toy.type === 0) {
        // Building blocks
        p.fill(200, 100, 80);
        p.noStroke();
        p.rect(-8, -8, 16, 16);
        p.fill(220, 120, 100);
        p.rect(-6, -6, 12, 12);
      } else if(toy.type === 1) {
        // Ball
        p.fill(100, 180, 120);
        p.noStroke();
        p.ellipse(0, 0, 20, 20);
        p.stroke(80, 160, 100);
        p.strokeWeight(2);
        p.noFill();
        p.arc(0, 0, 20, 20, 0, p.PI);
      } else {
        // Crayon
        p.fill(200, 80, 100);
        p.noStroke();
        p.rect(-2, -10, 4, 20);
        p.fill(240, 200, 180);
        p.rect(-3, 8, 6, 4);
      }
      p.pop();
    }

    // Soft lamp glow in corner
    p.fill(255, 200, 120, 30);
    p.noStroke();
    for(let r = 100; r > 0; r -= 20) {
      let alpha = p.map(r, 0, 100, 40, 0);
      p.fill(255, 200, 120, alpha);
      p.ellipse(350, 100, r, r);
    }
  };

  p.mousePressed = function() {
    // Create burst of heart particles on click
    for(let i = 0; i < 8; i++) {
      particles.push({
        x: sparkle.x,
        y: sparkle.y,
        vx: p.cos(i * p.TWO_PI / 8) * 2,
        vy: p.sin(i * p.TWO_PI / 8) * 2,
        life: 255,
        size: p.random(5, 12)
      });
    }
  };
}

function sketch(p) {
  let particles = [];
  let doorAngle = 0;
  let heartBeat = 0;
  let warmGlow = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create floating heart particles
    for(let i = 0; i < 25; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(3, 8),
        speed: p.random(0.5, 1.5),
        opacity: p.random(100, 200),
        hue: p.random(320, 40)
      });
    }
  };

  p.draw = function() {
    // Warm gradient background - sunset/sunrise colors
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(255, 180, 120), p.color(120, 80, 150), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    heartBeat += 0.08;
    warmGlow += 0.05;
    doorAngle += 0.02;

    // Mouse influence for interactive glow
    let distFromCenter = p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2);
    mouseInfluence = p.map(distFromCenter, 0, 300, 1.5, 0.3);

    // Central warm glow
    p.push();
    p.translate(p.width/2, p.height/2);
    p.noFill();
    for(let r = 200; r > 0; r -= 10) {
      let alpha = p.map(r, 0, 200, 80, 0) * mouseInfluence;
      p.stroke(255, 200 + p.sin(warmGlow) * 30, 150, alpha);
      p.strokeWeight(2);
      p.ellipse(0, 0, r, r);
    }
    p.pop();

    // Two paths/doors - left and right
    // Left door - cool blues (logic/fear path)
    p.push();
    p.translate(120, 280);
    p.rotate(p.sin(doorAngle) * 0.1);
    p.fill(100, 150, 200, 180);
    p.stroke(80, 120, 180);
    p.strokeWeight(3);
    p.rect(-40, -80, 80, 160, 10);

    // Door handle
    p.fill(255, 220, 100);
    p.noStroke();
    p.ellipse(25, 0, 8, 8);

    // Cool path extending from door
    p.stroke(100, 150, 200, 100);
    p.strokeWeight(20);
    p.line(0, 80, -30, 180);
    p.pop();

    // Right door - warm oranges/pinks (heart path)
    p.push();
    p.translate(280, 280);
    p.rotate(-p.sin(doorAngle) * 0.1);
    p.fill(220, 120, 100, 180);
    p.stroke(200, 100, 80);
    p.strokeWeight(3);
    p.rect(-40, -80, 80, 160, 10);

    // Door handle
    p.fill(255, 220, 100);
    p.noStroke();
    p.ellipse(-25, 0, 8, 8);

    // Warm path extending from door
    p.stroke(220, 120, 100, 100);
    p.strokeWeight(20);
    p.line(0, 80, 30, 180);
    p.pop();

    // Two figures - Sulley and Boo silhouettes
    // Sulley (left figure)
    p.push();
    p.translate(120, 200);
    p.fill(80, 120, 180, 150 + p.sin(heartBeat) * 30);
    p.noStroke();
    p.ellipse(0, 0, 60, 80);
    p.ellipse(-15, -25, 20, 20);
    p.ellipse(15, -25, 20, 20);
    p.pop();

    // Boo (right figure) 
    p.push();
    p.translate(280, 220);
    p.fill(255, 180, 200, 150 + p.sin(heartBeat + 1) * 30);
    p.noStroke();
    p.ellipse(0, 0, 35, 50);
    p.ellipse(0, -15, 25, 25);
    p.pop();

    // Connection line between figures (heart bond)
    p.stroke(255, 150, 180, 100 + p.sin(heartBeat) * 50);
    p.strokeWeight(3);
    p.line(120, 200, 280, 220);

    // Floating particles
    for(let particle of particles) {
      particle.y -= particle.speed;
      particle.x += p.sin(p.frameCount * 0.01 + particle.y * 0.01) * 0.5;

      if(particle.y < -10) particle.y = p.height + 10;
      if(particle.x < -10) particle.x = p.width + 10;
      if(particle.x > p.width + 10) particle.x = -10;

      p.push();
      p.translate(particle.x, particle.y);
      p.rotate(p.frameCount * 0.02);
      p.noStroke();
      p.fill(particle.hue, 150, 255, particle.opacity);

      // Heart shape
      p.beginShape();
      for(let a = 0; a < p.TWO_PI; a += 0.1) {
        let r = particle.size * (13 * p.cos(a) - 5 * p.cos(2 * a) - 2 * p.cos(3 * a) - p.cos(4 * a)) * 0.05;
        let x = r * p.cos(a);
        let y = r * p.sin(a);
        p.vertex(x, -y);
      }
      p.endShape(p.CLOSE);
      p.pop();
    }

    // Home artifacts scattered around
    // Photo frames
    p.fill(139, 69, 19, 200);
    p.stroke(101, 67, 33);
    p.strokeWeight(2);
    p.rect(50, 450, 60, 80, 5);
    p.rect(290, 480, 60, 70, 5);

    // Toy blocks
    p.fill(255, 100, 100, 180);
    p.noStroke();
    p.rect(340, 520, 25, 25, 3);
    p.fill(100, 255, 100, 180);
    p.rect(30, 500, 30, 20, 3);

    // Interactive glow on mouse hover
    if(p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      p.push();
      p.translate(p.mouseX, p.mouseY);
      p.noFill();
      p.stroke(255, 200, 150, 80);
      p.strokeWeight(2);
      for(let r = 20; r > 0; r -= 5) {
        p.ellipse(0, 0, r + p.sin(p.frameCount * 0.1) * 5, r + p.sin(p.frameCount * 0.1) * 5);
      }
      p.pop();
    }
  };

  p.mousePressed = function() {
    // Create burst of hearts on click
    for(let i = 0; i < 8; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        size: p.random(4, 12),
        speed: p.random(1, 3),
        opacity: 255,
        hue: p.random(320, 40)
      });
    }
  };
}

function sketch(p) {
  let connections = [];
  let figures = [];
  let particles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create three main figures in triangular formation
    figures.push({
      x: 200, y: 180,
      size: 60,
      color: p.color(255, 180, 100),
      bobOffset: 0
    });
    figures.push({
      x: 150, y: 300,
      size: 55,
      color: p.color(100, 200, 255),
      bobOffset: p.PI / 3
    });
    figures.push({
      x: 250, y: 300,
      size: 58,
      color: p.color(255, 150, 200),
      bobOffset: 2 * p.PI / 3
    });

    // Initialize connection lines between figures
    for(let i = 0; i < figures.length; i++) {
      for(let j = i + 1; j < figures.length; j++) {
        connections.push({
          from: i,
          to: j,
          strength: 0,
          maxStrength: p.random(0.6, 1.0),
          pulse: p.random(0, p.TWO_PI)
        });
      }
    }
  };

  p.draw = function() {
    // Warm gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(255, 200, 150), p.color(255, 150, 100), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    time += 0.02;

    // Draw soft ambient lighting
    p.push();
    p.drawingContext.globalCompositeOperation = 'screen';
    for(let i = 0; i < 3; i++) {
      let x = p.width * (0.3 + i * 0.2);
      let y = p.height * 0.4;
      let size = 150 + 50 * p.sin(time + i);
      let alpha = 0.1 + 0.05 * p.sin(time * 0.5 + i);

      p.fill(255, 220, 180, alpha * 255);
      p.noStroke();
      p.ellipse(x, y, size, size);
    }
    p.pop();

    // Update and draw connection strength
    for(let conn of connections) {
      conn.strength += 0.02;
      if(conn.strength > conn.maxStrength) {
        conn.strength = conn.maxStrength;
      }
      conn.pulse += 0.1;
    }

    // Draw connection lines with pulsing energy
    p.strokeWeight(3);
    for(let conn of connections) {
      let fig1 = figures[conn.from];
      let fig2 = figures[conn.to];

      let alpha = conn.strength * (0.6 + 0.4 * p.sin(conn.pulse));
      p.stroke(255, 200, 100, alpha * 255);

      // Curved connection line
      let midX = (fig1.x + fig2.x) / 2;
      let midY = (fig1.y + fig2.y) / 2 - 30;

      p.noFill();
      p.beginShape();
      p.vertex(fig1.x, fig1.y);
      p.quadraticVertex(midX, midY, fig2.x, fig2.y);
      p.endShape();

      // Energy particles along connections
      if(p.random() < 0.3) {
        let t = p.random();
        let px = p.lerp(fig1.x, midX, t);
        let py = p.lerp(fig1.y, midY, t);
        if(t > 0.5) {
          px = p.lerp(midX, fig2.x, (t - 0.5) * 2);
          py = p.lerp(midY, fig2.y, (t - 0.5) * 2);
        }

        particles.push({
          x: px, y: py,
          vx: p.random(-1, 1),
          vy: p.random(-1, 1),
          life: 30,
          maxLife: 30,
          color: p.color(255, 220, 150)
        });
      }
    }

    // Update and draw particles
    for(let i = particles.length - 1; i >= 0; i--) {
      let part = particles[i];
      part.x += part.vx;
      part.y += part.vy;
      part.life--;

      if(part.life <= 0) {
        particles.splice(i, 1);
        continue;
      }

      let alpha = p.map(part.life, 0, part.maxLife, 0, 1);
      p.fill(p.red(part.color), p.green(part.color), p.blue(part.color), alpha * 200);
      p.noStroke();
      p.ellipse(part.x, part.y, 4, 4);
    }

    // Draw figures with gentle bobbing motion
    for(let i = 0; i < figures.length; i++) {
      let fig = figures[i];
      let bobY = fig.y + 5 * p.sin(time + fig.bobOffset);

      // Glow effect
      p.push();
      p.drawingContext.globalCompositeOperation = 'screen';
      p.fill(p.red(fig.color), p.green(fig.color), p.blue(fig.color), 50);
      p.noStroke();
      p.ellipse(fig.x, bobY, fig.size + 20, fig.size + 20);
      p.pop();

      // Main figure
      p.fill(fig.color);
      p.stroke(255, 255, 255, 150);
      p.strokeWeight(2);
      p.ellipse(fig.x, bobY, fig.size, fig.size);

      // Simple face
      p.fill(255, 255, 255, 200);
      p.noStroke();
      p.ellipse(fig.x - fig.size * 0.15, bobY - fig.size * 0.1, 8, 8);
      p.ellipse(fig.x + fig.size * 0.15, bobY - fig.size * 0.1, 8, 8);

      // Happy mouth
      p.stroke(255, 255, 255, 200);
      p.strokeWeight(2);
      p.noFill();
      p.arc(fig.x, bobY + fig.size * 0.1, 15, 10, 0, p.PI);
    }

    // Add scattered heart symbols
    p.fill(255, 150, 150, 100 + 50 * p.sin(time * 2));
    p.noStroke();
    for(let i = 0; i < 5; i++) {
      let heartX = 50 + i * 80;
      let heartY = 450 + 20 * p.sin(time + i);
      drawHeart(heartX, heartY, 12);
    }

    // Interactive glow around mouse
    let mouseDistance = p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2);
    if(mouseDistance < 200) {
      p.push();
      p.drawingContext.globalCompositeOperation = 'screen';
      let glowSize = p.map(mouseDistance, 0, 200, 100, 20);
      p.fill(255, 200, 150, 30);
      p.noStroke();
      p.ellipse(p.mouseX, p.mouseY, glowSize, glowSize);
      p.pop();
    }
  };

  function drawHeart(x, y, size) {
    p.push();
    p.translate(x, y);
    p.scale(size / 20);
    p.beginShape();
    p.vertex(0, 5);
    p.bezierVertex(-10, -5, -20, 5, 0, 20);
    p.bezierVertex(20, 5, 10, -5, 0, 5);
    p.endShape(p.CLOSE);
    p.pop();
  }

  p.mousePressed = function() {
    // Add burst of particles on click
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-3, 3),
        vy: p.random(-3, 3),
        life: 60,
        maxLife: 60,
        color: p.color(255, p.random(150, 250), p.random(100, 200))
      });
    }

    // Strengthen connections temporarily
    for(let conn of connections) {
      conn.maxStrength = p.min(1.0, conn.maxStrength + 0.2);
    }
  };
}

