      p.line(0, i, p.width, i);
    }

    // Soft ambient glow that responds to mouse
    warmGlow = p.lerp(warmGlow, p.map(p.mouseY, 0, p.height, 50, 150), 0.05);

    // Draw soft circular glow in center
    p.push();
    p.drawingContext.shadowBlur = 100;
    p.drawingContext.shadowColor = p.color(255, 220, 180, warmGlow);
    p.fill(255, 220, 180, warmGlow * 0.3);
    p.noStroke();
    p.ellipse(p.width/2, p.height/2, 200, 200);
    p.pop();

    // Draw floating memory photos
    p.push();
    for(let photo of photos) {
      p.push();
      p.translate(photo.x, photo.y + p.sin(p.millis() * 0.001 + photo.floatOffset) * 10);
      p.rotate(photo.rotation + p.sin(p.millis() * 0.0005) * 0.2);

      // Photo frame
      p.fill(255, 240, 220, 200);
      p.stroke(139, 90, 43, 150);
      p.strokeWeight(3);
      p.rect(-photo.size/2, -photo.size/2, photo.size, photo.size);

      // Photo content (abstract memory)
      p.fill(photo.color);
      p.noStroke();
      p.rect(-photo.size/2 + 5, -photo.size/2 + 5, photo.size - 10, photo.size - 10);

      // Gentle sparkle
      if(p.random() < 0.1) {
        p.fill(255, 255, 200, 180);
        p.ellipse(p.random(-photo.size/3, photo.size/3), p.random(-photo.size/3, photo.size/3), 3, 3);
      }
      p.pop();
    }
    p.pop();

    // Draw foundation that grows with mouse proximity
    let mouseDistance = p.dist(p.mouseX, p.mouseY, p.width/2, 500);
    foundationHeight = p.lerp(foundationHeight, p.map(mouseDistance, 0, 200, 30, 10), 0.1);

    p.fill(139, 90, 43, 180);
    p.stroke(101, 67, 33);
    p.strokeWeight(2);
    p.rect(60, 520, 280, foundationHeight);

    // Draw the four pillars with gentle glow
    for(let i = 0; i < pillars.length; i++) {
      let pillar = pillars[i];
      let distance = p.dist(p.mouseX, p.mouseY, pillar.x + pillar.width/2, pillar.y);
      pillar.glow = p.lerp(pillar.glow, p.map(distance, 0, 100, 80, 20), 0.1);

      // Pillar glow
      p.push();
      p.drawingContext.shadowBlur = pillar.glow;
      p.drawingContext.shadowColor = p.color(255, 180, 100, pillar.glow);
      p.fill(pillar.color);
      p.stroke(101, 67, 33);
      p.strokeWeight(2);
      p.rect(pillar.x, pillar.y, pillar.width, pillar.height);
      p.pop();

      // Roman numeral on each pillar
      p.fill(255, 240, 220, 200);
      p.textAlign(p.CENTER);
      p.textSize(16);
      p.text(['I', 'II', 'III', 'IV'][i], pillar.x + pillar.width/2, pillar.y + pillar.height/2);
    }

    // Draw walls that build over time
    p.stroke(139, 90, 43, 120);
    p.strokeWeight(8);
    for(let wall of walls) {
      wall.progress = p.min(wall.progress + 0.01, 1);
      wall.opacity = p.lerp(wall.opacity, wall.progress * 120, 0.05);

      let endX = p.lerp(wall.x1, wall.x2, wall.progress);
      let endY = p.lerp(wall.y1, wall.y2, wall.progress);

      p.stroke(139, 90, 43, wall.opacity);
      p.line(wall.x1, wall.y1, endX, endY);
    }

    // Draw playful toys/artifacts
    for(let toy of toys) {
      let bounce = p.sin(p.millis() * 0.003 + toy.bounceOffset) * 5;

      p.push();
      p.translate(toy.x, toy.y + bounce);
      p.fill(toy.color);
      p.noStroke();

      if(toy.shape === 0) {
        // Circle toy
        p.ellipse(0, 0, toy.size, toy.size);
      } else if(toy.shape === 1) {
        // Square building block
        p.rect(-toy.size/2, -toy.size/2, toy.size, toy.size);
      } else {
        // Triangle toy
        p.triangle(-toy.size/2, toy.size/2, toy.size/2, toy.size/2, 0, -toy.size/2);
      }
      p.pop();
    }

    // Draw and update warm particles
    for(let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= particle.fadeRate;

      if(particle.life <= 0 || particle.x < 0 || particle.x > p.width || particle.y < 0 || particle.y > p.height) {
        particle.x = p.random(p.width);
        particle.y = p.random(p.height);
        particle.life = 255;
        particle.vx = p.random(-0.5, 0.5);
        particle.vy = p.random(-0.5, 0.5);
      }

      p.fill(255, 200, 150, particle.life);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size, particle.size);
    }

    // Interactive heart connections on mouse movement
    if(p.mouseIsPressed) {
      p.stroke(255, 150, 150, 100);
      p.strokeWeight(2);
      for(let i = 0; i < 4; i++) {
        p.line(p.mouseX, p.mouseY, pillars[i].x + pillars[i].width/2, pillars[i].y + pillars[i].height/2);
      }

      // Add extra particles near mouse
      if(p.random() < 0.3) {
        particles.push({
          x: p.mouseX + p.random(-20, 20),
          y: p.mouseY + p.random(-20, 20),
          vx: p.random(-1, 1),
          vy: p.random(-1, 1),
          size: p.random(3, 8),
          life: 255,
          fadeRate: p.random(2, 4)
        });
      }
    }

    // Gentle organic border
    p.stroke(139, 90, 43, 100);
    p.strokeWeight(6);
    p.noFill();
    p.rect(10, 10, p.width-20, p.height-20, 15);
  };
}

function sketch(p) {
  let crack = [];
  let toys = [];
  let photos = [];
  let glowParticles = [];
  let crackProgress = 0;
  let lightBeam = 0;
  let warmColors = [];

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 1);

    warmColors = [
      p.color(30, 80, 95),   // warm orange
      p.color(45, 85, 90),   // golden
      p.color(15, 90, 85),   // deep orange
      p.color(60, 70, 95),   // warm yellow
      p.color(350, 60, 90)   // warm pink
    ];

    // Generate organic crack path
    crack.push({x: 50, y: 300});
    let currentX = 50;
    let currentY = 300;

    for(let i = 0; i < 80; i++) {
      currentX += p.random(3, 8);
      currentY += p.random(-15, 15);
      currentY = p.constrain(currentY, 100, 500);
      crack.push({x: currentX, y: currentY});
    }

    // Scattered toys and photos
    for(let i = 0; i < 6; i++) {
      toys.push({
        x: p.random(50, 350),
        y: p.random(400, 550),
        size: p.random(15, 30),
        rotation: p.random(p.TWO_PI),
        bobOffset: p.random(p.TWO_PI),
        type: p.floor(p.random(3))
      });
    }

    for(let i = 0; i < 4; i++) {
      photos.push({
        x: p.random(60, 300),
        y: p.random(80, 200),
        w: p.random(40, 60),
        h: p.random(30, 45),
        rotation: p.random(-0.3, 0.3),
        shimmer: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    // Gradient background - cozy interior
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(220, 30, 25), p.color(280, 40, 15), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Soft ambient lighting
    p.push();
    p.blendMode(p.SCREEN);
    let glowAlpha = 0.1 + 0.05 * p.sin(p.millis() * 0.002);
    p.fill(45, 60, 90, glowAlpha);
    p.noStroke();
    p.ellipse(300, 150, 200, 150);
    p.fill(30, 70, 85, glowAlpha * 0.7);
    p.ellipse(100, 450, 180, 120);
    p.pop();

    // Draw cozy room elements
    drawPhotos();
    drawToys();

    // Animated crack progress
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, 200, 300) < 100 ? 0.02 : 0.005;
    crackProgress = p.min(crackProgress + mouseInfluence, crack.length - 1);

    // Draw the transformative crack
    drawCrack();

    // Light beam through crack
    if(crackProgress > crack.length * 0.6) {
      drawLightBeam();
    }

    // Magical particles
    updateParticles();

    // Add more particles on interaction
    if(p.mouseIsPressed && p.random() < 0.3) {
      glowParticles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-2, 2),
        vy: p.random(-3, -1),
        life: 1.0,
        color: p.random(warmColors)
      });
    }
  };

  function drawCrack() {
    // Draw crack as disruption
    p.strokeWeight(3);
    p.stroke(60, 90, 95, 0.9);
    p.noFill();

    p.beginShape();
    for(let i = 0; i < p.floor(crackProgress); i++) {
      if(i === 0) {
        p.vertex(crack[i].x, crack[i].y);
      } else {
        p.vertex(crack[i].x, crack[i].y);
      }
    }
    p.endShape();

    // Crack edges with warm glow
    p.strokeWeight(1);
    p.stroke(45, 70, 100, 0.6);
    p.beginShape();
    for(let i = 0; i < p.floor(crackProgress); i++) {
      p.vertex(crack[i].x - 2, crack[i].y);
    }
    p.endShape();

    p.beginShape();
    for(let i = 0; i < p.floor(crackProgress); i++) {
      p.vertex(crack[i].x + 2, crack[i].y);
    }
    p.endShape();
  }

  function drawLightBeam() {
    lightBeam = 0.3 + 0.2 * p.sin(p.millis() * 0.003);

    p.push();
    p.blendMode(p.SCREEN);
    p.noStroke();

    // Warm light streaming through crack
    for(let i = 0; i < 20; i++) {
      let alpha = lightBeam * (1 - i/20);
      p.fill(50, 60, 95, alpha);

      for(let j = 10; j < p.floor(crackProgress); j += 5) {
        let beamWidth = (i + 1) * 2;
        p.ellipse(crack[j].x, crack[j].y, beamWidth, beamWidth);
      }
    }
    p.pop();
  }

  function drawPhotos() {
    for(let photo of photos) {
      p.push();
      p.translate(photo.x, photo.y);
      p.rotate(photo.rotation);

      // Photo frame
      p.fill(0, 0, 95);
      p.stroke(0, 0, 85);
      p.strokeWeight(2);
      p.rect(-photo.w/2, -photo.h/2, photo.w, photo.h);

      // Photo content - warm memory
      p.fill(30, 40, 80);
      p.noStroke();
      p.rect(-photo.w/2 + 3, -photo.h/2 + 3, photo.w - 6, photo.h - 6);

      // Gentle shimmer
      let shimmer = 0.1 + 0.05 * p.sin(p.millis() * 0.001 + photo.shimmer);
      p.fill(45, 30, 100, shimmer);
      p.rect(-photo.w/2 + 3, -photo.h/2 + 3, photo.w - 6, photo.h - 6);

      p.pop();
    }
  }

  function drawToys() {
    for(let toy of toys) {
      p.push();
      p.translate(toy.x, toy.y + 5 * p.sin(p.millis() * 0.002 + toy.bobOffset));
      p.rotate(toy.rotation);

      p.noStroke();

      if(toy.type === 0) {
        // Building block
        p.fill(350, 70, 85);
        p.rect(-toy.size/2, -toy.size/2, toy.size, toy.size, 3);
        p.fill(350, 50, 95);
        p.rect(-toy.size/3, -toy.size/3, toy.size/1.5, toy.size/1.5, 2);
      } else if(toy.type === 1) {
        // Ball
        p.fill(180, 60, 90);
        p.ellipse(0, 0, toy.size, toy.size);
        p.fill(180, 40, 100);
        p.ellipse(-toy.size/4, -toy.size/4, toy.size/2, toy.size/2);
      } else {
        // Star toy
        p.fill(60, 80, 95);
        drawStar(0, 0, toy.size/3, toy.size/2, 5);
      }

      p.pop();
    }
  }

  function drawStar(x, y, radius1, radius2, npoints) {
    let angle = p.TWO_PI / npoints;
    let halfAngle = angle / 2.0;
    p.beginShape();
    for (let a = 0; a < p.TWO_PI; a += angle) {
      let sx = x + p.cos(a) * radius2;
      let sy = y + p.sin(a) * radius2;
      p.vertex(sx, sy);
      sx = x + p.cos(a + halfAngle) * radius1;
      sy = y + p.sin(a + halfAngle) * radius1;
      p.vertex(sx, sy);
    }
    p.endShape(p.CLOSE);
  }

  function updateParticles() {
    for(let i = glowParticles.length - 1; i >= 0; i--) {
      let particle = glowParticles[i];

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.vy += 0.05; // gentle gravity
      particle.life -= 0.02;

      if(particle.life > 0) {
        p.push();
        p.blendMode(p.SCREEN);
        p.noStroke();
        p.fill(p.hue(particle.color), p.saturation(particle.color), 
               p.brightness(particle.color), particle.life * 0.6);
        p.ellipse(particle.x, particle.y, 8 * particle.life, 8 * particle.life);
        p.pop();
      } else {
        glowParticles.splice(i, 1);
      }
    }
  }
}

function sketch(p) {
  let hearts = [];
  let particles = [];
  let warmColors = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Warm sunset/sunrise color palette
    warmColors = [
      p.color(20, 80, 90),   // warm orange
      p.color(40, 70, 95),   // golden yellow
      p.color(350, 60, 85),  // soft pink
      p.color(15, 90, 80),   // deep orange
      p.color(45, 50, 100),  // cream
      p.color(320, 40, 90)   // lavender pink
    ];

    // Create six heart elements in balanced arrangement
    let positions = [
      {x: 120, y: 150, size: 1.2},
      {x: 280, y: 180, size: 0.8},
      {x: 80, y: 300, size: 1.0},
      {x: 320, y: 320, size: 0.9},
      {x: 160, y: 450, size: 1.1},
      {x: 240, y: 480, size: 0.7}
    ];

    for(let i = 0; i < 6; i++) {
      hearts.push({
        x: positions[i].x,
        y: positions[i].y,
        targetX: positions[i].x,
        targetY: positions[i].y,
        size: positions[i].size * 25,
        color: warmColors[i % warmColors.length],
        pulseOffset: i * p.PI / 3,
        settled: false,
        settleTime: i * 30 + 120
      });
    }

    // Initialize floating particles for atmosphere
    for(let i = 0; i < 40; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.3, 0.3),
        vy: p.random(-0.5, -0.1),
        size: p.random(2, 6),
        color: p.random(warmColors),
        alpha: p.random(20, 60)
      });
    }
  };

  p.draw = function() {
    // Soft gradient background
    drawGradientBackground();

    time += 0.02;
    mouseInfluence = p.lerp(mouseInfluence, p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2) / 200, 0.05);

    // Draw atmospheric particles
    drawParticles();

    // Draw connecting lines between hearts (organic, flowing)
    drawConnections();

    // Draw the six hearts with settling animation
    drawHearts();

    // Add gentle glow overlay
    drawGlow();
  };

  function drawGradientBackground() {
    p.noFill();
    for(let i = 0; i <= p.height; i += 2) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c1 = p.color(25, 60, 95); // warm peachy top
      let c2 = p.color(320, 50, 70); // soft purple bottom
      let c = p.lerpColor(c1, c2, inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }
  };

  function drawParticles() {
    for(let particle of particles) {
      particle.x += particle.vx + p.sin(time + particle.x * 0.01) * 0.1;
      particle.y += particle.vy;

      // Reset particles that float off screen
      if(particle.y < -10) {
        particle.y = p.height + 10;
        particle.x = p.random(p.width);
      }
      if(particle.x < -10 || particle.x > p.width + 10) {
        particle.x = p.random(p.width);
      }

      // Draw particle with soft glow
      p.fill(p.hue(particle.color), p.saturation(particle.color), p.brightness(particle.color), particle.alpha);
      p.noStroke();
      p.circle(particle.x, particle.y, particle.size);

      // Subtle glow effect
      p.fill(p.hue(particle.color), p.saturation(particle.color) * 0.3, 100, particle.alpha * 0.3);
      p.circle(particle.x, particle.y, particle.size * 2);
    }
  };

  function drawConnections() {
    p.strokeWeight(1);
    p.noFill();

    for(let i = 0; i < hearts.length; i++) {
      for(let j = i + 1; j < hearts.length; j++) {
        let heart1 = hearts[i];
        let heart2 = hearts[j];
        let distance = p.dist(heart1.x, heart1.y, heart2.x, heart2.y);

        if(distance < 200 && heart1.settled && heart2.settled) {
          let alpha = p.map(distance, 0, 200, 60, 10);
          p.stroke(40, 30, 100, alpha);

          // Organic curved connection
          let midX = (heart1.x + heart2.x) / 2 + p.sin(time + i + j) * 15;
          let midY = (heart1.y + heart2.y) / 2 + p.cos(time * 1.2 + i + j) * 10;

          p.bezier(heart1.x, heart1.y, midX, midY - 30, midX, midY + 30, heart2.x, heart2.y);
        }
      }
    }
  };

  function drawHearts() {
    for(let i = 0; i < hearts.length; i++) {
      let heart = hearts[i];

      // Settling animation - hearts drift into final position
      if(p.frameCount < heart.settleTime) {
        let chaosX = p.sin(time * 2 + i) * 30;
        let chaosY = p.cos(time * 1.5 + i) * 20;
        heart.x = heart.targetX + chaosX;
        heart.y = heart.targetY + chaosY;
      } else {
        heart.settled = true;
        heart.x = p.lerp(heart.x, heart.targetX, 0.05);
        heart.y = p.lerp(heart.y, heart.targetY, 0.05);
      }

      // Mouse interaction - gentle attraction
      if(heart.settled) {
        let mouseDistance = p.dist(p.mouseX, p.mouseY, heart.x, heart.y);
        if(mouseDistance < 80) {
          let attraction = p.map(mouseDistance, 0, 80, 8, 0);
          let angle = p.atan2(p.mouseY - heart.y, p.mouseX - heart.x);
          heart.x += p.cos(angle) * attraction * 0.3;
          heart.y += p.sin(angle) * attraction * 0.3;
        }
      }

      // Gentle pulsing
      let pulse = p.sin(time * 2 + heart.pulseOffset) * 0.1 + 1;
      let currentSize = heart.size * pulse;

      // Draw heart shape
      p.push();
      p.translate(heart.x, heart.y);
      p.fill(heart.color);
      p.noStroke();

      // Heart glow
      p.fill(p.hue(heart.color), p.saturation(heart.color) * 0.4, 100, 30);
      drawHeartShape(0, 0, currentSize * 1.8);

      // Main heart
      p.fill(heart.color);
      drawHeartShape(0, 0, currentSize);

      p.pop();
    }
  };

  function drawHeartShape(x, y, size) {
    p.beginShape();
    for(let a = 0; a < p.TWO_PI; a += 0.1) {
      let r = size * (13 * p.cos(a) - 5 * p.cos(2*a) - 2 * p.cos(3*a) - p.cos(4*a)) / 16;
      let px = x + r * p.sin(a);
      let py = y - r * p.cos(a);
      p.vertex(px, py);
    }
    p.endShape(p.CLOSE);
  };

  function drawGlow() {
    // Soft overall glow effect
    p.fill(45, 40, 100, 8);
    p.noStroke();
    for(let i = 0; i < 3; i++) {
      p.circle(p.width/2, p.height/2, (p.width + p.height) * (1 + i * 0.5));
    }
  };

  p.mousePressed = function() {
    // Create burst of particles on click
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-2, 2),
        vy: p.random(-3, -0.5),
        size: p.random(3, 8),
        color: p.random(warmColors),
        alpha: 80
      });
    }
  };
}

