      p.line(0, y, p.width, y);
    }

    // Draw floating heart particles (memories, love, connection)
    for (let particle of heartParticles) {
      particle.y -= particle.speed;
      particle.x += p.sin(time + particle.y * 0.01) * particle.drift;

      if (particle.y < -10) particle.y = p.height + 10;
      if (particle.x < -10) particle.x = p.width + 10;
      if (particle.x > p.width + 10) particle.x = -10;

      let mouseDistance = p.dist(p.mouseX, p.mouseY, particle.x, particle.y);
      let size = particle.size;
      if (mouseDistance < 50) {
        size *= p.map(mouseDistance, 0, 50, 2, 1);
      }

      p.fill(particle.hue, 70, 90, particle.alpha);
      p.noStroke();
      p.circle(particle.x, particle.y, size);

      // Heart shape
      p.fill(particle.hue, 90, 95, particle.alpha * 0.7);
      p.circle(particle.x - size/4, particle.y - size/4, size/2);
      p.circle(particle.x + size/4, particle.y - size/4, size/2);
    }

    // Draw scattered photo memories
    for (let i = 0; i < photos.length; i++) {
      let photo = photos[i];
      let mouseDistance = p.dist(p.mouseX, p.mouseY, photo.x, photo.y);

      if (mouseDistance < 60) {
        photo.glow = p.lerp(photo.glow, 30, 0.1);
      } else {
        photo.glow = p.lerp(photo.glow, 0, 0.05);
      }

      p.push();
      p.translate(photo.x, photo.y);
      p.rotate(photo.rotation + p.sin(time + i) * 0.05);

      // Glow effect
      if (photo.glow > 0) {
        p.fill(45, 60, 100, 0.3);
        p.noStroke();
        p.rect(-photo.w/2 - 5, -photo.h/2 - 5, photo.w + 10, photo.h + 10, 3);
      }

      // Photo frame
      p.fill(40, 20, 90);
      p.stroke(40, 30, 70);
      p.strokeWeight(2);
      p.rect(-photo.w/2, -photo.h/2, photo.w, photo.h, 2);

      // Photo content (warm memory)
      p.fill(20 + i*10, 80, 85);
      p.noStroke();
      p.rect(-photo.w/2 + 3, -photo.h/2 + 3, photo.w - 6, photo.h - 6, 1);

      p.pop();
    }

    // Draw toys scattered on floor
    for (let i = 0; i < toys.length; i++) {
      let toy = toys[i];
      toy.bob += 0.03;

      let mouseDistance = p.dist(p.mouseX, p.mouseY, toy.x, toy.y);
      if (mouseDistance < 40) {
        toy.glow = p.lerp(toy.glow, 20, 0.1);
      } else {
        toy.glow = p.lerp(toy.glow, 0, 0.05);
      }

      p.push();
      p.translate(toy.x, toy.y + p.sin(toy.bob) * 2);

      // Glow
      if (toy.glow > 0) {
        p.fill(60, 70, 100, 0.4);
        p.noStroke();
        p.circle(0, 0, toy.size + toy.glow);
      }

      // Different toy types
      if (toy.type === 0) {
        // Ball
        p.fill(350, 80, 90);
        p.stroke(350, 90, 60);
        p.strokeWeight(2);
        p.circle(0, 0, toy.size);
        p.fill(350, 60, 95);
        p.noStroke();
        p.circle(-toy.size/4, -toy.size/4, toy.size/3);
      } else if (toy.type === 1) {
        // Block
        p.fill(200, 70, 85);
        p.stroke(200, 80, 60);
        p.strokeWeight(2);
        p.rect(-toy.size/2, -toy.size/2, toy.size, toy.size, 3);
        p.fill(200, 50, 95);
        p.noStroke();
        p.rect(-toy.size/4, -toy.size/4, toy.size/2, toy.size/2, 1);
      } else {
        // Star
        p.fill(50, 90, 90);
        p.stroke(50, 100, 70);
        p.strokeWeight(2);
        p.beginShape();
        for (let j = 0; j < 5; j++) {
          let angle = j * p.TWO_PI / 5 - p.PI/2;
          let x1 = p.cos(angle) * toy.size/2;
          let y1 = p.sin(angle) * toy.size/2;
          let x2 = p.cos(angle + p.PI/5) * toy.size/4;
          let y2 = p.sin(angle + p.PI/5) * toy.size/4;
          p.vertex(x1, y1);
          p.vertex(x2, y2);
        }
        p.endShape(p.CLOSE);
      }

      p.pop();
    }

    // Draw the contemplative figure
    p.push();
    p.translate(figure.x, figure.y);

    // Figure's contemplative head turn
    figure.headTurn = p.sin(time * 0.5) * 0.3;

    // Body silhouette
    p.fill(240, 30, 20, 0.8);
    p.noStroke();
    p.ellipse(0, 20, 60, 80);

    // Head looking back
    p.push();
    p.rotate(figure.headTurn);
    p.fill(30, 40, 90);
    p.circle(0, -20, 40);

    // Eyes showing contemplation
    p.fill(200, 80, 100);
    p.circle(-8, -25, 6);
    p.circle(8, -25, 6);
    p.fill(0, 0, 0);
    p.circle(-6, -25, 3);
    p.circle(6, -25, 3);
    p.pop();

    // Arms gesture of questioning/pondering
    p.stroke(240, 30, 30);
    p.strokeWeight(8);
    p.line(-15, 0, -35, -10);
    p.line(15, 0, 30, 15);

    p.pop();

    // Draw seven paths/choices emanating from figure
    p.push();
    p.translate(figure.x, figure.y - 30);

    for (let i = 0; i < paths.length; i++) {
      let path = paths[i];
      path.length = p.lerp(path.length, path.targetLength, 0.02);

      // Check mouse interaction with paths
      let pathEndX = p.cos(path.angle) * path.length;
      let pathEndY = p.sin(path.angle) * path.length;
      let mouseDistance = p.dist(p.mouseX - figure.x, p.mouseY - figure.y + 30, pathEndX, pathEndY);

      if (mouseDistance < 30) {
        path.glow = p.lerp(path.glow, 40, 0.1);
        path.targetLength = p.lerp(path.targetLength, 160, 0.05);
      } else {
        path.glow = p.lerp(path.glow, 0, 0.05);
        path.targetLength = p.lerp(path.targetLength, p.random(80, 140), 0.02);
      }

      // Path glow
      if (path.glow > 0) {
        p.stroke(60 + i*15, 60, 100, 0.6);
        p.strokeWeight(path.glow/3);
        p.line(0, 0, pathEndX, pathEndY);
      }

      // Main path
      p.stroke(40 + i*20, 80, 80, 0.8);
      p.strokeWeight(4);
      p.line(0, 0, pathEndX, pathEndY);

      // Path endpoint - choice markers
      p.fill(40 + i*20, 90, 90);
      p.noStroke();
      p.circle(pathEndX, pathEndY, 12);

      // Small heart at each path end
      p.fill(10, 100, 100, 0.7);
      p.circle(pathEndX - 3, pathEndY - 3, 4);
      p.circle(pathEndX + 3, pathEndY - 3, 4);
    }

    p.pop();

    // Gentle domestic lighting effect
    let lightX = p.width * 0.7;
    let lightY = 100;
    let lightRadius = 150 + p.sin(time) * 20;

    p.fill(45, 30, 100, 0.1);
    p.noStroke();
    p.circle(lightX, lightY, lightRadius);
    p.fill(45, 50, 100, 0.05);
    p.circle(lightX, lightY, lightRadius * 1.5);
  };

  p.mousePressed = function() {
    // Add burst of heart particles on click
    for (let i = 0; i < 10; i++) {
      heartParticles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        size: p.random(5, 12),
        speed: p.random(1, 3),
        hue: p.random(10, 50),
        alpha: p.random(0.6, 0.9),
        drift: p.random(-0.05, 0.05)
      });
    }
  };
}

function sketch(p) {
  let monsters = [];
  let heartParticles = [];
  let tools = [];
  let warmGlow;
  let homeItems = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create 8 monsters working together in a cozy home setting
    for(let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI;
      let radius = 80;
      monsters.push({
        x: 200 + p.cos(angle) * radius,
        y: 250 + p.sin(angle) * radius,
        size: p.random(25, 40),
        color: p.color(p.random(100, 255), p.random(150, 255), p.random(200, 255)),
        bobOffset: i * 0.5,
        armAngle: 0,
        eyeSize: p.random(3, 8),
        tool: i
      });
    }

    // Create 8 tools they're using together
    let toolTypes = ['heart', 'star', 'flower', 'gift', 'photo', 'toy', 'letter', 'cookie'];
    for(let i = 0; i < 8; i++) {
      tools.push({
        type: toolTypes[i],
        x: 200 + p.cos((i / 8) * p.TWO_PI) * 120,
        y: 250 + p.sin((i / 8) * p.TWO_PI) * 120,
        rotation: 0,
        scale: 1
      });
    }

    // Home decoration items
    homeItems = [
      {type: 'window', x: 50, y: 80},
      {type: 'lamp', x: 350, y: 120},
      {type: 'rug', x: 200, y: 450},
      {type: 'picture', x: 100, y: 150},
      {type: 'plant', x: 320, y: 400}
    ];

    warmGlow = p.createGraphics(400, 600);
  };

  p.draw = function() {
    // Warm sunset/sunrise gradient background
    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(255, 200, 150), p.color(255, 150, 100), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Create warm ambient glow
    warmGlow.clear();
    warmGlow.fill(255, 180, 120, 30);
    warmGlow.noStroke();
    warmGlow.ellipse(200, 200, 300, 300);
    p.image(warmGlow, 0, 0);

    // Draw home items
    drawHomeItems();

    // Draw connecting energy between monsters
    drawConnectionLines();

    // Draw the 8 monsters working together
    for(let monster of monsters) {
      drawMonster(monster);
    }

    // Draw the 8 tools
    for(let tool of tools) {
      drawTool(tool);
    }

    // Heart particles floating around
    updateHeartParticles();

    // Add gentle floating hearts on mouse interaction
    if(p.frameCount % 15 == 0) {
      heartParticles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        life: 255,
        size: p.random(3, 8),
        drift: p.random(-1, 1)
      });
    }
  };

  function drawMonster(monster) {
    p.push();
    p.translate(monster.x, monster.y + p.sin(p.frameCount * 0.03 + monster.bobOffset) * 3);

    // Body glow
    p.fill(p.red(monster.color), p.green(monster.color), p.blue(monster.color), 50);
    p.noStroke();
    p.ellipse(0, 0, monster.size + 10, monster.size + 10);

    // Body
    p.fill(monster.color);
    p.ellipse(0, 0, monster.size, monster.size);

    // Arms reaching toward tools (showing purposeful action)
    p.stroke(p.red(monster.color) * 0.8, p.green(monster.color) * 0.8, p.blue(monster.color) * 0.8);
    p.strokeWeight(3);
    monster.armAngle = p.atan2(tools[monster.tool].y - (monster.y + p.sin(p.frameCount * 0.03 + monster.bobOffset) * 3), 
                              tools[monster.tool].x - monster.x);
    p.line(0, 0, p.cos(monster.armAngle) * 15, p.sin(monster.armAngle) * 15);

    // Eyes showing warmth and connection
    p.fill(255);
    p.noStroke();
    p.ellipse(-5, -5, monster.eyeSize, monster.eyeSize);
    p.ellipse(5, -5, monster.eyeSize, monster.eyeSize);
    p.fill(50, 100, 200);
    p.ellipse(-5, -5, monster.eyeSize * 0.6, monster.eyeSize * 0.6);
    p.ellipse(5, -5, monster.eyeSize * 0.6, monster.eyeSize * 0.6);

    // Smile
    p.noFill();
    p.stroke(100);
    p.strokeWeight(2);
    p.arc(0, 3, 12, 8, 0, p.PI);

    p.pop();
  }

  function drawTool(tool) {
    p.push();
    p.translate(tool.x, tool.y);
    p.rotate(tool.rotation + p.sin(p.frameCount * 0.02) * 0.1);
    p.scale(tool.scale + p.sin(p.frameCount * 0.04) * 0.1);

    p.stroke(200, 150, 100);
    p.strokeWeight(2);

    switch(tool.type) {
      case 'heart':
        p.fill(255, 100, 150);
        drawHeart(0, 0, 15);
        break;
      case 'star':
        p.fill(255, 220, 100);
        drawStar(0, 0, 8, 15, 5);
        break;
      case 'flower':
        p.fill(255, 150, 200);
        drawFlower(0, 0, 12);
        break;
      case 'gift':
        p.fill(150, 255, 150);
        p.rect(-8, -8, 16, 16);
        p.stroke(255, 200, 100);
        p.line(-8, 0, 8, 0);
        p.line(0, -8, 0, 8);
        break;
      case 'photo':
        p.fill(255, 255, 200);
        p.rect(-10, -8, 20, 16);
        p.fill(200, 200, 255);
        p.ellipse(-3, -2, 6, 6);
        p.ellipse(3, -2, 6, 6);
        p.arc(0, 3, 8, 5, 0, p.PI);
        break;
      case 'toy':
        p.fill(255, 200, 100);
        p.ellipse(0, 0, 16, 16);
        p.fill(50);
        p.ellipse(-3, -3, 3, 3);
        p.ellipse(3, -3, 3, 3);
        break;
      case 'letter':
        p.fill(255, 250, 240);
        p.rect(-8, -6, 16, 12);
        p.stroke(255, 100, 100);
        p.line(-6, -3, 6, -3);
        p.line(-6, 0, 6, 0);
        p.line(-6, 3, 3, 3);
        break;
      case 'cookie':
        p.fill(200, 150, 100);
        p.ellipse(0, 0, 14, 14);
        p.fill(100, 50, 0);
        p.ellipse(-2, -2, 2, 2);
        p.ellipse(3, 0, 2, 2);
        p.ellipse(0, 3, 2, 2);
        break;
    }

    tool.rotation += 0.005;
    p.pop();
  }

  function drawConnectionLines() {
    p.stroke(255, 200, 150, 100);
    p.strokeWeight(1);

    // Draw gentle connecting lines between monsters showing coordination
    for(let i = 0; i < monsters.length; i++) {
      let next = (i + 1) % monsters.length;
      let m1 = monsters[i];
      let m2 = monsters[next];

      // Curved connection line
      let midX = (m1.x + m2.x) / 2 + p.sin(p.frameCount * 0.02 + i) * 10;
      let midY = (m1.y + m2.y) / 2 + p.cos(p.frameCount * 0.02 + i) * 10;

      p.noFill();
      p.bezier(m1.x, m1.y, midX, midY, midX, midY, m2.x, m2.y);
    }
  }

  function drawHomeItems() {
    for(let item of homeItems) {
      p.push();
      p.translate(item.x, item.y);

      switch(item.type) {
        case 'window':
          p.fill(200, 230, 255, 150);
          p.stroke(150, 100, 80);
          p.strokeWeight(4);
          p.rect(0, 0, 80, 60);
          p.line(40, 0, 40, 60);
          p.line(0, 30, 80, 30);
          break;
        case 'lamp':
          p.fill(255, 240, 200);
          p.noStroke();
          p.ellipse(0, 0, 30, 40);
          p.fill(100, 80, 60);
          p.rect(-2, 20, 4, 20);
          break;
        case 'rug':
          p.fill(200, 100, 150, 180);
          p.noStroke();
          p.ellipse(0, 0, 120, 80);
          break;
        case 'picture':
          p.fill(255, 220, 180);
          p.stroke(100, 80, 60);
          p.strokeWeight(3);
          p.rect(-15, -10, 30, 20);
          p.fill(255, 100, 100);
          p.noStroke();
          drawHeart(0, 0, 8);
          break;
        case 'plant':
          p.fill(100, 200, 100);
          p.noStroke();
          p.ellipse(-5, -10, 8, 12);
          p.ellipse(5, -15, 6, 10);
          p.ellipse(0, -8, 10, 8);
          p.fill(150, 100, 80);
          p.rect(-8, 0, 16, 12);
          break;
      }
      p.pop();
    }
  }

  function updateHeartParticles() {
    for(let i = heartParticles.length - 1; i >= 0; i--) {
      let heart = heartParticles[i];
      heart.life -= 3;
      heart.y -= 1;
      heart.x += heart.drift;

      p.push();
      p.fill(255, 150, 180, heart.life);
      p.noStroke();
      p.translate(heart.x, heart.y);
      drawHeart(0, 0, heart.size);
      p.pop();

      if(heart.life <= 0) {
        heartParticles.splice(i, 1);
      }
    }
  }

  function drawHeart(x, y, size) {
    p.push();
    p.translate(x, y);
    p.scale(size / 15);
    p.beginShape();
    p.vertex(0, 3);
    p.bezierVertex(-5, -2, -10, 1, -5, 6);
    p.vertex(0, 10);
    p.vertex(5, 6);
    p.bezierVertex(10, 1, 5, -2, 0, 3);
    p.endShape();
    p.pop();
  }

  function drawStar(x, y, radius1, radius2, npoints) {
    let angle = p.TWO_PI / npoints;
    let halfAngle = angle / 2.0;
    p.beginShape();
    for(let a = 0; a < p.TWO_PI; a += angle) {
      let sx = x + p.cos(a) * radius2;
      let sy = y + p.sin(a) * radius2;
      p.vertex(sx, sy);
      sx = x + p.cos(a + halfAngle) * radius1;
      sy = y + p.sin(a + halfAngle) * radius1;
      p.vertex(sx, sy);
    }
    p.endShape(p.CLOSE);
  }

  function drawFlower(x, y, size) {
    for(let i = 0; i < 6; i++) {
      p.push();
      p.translate(x, y);
      p.rotate(i * p.PI / 3);
      p.ellipse(0, -size/2, size/2, size);
      p.pop();
    }
    p.fill(255, 255, 100);
    p.ellipse(x, y, size/2, size/2);
  }

  p.mousePressed = function() {
    // Create burst of hearts when clicked
    for(let i = 0; i < 5; i++) {
      heartParticles.push({
        x: p.mouseX + p.random(-30, 30),
        y: p.mouseY + p.random(-30, 30),
        life: 255,
        size: p.random(5, 15),
        drift: p.random(-2, 2)
      });
    }

    // Make monsters briefly look toward mouse
    for(let monster of monsters) {
      monster.lookAtMouse = 30;
    }
  };
}

function sketch(p) {
  let hearts = [];
  let photos = [];
  let toys = [];
  let particles = [];
  let mike, boo;
  let warmGlow = 0;
  let completion = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create Mike and Boo figures
    mike = {
      x: 200,
      y: 380,
      eyeBlink: 0,
      satisfied: 0
    };

    boo = {
      x: 280,
      y: 420,
      giggle: 0,
      reach: 0
    };

    // Create 9 heart elements in completion arrangement
    let positions = [
      {x: 80, y: 150}, {x: 200, y: 120}, {x: 320, y: 150},
      {x: 120, y: 220}, {x: 200, y: 200}, {x: 280, y: 220},
      {x: 80, y: 290}, {x: 200, y: 270}, {x: 320, y: 290}
    ];

    for(let i = 0; i < 9; i++) {
      hearts.push({
        x: positions[i].x,
        y: positions[i].y,
        size: p.random(15, 25),
        pulse: p.random(p.TWO_PI),
        glow: p.random(0.5, 1),
        complete: false,
        completeTime: i * 0.3
      });
    }

    // Create domestic artifacts
    for(let i = 0; i < 5; i++) {
      photos.push({
        x: p.random(50, 350),
        y: p.random(80, 180),
        w: p.random(20, 35),
        h: p.random(15, 25),
        rotation: p.random(-0.2, 0.2),
        warmth: p.random(0.7, 1)
      });
    }

    for(let i = 0; i < 4; i++) {
      toys.push({
        x: p.random(60, 340),
        y: p.random(480, 550),
        size: p.random(8, 15),
        type: p.floor(p.random(3)),
        bob: p.random(p.TWO_PI),
        playful: p.random(0.8, 1.2)
      });
    }
  };

  p.draw = function() {
    // Warm sunset gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(255, 200, 150, 200),
        p.color(150, 100, 80, 255),
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Soft apartment lighting overlay
    p.fill(255, 220, 180, 30);
    p.noStroke();
    p.ellipse(200, 200, 600, 400);

    warmGlow += 0.02;
    completion += 0.008;

    // Draw domestic photos on walls
    p.push();
    for(let photo of photos) {
      p.push();
      p.translate(photo.x, photo.y);
      p.rotate(photo.rotation);
      p.fill(240, 220, 200, 150);
      p.stroke(200, 180, 160);
      p.strokeWeight(2);
      p.rect(-photo.w/2, -photo.h/2, photo.w, photo.h);

      // Warm memory glow
      p.fill(255, 200, 150, photo.warmth * 50 * (1 + 0.3 * p.sin(warmGlow)));
      p.noStroke();
      p.rect(-photo.w/2, -photo.h/2, photo.w, photo.h);
      p.pop();
    }
    p.pop();

    // Draw toys scattered around
    for(let toy of toys) {
      toy.bob += 0.05;
      let bobY = toy.y + 2 * p.sin(toy.bob);

      p.push();
      p.translate(toy.x, bobY);
      p.fill(200 + 30 * p.sin(warmGlow), 150 + 20 * p.cos(warmGlow), 180, 180);
      p.noStroke();

      if(toy.type === 0) {
        // Block
        p.rect(-toy.size/2, -toy.size/2, toy.size, toy.size);
      } else if(toy.type === 1) {
        // Ball
        p.ellipse(0, 0, toy.size);
      } else {
        // Star
        p.beginShape();
        for(let i = 0; i < 5; i++) {
          let angle = i * p.TWO_PI / 5 - p.PI/2;
          let x = toy.size * 0.5 * p.cos(angle);
          let y = toy.size * 0.5 * p.sin(angle);
          p.vertex(x, y);
        }
        p.endShape(p.CLOSE);
      }
      p.pop();
    }

    // Draw Mike (one-eyed green monster)
    p.push();
    mike.eyeBlink += 0.1;
    mike.satisfied = 0.5 + 0.3 * p.sin(completion);

    p.translate(mike.x, mike.y);

    // Body
    p.fill(100 + 20 * mike.satisfied, 200, 120);
    p.noStroke();
    p.ellipse(0, 20, 60, 80);

    // Head
    p.fill(120 + 30 * mike.satisfied, 220, 140);
    p.ellipse(0, -10, 50, 50);

    // Eye
    p.fill(255);
    p.ellipse(0, -15, 25, 25);
    p.fill(50, 100, 200);
    let blinkAmount = p.abs(p.sin(mike.eyeBlink * 0.1)) > 0.95 ? 0 : 1;
    p.ellipse(0, -15, 15 * blinkAmount, 15 * blinkAmount);

    // Mouth (satisfied smile)
    p.stroke(80, 150, 100);
    p.strokeWeight(3);
    p.noFill();
    p.arc(0, -5, 20, 15, 0, p.PI);
    p.pop();

    // Draw Boo (small human child)
    p.push();
    boo.giggle += 0.08;
    boo.reach = 0.3 + 0.2 * p.sin(completion * 1.2);

    p.translate(boo.x, boo.y);

    // Body
    p.fill(255, 200 + 20 * boo.reach, 220);
    p.noStroke();
    p.ellipse(0, 10, 25, 35);

    // Head
    p.fill(255, 220, 180);
    p.ellipse(0, -8, 20, 20);

    // Hair
    p.fill(100, 80, 60);
    p.ellipse(-2, -15, 18, 12);

    // Eyes
    p.fill(50);
    p.ellipse(-4, -10, 3, 3);
    p.ellipse(4, -10, 3, 3);

    // Reaching gesture
    p.stroke(255, 220, 180);
    p.strokeWeight(3);
    p.line(0, 0, -15 * boo.reach, -10 * boo.reach);
    p.pop();

    // Draw 9 hearts in completion formation
    for(let i = 0; i < hearts.length; i++) {
      let heart = hearts[i];
      heart.pulse += 0.08;

      // Check if this heart should be complete
      if(completion > heart.completeTime) {
        heart.complete = true;
      }

      p.push();
      p.translate(heart.x, heart.y);

      let pulseScale = heart.complete ? 1 + 0.2 * p.sin(heart.pulse) : 0.7;
      let alpha = heart.complete ? 255 : 100;

      // Heart glow
      p.fill(255, 150, 180, alpha * 0.3 * heart.glow);
      p.noStroke();
      p.scale(pulseScale * 1.5);
      drawHeart(heart.size * 1.2);

      // Main heart
      p.fill(255, 100 + 50 * heart.glow, 150, alpha);
      p.scale(0.8);
      drawHeart(heart.size);
      p.pop();

      // Connection lines between completed hearts
      if(heart.complete && i < hearts.length - 1) {
        let nextHeart = hearts[i + 1];
        if(nextHeart.complete) {
          p.stroke(255, 180, 200, 80);
          p.strokeWeight(1);
          p.line(heart.x, heart.y, nextHeart.x, nextHeart.y);
        }
      }
    }

    // Warm particles of connection
    if(p.frameCount % 20 === 0 && completion > 0.5) {
      particles.push({
        x: mike.x + p.random(-20, 20),
        y: mike.y + p.random(-20, 20),
        vx: p.random(-1, 1),
        vy: p.random(-2, -1),
        life: 60,
        maxLife: 60,
        size: p.random(3, 8)
      });
    }

    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life--;

      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 255);
      p.fill(255, 200, 100, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);

      if(particle.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Interactive mouse warmth
    let mouseDistance = p.dist(p.mouseX, p.mouseY, mike.x, mike.y);
    if(mouseDistance < 100) {
      p.fill(255, 200, 150, 50);
      p.noStroke();
      p.ellipse(mike.x, mike.y, 120, 120);
    }
  };

  function drawHeart(size) {
    p.beginShape();
    for(let t = 0; t < p.TWO_PI; t += 0.1) {
      let x = size * 0.5 * (16 * p.pow(p.sin(t), 3));
      let y = -size * 0.5 * (13 * p.cos(t) - 5 * p.cos(2*t) - 2 * p.cos(3*t) - p.cos(4*t));
      p.vertex(x * 0.05, y * 0.05);
    }
    p.endShape(p.CLOSE);
  }

  p.mousePressed = function() {
    // Create burst of connection particles
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-3, 3),
        vy: p.random(-3, 3),
        life: 40,
        maxLife: 40,
        size: p.random(4, 12)
      });
    }
  };
}

function sketch(p) {
  let hearts = [];
  let laughter = [];
  let photos = [];
  let warmth;
  let overflowParticles = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create 10 hearts arranged in completion pattern
    for(let i = 0; i < 10; i++) {
      hearts.push({
        x: 60 + (i % 4) * 70 + (Math.floor(i/4) % 2) * 35,
        y: 150 + Math.floor(i/4) * 60,
        size: 20 + p.random(-5, 5),
        pulse: p.random(0, p.TWO_PI),
        glow: p.random(150, 255)
      });
    }

    // Laughter bubbles
    for(let i = 0; i < 15; i++) {
      laughter.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        size: p.random(8, 25),
        speed: p.random(0.5, 2),
        phase: p.random(0, p.TWO_PI),
        opacity: p.random(100, 200)
      });
    }

    // Family photos/memories scattered
    for(let i = 0; i < 6; i++) {
      photos.push({
        x: p.random(30, 370),
        y: p.random(80, 520),
        w: p.random(40, 60),
        h: p.random(30, 45),
        rotation: p.random(-0.3, 0.3),
        warmth: p.random(200, 255)
      });
    }
  };

  p.draw = function() {
    // Warm gradient background - sunset/sunrise
    for(let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(255, 180, 120), p.color(255, 220, 160), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Soft room glow
    p.fill(255, 200, 150, 30);
    p.noStroke();
    p.ellipse(p.width/2, p.height/2, p.width * 1.5, p.height * 1.2);

    // Draw scattered photos/memories
    for(let photo of photos) {
      p.push();
      p.translate(photo.x, photo.y);
      p.rotate(photo.rotation);

      // Photo with warm glow
      p.fill(255, photo.warmth, photo.warmth - 50, 180);
      p.stroke(255, 255, 255, 100);
      p.strokeWeight(2);
      p.rect(-photo.w/2, -photo.h/2, photo.w, photo.h, 3);

      // Simple drawing inside
      p.noStroke();
      p.fill(255, 150, 100, 150);
      p.ellipse(-photo.w/4, -photo.h/4, 8, 8);
      p.ellipse(photo.w/4, -photo.h/4, 8, 8);
      p.arc(0, photo.h/6, photo.w/3, photo.h/4, 0, p.PI);

      p.pop();
    }

    // Draw laughter bubbles
    for(let laugh of laughter) {
      laugh.y -= laugh.speed;
      if(laugh.y < -20) laugh.y = p.height + 20;

      let wobble = p.sin(p.frameCount * 0.02 + laugh.phase) * 3;

      p.fill(255, 255, 200, laugh.opacity);
      p.noStroke();
      p.ellipse(laugh.x + wobble, laugh.y, laugh.size, laugh.size);

      // Inner sparkle
      p.fill(255, 255, 255, laugh.opacity * 0.7);
      p.ellipse(laugh.x + wobble - laugh.size/4, laugh.y - laugh.size/4, laugh.size/3, laugh.size/3);
    }

    // Draw the ten hearts in completion
    for(let i = 0; i < hearts.length; i++) {
      let heart = hearts[i];
      let pulse = p.sin(p.frameCount * 0.03 + heart.pulse) * 5;
      let currentSize = heart.size + pulse;

      // Heart glow
      p.fill(255, 100, 100, 60);
      p.noStroke();
      p.ellipse(heart.x, heart.y, currentSize * 1.8, currentSize * 1.8);

      // Main heart
      p.fill(255, heart.glow - 50, heart.glow - 80);
      drawHeart(heart.x, heart.y, currentSize);

      // Overflow effect from central hearts
      if(i >= 4 && i <= 6) {
        if(p.frameCount % 20 == 0) {
          overflowParticles.push({
            x: heart.x,
            y: heart.y,
            vx: p.random(-2, 2),
            vy: p.random(-3, -1),
            life: 60,
            size: p.random(3, 8)
          });
        }
      }
    }

    // Draw overflow particles
    for(let i = overflowParticles.length - 1; i >= 0; i--) {
      let particle = overflowParticles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.vy += 0.1; // gravity
      particle.life--;

      let alpha = p.map(particle.life, 0, 60, 0, 255);
      p.fill(255, 200, 150, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size, particle.size);

      if(particle.life <= 0) {
        overflowParticles.splice(i, 1);
      }
    }

    // Interactive glow following mouse
    let mouseGlow = p.map(p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2), 0, p.width/2, 100, 20);
    p.fill(255, 255, 200, mouseGlow);
    p.noStroke();
    p.ellipse(p.mouseX, p.mouseY, 40, 40);

    // Completion crown - overflow symbol at top
    p.push();
    p.translate(p.width/2, 60);
    p.rotate(p.sin(p.frameCount * 0.02) * 0.1);

    // Golden overflow cup
    p.fill(255, 220, 100, 200);
    p.stroke(255, 255, 150);
    p.strokeWeight(2);
    p.arc(0, 0, 60, 40, 0, p.PI);
    p.rect(-30, -5, 60, 15);

    // Overflow streams
    for(let i = 0; i < 5; i++) {
      let angle = p.map(i, 0, 4, -p.PI/3, p.PI/3);
      let length = 20 + p.sin(p.frameCount * 0.05 + i) * 10;
      p.stroke(255, 255, 200, 150);
      p.strokeWeight(3);
      p.line(0, 20, p.sin(angle) * length, 20 + p.cos(angle + p.PI) * length);
    }

    p.pop();
  };

  function drawHeart(x, y, size) {
    p.push();
    p.translate(x, y);
    p.scale(size/20);
    p.noStroke();

    // Left circle
    p.ellipse(-5, -5, 10, 10);
    // Right circle  
    p.ellipse(5, -5, 10, 10);
    // Triangle bottom
    p.triangle(-8, -2, 8, -2, 0, 12);

    p.pop();
  }

  p.mousePressed = function() {
    // Add burst of laughter on click
    for(let i = 0; i < 8; i++) {
      laughter.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        size: p.random(15, 30),
        speed: p.random(1, 3),
        phase: p.random(0, p.TWO_PI),
        opacity: p.random(150, 255)
      });
    }

    // Remove excess laughter bubbles
    if(laughter.length > 30) {
      laughter.splice(0, laughter.length - 30);
    }
  };
}

function sketch(p) {
  let monsters = [];
  let heartParticles = [];
  let glowIntensity = 0;
  let sceneWarmth = 0;
  let trainingManual = [];
  let lampGlow = 0;
  let toyObjects = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create mentor monster (experienced, warm)
    monsters.push({
      x: 120,
      y: 280,
      size: 80,
      eyeSize: 15,
      color: p.color(180, 120, 200, 200),
      bobOffset: 0,
      isTeaching: true
    });

    // Create trainee monster (smaller, eager)
    monsters.push({
      x: 280,
      y: 320,
      size: 60,
      eyeSize: 12,
      color: p.color(100, 180, 140, 200),
      bobOffset: p.PI,
      isTrainee: true
    });

    // Training manual pages floating around
    for(let i = 0; i < 8; i++) {
      trainingManual.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        rotation: p.random(p.TWO_PI),
        drift: p.random(0.01, 0.03),
        page: i
      });
    }

    // Toy objects for warmth
    for(let i = 0; i < 6; i++) {
      toyObjects.push({
        x: p.random(50, 350),
        y: p.random(400, 550),
        type: p.floor(p.random(3)),
        bob: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    // Warm gradient background (sunrise/sunset colors)
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let from = p.color(255, 220, 150);
      let to = p.color(180, 100, 120);
      let currentColor = p.lerpColor(from, to, inter);
      p.stroke(currentColor);
      p.line(0, y, p.width, y);
    }

    sceneWarmth = p.sin(p.frameCount * 0.02) * 0.3 + 0.7;
    lampGlow = p.sin(p.frameCount * 0.01) * 20 + 40;

    // Cozy apartment lamp in corner
    p.fill(255, 230, 180, 100 + lampGlow);
    p.noStroke();
    p.ellipse(350, 100, 80, 80);
    p.fill(200, 170, 100);
    p.rect(345, 100, 10, 40);
    p.ellipse(350, 80, 30, 20);

    // Window with soft light
    p.fill(255, 240, 200, 100);
    p.rect(30, 80, 60, 80, 5);
    p.fill(255, 250, 220, 80);
    p.rect(35, 85, 50, 70, 3);

    // Training manual pages
    for(let manual of trainingManual) {
      p.push();
      p.translate(manual.x, manual.y);
      p.rotate(manual.rotation + p.sin(p.frameCount * manual.drift) * 0.1);
      p.fill(255, 250, 240, 180);
      p.stroke(200, 180, 150);
      p.strokeWeight(1);
      p.rect(-15, -20, 30, 40, 2);

      // Simple text lines
      p.stroke(100, 80, 60);
      p.strokeWeight(0.5);
      for(let i = 0; i < 4; i++) {
        p.line(-10, -12 + i * 6, 10, -12 + i * 6);
      }
      p.pop();

      manual.rotation += manual.drift;
      manual.y += p.sin(p.frameCount * 0.01 + manual.page) * 0.2;
    }

    // Draw monsters
    for(let monster of monsters) {
      let bobY = p.sin(p.frameCount * 0.05 + monster.bobOffset) * 8;

      p.push();
      p.translate(monster.x, monster.y + bobY);

      // Soft glow around monsters
      p.fill(monster.color.levels[0], monster.color.levels[1], monster.color.levels[2], 30);
      p.noStroke();
      p.ellipse(0, 0, monster.size * 1.5, monster.size * 1.5);

      // Monster body
      p.fill(monster.color);
      p.stroke(255, 255, 255, 100);
      p.strokeWeight(2);
      p.ellipse(0, 0, monster.size, monster.size);

      // Eyes with warmth
      p.fill(255, 255, 255);
      p.noStroke();
      let eyeDistance = monster.size * 0.3;
      p.ellipse(-eyeDistance/2, -monster.size * 0.1, monster.eyeSize, monster.eyeSize);
      p.ellipse(eyeDistance/2, -monster.size * 0.1, monster.eyeSize, monster.eyeSize);

      // Pupils looking at each other
      p.fill(50, 50, 100);
      let lookDirection = monster.isTeaching ? 1 : -1;
      p.ellipse(-eyeDistance/2 + lookDirection * 2, -monster.size * 0.1, monster.eyeSize * 0.4, monster.eyeSize * 0.4);
      p.ellipse(eyeDistance/2 + lookDirection * 2, -monster.size * 0.1, monster.eyeSize * 0.4, monster.eyeSize * 0.4);

      // Warm smile
      p.noFill();
      p.stroke(255, 200, 150);
      p.strokeWeight(3);
      p.arc(0, monster.size * 0.15, monster.size * 0.4, monster.size * 0.3, 0, p.PI);

      // Arms reaching toward each other
      if(monster.isTeaching) {
        p.stroke(monster.color);
        p.strokeWeight(8);
        p.line(monster.size * 0.3, 0, monster.size * 0.6, -10);
      }

      p.pop();
    }

    // Heart particles representing connection
    glowIntensity = p.map(p.mouseX, 0, p.width, 0.2, 1.0);

    if(p.frameCount % 15 === 0) {
      heartParticles.push({
        x: p.lerp(monsters[0].x, monsters[1].x, 0.5) + p.random(-30, 30),
        y: p.lerp(monsters[0].y, monsters[1].y, 0.5) + p.random(-20, 20),
        size: p.random(8, 16),
        life: 255,
        vx: p.random(-1, 1),
        vy: p.random(-2, -0.5),
        color: p.color(255, p.random(180, 220), p.random(180, 220))
      });
    }

    // Draw and update heart particles
    for(let i = heartParticles.length - 1; i >= 0; i--) {
      let heart = heartParticles[i];

      p.push();
      p.translate(heart.x, heart.y);
      p.fill(heart.color.levels[0], heart.color.levels[1], heart.color.levels[2], heart.life * glowIntensity);
      p.noStroke();

      // Draw heart shape
      p.beginShape();
      for(let a = 0; a < p.TWO_PI; a += 0.1) {
        let r = heart.size * (13 * p.cos(a) - 5 * p.cos(2*a) - 2 * p.cos(3*a) - p.cos(4*a)) / 16;
        let x = r * p.cos(a);
        let y = -r * p.sin(a);
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);
      p.pop();

      heart.x += heart.vx;
      heart.y += heart.vy;
      heart.life -= 3;
      heart.size *= 1.01;

      if(heart.life <= 0) {
        heartParticles.splice(i, 1);
      }
    }

    // Toy objects on floor
    for(let toy of toyObjects) {
      let bobOffset = p.sin(p.frameCount * 0.03 + toy.bob) * 3;

      p.push();
      p.translate(toy.x, toy.y + bobOffset);

      if(toy.type === 0) { // Building block
        p.fill(255, 180, 180, 200);
        p.stroke(255, 255, 255, 100);
        p.strokeWeight(1);
        p.rect(-8, -8, 16, 16, 2);
        p.fill(255, 255, 255, 150);
        p.noStroke();
        p.rect(-6, -6, 4, 4);
        p.rect(2, -6, 4, 4);
        p.rect(-6, 2, 4, 4);
        p.rect(2, 2, 4, 4);
      } else if(toy.type === 1) { // Photo frame
        p.fill(180, 140, 100);
        p.stroke(255, 255, 255, 100);
        p.strokeWeight(2);
        p.rect(-12, -8, 24, 16, 2);
        p.fill(255, 240, 220);
        p.noStroke();
        p.rect(-8, -4, 16, 8);
      } else { // Drawing/crayon
        p.stroke(p.random(100, 255), p.random(100, 255), p.random(100, 255));
        p.strokeWeight(6);
        p.line(-10, 0, 10, 0);
        p.fill(255, 200, 150);
        p.noStroke();
        p.ellipse(10, 0, 4, 4);
      }
      p.pop();
    }

    // Interactive glow on mouse hover
    let mouseDistance = p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2);
    if(mouseDistance < 150) {
      p.fill(255, 220, 150, 30);
      p.noStroke();
      p.ellipse(p.mouseX, p.mouseY, 100, 100);
    }
  };

  p.mousePressed = function() {
    // Add extra heart burst on click
    for(let i = 0; i < 5; i++) {
      heartParticles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        size: p.random(12, 20),
        life: 255,
        vx: p.random(-2, 2),
        vy: p.random(-3, -1),
        color: p.color(255, p.random(150, 255), p.random(150, 255))
      });
    }
  };
}

