    // Magical sparkles around door
    for (let i = 0; i < 5; i++) {
      let sparkleX = 350 + p.cos(time * 2 + i) * 15;
      let sparkleY = 240 + p.sin(time * 3 + i) * 20;
      p.fill(255, 240, 180, 150);
      p.circle(sparkleX, sparkleY, 3);
    }
  }

  function drawToys() {
    // Scattered toys showing domestic/play environment
    // Building blocks
    p.fill(255, 150, 150);
    p.rect(80, 520, 15, 15);
    p.fill(150, 255, 150);
    p.rect(98, 520, 15, 15);
    p.fill(150, 150, 255);
    p.rect(89, 505, 15, 15);

    // Teddy bear
    p.fill(200, 160, 120);
    p.circle(130, 530, 20);
    p.circle(125, 525, 8);
    p.circle(135, 525, 8);
    p.fill(50);
    p.circle(127, 522, 2);
    p.circle(133, 522, 2);

    // Drawing/photo on wall
    p.fill(255, 240, 240);
    p.rect(250, 80, 80, 60);
    p.fill(255, 200, 200, 150);
    p.circle(280, 105, 15);
    p.circle(300, 105, 15);
    p.arc(290, 120, 20, 15, 0, p.PI);
  }

  function drawMike() {
    p.push();
    p.translate(150, 350 + mikeBounce);

    // Mike's body - professional at work, confident
    p.fill(100, 200, 100);
    p.stroke(80, 160, 80);
    p.strokeWeight(2);
    p.circle(0, 0, 80);

    // Mike's eye - large, alert, professional
    p.fill(255);
    p.circle(0, -10, 50);
    p.fill(50);
    p.circle(0, -10, 30);
    p.fill(255);
    p.circle(-5, -15, 8);

    // Mike's smile - genuine connection
    p.noFill();
    p.stroke(50);
    p.strokeWeight(3);
    p.arc(0, 15, 40, 20, 0, p.PI);

    // Arms showing capability and welcome
    p.strokeWeight(8);
    p.stroke(100, 200, 100);
    p.line(-35, -5, -55, -15);
    p.line(35, -5, 55, -15);

    // Hands
    p.fill(120, 220, 120);
    p.noStroke();
    p.circle(-55, -15, 12);
    p.circle(55, -15, 12);

    // Legs
    p.stroke(100, 200, 100);
    p.strokeWeight(12);
    p.line(-15, 35, -15, 65);
    p.line(15, 35, 15, 65);

    // Feet
    p.fill(120, 220, 120);
    p.noStroke();
    p.ellipse(-15, 70, 20, 12);
    p.ellipse(15, 70, 20, 12);

    p.pop();
  }

  function drawBoo() {
    p.push();
    p.translate(250, 420 + booGiggle);

    // Boo - small, trusting, the heart of genuine connection
    p.fill(255, 220, 200);
    p.noStroke();
    p.circle(0, -10, 30);

    // Hair
    p.fill(100, 50, 30);
    for (let i = 0; i < 6; i++) {
      let hairX = -12 + i * 5;
      let hairY = -22 + p.sin(time + i) * 2;
      p.circle(hairX, hairY, 6);
    }

    // Eyes - wide with wonder and trust
    p.fill(50);
    p.circle(-6, -12, 4);
    p.circle(6, -12, 4);
    p.fill(255);
    p.circle(-5, -13, 2);
    p.circle(7, -13, 2);

    // Smile
    p.stroke(50);
    p.strokeWeight(1);
    p.noFill();
    p.arc(0, -5, 10, 8, 0, p.PI);

    // Body
    p.fill(255, 200, 150);
    p.noStroke();
    p.rect(-8, 5, 16, 20, 3);

    // Arms reaching toward Mike
    p.strokeWeight(4);
    p.stroke(255, 220, 200);
    p.line(-8, 10, -20, 5);
    p.line(8, 10, 20, 5);

    // Little hands
    p.fill(255, 220, 200);
    p.noStroke();
    p.circle(-20, 5, 6);
    p.circle(20, 5, 6);

    p.pop();
  }

  function updateHeartParticles() {
    for (let heart of heartParticles) {
      // Draw heart shape
      p.push();
      p.translate(heart.x, heart.y);
      p.rotate(heart.angle);
      p.fill(255, 150, 150, heart.alpha);
      p.noStroke();

      let s = heart.size;
      p.circle(-s/4, -s/4, s/2);
      p.circle(s/4, -s/4, s/2);
      p.triangle(-s/2, 0, s/2, 0, 0, s/2);

      p.pop();

      // Float and rotate
      heart.y -= heart.speed;
      heart.angle += 0.02;
      heart.alpha = 100 + 50 * p.sin(time + heart.x * 0.01);

      // Reset when off screen
      if (heart.y < 0) {
        heart.y = p.height + 20;
        heart.x = p.random(50, 350);
      }
    }
  }

  function updateLaughParticles() {
    for (let laugh of laughParticles) {
      p.fill(255, laugh.hue * 4, 100, laugh.alpha);
      p.noStroke();
      p.circle(laugh.x, laugh.y, laugh.size);

      // Bubble up with slight wobble
      laugh.y -= laugh.speed;
      laugh.x += p.sin(time + laugh.y * 0.01) * 0.5;
      laugh.alpha = 80 + 40 * p.sin(time * 2 + laugh.x * 0.02);

      // Reset when off screen
      if (laugh.y < 0) {
        laugh.y = p.height + 20;
        laugh.x = p.random(100, 300);
        laugh.hue = p.random(40, 60);
      }
    }
  }

  function drawMouseGlow() {
    if (p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      let distance = p.dist(p.mouseX, p.mouseY, 200, 385);
      if (distance < 150) {
        p.fill(255, 240, 150, 30);
        p.noStroke();
        p.circle(p.mouseX, p.mouseY, 60);

        // Extra sparkle on click
        if (p.mouseIsPressed) {
          for (let i = 0; i < 8; i++) {
            let sparkleX = p.mouseX + p.cos(i * p.PI/4) * 30;
            let sparkleY = p.mouseY + p.sin(i * p.PI/4) * 30;
            p.fill(255, 255, 200, 180);
            p.circle(sparkleX, sparkleY, 4);
          }
        }
      }
    }
  }
}

function sketch(p) {
  let figure;
  let documents = [];
  let heartParticles = [];
  let homeObjects = [];
  let lightGlow = 0;
  let breathingOffset = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize figure position
    figure = {
      x: 200,
      y: 400,
      armExtension: 0,
      courage: 0
    };

    // Create floating documents
    for (let i = 0; i < 5; i++) {
      documents.push({
        x: p.random(50, 150),
        y: p.random(200, 500),
        rotation: p.random(0, p.TWO_PI),
        speed: p.random(0.5, 1.5),
        opacity: p.random(150, 255)
      });
    }

    // Create heart particles
    for (let i = 0; i < 20; i++) {
      heartParticles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(3, 8),
        speed: p.random(0.2, 0.8),
        phase: p.random(0, p.TWO_PI)
      });
    }

    // Create home objects (toys, photos, etc)
    for (let i = 0; i < 8; i++) {
      homeObjects.push({
        x: p.random(50, 350),
        y: p.random(100, 550),
        type: p.floor(p.random(3)),
        size: p.random(15, 30),
        rotation: p.random(0, p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    // Warm gradient background
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(255, 200, 150), p.color(255, 150, 100), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Soft ambient light
    lightGlow += 0.03;
    let glowIntensity = p.sin(lightGlow) * 30 + 200;

    // Draw cozy interior elements
    p.fill(255, 220, 180, 100);
    p.noStroke();
    p.ellipse(200, 200, 300 + p.sin(lightGlow) * 20, 200 + p.sin(lightGlow) * 15);

    // Mouse influence for interactivity
    mouseInfluence = p.lerp(mouseInfluence, p.map(p.mouseX, 0, p.width, 0, 1), 0.05);
    breathingOffset += 0.02;

    // Draw home objects (toys, photos, personal items)
    p.push();
    for (let obj of homeObjects) {
      p.push();
      p.translate(obj.x, obj.y);
      p.rotate(obj.rotation + p.sin(breathingOffset) * 0.1);
      p.fill(255, 180 + p.sin(breathingOffset + obj.x) * 30, 120, 180);
      p.noStroke();

      if (obj.type === 0) { // toy block
        p.rect(-obj.size/2, -obj.size/2, obj.size, obj.size, 3);
      } else if (obj.type === 1) { // photo frame
        p.rect(-obj.size/2, -obj.size/2, obj.size, obj.size * 0.8, 2);
        p.fill(255, 200, 150);
        p.rect(-obj.size/2 + 3, -obj.size/2 + 3, obj.size - 6, obj.size * 0.8 - 6);
      } else { // drawing/artwork
        p.fill(255, 160, 100, 160);
        p.ellipse(0, 0, obj.size, obj.size);
      }
      p.pop();
    }
    p.pop();

    // Draw heart particles for warmth and love
    for (let heart of heartParticles) {
      heart.y -= heart.speed;
      heart.phase += 0.05;

      if (heart.y < 0) heart.y = p.height;

      p.push();
      p.translate(heart.x + p.sin(heart.phase) * 20, heart.y);
      p.fill(255, 120, 120, 150 + p.sin(heart.phase) * 50);
      p.noStroke();

      // Draw heart shape
      let s = heart.size;
      p.beginShape();
      p.vertex(0, s/2);
      p.bezierVertex(-s/2, -s/4, -s/2, -s, 0, -s/4);
      p.bezierVertex(s/2, -s, s/2, -s/4, 0, s/2);
      p.endShape(p.CLOSE);
      p.pop();
    }

    // Draw floating documents
    for (let doc of documents) {
      doc.y -= doc.speed;
      doc.rotation += 0.01;

      if (doc.y < 0) doc.y = p.height;

      p.push();
      p.translate(doc.x, doc.y);
      p.rotate(doc.rotation);
      p.fill(255, 255, 240, doc.opacity * (0.7 + mouseInfluence * 0.3));
      p.stroke(200, 200, 180);
      p.strokeWeight(1);
      p.rect(-15, -20, 30, 40, 2);

      // Document lines
      p.stroke(150, 150, 130);
      p.strokeWeight(0.5);
      for (let i = -15; i < 15; i += 4) {
        p.line(-10, i, 10, i);
      }
      p.pop();
    }

    // Draw authority figure in background (subtle, shadowy)
    p.fill(100, 80, 60, 100);
    p.noStroke();
    p.ellipse(300, 200, 80, 120);
    p.ellipse(300, 180, 60, 60);

    // Main figure - the whistleblower
    figure.courage = p.lerp(figure.courage, mouseInfluence, 0.03);
    figure.armExtension = p.sin(breathingOffset) * 10 + figure.courage * 20;

    p.push();
    p.translate(figure.x, figure.y);

    // Figure's body with warm colors
    p.fill(200 + figure.courage * 55, 150 + figure.courage * 30, 100);
    p.noStroke();
    p.ellipse(0, 0, 60, 100); // body
    p.ellipse(0, -40, 50, 50); // head

    // Extended arm holding evidence
    p.push();
    p.translate(-20, -10);
    p.rotate(-0.3 - figure.armExtension * 0.02);
    p.fill(180 + figure.courage * 40, 140 + figure.courage * 25, 90);
    p.rect(0, 0, 40, 12, 6);

    // Evidence/documents in hand
    p.translate(40, 0);
    p.fill(255, 255, 240, 200 + figure.courage * 55);
    p.stroke(200, 200, 180);
    p.strokeWeight(1);
    p.rect(-5, -8, 10, 16, 1);
    p.noStroke();
    p.pop();

    // Glow of courage and authenticity
    let glowSize = 80 + figure.courage * 40 + p.sin(breathingOffset) * 15;
    p.fill(255, 200, 120, 30 + figure.courage * 20);
    p.ellipse(0, -20, glowSize, glowSize);

    p.pop();

    // Interactive light beam when mouse is near
    if (p.mouseX > 0 && p.mouseY > 0) {
      let distance = p.dist(p.mouseX, p.mouseY, figure.x, figure.y);
      if (distance < 100) {
        p.stroke(255, 220, 150, 100);
        p.strokeWeight(3);
        p.line(figure.x - 20, figure.y - 30, p.mouseX, p.mouseY);

        // Sparkles at mouse position
        for (let i = 0; i < 5; i++) {
          p.fill(255, 200, 100, p.random(100, 200));
          p.noStroke();
          p.ellipse(p.mouseX + p.random(-10, 10), p.mouseY + p.random(-10, 10), 3, 3);
        }
      }
    }

    // Warm lighting overlay
    p.fill(255, 200, 120, 15);
    p.noStroke();
    p.rect(0, 0, p.width, p.height);
  };
}

function sketch(p) {
  let rubbleBlocks = [];
  let newStructures = [];
  let heartParticles = [];
  let glowIntensity = 0;
  let constructionProgress = 0;
  let followers = [];
  let photos = [];
  let toys = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize rubble blocks (old system)
    for(let i = 0; i < 15; i++) {
      rubbleBlocks.push({
        x: p.random(50, 350),
        y: p.random(400, 550),
        size: p.random(15, 35),
        angle: p.random(p.TWO_PI),
        opacity: 180
      });
    }

    // Initialize new structures being built
    for(let i = 0; i < 8; i++) {
      newStructures.push({
        x: 100 + i * 35,
        y: 350,
        targetHeight: p.random(80, 150),
        currentHeight: 0,
        hue: p.random(25, 45),
        growing: false
      });
    }

    // Initialize followers
    for(let i = 0; i < 5; i++) {
      followers.push({
        x: p.random(300, 380),
        y: p.random(450, 550),
        bobOffset: p.random(p.TWO_PI),
        size: p.random(8, 15)
      });
    }

    // Initialize heart particles
    for(let i = 0; i < 20; i++) {
      heartParticles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(3, 8),
        speed: p.random(0.5, 2),
        opacity: p.random(100, 255)
      });
    }

    // Initialize personal artifacts
    photos.push({x: 60, y: 120, rotation: -0.2});
    photos.push({x: 320, y: 80, rotation: 0.15});
    toys.push({x: 80, y: 480, type: 'block'});
    toys.push({x: 350, y: 520, type: 'ball'});
  };

  p.draw = function() {
    // Warm gradient background (sunrise colors)
    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(255, 200, 150), p.color(100, 50, 80), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    glowIntensity = p.sin(p.millis() * 0.003) * 0.3 + 0.7;
    constructionProgress += 0.01;

    // Draw soft ambient lighting
    p.push();
    p.drawingContext.filter = 'blur(20px)';
    p.fill(255, 220, 180, 30);
    p.noStroke();
    p.ellipse(200, 150, 300, 200);
    p.pop();

    // Draw personal artifacts in background
    drawPersonalArtifacts();

    // Draw the revolutionary leader figure
    drawLeader();

    // Draw rubble (old system)
    drawRubble();

    // Draw new structures being built
    drawNewStructures();

    // Draw followers
    drawFollowers();

    // Draw floating heart particles
    drawHeartParticles();

    // Interactive glow effect
    if(p.dist(p.mouseX, p.mouseY, 150, 250) < 100) {
      p.push();
      p.drawingContext.filter = 'blur(10px)';
      p.fill(255, 200, 100, 50);
      p.noStroke();
      p.ellipse(150, 250, 150, 150);
      p.pop();
    }
  };

  function drawLeader() {
    p.push();
    p.translate(150, 250);

    // Leader's warm glow
    p.push();
    p.drawingContext.filter = 'blur(15px)';
    p.fill(255, 180, 120, 80 * glowIntensity);
    p.noStroke();
    p.ellipse(0, 0, 120, 120);
    p.pop();

    // Leader figure
    p.fill(200, 150, 100);
    p.noStroke();
    p.ellipse(0, -20, 35, 40); // head

    p.fill(180, 120, 80);
    p.rect(-15, -5, 30, 50, 5); // body

    // Arms reaching out (building gesture)
    p.stroke(180, 120, 80);
    p.strokeWeight(8);
    p.line(-15, 10, -40, 30);
    p.line(15, 10, 40, 25);

    // Gentle expression
    p.fill(100, 60, 40);
    p.noStroke();
    p.ellipse(-8, -25, 3, 3); // eyes
    p.ellipse(8, -25, 3, 3);
    p.arc(0, -15, 10, 8, 0, p.PI); // smile

    p.pop();
  }

  function drawRubble() {
    for(let block of rubbleBlocks) {
      p.push();
      p.translate(block.x, block.y);
      p.rotate(block.angle);
      p.fill(80, 70, 60, block.opacity);
      p.noStroke();
      p.rect(-block.size/2, -block.size/2, block.size, block.size, 3);

      // Slowly fade rubble
      block.opacity *= 0.999;
      p.pop();
    }
  }

  function drawNewStructures() {
    for(let structure of newStructures) {
      // Trigger growth based on construction progress
      if(p.sin(constructionProgress + structure.x * 0.01) > 0.5) {
        structure.growing = true;
      }

      if(structure.growing && structure.currentHeight < structure.targetHeight) {
        structure.currentHeight += 1.5;
      }

      if(structure.currentHeight > 0) {
        p.fill(structure.hue + 20, 200, 150, 200);
        p.noStroke();
        p.rect(structure.x - 15, structure.y - structure.currentHeight, 
               30, structure.currentHeight, 5);

        // Warm glow on new structures
        p.push();
        p.drawingContext.filter = 'blur(8px)';
        p.fill(255, 220, 150, 30);
        p.rect(structure.x - 15, structure.y - structure.currentHeight, 
               30, structure.currentHeight);
        p.pop();
      }
    }
  }

  function drawFollowers() {
    for(let follower of followers) {
      let bob = p.sin(p.millis() * 0.002 + follower.bobOffset) * 3;

      p.push();
      p.translate(follower.x, follower.y + bob);

      p.fill(150, 100, 80, 180);
      p.noStroke();
      p.ellipse(0, 0, follower.size, follower.size);

      // Simple following gesture
      p.stroke(150, 100, 80);
      p.strokeWeight(2);
      p.line(-3, 2, -8, 8);
      p.line(3, 2, 8, 8);

      p.pop();
    }
  }

  function drawHeartParticles() {
    for(let heart of heartParticles) {
      p.push();
      p.translate(heart.x, heart.y);
      p.fill(255, 150, 150, heart.opacity);
      p.noStroke();

      // Simple heart shape
      p.beginShape();
      p.vertex(0, heart.size);
      p.bezierVertex(-heart.size, 0, -heart.size, -heart.size/2, 0, -heart.size/4);
      p.bezierVertex(heart.size, -heart.size/2, heart.size, 0, 0, heart.size);
      p.endShape();

      heart.y -= heart.speed;
      heart.opacity -= 1;

      if(heart.y < -10 || heart.opacity <= 0) {
        heart.y = p.height + 10;
        heart.x = p.random(p.width);
        heart.opacity = p.random(100, 255);
      }

      p.pop();
    }
  }

  function drawPersonalArtifacts() {
    // Family photos
    for(let photo of photos) {
      p.push();
      p.translate(photo.x, photo.y);
      p.rotate(photo.rotation);
      p.fill(240, 230, 200, 180);
      p.stroke(200, 180, 150);
      p.strokeWeight(2);
      p.rect(-25, -20, 50, 40, 2);

      // Simple photo content
      p.fill(100, 150, 200, 100);
      p.noStroke();
      p.rect(-20, -15, 40, 30);
      p.pop();
    }

    // Toys
    for(let toy of toys) {
      p.push();
      p.translate(toy.x, toy.y);

      if(toy.type === 'block') {
        p.fill(200, 100, 100, 150);
        p.noStroke();
        p.rect(-8, -8, 16, 16, 2);
      } else {
        p.fill(100, 200, 150, 150);
        p.noStroke();
        p.ellipse(0, 0, 15, 15);
      }

      p.pop();
    }
  }

  p.mousePressed = function() {
    // Create burst of heart particles on click
    for(let i = 0; i < 5; i++) {
      heartParticles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY,
        size: p.random(4, 10),
        speed: p.random(1, 3),
        opacity: 255
      });
    }
  };
}
